static void load_favorites(browser_window *w) {
    free(w->favorites);
    w->favorites = NULL;
    char *acc = (char *)malloc(1);
    if (acc == NULL) return;
    acc[0] = '\0';
    size_t len = 0;

    hcf_dirs hd;
    hcf_search_dirs_from_env(&hd);
