/* An editable control gets a live text field; submit/button/hidden do not.
 * Checkboxes, radios, and selects are interactive (click toggles/opens) but
 * are not text-editable -- they are tracked via rebuild_inputs so clicks
 * dispatch to them, but they have no tf_field. */

static int input_is_interactive(int input_type) {
    return input_type == PV_IN_TEXT || input_type == PV_IN_PASSWORD
        || input_type == PV_IN_TEXTAREA || input_type == PV_IN_CHECKBOX
        || input_type == PV_IN_RADIO || input_type == PV_IN_SELECT;
}

static int input_is_editable(int input_type) {
    return input_type == PV_IN_TEXT || input_type == PV_IN_PASSWORD
        || input_type == PV_IN_TEXTAREA;
}

/* Releases the live form-control states (the array; fields are inline). */

static void free_inputs(browser_window *w) {
    free(w->inputs);
    w->inputs = NULL;
    w->input_count = 0;
    w->focused_input = -1;
}

/* Releases the decoded image surfaces of the current page and the array. */

static void free_images(browser_window *w) {
    for (size_t i = 0; i < w->image_count; ++i) {
        if (w->images[i].surface != NULL) cairo_surface_destroy(w->images[i].surface);
        free(w->images[i].href);
    }
    free(w->images);
    w->images = NULL;
    w->image_count = 0;
}

/* The decoded image for href (a doc block's URL), or NULL when it has none
 * (blocked / failed / never fetched). Matches by URL content, not block
 * identity: a worker result applied outside a fresh navigation (click, JS
 * timer) rebuilds w->doc from scratch, so the block pointer a slot was loaded
 * against no longer exists -- see the ui_image comment. */
static const ui_image *find_image(const browser_window *w, const char *href) {
    if (href == NULL) return NULL;
    for (size_t i = 0; i < w->image_count; ++i) {
        if (w->images[i].href != NULL && strcmp(w->images[i].href, href) == 0)
            return &w->images[i];
    }
    return NULL;
}

/* Releases the decoded background-image surfaces of the current page and the
 * array (2026-07-16, mirrors free_images). */
static void free_bg_images(browser_window *w) {
    for (size_t i = 0; i < w->bg_image_count; ++i) {
        if (w->bg_images[i].surface != NULL) cairo_surface_destroy(w->bg_images[i].surface);
        free(w->bg_images[i].url);
    }
    free(w->bg_images);
    w->bg_images = NULL;
    w->bg_image_count = 0;
}

/* The decoded background-image for url (a box's bg_image_url), or NULL when it
 * has none (unset / blocked / failed -- the caller paints as if there were no
 * background-image). Matches by URL content,

static const ui_bg_image *find_bg_image(const browser_window *w, const char *url) {
    if (url == NULL || url[0] == '\0') return NULL;
    const ui_bg_image *first = NULL;
    for (size_t i = 0; i < w->bg_image_count; ++i) {
        if (w->bg_images[i].url == NULL || strcmp(w->bg_images[i].url, url) != 0) continue;
        if (w->bg_images[i].surface != NULL) return &w->bg_images[i];   /* one that is loaded wins */
        if (first == NULL) first = &w->bg_images[i];
    }
    return first;
}

/* On-screen size of a decoded image: fit to the content width, never upscaled past
 * the natural size. Returns 1 and sets dw/dh when a decoded surface exists for the
 * block; 0 otherwise (the caller draws the placeholder). The single source of truth
 * shared by layout (row height) and paint (blit), so they cannot drift apart. */
/* A replaced element's own box edges, px per side (spec/box_engine.md "Bordes
 * del reemplazado"): its margin, border and padding from own_box_id -- what
 * `img{border:1px solid;margin:3px}` adds around the picture in every browser
 * (the wikipedia thumbnail frame). All zero without an own box. */

typedef struct repl_edges {
    double mt, mr, mb, ml, bt, br, bb, bl, pt, pr, pb, pl;
} repl_edges;

static double box_edge_px(int wpx);

static repl_edges replaced_edges(const rd_doc *doc, const rd_block *b, double cb_w) {
    repl_edges e;
    memset(&e, 0, sizeof e);
    if (doc == NULL || b == NULL || b->own_box_id < 0) return e;
    const pv_box_def *d = rd_box_at(doc, (size_t)b->own_box_id);
    if (d == NULL) return e;
    e.pl = box_pad_px(d->pad_l, d->pad_l_pct, cb_w);
    e.pr = box_pad_px(d->pad_r, d->pad_r_pct, cb_w);
    e.pt = box_pad_px(d->pad_t, d->pad_t_pct, cb_w);
    e.pb = box_pad_px(d->pad_b, d->pad_b_pct, cb_w);
    e.bl = box_edge_px(d->bord_lw); e.br = box_edge_px(d->bord_rw);
    e.bt = box_edge_px(d->bord_tw); e.bb = box_edge_px(d->bord_bw);
    /* box_l/box_r carry margin + padding (the box's horizontal insets). */
    e.ml = bx_lp_px(d->box_l, d->box_l_pct, cb_w) - e.pl; if (e.ml < 0.0) e.ml = 0.0;
    e.mr = bx_lp_px(d->box_r, d->box_r_pct, cb_w) - e.pr; if (e.mr < 0.0) e.mr = 0.0;
    if (d->box_mt != PV_LEN_UNSET || d->box_mt_pct != 0)
        e.mt = bx_lp_px(d->box_mt, d->box_mt_pct, cb_w);
    if (d->box_mb != PV_LEN_UNSET || d->box_mb_pct != 0)
        e.mb = bx_lp_px(d->box_mb, d->box_mb_pct, cb_w);
    if (e.mt < 0.0) e.mt = 0.0;
    if (e.mb < 0.0) e.mb = 0.0;
    return e;
}

static double repl_edges_x(const repl_edges *e) {
    return e->ml + e->bl + e->pl + e->pr + e->br + e->mr;
}

static double repl_edges_y(const repl_edges *e) {
    return e->mt + e->bt + e->pt + e->pb + e->bb + e->mb;
}

/* Paints a replaced element's own background and solid borders around its
 * content rect (x, y, cw, ch) -- the frame the edges above reserve. */
static void paint_replaced_frame(cairo_t *cr, const rd_doc *doc, const rd_block *b,
                                 const repl_edges *e, double x, double y,
                                 double cw, double ch) {
    if (cr == NULL || doc == NULL || b->own_box_id < 0) return;
    const pv_box_def *d = rd_box_at(doc, (size_t)b->own_box_id);
    if (d == NULL) return;
    double bx = x - e->pl - e->bl, by = y - e->pt - e->bt;
    double bw = cw + e->pl + e->pr + e->bl + e->br;
    double bh = ch + e->pt + e->pb + e->bt + e->bb;
    if (d->bg_rgb >= 0) {
        set_rgb(cr, rgb_from_packed(d->bg_rgb));
        cairo_rectangle(cr, bx + e->bl, by + e->bt, bw - e->bl - e->br, bh - e->bt - e->bb);
        cairo_fill(cr);
    }
    const struct { double w; int c, st; double x, y, rw, rh; } side[4] = {
        { e->bt, d->bord_tc, d->bord_ts, bx, by, bw, e->bt },
        { e->bb, d->bord_bc, d->bord_bs, bx, by + bh - e->bb, bw, e->bb },
        { e->bl, d->bord_lc, d->bord_ls, bx, by, e->bl, bh },
        { e->br, d->bord_rc, d->bord_rs, bx + bw - e->br, by, e->br, bh },
    };
    for (int k = 0; k < 4; ++k) {
        if (!(side[k].w > 0.0) || side[k].st < CSS_BST_SOLID) continue;
        set_rgb(cr, rgb_from_packed(side[k].c >= 0 ? side[k].c : 0));
        cairo_rectangle(cr, side[k].x, side[k].y, side[k].rw, side[k].rh);

static int image_display_size(const browser_window *w, const rd_block *blk,
                              double box_w, double *dw, double *dh) {
    const ui_image *im = find_image(w, blk->href);
    if (im == NULL || im->surface == NULL || im->nat_w <= 0 || im->nat_h <= 0) return 0;
    /* A specified % width IS the used width (CSS 2.1 §10.3.2), winning over the
     * intrinsic bitmap; the aspect ratio carries the height (spec/box_engine.md
     * tanda 42). A % height needs a definite container height this flat layout
     * does not model, so it stays fail-closed. */
    if (blk->box_w_pct != 0 && box_w > 0.0) {
        double pw = box_w * (double)blk->box_w_pct / 1000.0;
        if (!(pw >= 1.0)) return 0;
        *dw = pw;
        *dh = pw * (double)im->nat_h / (double)im->nat_w;
        return 1;
    }
    if (box_w < 1.0) box_w = 1.0;
    /* The markup's declared size wins over the decoded bitmap's: <img width="180">
     * asks for 180px, whatever the file happens to contain. One declared axis
     * scales the other so the aspect ratio survives. */
    double base_w = (double)im->nat_w, base_h = (double)im->nat_h;
    if (blk->video_w > 0 && blk->video_h > 0) {
        base_w = (double)blk->video_w;
        base_h = (double)blk->video_h;
    } else if (blk->video_w > 0) {
        base_h = base_h * ((double)blk->video_w / base_w);
        base_w = (double)blk->video_w;
    } else if (blk->video_h > 0) {
        base_w = base_w * ((double)blk->video_h / base_h);
        base_h = (double)blk->video_h;
    }
    double scale = (base_w > box_w) ? box_w / base_w : 1.0;

static int placeholder_display_size(const rd_block *blk, double box_w,
                                    double *dw, double *dh) {
    if (image_is_alt_text(blk)) return 0;
    if (blk->video_w <= 0 || blk->video_h <= 0) return 0;
    if (box_w < 1.0) box_w = 1.0;
    /* A percentage width is the used width (CSS 2.1 10.3.2); a CSS px height is
     * kept as is -- both are definite, so the aspect ratio does not apply (the
     * card cover `img{width:100%;height:150px}`); an attribute height scales. */
    if (blk->box_w_pct > 0) {
        *dw = box_w * (double)blk->box_w_pct / 1000.0;
        *dh = blk->img_h_css ? (double)blk->video_h
                             : *dw * (double)blk->video_h / (double)blk->video_w;
        return *dw >= 1.0 && *dh >= 1.0;
    }
    double base_w = (double)blk->video_w, base_h = (double)blk->video_h;
    double scale = (base_w > box_w) ? box_w / base_w : 1.0;
    *dw = base_w * scale;
    *dh = base_h * scale;
    return 1;
}

/* Builds the live editable state for the current doc: one entry per editable
 * control, seeded with its declared value. Aliases the doc blocks (not owned). */

static void rebuild_inputs(browser_window *w) {
    free_inputs(w);
    if (w->doc == NULL) return;
    size_t n = rd_count(w->doc);
    size_t editable = 0;
    for (size_t i = 0; i < n; ++i) {
        const rd_block *b = rd_at(w->doc, i);
        if (b->kind == RD_INPUT && input_is_interactive(b->input_type)) editable++;
    }
    if (editable == 0) return;
    w->inputs = (ui_input_state *)calloc(editable, sizeof *w->inputs);
    if (w->inputs == NULL) return; /* fail closed: no editable fields, page still shows */
    size_t k = 0;
    for (size_t i = 0; i < n; ++i) {
        const rd_block *b = rd_at(w->doc, i);
        if (b->kind != RD_INPUT || !input_is_interactive(b->input_type)) continue;
        ui_input_state *st = &w->inputs[k++];
        st->blk = b;
        tf_init(&st->field);
        if (b->value != NULL) tf_set(&st->field, b->value);
    }
    w->input_count = k;
}

/* The live state for a given doc block, or NULL when it has none. */

static ui_input_state *find_input_state(browser_window *w, const rd_block *blk) {
    for (size_t i = 0; i < w->input_count; ++i)
        if (w->inputs[i].blk == blk) return &w->inputs[i];
    return NULL;
}

/* Releases the structured render of the previous page (text mode resumes). The
 * hovered link and the live form controls alias the doc, so they are cleared too. */

static void clear_doc(browser_window *w) {
    free_inputs(w);
    free_images(w);
    free_bg_images(w);
    if (w->doc != NULL) { rd_free(w->doc); w->doc = NULL; }
    w->hover_href = NULL;
    w->hover_cursor = CSS_CUR_UNSET;
}

/* Replaces the cached page source. Takes ownership of html; copies top. */

static void set_cache(browser_window *w, char *html, size_t len, const char *top) {
    gui_quiesce(w);   /* a background tick reads what this changes */
    free(w->cur_html);
    free(w->cur_top);
    w->cur_html = html;
    w->cur_html_len = len;
    w->cur_top = (top != NULL) ? strdup(top) : NULL;
}

/* Wraps decoded ARGB32 pixels in a Cairo surface the painter can blit. Copies row
 * by row because Cairo may use a wider stride than the tightly packed worker buffer.
 * Returns NULL on failure. */

static cairo_surface_t *surface_from_pixels(const tab_image *img) {
    if (img->data == NULL || img->width == 0 || img->height == 0) return NULL;
    cairo_surface_t *s = cairo_image_surface_create(
        CAIRO_FORMAT_ARGB32, (int)img->width, (int)img->height);
    if (cairo_surface_status(s) != CAIRO_STATUS_SUCCESS) {
        cairo_surface_destroy(s);
        return NULL;
    }
    cairo_surface_flush(s);
    unsigned char *dst = cairo_image_surface_get_data(s);
    int dstride = cairo_image_surface_get_stride(s);
    size_t rowbytes = (size_t)img->width * 4u;
    if (dstride < 0 || (size_t)dstride < rowbytes) { cairo_surface_destroy(s); return NULL; }
    for (uint32_t y = 0; y < img->height; ++y) {
        memcpy(dst + (size_t)y * (size_t)dstride,
               img->data + (size_t)y * (size_t)img->stride, rowbytes);
    }
    cairo_surface_mark_dirty(s);
    return s;
}

