static double container_inner_h(const rd_doc *doc, const pv_cont_def *cdv, double content_w) {
    const pv_box_def *cbd = (cdv->box_id >= 0 && cdv->box_own)
                          ? rd_box_at(doc, (size_t)cdv->box_id) : NULL;
    if (cbd == NULL) return 0.0;
