/* Applies the appropriate Wayland cursor for the given CSS cursor value.
 * A no-op when no themed cursor is available (the compositor keeps its own default). */

static void set_cursor(browser_window *w, int cur_kind) {
    if (w->pointer == NULL || w->cursor_surface == NULL) return;
    struct wl_cursor *c = w->cursor_default;
    switch (cur_kind) {
        case CSS_CUR_POINTER:     c = w->cursor_hand; break;
        case CSS_CUR_TEXT:        c = w->cursor_text; break;
        case CSS_CUR_MOVE:        c = w->cursor_move; break;
        case CSS_CUR_WAIT:        c = w->cursor_wait; break;
        case CSS_CUR_NOT_ALLOWED: c = w->cursor_not_allowed; break;
        case CSS_CUR_CROSSHAIR:   /* fallback to default arrow */ break;
        case CSS_CUR_HELP:        /* fallback to default arrow */ break;
        case CSS_CUR_GRAB:        /* fallback to default arrow */ break;
        case CSS_CUR_ZOOM_IN:     /* fallback to default arrow */ break;
        case CSS_CUR_NONE:        return; /* hide cursor */
        default:                  c = w->cursor_default; break;
    }
    if (c == NULL || c->image_count == 0) return;
    struct wl_cursor_image *img = c->images[0];
    struct wl_buffer *buf = wl_cursor_image_get_buffer(img);
    if (buf == NULL) return;
    wl_pointer_set_cursor(w->pointer, w->pointer_serial, w->cursor_surface,
                          (int32_t)img->hotspot_x, (int32_t)img->hotspot_y);
    wl_surface_attach(w->cursor_surface, buf, 0, 0);
    wl_surface_damage(w->cursor_surface, 0, 0, (int32_t)img->width, (int32_t)img->height);
    wl_surface_commit(w->cursor_surface);
}

/* Recomputes which link (if any) is under the pointer; on a change, updates the
 * cursor shape and repaints so the hover highlight follows. Th

 * cursor:pointer element (a JS-driven button/div, not just an <a>) shows the hand
 * even without an href. v1 supports: default (arrow), pointer (hand), text (I-beam),
 * move, wait (watch), not-allowed, crosshair, help, grab, zoom-in, none. */
static void update_hover(browser_window *w) {
    const char *h = (w->doc != NULL && !w->menu_open)
                    ? link_at_point(w, w->ptr_x, w->ptr_y) : NULL;
    int cur = (w->doc != NULL && !w->menu_open)
              ? cursor_at_point(w, w->ptr_x, w->ptr_y) : CSS_CUR_UNSET;
    ui_hot hot = toolbar_button_at(w, w->ptr_x, w->ptr_y);
    if (h == w->hover_href && cur == w->hover_cursor && hot == w->hot) return;

    int cursor_kind = cur;
    if (cursor_kind == CSS_CUR_UNSET || cursor_kind == CSS_CUR_AUTO) {
        int is_link = (h != NULL) || hot_actionable(w, hot);
        cursor_kind = is_link ? CSS_CUR_POINTER : CSS_CUR_DEFAULT;
    }
    int old_cursor_kind = w->hover_cursor;
    if (old_cursor_kind == CSS_CUR_UNSET || old_cursor_kind == CSS_CUR_AUTO) {
        int was_link = (w->hover_href != NULL) || hot_actionable(w, w->hot);
        old_cursor_kind = was_link ? CSS_CUR_POINTER : CSS_CUR_DEFAULT;
    }
    w->hover_href = h;
    w->hover_cursor = cur;
    w->hot = hot;
    if (cursor_kind != old_cursor_kind) set_cursor(w, cursor_kind);
    redraw(w);
}

/* ===================== Freebug (developer console, second window) ===================== */
/* A second Wayland xdg_toplevel: a log pane (the active page's captured console.* +
 * uncaught script errors, held in browser_window.console) over a JS REPL editor that

struct freebug_window {
    browser_window      *owner;
    struct wl_surface   *surface;
    struct xdg_surface  *xdg_surface;
    struct xdg_toplevel *xdg_toplevel;
    struct zxdg_toplevel_decoration_v1 *deco;
    int    width, height;
    int    configured;
    int    visible;
    struct wl_buffer *buffer;
    void  *shm_data;
    size_t shm_size;
    cairo_surface_t *cairo_surface;
    double split;          /* log-pane fraction of the body height */
    double scroll;         /* log scroll offset (px) */
    int    dragging_split; /* the divider is being dragged */
    int    hover_copy;     /* mouse is over the copy button */
    int    copy_status;    /* 0=idle, 1=no-clipboard(red), 2=OK(green) */
    uint64_t copy_ts;      /* last copy timestamp (ms), for "Copied!" feedback */
    tf_field editor;       /* the JS REPL input (newlines allowed) */
    int    tab;                        /* active fbp_tab */
    char  *pane_text[FBP_COUNT];       /* last text of each panel, NULL = not fetched */
    char  *saved_arg[FBP_COUNT];       /* each tab's editor text while another tab is active */
    double saved_scroll[FBP_COUNT];    /* each tab's scroll while another tab is active */
};

/* y of the divider between the log pane and the editor. */

static double fbw_split_y(const freebug_window *fb) {
    double body = (double)fb->height - FBW_TOP;
    if (body < 0) body = 0;
    double s = fb->split;
    if (s < FBW_MIN_SPLIT) s = FBW_MIN_SPLIT;
    if (s > FBW_MAX_SPLIT) s = FBW_MAX_SPLIT;
    return FBW_TOP + body * s;
}

static int freebug_ensure_buffer(freebug_window *fb) {
    int stride = fb->width * 4;
    size_t size = (size_t)stride * (size_t)fb->height;
    if (fb->buffer && fb->shm_size == size && fb->cairo_surface) return 0;
    if (fb->cairo_surface) { cairo_surface_destroy(fb->cairo_surface); fb->cairo_surface = NULL; }
    if (fb->buffer) { wl_buffer_destroy(fb->buffer); fb->buffer = NULL; }
    if (fb->shm_data) { munmap(fb->shm_data, fb->shm_size); fb->shm_data = NULL; fb->shm_size = 0; }

    int fd = memfd_create("freedom-freebug", MFD_CLOEXEC);
    if (fd < 0) return -1;
    if (ftruncate(fd, (off_t)size) < 0) { close(fd); return -1; }
    void *data = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (data == MAP_FAILED) { close(fd); return -1; }
    struct wl_shm_pool *pool = wl_shm_create_pool(fb->owner->shm, fd, (int32_t)size);
    fb->buffer = wl_shm_pool_create_buffer(pool, 0, fb->width, fb->height, stride, WL_SHM_FORMAT_ARGB8888);
    wl_shm_pool_destroy(pool);
    close(fd);
    if (fb->buffer == NULL) { munmap(data, size); return -1; }
    wl_buffer_add_listener(fb->buffer, &fb_buffer_listener, fb); /* release is a no-op */
    fb->shm_data = data;
    fb->shm_size = size;
    fb->cairo_surface = cairo_image_surface_create_for_data(
        (unsigned char *)data, CAIRO_FORMAT_ARGB32, fb->width, fb->height, stride);
    return (cairo_surface_status(fb->cairo_surface) == CAIRO_STATUS_SUCCESS) ? 0 : -1;
}

/* Color for a console level (dark devtools palette). */

static void fbw_level_rgb(int level, double *r, double *g, double *b) {
    switch (level) {
        case FB_ERROR: *r = 0.95; *g = 0.36; *b = 0.36; break;
        case FB_WARN:  *r = 0.93; *g = 0.78; *b = 0.36; break;
        case FB_INFO:  *r = 0.46; *g = 0.80; *b = 0.95; break;
        case FB_DEBUG: *r = 0.60; *g = 0.60; *b = 0.66; break;
        default:       *r = 0.86; *g = 0.88; *b = 0.91; break; /* log */
    }
}

/* Counts the visual lines a console buffer occupies (entries split on '\n'). */

static size_t fbw_console_lines(const fb_buffer *log) {
    size_t lines = 0;
    for (size_t i = 0; i < fb_buffer_count(log); ++i) {
        const fb_entry *e = fb_buffer_at(log, i);
        lines += 1;
        for (size_t k = 0; k < e->len; ++k) if (e->text[k] == '\n') lines++;
    }
    return lines;
}

/* Forward declaration (defined in the clipboard section below). */
static void freebug_copy_console(browser_window *w);

/* Width of one monospace cell at the panel font size (the tab bar's unit). */

static double fbw_cell_w(cairo_t *cr) {
    cairo_text_extents_t te;
    cairo_text_extents(cr, "M", &te);
    return te.x_advance > 1.0 ? te.x_advance : 8.0;
}

static size_t fbw_text_lines(const char *t) {
    if (t == NULL || *t == '\0') return 0;
    size_t n = 1;
    for (const char *p = t; *p != '\0'; ++p) if (*p == '\n') ++n;
    return n;
}

static const char *fbw_arg_hint(int which) {
    switch (which) {
    case FBP_HTML:   return "CSS selector (empty = whole page), Enter to inspect";
    case FBP_CSS:    return "CSS selector (empty = body), Enter to inspect";
    case FBP_SCRIPT: return "script number (empty = list), Enter to show";
    case FBP_NET:    return "URL filter (empty = all requests), Enter to refresh";
    default:         return "";
    }
}

/* Firebug-style tab bar under the header: one cell strip per fbp_tab, the active one lit. */

static void fbw_paint_tabs(cairo_t *cr, const freebug_window *fb) {
    double cw = fbw_cell_w(cr);
    cairo_set_source_rgb(cr, 0.15, 0.16, 0.19);
    cairo_rectangle(cr, 0, FBW_HEADER, fb->width, FBW_TABBAR);
    cairo_fill(cr);
    for (int t = 0; t < FBP_COUNT; ++t) {
        double x, w;
        fbp_tab_span(t, cw, FBW_TAB_PAD, &x, &w);
        int on = (t == fb->tab);
        if (on) {
            cairo_set_source_rgb(cr, 0.11, 0.12, 0.14);
            cairo_rectangle(cr, x, FBW_HEADER + 2.0, w, FBW_TABBAR - 2.0);
            cairo_fill(cr);
            cairo_set_source_rgb(cr, 0.38, 0.62, 0.92);
            cairo_rectangle(cr, x, FBW_HEADER + 2.0, w, 2.0);
            cairo_fill(cr);
        }
        cairo_set_source_rgb(cr, on ? 0.92 : 0.62, on ? 0.94 : 0.65, on ? 0.97 : 0.70);
        cairo_move_to(cr, x + cw * FBW_TAB_PAD, FBW_HEADER + FBW_TABBAR - 8.0);
        cairo_show_text(cr, fbp_tab_label(t));
    }
}

/* A panel's text, one monospace line per source line, from `y` (already scrolled). */

static void fbw_paint_pane(cairo_t *cr, const freebug_window *fb, double y, double split_y) {
    const char *t = fb->pane_text[fb->tab];
    if (t == NULL) {
        cairo_set_source_rgb(cr, 0.55, 0.58, 0.64);
        cairo_move_to(cr, FBW_PAD, y);
        cairo_show_text(cr, "(nothing yet: press Enter in the box below to inspect)");
        return;
    }
    const char *p = t;
    for (;;) {
        const char *nl = strchr(p, '\n');
        size_t len = nl ? (size_t)(nl - p) : strlen(p);
        if (y > FBW_TOP && y < split_y + FBW_LINE) {
            char buf[1024];
            size_t cpy = (len < sizeof buf - 1) ? len : sizeof buf - 1;
            memcpy(buf, p, cpy);
            buf[cpy] = '\0';
            int dim = (buf[0] == '=' && buf[1] == '=');
            int lost = (buf[0] == ' ' && buf[1] == ' ' && buf[2] == '~');
            if (dim) cairo_set_source_rgb(cr, 0.45, 0.70, 0.95);
            else if (lost) cairo_set_source_rgb(cr, 0.50, 0.52, 0.56);   /* overridden declaration */
            else cairo_set_source_rgb(cr, 0.86, 0.88, 0.91);
            cairo_move_to(cr, FBW_PAD, y);
            cairo_show_text(cr, buf);
        }
        y += FBW_LINE;
        if (nl == NULL) break;
        p = nl + 1;
    }
}

