            if (w->inputs[i].blk != NULL && w->inputs[i].blk->node_id == node_id
                && input_is_editable(w->inputs[i].blk->input_type)) {
                tf_set(&w->inputs[i].field, value);
                w->focused_input = (int)i;
                break;
            }
        }
    }
}

