/* Reads the whole file into a NUL-terminated buffer. Caller frees. */
static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (f == NULL) return NULL;
    if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return NULL; }
    long sz = ftell(f);
    if (sz < 0) { fclose(f); return NULL; }
    rewind(f);

    char *buf = (char *)malloc((size_t)sz + 1);
    if (buf == NULL) { fclose(f); return NULL; }
    size_t n = fread(buf, 1, (size_t)sz, f);
    fclose(f);
    buf[n] = '\0';
    if (out_len != NULL) *out_len = n;
    return buf;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file.html>\n", argv[0]);
        return 2;
    }

    size_t html_len = 0;
    char *html = read_file(argv[1], &html_len);
    if (html == NULL) {
        fprintf(stderr, "freedom-view: cannot read '%s'\n", argv[1]);
        return 1;
    }

    hp_document *doc = NULL;
    hp_status ps = hp_parse(html, html_len, NULL, &doc);
    free(html);
    if (ps != HP_OK) {
        fprintf(stderr, "freedom-view: parse failed (status %d)\n", ps);
        return 1;
    }

    size_t title_len = 0, text_len = 0;
    char *title = hp_get_title(doc, &title_len);
    char *text = hp_extract_text(doc, &text_len);
    hp_document_free(doc);

    const char *win_title = (title != NULL && title_len > 0) ? title : "Freedom";
    ui_status us = ui_run_text_view(win_title,
                                    (text != NULL) ? text : "",
                                    (text != NULL) ? text_len : 0);

    hp_free(title);
    hp_free(text);

    if (us == UI_ERR_DISPLAY) {
        fprintf(stderr, "freedom-view: no Wayland display (set WAYLAND_DISPLAY)\n");
        return 1;
    }
    return (us == UI_OK) ? 0 : 1;
}

static double svp_alpha(int opacity, int paint_opacity) {
    double o = (opacity >= 0 && opacity <= 100) ? opacity / 100.0 : 1.0;
    double p = (paint_opacity >= 0 && paint_opacity <= 100) ? paint_opacity / 100.0 : 1.0;
    return o * p;
}

/* Appends a rounded rectangle (or a plain one when the radii are zero). */

static void svp_rect_path(cairo_t *cr, const sv_shape *sh) {
    double x = sh->a, y = sh->b, w = sh->c, h = sh->d;
    double rx = sh->rx, ry = sh->ry;
    if (rx <= 0.0 || ry <= 0.0) {
        cairo_rectangle(cr, x, y, w, h);
        return;
    }
    /* Corner arcs drawn on a unit circle scaled to (rx, ry): one save/restore per
     * corner would reset the path, so the ellipse is produced by scaling the
     * coordinate system around each corner centre instead. */
    const double PI = 3.14159265358979323846;
    cairo_new_sub_path(cr);
    cairo_save(cr);
    cairo_translate(cr, x + rx, y + ry);
    cairo_scale(cr, rx, ry);
    cairo_arc(cr, 0.0, 0.0, 1.0, PI, 1.5 * PI);
    cairo_restore(cr);
    cairo_save(cr);
    cairo_translate(cr, x + w - rx, y + ry);
    cairo_scale(cr, rx, ry);
    cairo_arc(cr, 0.0, 0.0, 1.0, 1.5 * PI, 2.0 * PI);
    cairo_restore(cr);
    cairo_save(cr);
    cairo_translate(cr, x + w - rx, y + h - ry);
    cairo_scale(cr, rx, ry);
    cairo_arc(cr, 0.0, 0.0, 1.0, 0.0, 0.5 * PI);
    cairo_restore(cr);
    cairo_save(cr);
    cairo_translate(cr, x + rx, y + h - ry);
    cairo_scale(cr, rx, ry);
    cairo_arc(cr, 0.0, 0.0, 1.0, 0.5 * PI, PI);
    cairo_restore(cr);
    cairo_close_path(cr);
}

static void svp_shape_path(cairo_t *cr, const sv_image *img, const sv_shape *sh) {
    const double PI = 3.14159265358979323846;
