/* --- framed pipe I/O (EINTR-safe, all-or-nothing) --- */

static inline int write_full(int fd, const void *buf, size_t n) {
    const uint8_t *p = (const uint8_t *)buf;
    size_t done = 0;
    while (done < n) {
        ssize_t w = write(fd, p + done, n - done);
        if (w < 0) { if (errno == EINTR) continue; return -1; }
        done += (size_t)w;
    }
    return 0;
}

static inline int read_full(int fd, void *buf, size_t n) {
    uint8_t *p = (uint8_t *)buf;
    size_t got = 0;
    while (got < n) {
        ssize_t r = read(fd, p + got, n - got);
        if (r < 0) { if (errno == EINTR) continue; return -1; }
        if (r == 0) return -1; /* unexpected EOF */
        got += (size_t)r;
    }
    return 0;
}

/* --- case-insensitive bounded substring search --- */

/* Returns 1 when the trusted lowercase-ASCII needle (letters/digits) occurs in
 * the hostile, length-delimited haystack, matching case-insensitively. The
 * `| 0x20` fold maps A-Z to a-z and leaves digits unchanged. */

static inline int mem_contains_ci(const void *hay, size_t hlen, const char *needle) {
    const unsigned char *h = (const unsigned char *)hay;
    size_t nlen = strlen(needle);
    if (h == NULL || nlen == 0 || hlen < nlen) return 0;
    for (size_t i = 0; i + nlen <= hlen; ++i) {
        size_t j = 0;
        while (j < nlen && (char)(h[i + j] | 0x20) == needle[j]) j++;
        if (j == nlen) return 1;
    }
    return 0;
}

/* --- UTF-8 lead-byte length table --- */

static inline size_t utf8_seq_len(unsigned char c) {
    if (c < 0x80) return 1;
    if (c >= 0xC2 && c <= 0xDF) return 2;
    if (c >= 0xE0 && c <= 0xEF) return 3;
    if (c >= 0xF0 && c <= 0xF4) return 4;
    return 0;
}

/* --- FNV-1a 64-bit hash --- */

static inline uint64_t fnv1a(const char *s, size_t n) {
    uint64_t h = 1469598103934665603ULL;
    for (size_t i = 0; i < n; ++i) {
        h ^= (unsigned char)s[i];
        h *= 1099511628211ULL;
    }
    return h;
}

