/* --- screen bucketing --- */

void fp_bucket_screen(int w, int h, int *out_w, int *out_h) {
    static const int buckets[][2] = {
        {1920, 1080}, {1600, 900}, {1536, 864}, {1440, 900},
        {1366, 768},  {1280, 720}, {1024, 768}, {800, 600},
    };
    const size_t n = sizeof buckets / sizeof buckets[0];
    const size_t smallest = n - 1; /* last entry has the smallest area */

    long best_area = -1;
    size_t best = smallest;
    for (size_t i = 0; i < n; ++i) {
        if (buckets[i][0] <= w && buckets[i][1] <= h) {
            long area = (long)buckets[i][0] * (long)buckets[i][1];
            if (area > best_area) { best_area = area; best = i; }
        }
    }
    if (out_w != NULL) *out_w = buckets[best][0];
    if (out_h != NULL) *out_h = buckets[best][1];
}

/* --- readback poisoning --- */

static uint64_t splitmix64(uint64_t *state) {
    uint64_t z = (*state += 0x9e3779b97f4a7c15ULL);
    z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
    z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
    return z ^ (z >> 31);
}

void fp_perturb(uint8_t *buf, size_t len, uint64_t session_key) {
    if (buf == NULL || len == 0) return;
    uint64_t state = session_key;
    for (size_t i = 0; i < len; ++i) {
        /* Sparse selection (~1/16) keyed by the session and the byte index. */
        if ((splitmix64(&state) & 0xF) == 0) {
            buf[i] ^= 1u; /* flip only the least-significant bit */
        }
    }
}

uint64_t fp_origin_key(uint64_t session_key, const char *registrable_domain) {
    /* FNV-1a over the domain bytes; a NULL/empty domain stays at the basis, so
     * both collapse to one stable namespace distinct from any real site. */
    uint64_t h = 0xcbf29ce484222325ULL; /* FNV-1a 64-bit offset basis */
    if (registrable_domain != NULL) {
        for (const unsigned char *p = (const unsigned char *)registrable_domain;
             *p != '\0'; ++p) {
            h ^= (uint64_t)*p;
            h *= 0x00000100000001b3ULL; /* FNV-1a 64-bit prime */
        }
    }
    /* splitmix64 is a bijection on the post-add state, so distinct (session_key,
     * domain) pairs that differ in session_key ^ h yield distinct keys; the
     * finalisation also diffuses FNV's weak avalanche so near-identical domains
     * still produce well-separated keys. */
    uint64_t state = session_key ^ h;
    return splitmix64(&state);
}

static double finite_or_zero(double v) {
    return isfinite(v) ? v : 0.0;
}

double bf_collapse_n(const double *m, size_t n) {
    if (m == NULL || n == 0) return 0.0;
    /* CSS 2.1 8.3.1: the used margin is the largest POSITIVE adjoining margin
     * with the largest-in-magnitude NEGATIVE one deducted from it. Tracking the
     * two extremes separately is what makes the rule associative, so the n-ary
     * form and repeated binary calls cannot disagree. */
    double pos = 0.0, neg = 0.0;
    for (size_t i = 0; i < n; ++i) {
        double v = finite_or_zero(m[i]);
        if (v > pos) pos = v;
        else if (v < neg) neg = v;
    }
    return pos + neg;
}

double bf_collapse(double a, double b) {
    const double pair[2] = { a, b };
    return bf_collapse_n(pair, 2);
}

int bf_margins_adjoin(double border_px, double padding_px) {
    /* Fail closed: a non-finite edge is treated as PRESENT, so the margins do not
     * collapse. Over-collapsing deletes space the author asked for and fuses two
     * blocks; under-collapsing merely leaves a gap. */
    if (!isfinite(border_px) || !isfinite(padding_px)) return 0;
    return (border_px == 0.0 && padding_px == 0.0) ? 1 : 0;
}

int bb_box_sizes(double sigma, int sizes[3]) {
    if (sizes == NULL || !isfinite(sigma) || !(sigma > 0.0)) return 0;
    /* Three successive boxes whose variances add up to sigma^2 (a box of odd

     * width w has variance (w^2 - 1) / 12): the ideal common width, rounded down
     * to an odd wl and up to wu = wl + 2, mixed so the sum lands on sigma^2. */
    double wideal = sqrt(12.0 * sigma * sigma / 3.0 + 1.0);
    int wl = (int)floor(wideal);
    if (wl % 2 == 0) --wl;
    if (wl < 1) wl = 1;
    int wu = wl + 2;
    double mideal = (12.0 * sigma * sigma - 3.0 * wl * wl - 12.0 * wl - 9.0)
                  / (-4.0 * wl - 4.0);
    int m = (int)lround(mideal);
    if (m < 0) m = 0;
    if (m > 3) m = 3;
    for (int k = 0; k < 3; ++k) sizes[k] = (k < m) ? wl : wu;
    return 1;
}

/* One box pass of odd width bw over n samples spaced `step` apart, through tmp
 * (n bytes). Samples outside [0, n) are 0. Running sum, so O(n) per line. */

static void box_line(unsigned char *p, int n, int step, int bw, unsigned char *tmp) {
    int r = bw / 2;
    long sum = 0;
    for (int i = 0; i < n; ++i) tmp[i] = p[(long)i * step];
    for (int i = 0; i <= r && i < n; ++i) sum += tmp[i];
    for (int i = 0; i < n; ++i) {
        p[(long)i * step] = (unsigned char)((sum + bw / 2) / bw);
        int add = i + r + 1, sub = i - r;
        if (add < n) sum += tmp[add];
        if (sub >= 0) sum -= tmp[sub];
    }
}

int bb_blur_a8(unsigned char *buf, int w, int h, int stride, double sigma) {
    if (buf == NULL || w <= 0 || h <= 0 || stride < w) return -1;
    if ((long long)w * (long long)h > (long long)BB_MAX_PIXELS) return -1;
    int sizes[3];
    if (!bb_box_sizes(sigma, sizes)) return 0;
    int longest = (w > h) ? w : h;
    unsigned char *tmp = (unsigned char *)calloc((size_t)longest, 1);
    if (tmp == NULL) return -1;
    for (int k = 0; k < 3; ++k) {
        for (int y = 0; y < h; ++y) box_line(buf + (long)y * stride, w, 1, sizes[k], tmp);
        for (int x = 0; x < w; ++x) box_line(buf + x, h, stride, sizes[k], tmp);
    }
    free(tmp);
    return 1;
}

