    unsigned char al[BT_MAX_CHILDREN], ar[BT_MAX_CHILDREN];
    int any = 0;
    for (size_t k = 0; k < ln && k < BT_MAX_CHILDREN; ++k) {
        al[k] = (kids[k]->mauto & BT_MAUTO_LEFT) != 0;
        ar[k] = (kids[k]->mauto & BT_MAUTO_RIGHT) != 0;
        any |= al[k] | ar[k];
    }
    if (!any) return FX_OK;
    return fx_auto_margins(res, ln, al, ar, cw, gap);
}

