    if (bs == NULL) return BROWSER_ERR_NULL;
    browser_free(bs);
    memset(bs, 0, sizeof *bs);
    if (browser_set_url_bar(bs, "about:blank") != BROWSER_OK) {
        browser_free(bs);
        return BROWSER_ERR_OOM;
    }
    return BROWSER_OK;
}

void browser_free(browser_state *bs) {
