    if (bs == NULL) return BROWSER_ERR_NULL;
    return browser_navigate(bs, bs->url_bar);
}

/* Appends url as a new entry of document doc after history_pos, discarding the
 * forward entries (standard Back/Forward semantics). Both arrays grow together. */
static browser_status append_entry(browser_state *bs, const char *url, int doc) {
    if (bs->history_pos < bs->history_len) {
        for (size_t i = bs->history_pos + 1; i < bs->history_len; ++i) {
            free(bs->history[i]);
        }
        bs->history_len = bs->history_pos + 1;
    }
    if (bs->history_len >= bs->history_cap) {
        size_t new_cap = bs->history_cap ? bs->history_cap * 2 : 8;
        char **nh = (char **)realloc(bs->history, new_cap * sizeof *nh);
        if (nh == NULL) return BROWSER_ERR_OOM;
        bs->history = nh;
        int *nd = (int *)realloc(bs->history_doc, new_cap * sizeof *nd);
        if (nd == NULL) return BROWSER_ERR_OOM;
        bs->history_doc = nd;
        bs->history_cap = new_cap;
    }
    char *copy = xstrdup(url);
    if (copy == NULL) return BROWSER_ERR_OOM;
    bs->history[bs->history_len] = copy;
    bs->history_doc[bs->history_len] = doc;
    bs->history_len++;
    bs->history_pos = bs->history_len - 1;
    browser_set_url_bar(bs, url);
    return BROWSER_OK;
}

browser_status browser_navigate(browser_state *bs, const char *url) {
    if (bs == NULL || url == NULL) return BROWSER_ERR_NULL;
    if (!url_is_allowed(url)) return BROWSER_ERR_INVALID_URL;
    browser_status st = append_entry(bs, url, bs->next_doc);
    if (st != BROWSER_OK) return st;
    bs->next_doc++;
    free_page(bs);
    bs->loading_error = 0;
    clear_status(bs);
    return BROWSER_OK;
}

browser_status browser_push_state(browser_state *bs, const char *url) {
    if (bs == NULL || url == NULL) return BROWSER_ERR_NULL;
    if (bs->history_len == 0) return BROWSER_ERR_NO_BACK;
    if (!url_is_allowed(url)) return BROWSER_ERR_INVALID_URL;
    return append_entry(bs, url, bs->history_doc[bs->history_pos]);
}

browser_status browser_replace_state(browser_state *bs, const char *url) {
    if (bs == NULL || url == NULL) return BROWSER_ERR_NULL;
    if (bs->history_len == 0) return BROWSER_ERR_NO_BACK;
    if (!url_is_allowed(url)) return BROWSER_ERR_INVALID_URL;
    char *copy = xstrdup(url);
    if (copy == NULL) return BROWSER_ERR_OOM;
    free(bs->history[bs->history_pos]);
    bs->history[bs->history_pos] = copy;
    browser_set_url_bar(bs, url);
    return BROWSER_OK;
}

int browser_entry_doc(const browser_state *bs, size_t pos) {
    if (bs == NULL || pos >= bs->history_len) return -1;
    return bs->history_doc[pos];
}

int browser_doc_index(const browser_state *bs) {
    if (bs == NULL || bs->history_len == 0) return -1;
    size_t start = bs->history_pos;
    int doc = bs->history_doc[start];
    while (start > 0 && bs->history_doc[start - 1] == doc) start--;
    return (int)(bs->history_pos - start);
}

browser_status browser_back(browser_state *bs) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    if (bs->history_pos == 0 || bs->history_len == 0) return BROWSER_ERR_NO_BACK;
    bs->history_pos--;
    const char *url = bs->history[bs->history_pos];
    browser_set_url_bar(bs, url ? url : "");
    free_page(bs);
    bs->loading_error = 0;
    clear_status(bs);
    return BROWSER_OK;
}

browser_status browser_forward(browser_state *bs) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    if (bs->history_pos + 1 >= bs->history_len) return BROWSER_ERR_NO_FORWARD;
    bs->history_pos++;
    const char *url = bs->history[bs->history_pos];
    browser_set_url_bar(bs, url ? url : "");
    free_page(bs);
    bs->loading_error = 0;
    clear_status(bs);
    return BROWSER_OK;
}

int browser_can_back(const browser_state *bs) {
    return (bs != NULL && bs->history_pos > 0);
}

int browser_can_forward(const browser_state *bs) {
    return (bs != NULL && bs->history_len > 0 && bs->history_pos + 1 < bs->history_len);
}

const char *browser_current_url(const browser_state *bs) {
    if (bs == NULL || bs->history_len == 0) return NULL;
    return bs->history[bs->history_pos];
}

int browser_url_bar_selection(const browser_state *bs, size_t *start, size_t *len) {
    if (bs == NULL || bs->url_bar_anchor == bs->url_bar_cursor) return 0;
    size_t a = bs->url_bar_anchor, c = bs->url_bar_cursor;
    size_t s = (a < c) ? a : c, e = (a < c) ? c : a;
    if (e > bs->url_bar_len) e = bs->url_bar_len;   /* defensive clamp */
    if (s >= e) return 0;
    if (start != NULL) *start = s;
    if (len != NULL) *len = e - s;
    return 1;
}

int browser_url_bar_delete_selection(browser_state *bs) {
    size_t s = 0, l = 0;
    if (!browser_url_bar_selection(bs, &s, &l)) return 0;
    memmove(bs->url_bar + s, bs->url_bar + s + l, bs->url_bar_len - (s + l) + 1);
    bs->url_bar_len -= l;
    bs->url_bar_cursor = s;
    bs->url_bar_anchor = s;
    return 1;
}

browser_status browser_url_bar_insert(browser_state *bs, char c) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    browser_url_bar_delete_selection(bs);   /* typing replaces a selection */
    if (bs->url_bar_len + 1 >= BROWSER_URL_MAX) return BROWSER_ERR_OOM;
    if (bs->url_bar_cursor > bs->url_bar_len) bs->url_bar_cursor = bs->url_bar_len;
    memmove(bs->url_bar + bs->url_bar_cursor + 1,
            bs->url_bar + bs->url_bar_cursor,
            bs->url_bar_len - bs->url_bar_cursor + 1);
    bs->url_bar[bs->url_bar_cursor] = c;
    bs->url_bar_len++;
    bs->url_bar_cursor++;
    bs->url_bar_anchor = bs->url_bar_cursor;
    return BROWSER_OK;
}

browser_status browser_url_bar_backspace(browser_state *bs) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    if (browser_url_bar_delete_selection(bs)) return BROWSER_OK;
    if (bs->url_bar_cursor == 0) return BROWSER_OK;
    size_t pos = bs->url_bar_cursor - 1;
    memmove(bs->url_bar + pos,
            bs->url_bar + pos + 1,
            bs->url_bar_len - pos);
    bs->url_bar_len--;
    bs->url_bar_cursor = pos;
    bs->url_bar_anchor = pos;
    return BROWSER_OK;
}

browser_status browser_url_bar_delete(browser_state *bs) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    if (browser_url_bar_delete_selection(bs)) return BROWSER_OK;
    if (bs->url_bar_cursor >= bs->url_bar_len) return BROWSER_OK;
    memmove(bs->url_bar + bs->url_bar_cursor,
            bs->url_bar + bs->url_bar_cursor + 1,
            bs->url_bar_len - bs->url_bar_cursor);
    bs->url_bar_len--;
    return BROWSER_OK;
}

browser_status browser_url_bar_move_cursor(browser_state *bs, long delta) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    long pos = (long)bs->url_bar_cursor + delta;
    if (pos < 0) pos = 0;
    if ((size_t)pos > bs->url_bar_len) pos = (long)bs->url_bar_len;
    bs->url_bar_cursor = (size_t)pos;
    bs->url_bar_anchor = bs->url_bar_cursor;   /* plain motion collapses the selection */
    return BROWSER_OK;
}

browser_status browser_url_bar_extend_cursor(browser_state *bs, long delta) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    long pos = (long)bs->url_bar_cursor + delta;
    if (pos < 0) pos = 0;
    if ((size_t)pos > bs->url_bar_len) pos = (long)bs->url_bar_len;
    bs->url_bar_cursor = (size_t)pos;          /* anchor kept: extends the selection */
    return BROWSER_OK;
}

browser_status browser_url_bar_set_cursor(browser_state *bs, size_t pos, int extend) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    if (pos > bs->url_bar_len) pos = bs->url_bar_len;
    bs->url_bar_cursor = pos;
    if (!extend) bs->url_bar_anchor = pos;
    return BROWSER_OK;
}

browser_status browser_url_bar_select_all(browser_state *bs) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    bs->url_bar_anchor = 0;
    bs->url_bar_cursor = bs->url_bar_len;
    return BROWSER_OK;
}

browser_status browser_url_bar_clear(browser_state *bs) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    bs->url_bar[0] = '\0';
    bs->url_bar_len = 0;
    bs->url_bar_cursor = 0;
    bs->url_bar_anchor = 0;
    return BROWSER_OK;
}

browser_status browser_set_page(browser_state *bs, const char *title,
                                const char *text, int error) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    free_page(bs);
    bs->loading_error = error;
    if (error) {
        const char *msg = (text != NULL) ? text : "Failed to load page.";
        bs->page_text = utf8_sanitized_dup(msg);
        bs->page_title = xstrdup("Error");
        return (bs->page_text != NULL && bs->page_title != NULL) ? BROWSER_OK : BROWSER_ERR_OOM;
    }
    /* Page title and text come from a hostile remote document: store them as
     * well-formed UTF-8 so the renderer can never be poisoned by bad bytes. */
    bs->page_title = utf8_sanitized_dup(title);
    bs->page_text = utf8_sanitized_dup(text);
    if ((title != NULL && bs->page_title == NULL) || (text != NULL && bs->page_text == NULL)) {
        free_page(bs);
        return BROWSER_ERR_OOM;
    }
    return BROWSER_OK;
}

browser_status browser_set_status(browser_state *bs, const char *msg, uint64_t now_ms) {
    if (bs == NULL) return BROWSER_ERR_NULL;
    if (msg == NULL || msg[0] == '\0') {
        clear_status(bs);
        return BROWSER_OK;
    }
    size_t n = strlen(msg);
    if (n >= BROWSER_STATUS_MAX) n = BROWSER_STATUS_MAX - 1;
    memcpy(bs->status_msg, msg, n);
    bs->status_msg[n] = '\0';
    bs->status_expiry_ms = now_ms + BROWSER_STATUS_DURATION_MS;
    return BROWSER_OK;
}

const char *browser_status_text(const browser_state *bs, uint64_t now_ms) {
    if (bs == NULL || bs->status_msg[0] == '\0') return NULL;
    if (now_ms >= bs->status_expiry_ms) return NULL;
    return bs->status_msg;
}

/* --- exceptions (user override for weak TLS) --- */

static int host_equal(const char *a, const char *b) {
    while (*a && *b) {
        int ca = (unsigned char)*a, cb = (unsigned char)*b;
        if (ca >= 'A' && ca <= 'Z') ca += 'a' - 'A';
        if (cb >= 'A' && cb <= 'Z') cb += 'a' - 'A';
        if (ca != cb) return 0;
        ++a; ++b;
    }
    return *a == '\0' && *b == '\0';
}

int browser_is_exception(const browser_state *bs, const char *host) {
    if (bs == NULL || host == NULL) return 0;
    for (size_t i = 0; i < bs->exceptions_len; ++i) {
        if (bs->exceptions[i] != NULL && host_equal(bs->exceptions[i], host)) return 1;
    }
    return 0;
}

browser_status browser_add_exception(browser_state *bs, const char *host) {
    if (bs == NULL || host == NULL) return BROWSER_ERR_NULL;
    if (browser_is_exception(bs, host)) return BROWSER_OK;

    if (bs->exceptions_len >= bs->exceptions_cap) {
        size_t new_cap = bs->exceptions_cap ? bs->exceptions_cap * 2 : 4;
        char **ne = (char **)realloc(bs->exceptions, new_cap * sizeof *ne);
        if (ne == NULL) return BROWSER_ERR_OOM;
        bs->exceptions = ne;
        bs->exceptions_cap = new_cap;
    }

    char *copy = xstrdup(host);
    if (copy == NULL) return BROWSER_ERR_OOM;
    bs->exceptions[bs->exceptions_len++] = copy;
    return BROWSER_OK;
}

#define _POSIX_C_SOURCE 200809L

#include "cached_fetch.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static hc_store *g_store;

/* FREEDOM_TRACE_FETCH=1: one line per cache decision (hit = no network). */

static void trace(const char *what, const char *url) {
    if (getenv("FREEDOM_TRACE_FETCH") != NULL) fprintf(stderr, "cache[%s] %s\n", what, url);
}

static int cacheable_request(const sf_config *cfg, const char *url) {
    if (strncmp(url, "https://", 8) != 0 || strlen(url) >= HC_URL_MAX) return 0;
    if (cfg->username != NULL && cfg->username[0] != '\0') return 0;
    if (cfg->range_start >= 0) return 0;
    return !cfg->allow_overlay_http;
}

static void copy_val(char *dst, size_t cap, const char *src) {
    size_t n = strlen(src);
    if (n >= cap) n = 0;                         /* too long: dropped, never truncated */
    memcpy(dst, src, n);
    dst[n] = '\0';
}

static void meta_from_response(hc_meta *m, const sf_response *r, const char *url, time_t now) {
    memset(m, 0, sizeof *m);
    copy_val(m->final_url, sizeof m->final_url, (r->final_url != NULL) ? r->final_url : url);
    if (r->content_type != NULL) copy_val(m->content_type, sizeof m->content_type, r->content_type);
    copy_val(m->etag, sizeof m->etag, r->etag);
    copy_val(m->last_modified, sizeof m->last_modified, r->last_modified);
    copy_val(m->cache_control, sizeof m->cache_control, r->cache_control);
    copy_val(m->expires, sizeof m->expires, r->expires);
    copy_val(m->date, sizeof m->date, r->date);
    m->stored = now;
}

/* Rebuilds a 200 response from a stored entry. Takes ownership of `body`. */

static int response_from_cache(sf_response *out, const hc_meta *m, uint8_t *body, size_t len) {
    memset(out, 0, sizeof *out);
    out->content_type = (m->content_type[0] != '\0') ? strdup(m->content_type) : NULL;
    out->final_url = strdup(m->final_url);
    out->tls_version = strdup("cache");
    if ((m->content_type[0] != '\0' && out->content_type == NULL) || out->final_url == NULL
        || out->tls_version == NULL) {
        free(out->content_type); free(out->final_url); free(out->tls_version);
        memset(out, 0, sizeof *out);
        free(body);
        return -1;
    }
    out->status = SF_OK;
    out->http_code = 200;
    out->body = body;
    out->body_len = len;
    copy_val(out->etag, sizeof out->etag, m->etag);
    copy_val(out->last_modified, sizeof out->last_modified, m->last_modified);
    copy_val(out->cache_control, sizeof out->cache_control, m->cache_control);
    copy_val(out->expires, sizeof out->expires, m->expires);
    copy_val(out->date, sizeof out->date, m->date);
    return 0;
}

static void remember(hc_store *store, const char *partition, const char *url,
                     const sf_response *r, time_t now) {
    hc_meta m;
    meta_from_response(&m, r, url, now);
    if (!hc_storable(r->http_code, &m, r->body_len)) return;
    (void)hc_put(store, partition, url, &m, r->body, r->body_len);
}

sf_status cf_get_with(hc_store *store, cf_fetch_fn fetch, const char *partition, const char *url,
                      sf_config *cfg, sf_response *out, int *downgraded, int allowlisted,
                      time_t now) {
    if (fetch == NULL || url == NULL || cfg == NULL || out == NULL) return SF_ERR_INTERNAL;
    if (store == NULL || partition == NULL || partition[0] == '\0' || !cacheable_request(cfg, url))
        return fetch(url, cfg, out, downgraded, allowlisted);

    hc_meta m;
    uint8_t *body = NULL;
    size_t blen = 0;
    if (hc_get(store, partition, url, &m, &body, &blen) == HC_OK) {
        hc_class cls = hc_classify(&m, now);
        if (cls == HC_FRESH) {
            trace("hit", url);
            if (response_from_cache(out, &m, body, blen) == 0) return SF_OK;
            return fetch(url, cfg, out, downgraded, allowlisted);
        }
        if (cls == HC_REVALIDATE) {
            /* Validate against the FINAL url that produced the body: a validator is a
             * fingerprint of that resource and must not travel to another origin. */
            sf_config cond = *cfg;
            cond.if_none_match = (m.etag[0] != '\0') ? m.etag : NULL;
            cond.if_modified_since = (m.last_modified[0] != '\0') ? m.last_modified : NULL;
            sf_status st = fetch(m.final_url, &cond, out, downgraded, allowlisted);
            trace((st == SF_OK && out->http_code == 304) ? "revalidated" : "changed", url);
            if (st == SF_OK && out->http_code == 304) {
                m.stored = now;
                if (out->cache_control[0] != '\0') copy_val(m

sf_status cf_get(const char *partition, const char *url, sf_config *cfg, sf_response *out,
                 int *downgraded, int allowlisted) {
    return cf_get_with(g_store, sf_get_follow_navigable, partition, url, cfg, out, downgraded,
                       allowlisted, time(NULL));
}

/* Redirect memory: the backing the secure fetcher consults on a RAM miss. */

static int redirect_load(void *ctx, const char *from, time_t now, char *out, size_t cap) {
    return hc_redirect_get((hc_store *)ctx, from, now, out, cap) == HC_OK;
}

static void redirect_save(void *ctx, const char *from, const char *to, time_t now) {
    (void)hc_redirect_put((hc_store *)ctx, from, to, now);
}

void cf_attach_redirect_memory(hc_store *store) {
    if (store == NULL) sf_rcache_set_backing(NULL, NULL, NULL);
    else sf_rcache_set_backing(redirect_load, redirect_save, store);
}

int cx_forms_stacking_context(const cx_style *s) {
    if (s == NULL) return 0;
    /* opacity < 1 (a set percentage below 100). */
    if (s->opacity >= 0 && s->opacity < 100) return 1;
    /* mix-blend-mode other than normal (any real blend). */
    if (s->mix_blend > CSS_MB_NORMAL) return 1;
    /* isolation: isolate. */
    if (s->isolation == CSS_ISO_ISOLATE) return 1;
    /* transform other than none (M1.2). */
    if (s->has_transform) return 1;
    /* relative/absolute WITH a real z-index. */
    if ((s->position == CSS_POS_RELATIVE || s->position == CSS_POS_ABSOLUTE)
        && !s->z_auto) return 1;
    /* fixed / sticky always establish a stacking context. */
    if (s->position == CSS_POS_FIXED || s->position == CSS_POS_STICKY) return 1;
    return 0;
}

cx_layer cx_box_layer(const cx_style *s) {
    if (s == NULL) return CX_LAYER_BLOCK;
    if (cx_forms_stacking_context(s)) {
        if (!s->z_auto && s->z_index < 0) return CX_LAYER_NEG_Z;
        if (!s->z_auto && s->z_index > 0) return CX_LAYER_POS_Z;
        return CX_LAYER_ZERO_Z; /* z-index 0 or auto */
    }
    /* Not a stacking context: a positioned box with z:auto still paints in the
     * positioned/zero layer (CSS 2.1 App E point 8). */
    if (is_positioned(s->position)) return CX_LAYER_ZERO_Z;
    if (s->is_float) return CX_LAYER_FLOAT;
    if (s->is_inline) return CX_LAYER_INLINE;
    return CX_LAYER_BLOCK;
}

/* Effective z used to order within a layer: auto collapses to 0 (the ZERO_Z layer). */

static int eff_z(const cx_item *it) {
    return it->z_auto ? 0 : it->z_index;
}

int cx_item_compare(const cx_item *a, const cx_item *b) {
    if (a == NULL || b == NULL) {
        if (a == b) return 0;
        return (a == NULL) ? -1 : 1; /* NULL sorts first, defensively */
    }
    if (a->layer != b->layer) return (a->layer < b->layer) ? -1 : 1;
    int za = eff_z(a), zb = eff_z(b);
    if (za != zb) return (za < zb) ? -1 : 1;
    if (a->doc_order != b->doc_order) return (a->doc_order < b->doc_order) ? -1 : 1;
    return 0;
}

/* Stable insertion sort: n is bounded by the caller (BT_MAX_POSITIONED), so O(n^2)
 * is fine, and stability keeps equal-key boxes in their original relative order
 * (document order is already the final tie-break, so this only matters on true
 * key collisions). No allocation. */

void cx_sort(cx_item *items, size_t n) {
    if (items == NULL || n < 2) return;
    for (size_t i = 1; i < n; ++i) {
        cx_item key = items[i];
        size_t j = i;
        /* Shift strictly-greater elements up; `>= 0` compare keeps equal keys stable
         * because we stop as soon as items[j-1] is not greater than key. */
        while (j > 0 && cx_item_compare(&items[j - 1], &key) > 0) {
            items[j] = items[j - 1];
            --j;
        }
        items[j] = key;
    }
}

