        dst[0].prop = P_ROW_GAP; dst[0].ival = ga;   /* one value = both axes (CSS Box Alignment 3 8.5) */
        dst[1].prop = P_GAP;     dst[1].ival = ga;
        return 2;
    }
    int gb = interp_gap(b);
    if (gb < 0 || cap < 2) return 0;
    dst[0].prop = P_ROW_GAP; dst[0].ival = ga;
    dst[1].prop = P_GAP;     dst[1].ival = gb;
    return 2;
}

/* place-items / place-content / place-self (2026-07-10): `<align> [<justify>]`,
 * the justify half defaulting to the align token. place-content's justify half
 * feeds justify-content (its own keyword set); place-self's feeds justify-self.

 * An uninterpretable token drops the whole shorthand (fail closed). */
static int expand_place(const char *prop, const char *val, css_decl *dst, int cap) {
    char a[CSS_TOK_MAX], b[CSS_TOK_MAX], extra[CSS_TOK_MAX];
    const char *p = val;
    if (!next_ws_token(&p, a, sizeof a)) return 0;
    int has_b = next_ws_token(&p, b, sizeof b);
    if (has_b && next_ws_token(&p, extra, sizeof extra)) return 0;

    if (strcmp(prop, "place-self") == 0) {
        int av = interp_align_kw(a, 1, 0);
        int jv = interp_align_kw(has_b ? b : a, 1, 0);
        if (av < 0 || jv < 0 || cap < 2) return 0;
        dst[0].prop = P_ALIGN_SELF;   dst[0].ival = av;
        dst[1].prop = P_JUSTIFY_SELF; dst[1].ival = jv;
        return 2;
    }
    if (strcmp(prop, "place-items") == 0) {
        int av = interp_align_kw(a, 0, 0);
        int jv = interp_align_kw(has_b ? b : a, 0, 0);
        if (av < 0 || jv < 0 || cap < 2) return 0;
        dst[0].prop = P_ALIGN_ITEMS;   dst[0].ival = av;
        dst[1].prop = P_JUSTIFY_ITEMS; dst[1].ival = jv;
        return 2;
    }
    int av = interp_align_kw(a, 0, 1);
    int jv = interp_justify(has_b ? b : a);
    if (av < 0 || jv < 0 || cap < 2) return 0;
    dst[0].prop = P_ALIGN_CONTENT; dst[0].ival = av;
    dst[1].prop = P_JUSTIFY;       dst[1].ival = jv;
    return 2;
}

/* clip: rect() / auto for positioned boxes (CSS 2.1 §11.1.2). Emits four
 * P_CLIP_TOP/RIGHT/BOTTOM/LEFT decls. auto → all CSS_LEN_UNSET (edge of
 * border-box). rect(t r b l) with commas or spaces → px values. Any parse

 * error drops the whole property (fail closed). */
static int expand_clip(const char *val, css_decl *dst, int cap) {
    if (cap < 4) return 0;
    const char *p = val;
    while (*p == ' ' || *p == '\t') ++p;
    if (p[0] == 'a' && p[1] == 'u' && p[2] == 't' && p[3] == 'o'
        && (p[4] == '\0' || p[4] == ' ' || p[4] == '\t' || p[4] == ';')) {
        for (int i = 0; i < 4; ++i)
            { dst[i].prop = P_CLIP_TOP + i; dst[i].ival = CSS_LEN_UNSET; }
        return 4;
    }
    if (!(p[0] == 'r' && p[1] == 'e' && p[2] == 'c' && p[3] == 't' && p[4] == '('))
        return 0;
    p += 5;  /* past "rect(" */
    int vals[4] = { CSS_LEN_UNSET, CSS_LEN_UNSET, CSS_LEN_UNSET, CSS_LEN_UNSET };
    for (int i = 0; i < 4; ++i) {
        while (*p == ' ' || *p == '\t') ++p;
        if (*p == ')') break;
        if (*p == ',') { ++p; while (*p == ' ' || *p == '\t') ++p; }
        if (*p == 'a' && *(p + 1) == 'u' && *(p + 2) == 't' && *(p + 3) == 'o') {
            p += 4; vals[i] = CSS_LEN_UNSET; continue;
        }
        double d = 0.0; int neg = (*p == '-') ? (++p, 1) : 0;
        const char *e = p; int has_digit = 0;
        while (*e >= '0' && *e <= '9') { d = d * 10.0 + (double)(*e - '0'); ++e; has_digit = 1; }
        if (*e == '.') { double f = 0.1; ++e;
            while (*e >= '0' && *e <= '9') { d += (double)(*e - '0') * f; f *= 0.1; ++e; has_digit = 1; } }
        if (!has_digit) return 0;
        if (neg) d = -d;
        vals[i] = (int)(d + (d < 0 ? -0.5 : 0.5));
        while ((*e >= 'a' && *e <= 'z') || (*e >= 'A' && *e <= 'Z') || *e == '%' || *e == '-') ++e;

static int expand_clip_path(const char *val, css_decl *dst, int cap) {
    const char *v = val;
    while (*v == ' ') ++v;
    int px[4], pm[4];
    if (strncmp(v, "inset(", 6) == 0 && cb_clip_inset(v, px, pm) && cap >= 9) {
        dst[0].prop = P_ISOLATION; dst[0].ival = CSS_ISO_ISOLATE;
        for (int i = 0; i < 4; ++i) {
            dst[1 + i].prop = P_CLIP_TOP + i;    dst[1 + i].ival = px[i];
            dst[5 + i].prop = P_CLIP_TOP_PM + i; dst[5 + i].ival = pm[i];
        }
        return 9;
    }
    if (strncmp(v, "inset(", 6) == 0 || strncmp(v, "circle(", 7) == 0 ||
        strncmp(v, "ellipse(", 8) == 0 || strncmp(v, "polygon(", 8) == 0 ||
        strncmp(v, "path(", 5) == 0 || strncmp(v, "url(", 4) == 0) {
        if (cap < 1) return 0;
        dst[0].prop = P_ISOLATION; dst[0].ival = CSS_ISO_ISOLATE;
        return 1;
    }
    if (strncmp(v, "none", 4) == 0 && cap >= 5) {
        dst[0].prop = P_ISOLATION; dst[0].ival = 0;
        for (int i = 0; i < 4; ++i) { dst[1 + i].prop = P_CLIP_TOP + i; dst[1 + i].ival = CSS_LEN_UNSET; }
        return 5;
    }
    if (strncmp(v, "rect(", 5) == 0 && cap >= 1) {
        dst[0].prop = P_ISOLATION; dst[0].ival = 0;
        return 1;
    }
    return 0;
}

/* First family name of a font-family/font value: up to the first comma,
 * trimmed, quotes stripped -- the same entry walk ct_interp_fontfamily
 * (css_text.c) uses, so the name and the bucket agree about which entry is
 * first. Returns 1 with the name in out (truncated to WF_FAMILY_MAX, the same
 * cap the trusted scanner applies, so both sides hash the same bytes), 0

static void font_list_alias(const css_sheet *sheet, const char *ls, char *out, size_t cap) {
    size_t n = 0;
    out[0] = '\0';
    while (*ls != '\0') {
        size_t fl = strcspn(ls, ",");
        const char *nm = ls;
        size_t nl = fl;
        for (size_t fi = 0; sheet != NULL && fi < sheet->nfont_faces; ++fi) {
            const char *fam = sheet->font_faces[fi].family;
            if (sheet->font_faces[fi].local_name[0] == '\0' ||
                sheet->font_faces[fi].src_url[0] != '\0' || strlen(fam) != fl)
                continue;
            size_t q = 0;
            while (q < fl && csel_lower_ch(fam[q]) == csel_lower_ch(ls[q])) ++q;
            if (q == fl) {
                nm = sheet->font_faces[fi].local_name;
                nl = strlen(nm);
                break;
            }
        }
        /* A local() name is marked '=': it matches a face by exact full name,
         * never a family alias (CSS Fonts 4 4.3; text_shape resolves it). */
        int exact = (nm != ls);
        if (n + (n > 0) + (size_t)exact + nl + 1 > cap) break;
        if (n > 0) out[n++] = ',';
        if (exact) out[n++] = '=';
        memcpy(out + n, nm, nl);
        n += nl;
        out[n] = '\0';
        ls += fl;
        if (*ls == ',') ++ls;
    }
}

static int font_list_norm(const char *val, char *out, size_t cap) {
    if (cap == 0) return 0;
    out[0] = '\0';
    if (csel_substr(val, "url(", 1)) return 0;
    size_t w = 0;
    const char *p = val;
    while (*p != '\0') {
        while (*p == ' ' || *p == '\t' || *p == ',') ++p;
        if (*p == '\0') break;
        const char *st = p;
        while (*p != '\0' && *p != ',') ++p;
        size_t e = (size_t)(p - st);
        while (e > 0 && (st[e - 1] == ' ' || st[e - 1] == '\t')) --e;
        size_t a = 0;
        if (e >= 2 && (st[0] == '"' || st[0] == '\'') && st[e - 1] == st[0]) {
            a = 1;
            --e;
        }
        char name[CSS_FONT_LIST_MAX];
        size_t n = 0;
        int sp = 0;
        for (size_t k = a; k < e && n + 1 < sizeof name; ++k) {
            char c = st[k];
            if (c == ' ' || c == '\t') { sp = 1; continue; }
            if (sp && n > 0) name[n++] = ' ';
            sp = 0;
            if (n + 1 < sizeof name) name[n++] = csel_lower_ch(c);
        }
        if (n == 0) continue;
        size_t need = n + (w > 0 ? 1 : 0);
        if (w + need + 1 > cap) break;
        if (w > 0) out[w++] = ',';
        memcpy(out + w, name, n);
        w += n;
        out[w] = '\0';
    }
    return w > 0;
}

/* font-family longhand: the bucket (today's behaviour, byte-identical) plus a

 * Wide keywords claim BOTH slots without writing (inheritance then flows, as
 * the tail does for single-slot properties). */
static int expand_fontfamily(const char *val, css_decl *dst, int cap,
                             char (*contenttab)[CSS_URL_MAX], size_t *ncontent,
                             size_t contentcap) {
    if (cap < 1) return 0;
    if (css_wide_keyword(val)) {
        if (cap < 2) return 0;
        dst[0].prop = P_FONTFAMILY; dst[0].wide = 1;
        dst[1].prop = P_FONTFACE; dst[1].wide = 1;
        return 2;
    }
    int fam = interp_fontfamily(val);
    char name[CSS_FONT_LIST_MAX];
    int have_name = font_list_norm(val, name, sizeof name);
    if (fam < 0 && !have_name) return 0;
    int n = 0;
    if (fam >= 0) { dst[n].prop = P_FONTFAMILY; dst[n].ival = fam; ++n; }
    if (have_name && n < cap) {
        /* Pool full degrades to explicit none (ival -1 -> fontface 0 at
         * apply), exactly like a quoted content string past the cap: a
         * conforming declaration must not count as a discard just because an
         * icon font ate the pool (spec/webfont.md, slice2a doctrine). */
        if (*ncontent >= contentcap) {
            dst[n].prop = P_FONTFACE; dst[n].ival = -1;
            ++n;
            return n;
        }
        size_t nl = strlen(name);
        memcpy(contenttab[*ncontent], name, nl + 1);
        dst[n].prop = P_FONTFACE; dst[n].ival = (int)*ncontent;
        ++*ncontent;
        ++n;
    }
    return n;
}

