static size_t cb_copy_trim(const char *s, size_t a, size_t b, char *dst, size_t cap)
{
    size_t n;
    if (s == NULL || dst == NULL || cap == 0 || a >= b) {
        return (size_t)-1;
    }
    while (a < b && (s[a] == ' ' || s[a] == '\t')) {
        ++a;
    }
    while (b > a && (s[b - 1] == ' ' || s[b - 1] == '\t')) {
        --b;
    }
    n = b - a;
    if (n + 1 > cap) {
        return (size_t)-1;
    }
    memcpy(dst, s + a, n);
    dst[n] = '\0';
    return n;
