    if (cc_scan_number(b, e - 1, &num) != 0) return -1;
    if (num < 0.0 || num > (double)CC_PERCENT_MAX) return -1;
    *out = (int)cc_round(num * (double)CC_HSL_SCALE / (double)CC_PERCENT_MAX);
