static int parse_func(const char *s, cc_rgb *out) {
    int is_hsl = 0;
    const char *p;
    if (strncmp(s, "rgba(", 5) == 0) p = s + 5;
    else if (strncmp(s, "rgb(", 4) == 0) p = s + 4;
    else if (strncmp(s, "hsla(", 5) == 0) { p = s + 5; is_hsl = 1; }
    else if (strncmp(s, "hsl(", 4) == 0) { p = s + 4; is_hsl = 1; }
    else return -1;

    const char *close = strchr(p, ')');
    if (close == NULL) return -1;
    for (const char *q = close + 1; *q != '\0'; ++q) {
        if (*q != ' ') return -1; /* only trailing spaces after ')' */
    }

    const char *bs[4];
    const char *es[4];
    const char *ab = NULL, *ae = NULL;
    int comma = 0;
    int nc = cc_split_args(p, close, bs, es, &ab, &ae, &comma);
    if (nc < 0) return -1;

    int comps[3] = { 0, 0, 0 };
    if (is_hsl) {
        /* Legacy comma form keeps its 4th-component alpha (`hsla(h,s,l,a)`);
         * the space form carries it after the slash instead -- a 4th bare
         * space token is not an alpha (CSS Color 4 requires the slash). */
        if (nc < 3 || nc > 4) return -1;
        if (ab != NULL && nc != 3) return -1;
        if (ab == NULL && nc == 4 && !comma) return -1;
        for (int i = 0; i < 3; ++i)
            if (parse_hsl_comp(bs[i], es[i], i == 0, &comps[i]) != 0) return -1;
        int zero_a = 0;
        if (ab != NULL) {
            if (parse_component(ab, ae, 1, &zero_a) != 0) return -1;
        } else if (nc == 4) {
            if (parse_component(bs[3], es[3], 1, &zero_a) != 0) return -1;
        }
        hsl_to_rgb(comps[0], comps[1], comps[2], &out->r, &out->g, &out->b)

#define CC_PI 3.14159265358979323846

/* One component: a <number>, a <percentage> (scaled so 100% == pct_ref), `none`
 * (0), or -- when is_hue -- an <angle> in deg/grad/rad/turn, returned in degrees. */

static int lab_comp(const char *b, const char *e, double pct_ref, int is_hue, double *out) {
    while (b < e && *b == ' ') ++b;
    while (e > b && e[-1] == ' ') --e;
    if (b == e) return -1;
    if (e - b == 4 && memcmp(b, "none", 4) == 0) { *out = 0.0; return 0; }
    if (e[-1] == '%') {
        double v;
        if (cc_scan_number(b, e - 1, &v) != 0) return -1;
        if (is_hue) return -1;
        *out = v / 100.0 * pct_ref;
        return 0;
    }
    if (is_hue) {
        static const struct { const char *u; double to_deg; } U[] = {
            { "grad", 0.9 }, { "turn", 360.0 }, { "deg", 1.0 }, { "rad", 180.0 / CC_PI } };
        for (size_t k = 0; k < sizeof U / sizeof U[0]; ++k) {
            size_t n = strlen(U[k].u);
            if ((size_t)(e - b) > n && memcmp(e - n, U[k].u, n) == 0) {
                double v;
                if (cc_scan_number(b, e - n, &v) != 0) return -1;
                *out = v * U[k].to_deg;
                return 0;
            }
        }
    }
    return cc_scan_number(b, e, out);
}

static unsigned char srgb_encode(double lin) {
    double v = (lin <= 0.0031308) ? 12.92 * lin : 1.055 * pow(lin, 1.0 / 2.4) - 0.055;
    if (!(v > 0.0)) v = 0.0;          /* also catches NaN */
    if (v > 1.0) v = 1.0;
    return (unsigned char)cc_round(v * 255.0);
}

static int parse_lab_family(const char *s, cc_rgb *out) {
    int ok = 0, polar = 0;
    const char *p;
    if (strncmp(s, "oklab(", 6) == 0)      { p = s + 6; ok = 1; }
    else if (strncmp(s, "oklch(", 6) == 0) { p = s + 6; ok = 1; polar = 1; }
    else if (strncmp(s, "lab(", 4) == 0)   { p = s + 4; }
    else if (strncmp(s, "lch(", 4) == 0)   { p = s + 4; polar = 1; }
    else return -1;
    const char *close = strchr(p, ')');
    if (close == NULL) return -1;
    for (const char *q = close + 1; *q != '\0'; ++q) if (*q != ' ') return -1;
    const char *bs[4], *es[4], *ab = NULL, *ae = NULL;
    int comma = 0;
    int nc = cc_split_args(p, close, bs, es, &ab, &ae, &comma);
    if (nc != 3 || comma) return -1;
    int zero_a = 0;
    if (ab != NULL && parse_component(ab, ae, 1, &zero_a) != 0) return -1;
    if (zero_a) { out->r = 0; out->g = 0; out->b = 0; return 1; }   /* transparent */
    /* Percentage references (CSS Color 4 sections 8.1, 8.2, 9.2, 9.3). */
    double L, c1, c2;
    double l_ref = ok ? 1.0 : 100.0;
    double ab_ref = ok ? 0.4 : 125.0;
    double c_ref = ok ? 0.4 : 150.0;
    if (lab_comp(bs[0], es[0], l_ref, 0, &L) != 0) return -1;
    if (lab_comp(bs[1], es[1], polar ? c_ref : ab_ref, 0, &c1) != 0) return -1;
    if (lab_comp(bs[2], es[2], ab_ref, polar, &c2) != 0) return -1;
    if (L < 0.0) L = 0.0;
    if (L > l_ref) L = l_ref;
    if (polar) {
        double C = (c1 < 0.0) ? 0.0 : c1, h = c2 * CC_PI / 180.0;
        c1 = C * cos(h);
        c2 = C * sin(h);
    }
    if (ok) oklab_to_rgb(L, c1, c2, out);
    else    lab_to_rgb(L, c1, c2, out);

static int named_cmp(const void *key, const void *element) {
    const char *k = (const char *)key;
    const cc_named *n = (const cc_named *)element;
    return strcmp(k, n->name);
}

static int parse_named(const char *s, cc_rgb *out) {
    const cc_named *hit = (const cc_named *)bsearch(
        s, CC_NAMES, sizeof CC_NAMES / sizeof CC_NAMES[0], sizeof CC_NAMES[0], named_cmp);
    if (hit == NULL) return -1;
    out->r = hit->r;
    out->g = hit->g;
    out->b = hit->b;
    return 0;
}

cc_status cc_parse(const char *token, cc_rgb *out) {
    if (token == NULL || out == NULL) return CC_ERR_NULL_ARG;

    char buf[CC_TOKEN_MAX];
    if (normalize(token, buf) != 0) return CC_ERR_SYNTAX;

    cc_rgb tmp;
    int rc;
    if (buf[0] == '#') {
        rc = parse_hex(buf + 1, &tmp);
    } else if (strncmp(buf, "rgb", 3) == 0) {
        rc = parse_func(buf, &tmp);
    } else if (strncmp(buf, "hsl", 3) == 0) {
        rc = parse_func(buf, &tmp);
    } else if (strncmp(buf, "lab(", 4) == 0 || strncmp(buf, "lch(", 4) == 0 ||

               strncmp(buf, "oklab(", 6) == 0 || strncmp(buf, "oklch(", 6) == 0) {
        rc = parse_lab_family(buf, &tmp);
    } else if (strcmp(buf, "transparent") == 0) {
        tmp.r = 0; tmp.g = 0; tmp.b = 0;
        *out = tmp;
        return CC_TRANSPARENT;
    } else if (strcmp(buf, "currentcolor") == 0) {
        tmp.r = 0; tmp.g = 0; tmp.b = 0;
        *out = tmp;
        return CC_CURRENT_COLOR;
    } else {
        rc = parse_named(buf, &tmp);
    }
    /* 1 = parsed, but with a zero alpha: that colour IS `transparent`. */
    if (rc == 1) {
        tmp.r = 0; tmp.g = 0; tmp.b = 0;
        *out = tmp;
        return CC_TRANSPARENT;
    }
    if (rc != 0) return CC_ERR_SYNTAX;

    *out = tmp;
    return CC_OK;
}

int cc_pack(cc_rgb c) {
    return ((int)c.r << 16) | ((int)c.g << 8) | (int)c.b;
}

cc_rgb cc_unpack(int packed) {
    cc_rgb c;
    c.r = (unsigned char)((packed >> 16) & 0xff);
    c.g = (unsigned char)((packed >> 8) & 0xff);
    c.b = (unsigned char)(packed & 0xff);
    return c;
}

static size_t put(char *out, size_t cap, const char *s) {
    size_t n = strlen(s);
    if (n + 1 > cap) return 0;
    memcpy(out, s, n + 1);
    return n;
}

static size_t putf(char *out, size_t cap, const char *fmt, ...) __attribute__((format(printf, 3, 4)));

static size_t putf(char *out, size_t cap, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int r = vsnprintf(out, cap, fmt, ap);
    va_end(ap);
    if (r < 0 || (size_t)r >= cap) { out[0] = '\0'; return 0; }
    return (size_t)r;
}

static size_t put_rgb(char *out, size_t cap, int rgb, int alpha_pct) {
    int r = (rgb >> 16) & 0xff, g = (rgb >> 8) & 0xff, b = rgb & 0xff;
    if (alpha_pct >= 0 && alpha_pct < 100) {
        if (alpha_pct == 0) return putf(out, cap, "rgba(%d, %d, %d, 0)", r, g, b);
        if (alpha_pct % 10 == 0) return putf(out, cap, "rgba(%d, %d, %d, %d.%d)", r, g, b,
                                             alpha_pct / 100, alpha_pct / 10 % 10);
        return putf(out, cap, "rgba(%d, %d, %d, 0.%02d)", r, g, b, alpha_pct);
    }
    return putf(out, cap, "rgb(%d, %d, %d)", r, g, b);
}

static size_t put_len(char *out, size_t cap, int v, const char *unset_text) {
    if (v == CSS_LEN_UNSET || v == CSS_LEN_AUTO) return put(out, cap, unset_text);
    return putf(out, cap, "%dpx", v);
}

static size_t put_enum(char *out, size_t cap, int v, const char *const *names, size_t n,
                       const char *fallback) {
    return put(out, cap, (v > 0 && (size_t)v < n && names[v] != NULL) ? names[v] : fallback);
}

/* The HTML Rendering UA sheet's `display` for a tag when the cascade declared none
 * (the engine keeps block-ness of plain tags in its own tables, not in the sheet). */

static const char *ua_display(const char *tag) {
    static const char *const none[] = { "head", "link", "meta", "script", "style", "title",
        "template", "area", "base", "datalist", "noembed", "noframes", "param", "rp" };
    static const char *const block[] = { "html", "body", "address", "article", "aside",
        "blockquote", "center", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset",
        "figcaption", "figure", "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6", "header",
        "hgroup", "hr", "legend", "listing", "main", "menu", "nav", "ol", "p", "pre", "search",
        "section", "summary", "ul", "xmp", "optgroup" };
    static const char *const iblock[] = { "button", "input", "select", "textarea", "meter",
        "progress" };
    if (tag == NULL) return "inline";
    for (size_t i = 0; i < sizeof none / sizeof *none; ++i)
        if (strcmp(tag, none[i]) == 0) return "none";
    for (size_t i = 0; i < sizeof block / sizeof *block; ++i)
        if (strcmp(tag, block[i]) == 0) return "block";
    for (size_t i = 0; i < sizeof iblock / sizeof *iblock; ++i)
        if (strcmp(tag, iblock[i]) == 0) return "inline-block";
    if (strcmp(tag, "li") == 0) return "list-item";
    if (strcmp(tag, "table") == 0) return "table";
    if (strcmp(tag, "thead") == 0 || strcmp(tag, "tbody") == 0 || strcmp(tag, "tfoot") == 0)
        return "table-row-group";
    if (strcmp(tag, "tr") == 0) return "table-row";
    if (strcmp(tag, "td") == 0 || strcmp(tag, "th") == 0) return "table-cell";
    if (strcmp(tag, "caption") == 0) return "table-caption";

static size_t f_display(const ccm_input *in, char *out, size_t cap) {
    switch (in->st->display) {
    case CSS_DISP_NONE:            return put(out, cap, "none");
    case CSS_DISP_BLOCK:           return put(out, cap, "block");
    case CSS_DISP_INLINE_BLOCK:    return put(out, cap, "inline-block");
    case CSS_DISP_LIST_ITEM:       return put(out, cap, "list-item");
    case CSS_DISP_FLEX:            return put(out, cap, "flex");
    case CSS_DISP_GRID:            return put(out, cap, "grid");
    case CSS_DISP_TABLE:           return put(out, cap, "table");
    case CSS_DISP_TABLE_ROW_GROUP: return put(out, cap, "table-row-group");
    case CSS_DISP_TABLE_ROW:       return put(out, cap, "table-row");
    case CSS_DISP_TABLE_CELL:      return put(out, cap, "table-cell");
    case CSS_DISP_TABLE_CAPTION:   return put(out, cap, "table-caption");
    case CSS_DISP_TABLE_COLUMN:    return put(out, cap, "table-column");
    default:                       return put(out, cap, ua_display(in->tag));
    }
}

