            return (int)(((a % 360) + 360) % 360);
        return -2;   /* rad/grad/turn/junk angles: unsupported */
    }
    if (!(csel_lower_ch(p[0]) == 't' && csel_lower_ch(p[1]) == 'o' &&
          (p[2] == ' ' || p[2] == '\t')))
