                rad_ieq(tok[0], "at") || rad_ieq(tok[0], "closest-side") ||
                rad_ieq(tok[0], "farthest-side") || rad_ieq(tok[0], "closest-corner") ||
                rad_ieq(tok[0], "farthest-corner");
