    if (s == NULL || env == NULL) return 0;
    size_t i = 0;
    int any = 0;
    while (i <= len) {
        size_t seg = i;
        int d = 0;
        while (i < len && !(s[i] == ',' && d == 0)) {
            if (s[i] == '(') ++d;
            else if (s[i] == ')') --d;
