size_t csel_decl_end(const char *s, size_t i, size_t b, int stop_brace) {
    int depth = 0;
    char q = 0;
    for (; i < b; ++i) {
        char c = s[i];
        if (c == '\\' && i + 1 < b) { ++i; continue; }
        if (q) { if (c == q) q = 0; continue; }
        if (c == '"' || c == '\'') q = c;
        else if (c == '(') ++depth;
        else if (c == ')') { if (depth > 0) --depth; }
