    if (stored == NULL || tok == NULL) return 0;
    if (tlen < CSS_TOK_MAX) return strlen(stored) == tlen && memcmp(stored, tok, tlen) == 0;
    char f[CSS_TOK_MAX];
    csel_ident_fold(tok, tlen, f);
    return strcmp(stored, f) == 0;
}

