        if (i + 4 <= vlen && csel_lower_ch(val[i]) == 'v' && csel_lower_ch(val[i + 1]) == 'a' &&
            csel_lower_ch(val[i + 2]) == 'r' && val[i + 3] == '(') {
            size_t j = i + 4, argstart = j;
            int pdepth = 1;
            while (j < vlen) {
                if (val[j] == '(') ++pdepth;
                else if (val[j] == ')' && --pdepth == 0) break;
                ++j;
            }
            if (pdepth != 0) return 0;               /* unbalanced var(...) */
            size_t argend = j;
            /* First TOP-LEVEL comma splits name from fallback. */
            size_t comma = argend;
            int cd = 0;
            for (size_t k = argstart; k < argend; ++k) {
                if (val[k] == '(') ++cd;
                else if (val[k] == ')') --cd;
                else if (val[k] == ',' && cd == 0) { comma = k; break; }
            }
            size_t na = argstart, nb = comma;
            while (na < nb && is_ws(val[na])) ++na;
            while (nb > na && is_ws(val[nb - 1])) --nb;
            if (nb - na < 3 || val[na] != '-' || val[na + 1] != '-') return 0;
            if (depth >= CVR_MAX_DEPTH || --*budget < 0) return 0;
            /* A name that is absent, or present but itself unresolvable (a cycle,
             * CSS Variables 1 section 2.3), is guaranteed-invalid: the reference
             * takes its fallback. The partial expansi

int cvr_resolve(const char *val, char *out, size_t outcap, const cvr_scope *sc) {
    if (val == NULL || out == NULL || outcap == 0) return 0;
    size_t o = 0;
    int budget = CVR_MAX_LOOKUPS;
    if (!resolve_rec(val, strlen(val), out, outcap, &o, sc, 0, &budget)) return 0;
    out[o] = '\0';
    return 1;
}

const char *cvr_lookup(const cvr_scope *sc, const char *name, size_t nlen) {
    return (name == NULL) ? NULL : scope_get(sc, name, nlen);
}

static int lower(char c) {
    return (c >= 'A' && c <= 'Z') ? c + ('a' - 'A') : c;
}

static int ci_starts_with(const char *s, const char *prefix) {
    while (*prefix) {
        if (*s == '\0' || lower((unsigned char)*s) != lower((unsigned char)*prefix)) return 0;
        ++s; ++prefix;
    }
    return 1;
}

int du_is_data_url(const char *url) {
    return url != NULL && ci_starts_with(url, "data:");
}

du_status du_base64_payload(const char *url, const char **payload, size_t *payload_len) {
    if (url == NULL || payload == NULL || payload_len == NULL) return DU_ERR_NULL_ARG;
    if (!du_is_data_url(url)) return DU_ERR_NOT_DATA_URL;

    const char *p = url + 5; /* skip "data:" */
    const char *comma = strchr(p, ',');
    if (comma == NULL) return DU_ERR_NOT_BASE64;

    static const char TAG[] = ";base64";
    size_t taglen = sizeof(TAG) - 1;
    size_t header_len = (size_t)(comma - p);
    if (header_len < taglen) return DU_ERR_NOT_BASE64;

    const char *flag = comma - taglen;
    for (size_t i = 0; i < taglen; ++i) {
        if (lower((unsigned char)flag[i]) != TAG[i]) return DU_ERR_NOT_BASE64;
    }

    const char *data = comma + 1;
    size_t data_len = strlen(data);
    if (data_len > DU_MAX_ENCODED_LEN) return DU_ERR_TOO_LARGE;

    *payload = data;
    *payload_len = data_len;
    return DU_OK;
}

/* 0-63 for a base64 alphabet character, -1 otherwise. Kept as a small function
 * (not a 256-entry table) so the mapping stays trivially auditable. */

static int b64_val(unsigned char c) {
    if (c >= 'A' && c <= 'Z') return (int)(c - 'A');
    if (c >= 'a' && c <= 'z') return (int)(c - 'a') + 26;
    if (c >= '0' && c <= '9') return (int)(c - '0') + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

