    char mt[96];
    media_type(content_type, mt, sizeof mt);
    if (mt[0] == '\0') return "";

    static const struct { const char *type; const char *ext; } MAP[] = {
        { "application/pdf",       ".pdf"  },
        { "application/zip",       ".zip"  },
        { "application/epub+zip",  ".epub" },
        { "application/gzip",      ".gz"   },
        { "application/x-tar",     ".tar"  },
        { "application/json",      ".json" },
        { "text/html",             ".html" },
