        { "image/jpeg",            ".jpg"  },
        { "image/gif",             ".gif"  },
        { "image/svg+xml",         ".svg"  },
    };
    for (size_t i = 0; i < sizeof MAP / sizeof MAP[0]; ++i) {
        if (strcmp(mt, MAP[i].type) == 0) return MAP[i].ext;
    }
    return "";
}

/* Copies [src, end) into buf, bounded and NUL-terminated. */

static void copy_span(const char *src, const char *end, char *buf, size_t bufsz) {
    if (bufsz == 0) return;
    size_t n = 0;
    for (const char *p = src; p < end && n + 1 < bufsz; ++p) buf[n++] = *p;
    buf[n] = '\0';
}

/* Extracts a filename candidate from a Content-Disposition value into buf.
 * Handles filename="...", filename=..., and RFC 5987 filename*=charset''value
 * (the part after the second quote; not percent-decoded). Returns 1 if a
 * non-empty candidate was written. */

static int extract_disposition_name(const char *cd, char *buf, size_t bufsz) {
    if (bufsz == 0) return 0;
    buf[0] = '\0';
    const char *p = ci_find(cd, "filename");
    if (p == NULL) return 0;
    p += 8; /* strlen("filename") */

    int ext_form = 0;
    if (*p == '*') { ext_form = 1; ++p; }
    while (*p == ' ' || *p == '\t') ++p;
    if (*p != '=') return 0;
    ++p;
    while (*p == ' ' || *p == '\t') ++p;

    if (ext_form) {
        const char *q1 = strchr(p, '\'');
        if (q1 != NULL) {
            const char *q2 = strchr(q1 + 1, '\'');
            if (q2 != NULL) p = q2 + 1;
        }
        const char *end = p;
        while (*end != '\0' && *end != ';' && *end != ' ' && *end != '\t') ++end;
        copy_span(p, end, buf, bufsz);
    } else if (*p == '"') {
        ++p;
        const char *end = strchr(p, '"');
        if (end == NULL) end = p + strlen(p);
        copy_span(p, end, buf, bufsz);
    } else {
        const char *end = p;
        while (*end != '\0' && *end != ';' && *end != ' ' && *end != '\t') ++end;
        copy_span(p, end, buf, bufsz);
    }
    return buf[0] != '\0';
}

/* Extracts the last path segment of url (without ?query or #fragment) into buf.
 * Returns 1 if a non-empty candidate was written. */

static int extract_url_name(const char *url, char *buf, size_t bufsz) {
    if (bufsz == 0) return 0;
    buf[0] = '\0';
    if (url == NULL) return 0;
    const char *end = url;
    while (*end != '\0' && *end != '?' && *end != '#') ++end;
    const char *seg = end;
    while (seg > url && seg[-1] != '/') --seg;
    copy_span(seg, end, buf, bufsz);
    return buf[0] != '\0';
}

/* Does name already carry an extension (a '.' past the first byte with at least
 * one character after it)? */

static int has_extension(const char *name) {
    const char *dot = strrchr(name, '.');
    return dot != NULL && dot != name && dot[1] != '\0';
}

dl_status dl_pick_name(const char *url, const char *content_disposition,
                       const char *content_type, char *out, size_t outsz) {
    if (out == NULL || outsz == 0) return DL_ERR_NULL_ARG;
    out[0] = '\0';

    char cand[512];
    cand[0] = '\0';
    if (!(content_disposition != NULL && extract_disposition_name(content_disposition, cand, sizeof cand))) {
        if (!extract_url_name(url, cand, sizeof cand)) cand[0] = '\0';
    }

    /* If the candidate has no alphanumeric byte, it would sanitize to nothing;
     * use the controlled fallback instead of pe_safe_basename's generic one. */
    int has_alnum = 0;
    for (const char *p = cand; *p != '\0'; ++p) {
        if (isalnum((unsigned char)*p)) { has_alnum = 1; break; }
    }
    if (!has_alnum) {
        size_t fl = strlen(DL_FALLBACK_NAME);
        memcpy(cand, DL_FALLBACK_NAME, fl + 1);
    }

    char name[DL_NAME_MAX + 1];
    if (pe_safe_basename(cand, name, sizeof name) != PE_OK || name[0] == '\0') {
        size_t fl = strlen(DL_FALLBACK_NAME);
        memcpy(name, DL_FALLBACK_NAME, fl + 1);
    }

    if (!has_extension(name)) {
        const char *ext = dl_ext_for_type(content_type);
        if (ext[0] != '\0') {
            size_t l = strlen(name), e = strlen(ext);
            if (l + e < sizeof name) memcpy(name + l, ext, e + 1);
        }
    }

    size_t need = strlen(name) + 1;
    if (need > outsz) { out[0] = '\0'; return DL_ERR_OVERFLOW; }
    memcpy(out, name, need);
    return DL_OK;

dl_status dl_build_path(const char *dir, const char *name, char *out, size_t outsz) {
    if (dir == NULL || name == NULL || out == NULL || outsz == 0) return DL_ERR_NULL_ARG;
    out[0] = '\0';
    if (strchr(name, '/') != NULL) return DL_ERR_OVERFLOW; /* never escape dir */

    size_t dl = strlen(dir);
    int need_sep = (dl > 0 && dir[dl - 1] != '/');
    size_t need = dl + (need_sep ? 1u : 0u) + strlen(name) + 1u;
    if (need > outsz) { out[0] = '\0'; return DL_ERR_OVERFLOW; }

    memcpy(out, dir, dl);
    size_t pos = dl;
    if (need_sep) out[pos++] = '/';
    size_t nl = strlen(name);
    memcpy(out + pos, name, nl + 1);
    return DL_OK;
}

dl_status dl_check_size(size_t len) {
    return (len <= DL_MAX_BYTES) ? DL_OK : DL_ERR_TOO_LARGE;
}

static int ieq(const char *a, const char *b) {
    for (; *a != '\0' && *b != '\0'; ++a, ++b) {
        char ca = (*a >= 'A' && *a <= 'Z') ? (char)(*a + ('a' - 'A')) : *a;
        char cb = (*b >= 'A' && *b <= 'Z') ? (char)(*b + ('a' - 'A')) : *b;
        if (ca != cb) return 0;
    }
    return *a == '\0' && *b == '\0';
}

int fbp_tab_from_name(const char *name) {
    if (name == NULL) return -1;
    for (int t = 0; t < FBP_COUNT; ++t)
        if (ieq(name, TAB_LABEL[t])) return t;
    return -1;
}

int fbp_tab_wrap(int tab, int dir) {
    if (!tab_ok(tab)) tab = FBP_CONSOLE;
    int step = (dir > 0) ? 1 : (dir < 0) ? FBP_COUNT - 1 : 0;
    return (tab + step) % FBP_COUNT;
}

void fbp_tab_span(int tab, double cell_w, double pad_cells, double *x, double *w) {
    if (!tab_ok(tab)) tab = FBP_CONSOLE;
    double edge = 0.0;
    for (int t = 0; t < tab; ++t)
        edge += cell_w * ((double)strlen(TAB_LABEL[t]) + 2.0 * pad_cells);
    if (x != NULL) *x = edge;
    if (w != NULL) *w = cell_w * ((double)strlen(TAB_LABEL[tab]) + 2.0 * pad_cells);
}

int fbp_tab_at(double px, double cell_w, double pad_cells) {
    if (!(cell_w > 0.0) || px < 0.0) return -1;
    for (int t = 0; t < FBP_COUNT; ++t) {
        double x, w;
        fbp_tab_span(t, cell_w, pad_cells, &x, &w);
        if (px >= x && px < x + w) return t;
    }
    return -1;
}

size_t fbp_js_quote(const char *s, size_t n, char *out, size_t cap) {
    if (out == NULL || cap == 0 || (s == NULL && n > 0) || n > FBP_SELECTOR_MAX) return 0;
    size_t o = 0;
    if (o + 1 >= cap) return 0;
    out[o++] = '"';
    for (size_t i = 0; i < n; ++i) {
        unsigned char c = (unsigned char)s[i];
        if (c == '\0') return 0;
        char esc[8];
        size_t el;
        if (c == '"' || c == '\\') { esc[0] = '\\'; esc[1] = (char)c; el = 2; }
        else if (c == '\n') { esc[0] = '\\'; esc[1] = 'n'; el = 2; }
        else if (c == '\r') { esc[0] = '\\'; esc[1] = 'r'; el = 2; }
        else if (c == '\t') { esc[0] = '\\'; esc[1] = 't'; el = 2; }
        else if (c < 0x20 || c == 0x7f) {
            int r = snprintf(esc, sizeof esc, "\\u%04x", (unsigned)c);
            if (r < 0 || (size_t)r >= sizeof esc) return 0;
            el = (size_t)r;
        } else { esc[0] = (char)c; el = 1; }
        if (o + el + 2 > cap) return 0;       /* room for the closing quote and the NUL */
        memcpy(out + o, esc, el);
        o += el;
    }
    if (o + 2 > cap) return 0;
    out[o++] = '"';
    out[o] = '\0';
    return o;
}

size_t fbp_expr(int tab, const char *sel, size_t n, char *out, size_t cap) {
    if (out == NULL || !fbp_is_pane(tab) || (sel == NULL && n > 0)) return 0;
    char q[2 * FBP_SELECTOR_MAX * 3 + 8];
    size_t ql = fbp_js_quote(sel, n, q, sizeof q);
    if (ql == 0) return 0;
    static const char HEAD[] = "(function(q){";
    static const char MID[] = "})(";
    const char *body = JS_BODY[tab];
    size_t need = (sizeof HEAD - 1) + strlen(body) + (sizeof MID - 1) + ql + 1 /* ')' */ + 1 /* NUL */;
    if (need > cap) return 0;
    size_t o = 0;
    memcpy(out + o, HEAD, sizeof HEAD - 1); o += sizeof HEAD - 1;
    size_t bl = strlen(body);
    memcpy(out + o, body, bl); o += bl;
    memcpy(out + o, MID, sizeof MID - 1); o += sizeof MID - 1;
    memcpy(out + o, q, ql); o += ql;
    out[o++] = ')';
    out[o] = '\0';
    return o;
}

static double nn(double v) {
