static void print_dom(const rd_doc *doc) {
    size_t need = dd_format(doc, NULL, 0);
    if (need == (size_t)-1) { fprintf(stderr, "freedom: error measuring render tree\n"); return; }
    char *buf = (char *)malloc(need + 1);
