size_t hls_select_variant(const hls_playlist *pl, int max_w, int max_h) {
    if (pl == NULL || pl->nvariants == 0) return (size_t)-1;

    size_t best = 0;
    long best_bw = 0;
    int best_fits = 0;

    for (size_t i = 0; i < pl->nvariants; ++i) {
        int fits = 1;
        if (max_w > 0 && pl->variants[i].width > max_w) fits = 0;
        if (max_h > 0 && pl->variants[i].height > max_h) fits = 0;

        if (fits && !best_fits) { best = i; best_bw = pl->variants[i].bandwidth; best_fits = 1; }
        else if (fits == best_fits && pl->variants[i].bandwidth > best_bw) {
            best = i; best_bw = pl->variants[i].bandwidth;
        }
    }

    return best;
}

size_t hls_resolve_url(const char *base_url, const char *segment_url,
                       char *resolved, size_t resolved_sz) {
    if (base_url == NULL || segment_url == NULL || resolved == NULL
        || resolved_sz == 0) return 0;

    if (strncmp(segment_url, "http://", 7) == 0
        || strncmp(segment_url, "https://", 8) == 0) {
        size_t slen = strlen(segment_url);
        if (slen < resolved_sz) {
            memcpy(resolved, segment_url, slen + 1);
            return slen;
        }
        return 0;
    }

    size_t blen = strlen(base_url);
    const char *last_slash = last_char(base_url, blen, '/');
    if (last_slash == NULL) return 0;

    size_t base_part = (size_t)(last_slash - base_url) + 1;
    size_t slen = strlen(segment_url);

    if (base_part + slen < resolved_sz) {
        memcpy(resolved, base_url, base_part);
        memcpy(resolved + base_part, segment_url, slen + 1);
        return base_part + slen;
    }
    return 0;
}

void hls_playlist_free(hls_playlist *pl) {
    if (pl == NULL) return;
    for (size_t i = 0; i < pl->count; ++i)
        free(pl->segments[i].url);
    free(pl->segments);
    for (size_t i = 0; i < pl->nvariants; ++i)
        free(pl->variants[i].url);
    free(pl->variants);
    free(pl);
}

static void add_dir(hcf_dirs *out, const char *path) {
    if (path == NULL || path[0] == '\0' || out->n >= HCF_MAX_DIRS) return;
    size_t len = strlen(path);
    if (len >= HCF_PATH_MAX) return;
    for (size_t i = 0; i < out->n; ++i)
        if (strcmp(out->path[i], path) == 0) return;
    memcpy(out->path[out->n], path, len + 1);
    ++out->n;
}

void hcf_search_dirs(const char *env, const char *home, hcf_dirs *out) {
    if (out == NULL) return;
    out->n = 0;
    add_dir(out, env);
    if (home != NULL && home[0] != '\0') {
        char user[HCF_PATH_MAX];
        int n = snprintf(user, sizeof user, "%s" HCF_USER_SUBDIR, home);
        if (n > 0 && (size_t)n < sizeof user) add_dir(out, user);
    }
    add_dir(out, HCF_REPO_DIR);
}

void hcf_search_dirs_from_env(hcf_dirs *out) {
    hcf_search_dirs(getenv("FREEDOM_HOSTS_DIR"), getenv("HOME"), out);
}

/* Reads dir/name whole, or NULL when it is absent, unreadable or over the cap. */

static char *read_conf(const char *dir, const char *name) {
    char path[HCF_PATH_MAX * 2];
    int n = snprintf(path, sizeof path, "%s/%s", dir, name);
    if (n <= 0 || (size_t)n >= sizeof path) return NULL;
    FILE *f = fopen(path, "rb");
    if (f == NULL) return NULL;
    char *buf = NULL;
    if (fseek(f, 0, SEEK_END) == 0) {
        long sz = ftell(f);
        if (sz >= 0 && (unsigned long)sz <= HCF_MAX_FILE_BYTES && fseek(f, 0, SEEK_SET) == 0) {
            buf = (char *)malloc((size_t)sz + 1);
            if (buf != NULL) {
                size_t got = fread(buf, 1, (size_t)sz, f);
                buf[got] = '\0';
            }
        }
    }
    fclose(f);
    return buf;
}

static void load_into(hb_set *s, const char *dir, const char *name, hb_list list) {
    char *txt = read_conf(dir, name);
    if (txt == NULL) return;
    hb_load(s, txt, list);   /* HB_ERR_OOM only drops extra entries; not fatal */
    free(txt);
}

hb_set *hcf_load_filter(const hcf_dirs *dirs) {
    if (dirs == NULL) return NULL;
    hb_set *s = hb_new();
    if (s == NULL) return NULL;
    for (size_t i = 0; i < dirs->n; ++i) {
        load_into(s, dirs->path[i], "block.conf", HB_LIST_BLOCK);
        load_into(s, dirs->path[i], "allow.conf", HB_LIST_ALLOW);
    }
    return s;
}

hb_set *hcf_load_allowlist(const hcf_dirs *dirs, const char *fname) {
    if (dirs == NULL || fname == NULL) return NULL;
    hb_set *s = hb_new();
    if (s == NULL) return NULL;
    for (size_t i = 0; i < dirs->n; ++i) load_into(s, dirs->path[i], fname, HB_LIST_ALLOW);
    return s;
}

typedef struct hb_table {
    char  **slots;  /* NULL = empty slot; otherwise an owned NUL-terminated domain */
    size_t  cap;    /* slot count, a power of two, or 0 if unallocated */
    size_t  count;  /* number of occupied slots */
} hb_table;

struct hb_set {
    hb_table block;
    hb_table allow;
};


/* Finds the slot for key (length klen) in t, which must have a free slot. Returns
 * the index of either the matching entry or the first empty slot for it. */

static size_t table_probe(const hb_table *t, const char *key, size_t klen) {
    size_t mask = t->cap - 1;
    size_t i = (size_t)fnv1a(key, klen) & mask;
    while (t->slots[i] != NULL) {
        if (strlen(t->slots[i]) == klen && memcmp(t->slots[i], key, klen) == 0) break;
        i = (i + 1) & mask;
    }
    return i;
}

/* Grows (or first-allocates) t to newcap slots and rehashes. Returns 0, -1 OOM. */

static int table_grow(hb_table *t, size_t newcap) {
    char **ns = (char **)calloc(newcap, sizeof *ns);
    if (ns == NULL) return -1;

    char **old = t->slots;
    size_t oldcap = t->cap;
    t->slots = ns;
    t->cap = newcap;

    size_t mask = newcap - 1;
    for (size_t k = 0; k < oldcap; ++k) {
        if (old[k] == NULL) continue;
        size_t i = (size_t)fnv1a(old[k], strlen(old[k])) & mask;
        while (t->slots[i] != NULL) i = (i + 1) & mask;
        t->slots[i] = old[k];   /* move the existing owned string */
    }
    free(old);
    return 0;
}

/* Inserts key (length klen) into t, deduping. Returns 0 (inserted or already
 * present), -1 on OOM. */

static int table_insert(hb_table *t, const char *key, size_t klen) {
    /* Keep the load factor under 0.7 so probing stays cheap and terminates. */
    if (t->cap == 0) {
        if (table_grow(t, HB_INIT_CAP) != 0) return -1;
    } else if ((t->count + 1) * 10u >= t->cap * 7u) {
        if (table_grow(t, t->cap * 2u) != 0) return -1;
    }

    size_t i = table_probe(t, key, klen);
    if (t->slots[i] != NULL) return 0;   /* already present */

    if (klen == (size_t)-1) return -1;
    char *copy = (char *)malloc(klen + 1);
    if (copy == NULL) return -1;
    memcpy(copy, key, klen);
    copy[klen] = '\0';
    t->slots[i] = copy;
    t->count++;
    return 0;
}

static int table_contains(const hb_table *t, const char *key) {
    if (t->cap == 0) return 0;
    size_t i = table_probe(t, key, strlen(key));
    return t->slots[i] != NULL;
}

static void table_free(hb_table *t) {
    if (t->slots == NULL) return;
    for (size_t i = 0; i < t->cap; ++i) free(t->slots[i]);
    free(t->slots);
    t->slots = NULL; t->cap = 0; t->count = 0;
}

/* --- token helpers --- */

static char lower(char c) {
    return (c >= 'A' && c <= 'Z') ? (char)(c + ('a' - 'A')) : c;
}

/* A token made only of digits, '.' and ':' is an IP literal (v4 or v6), not a
 * domain. An empty token never reaches here. */

static int is_ip_token(const char *s, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        char c = s[i];
        if (!((c >= '0' && c <= '9') || c == '.' || c == ':')) return 0;
    }
    return 1;
}

/* True if c may appear in a domain we accept (after lowercasing). */

static int is_domain_char(char c) {
    return (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
        || c == '.' || c == '-' || c == '_';
}

/* Normalises a raw token into out (lowercased, one trailing dot trimmed) and
 * validates it (1..253 chars, domain charset). Returns the length, or 0 if the
 * token is not a domain we accept (caller skips it). */
static size_t normalise_domain(const char *tok, size_t n, char *out, size_t out_size) {
    if (n == 0 || n + 1 > out_size) return 0;
    for (size_t i = 0; i < n; ++i) out[i] = lower(tok[i]);
    out[n] = '\0';
    if (out[n - 1] == '.') { --n; out[n] = '\0'; }  /* trim one trailing dot */
    if (n == 0 || n > HB_MAX_HOST) return 0;
    for (size_t i = 0; i < n; ++i) {
        if (!is_domain_char(out[i])) return 0;
    }
    return n;
}

/* --- public --- */

hb_set *hb_new(void) {
    hb_set *s = (hb_set *)calloc(1, sizeof *s);
    return s;  /* both tables zeroed: slots NULL, cap 0, count 0 */
}

void hb_free(hb_set *s) {
    if (s == NULL) return;
    table_free(&s->block);
    table_free(&s->allow);
    free(s);
}

hb_status hb_load(hb_set *s, const char *text, hb_list list) {
    if (s == NULL || text == NULL) return HB_ERR_NULL_ARG;
    hb_table *t = (list == HB_LIST_ALLOW) ? &s->allow : &s->block;

    const char *p = text;
    char buf[HB_MAX_HOST + 2];
    while (*p != '\0') {
        /* One line: stop at '\n' or end; '#' starts a comment to end of line. */
        const char *line = p;
        while (*p != '\0' && *p != '\n') ++p;
        const char *line_end = p;
        if (*p == '\n') ++p;

        for (const char *q = line; q < line_end; ++q) {
            if (*q == '#') { line_end = q; break; }
        }

        /* Tokenise the line on ASCII whitespace. */
        const char *q = line;
        while (q < line_end) {
            while (q < line_end && (*q == ' ' || *q == '\t' || *q == '\r' ||
                                    *q == '\f' || *q == '\v')) ++q;
            const char *ts = q;
            while (q < line_end && !(*q == ' ' || *q == '\t' || *q == '\r' ||
                                     *q == '\f' || *q == '\v')) ++q;
            size_t tl = (size_t)(q - ts);
            if (tl == 0) continue;
            if (is_ip_token(ts, tl)) continue;

            size_t dl = normalise_domain(ts, tl, buf, sizeof buf);
            if (dl == 0) continue;  /* invalid token: skip, do not abort */
            if (table_insert(t, buf, dl) != 0) return HB_ERR_OOM;
        }
    }
    return HB_OK;
}

hb_decision hb_check(const hb_set *s, const char *host) {
    if (s == NULL || host == NULL) return HB_ALLOW;
    size_t n = strlen(host);
    if (n == 0 || n > HB_MAX_HOST) return HB_ALLOW;

    char buf[HB_MAX_HOST + 1];
    for (size_t i = 0; i < n; ++i) buf[i] = lower(host[i]);
    buf[n] = '\0';
    if (buf[n - 1] == '.') { --n; buf[n] = '\0'; }
    if (n == 0) return HB_ALLOW;

    /* Walk the domain suffixes from most to least specific. The allowlist wins, so
     * a match there short-circuits to ALLOW even if a broader suffix is blocked; a
     * block match is remembered but the scan continues in case a broader suffix is
     * allowlisted. */
    int blocked = 0;
    for (const char *suffix = buf; suffix != NULL; ) {
        if (table_contains(&s->allow, suffix)) return HB_ALLOW;
        if (!blocked && table_contains(&s->block, suffix)) blocked = 1;
        const char *dot = strchr(suffix, '.');
        suffix = (dot != NULL) ? dot + 1 : NULL;
    }
    return blocked ? HB_BLOCK : HB_ALLOW;
}

int hb_is_allowlisted(const hb_set *s, const char *host) {
    if (s == NULL || host == NULL) return 0;
    size_t n = strlen(host);
    if (n == 0 || n > HB_MAX_HOST) return 0;

    char buf[HB_MAX_HOST + 1];
    for (size_t i = 0; i < n; ++i) buf[i] = lower(host[i]);
    buf[n] = '\0';
    if (buf[n - 1] == '.') { --n; buf[n] = '\0'; }
    if (n == 0) return 0;

    /* Same suffix walk as hb_check's allowlist arm: an entry covers subdomains. */
    for (const char *suffix = buf; suffix != NULL; ) {
        if (table_contains(&s->allow, suffix)) return 1;
        const char *dot = strchr(suffix, '.');
        suffix = (dot != NULL) ? dot + 1 : NULL;
    }
    return 0;
}

size_t hb_count(const hb_set *s, hb_list list) {
    if (s == NULL) return 0;
    return (list == HB_LIST_ALLOW) ? s->allow.count : s->block.count;
}

static char he_lower(char c) {
    return (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c;
}

static int is_label_char(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
           (c >= '0' && c <= '9') || c == '-';
}

/* True if host is a plausible registrable hostname (see he_make_line contract). */

static int valid_host(const char *host, size_t n) {
    if (n == 0 || n > HE_MAX_HOST) return 0;
    if (host[0] == '.' || host[n - 1] == '.') return 0;  /* no empty edge label */
    size_t label = 0;
    for (size_t i = 0; i < n; ++i) {
        char c = host[i];
        if (c == '.') {
            if (label == 0) return 0;                    /* "a..b" / leading dot */
            label = 0;
            continue;
        }
        if (!is_label_char(c)) return 0;                 /* rejects / : @ ? # ws ctrl */
        if (c == '-' && (label == 0 || i + 1 == n || host[i + 1] == '.'))
            return 0;                                    /* label may not edge on '-' */
        if (++label > 63) return 0;                      /* DNS label limit */
    }
    return 1;
}

he_status he_make_line(const char *host, char *out, size_t cap) {
    if (host == NULL || out == NULL) return HE_ERR_NULL_ARG;
    size_t n = strlen(host);
    if (!valid_host(host, n)) return HE_ERR_INVALID_HOST;
    if (cap < n + 2) return HE_ERR_RANGE;                /* host + '\n' + '\0' */
    for (size_t i = 0; i < n; ++i) out[i] = he_lower(host[i]);
    out[n] = '\n';
    out[n + 1] = '\0';
    return HE_OK;
}

/* Case-insensitive compare of a token [ts,te) against host (NUL-terminated), with a
 * single trailing dot on the token ignored (a FQDN root). */
static int token_eq_host(const char *ts, const char *te, const char *host) {
    size_t tl = (size_t)(te - ts);
    if (tl > 0 && ts[tl - 1] == '.') --tl;               /* ignore one root dot */
    size_t i = 0;
    for (; i < tl; ++i) {
        if (host[i] == '\0') return 0;
        if (he_lower(ts[i]) != he_lower(host[i])) return 0;
    }
    return host[i] == '\0';
}

/* True if the token looks like an IPv4 dotted-quad / contains only digits and dots
 * (matches hostblock's is_ip_token spirit: such a leading token is the ignored IP). */

static int is_ip_token(const char *ts, const char *te) {
    int saw_digit = 0;
    for (const char *q = ts; q < te; ++q) {
        if (*q == '.') continue;
        if (*q < '0' || *q > '9') return 0;
        saw_digit = 1;
    }
    return saw_digit;
}

/* Visits each domain token (non-comment, non-IP) of a hosts-format text in document
 * order, calling fn(ts, tl, ctx). If fn returns nonzero, iteration stops and he_scan
 * returns 1; otherwise 0. Single source of the line/token tokenisation. */

static int he_scan(const char *text, int (*fn)(const char *, size_t, void *), void *ctx) {
    const char *p = text;
    while (*p != '\0') {
        const char *line = p;
        while (*p != '\0' && *p != '\n') ++p;
        const char *end = p;
        if (*p == '\n') ++p;
        for (const char *q = line; q < end; ++q)
            if (*q == '#') { end = q; break; }           /* strip comment */

        const char *q = line;
        while (q < end) {
            while (q < end && (*q == ' ' || *q == '\t' || *q == '\r' ||
                               *q == '\f' || *q == '\v')) ++q;
            const char *ts = q;
            while (q < end && !(*q == ' ' || *q == '\t' || *q == '\r' ||
                                *q == '\f' || *q == '\v')) ++q;
            if (q == ts) continue;
            if (is_ip_token(ts, q)) continue;            /* ignore the "0.0.0.0" field */
            if (fn(ts, (size_t)(q - ts), ctx)) return 1;
        }
    }
    return 0;
}

static int has_host_cb(const char *ts, size_t tl, void *ctx) {
    return token_eq_host(ts, ts + tl, (const char *)ctx);
}

int he_text_has_host(const char *text, const char *host) {
    if (text == NULL || host == NULL || host[0] == '\0') return 0;
    return he_scan(text, has_host_cb, (void *)host);
}

/* Lowercase substring search: 1 if needle (lowercased) occurs in [hs,he). */

static int contains_ci(const char *hs, size_t hl, const char *needle) {
    size_t nl = strlen(needle);
    if (nl == 0) return 1;
    if (nl > hl) return 0;
    for (size_t i = 0; i + nl <= hl; ++i) {
        size_t k = 0;
        for (; k < nl; ++k)
            if (he_lower(hs[i + k]) != he_lower(needle[k])) break;
        if (k == nl) return 1;
    }
    return 0;
}

static int starts_with_ci(const char *hs, size_t hl, const char *pfx) {
    size_t pl = strlen(pfx);
    if (pl > hl) return 0;
    for (size_t k = 0; k < pl; ++k)
        if (he_lower(hs[k]) != he_lower(pfx[k])) return 0;
    return 1;
}

struct suggest_ctx {
    const char *query;
    int prefix_only;                       /* pass 1 collects prefix matches only */
    char (*results)[HE_MAX_HOST + 1];
    int max;
    int n;
};

static int suggest_cb(const char *ts, size_t tl, void *vctx) {
    struct suggest_ctx *c = (struct suggest_ctx *)vctx;
    if (tl == 0 || tl > HE_MAX_HOST) return 0;           /* skip unstorable hosts */
    if (c->prefix_only) {
        if (!starts_with_ci(ts, tl, c->query)) return 0;
    } else {
        if (!contains_ci(ts, tl, c->query)) return 0;
        if (starts_with_ci(ts, tl, c->query)) return 0;  /* already taken in pass 1 */
    }
    for (int i = 0; i < c->n; ++i) {                     /* dedup (case-insensitive) */
        size_t j = 0;
        for (; j < tl && c->results[i][j] != '\0'; ++j)
            if (he_lower(c->results[i][j]) != he_lower(ts[j])) break;
        if (j == tl && c->results[i][j] == '\0') return 0;
    }
    for (size_t k = 0; k < tl; ++k) c->results[c->n][k] = he_lower(ts[k]);
    c->results[c->n][tl] = '\0';
    return (++c->n >= c->max);                            /* stop when full */
}

int he_suggest(const char *text, const char *query,
               char results[][HE_MAX_HOST + 1], int max) {
    if (text == NULL || query == NULL || results == NULL || max <= 0) return 0;
    struct suggest_ctx c = { query, 1, results, max, 0 };
    he_scan(text, suggest_cb, &c);       /* pass 1: prefix matches */
    if (c.n < max) { c.prefix_only = 0; he_scan(text, suggest_cb, &c); }  /* pass 2 */
    return c.n;
}

#define _POSIX_C_SOURCE 200809L

#include "html_parse.h"
#include "util.h"

#include <stdlib.h>
#include <string.h>

#include <lexbor/html/html.h>
#include <lexbor/dom/dom.h>
#include <lexbor/tag/const.h>

struct hp_document {
    lxb_html_document_t *doc;
};

/* --- helpers --- */

static char *dup_bytes(const lxb_char_t *src, size_t len) {
    if (len == (size_t)-1) return NULL; /* guard: len+1 would overflow to 0 */
    char *out = (char *)malloc(len + 1);
    if (out == NULL) return NULL;
    if (len != 0 && src != NULL) memcpy(out, src, len);
    out[len] = '\0';
    return out;
}

/* Iterative pre-order successor of node within the subtree rooted at root. */

static lxb_dom_node_t *node_next(lxb_dom_node_t *node, const lxb_dom_node_t *root) {
    if (node->first_child != NULL) return node->first_child;
    while (node != root && node->next == NULL) {
        if (node->parent == NULL) return NULL;
        node = node->parent;
    }
    if (node == root) return NULL;
    return node->next;
}

static int attr_is_event_handler(const lxb_dom_attr_t *attr) {
    size_t len = 0;
    const lxb_char_t *name = lxb_dom_attr_qualified_name(attr, &len);
    if (name == NULL || len < 3) return 0; /* "on" + at least one char */
    return (name[0] == 'o' || name[0] == 'O') && (name[1] == 'n' || name[1] == 'N');
}

static int node_is_script(const lxb_dom_node_t *node) {
    if (node->type != LXB_DOM_NODE_TYPE_ELEMENT) return 0;
    lxb_dom_element_t *el = lxb_dom_interface_element((lxb_dom_node_t *)node);
    return lxb_dom_element_tag_id(el) == LXB_TAG_SCRIPT;
}

static void strip_scripts(lxb_html_document_t *document) {
    lxb_dom_node_t *root = lxb_dom_interface_node(document);
    lxb_dom_node_t **list = NULL;
    size_t count = 0, cap = 0;

    for (lxb_dom_node_t *n = root; n != NULL; n = node_next(n, root)) {
        if (!node_is_script(n)) continue;
        if (count == cap) {
            size_t ncap = cap ? cap * 2 : 16;
            lxb_dom_node_t **grown = (lxb_dom_node_t **)realloc(list, ncap * sizeof *grown);
            if (grown == NULL) break; /* best effort; strip what we have */
            list = grown;
            cap = ncap;
        }
        list[count++] = n;
    }

    for (size_t i = 0; i < count; ++i) {
        lxb_dom_node_remove(list[i]);
        lxb_dom_node_destroy_deep(list[i]);
    }
    free(list);
}

/* How one <script> element executes. */
enum { SCRIPT_SKIP = 0, SCRIPT_INLINE = 1, SCRIPT_EXTERNAL = 2 };

/* Classifies a <script>: a classic program runs only when its type is absent/empty
 * or a JavaScript MIME type (contains "javascript"/"ecmascript"). Every other type
 * is a data block the browser never executes -- JSON/LD data, ES modules
 * (import/export cannot run as a classic script), and template blocks like
 * text/x-jquery-tmpl / text/html / text/template (executing their markup throws a
 * SyntaxError; this was Slashdot's "#each" errors). Fail closed: unrecognized type
 * -> skip. A src attribute makes it external (its inline body, if any, is ignored --
 * browser rule); otherwise it runs from its inline source. The parser never
 * fetches: external scripts are only REPORTED with their r

static int type_is(const lxb_char_t *t, size_t len, const char *word) {
    while (len > 0 && (t[0] == ' ' || t[0] == '\t' || t[0] == '\n' || t[0] == '\r' || t[0] == '\f')) {
        ++t; --len;
    }
    while (len > 0 && (t[len - 1] == ' ' || t[len - 1] == '\t' || t[len - 1] == '\n'
                       || t[len - 1] == '\r' || t[len - 1] == '\f'))
        --len;
    size_t wl = strlen(word);
    if (len != wl) return 0;
    for (size_t i = 0; i < len; ++i) {
        char c = (char)t[i];
        if (c >= 'A' && c <= 'Z') c = (char)(c + ('a' - 'A'));
        if (c != word[i]) return 0;
    }
    return 1;
}

static int type_is_module(const lxb_char_t *t, size_t len) {
    return type_is(t, len, "module");
}

static int script_classify(const lxb_dom_node_t *n,
                           const lxb_char_t **src, size_t *src_len, int *is_module,
                           int *is_importmap) {
    lxb_dom_element_t *el = lxb_dom_interface_element((lxb_dom_node_t *)n);
    size_t len = 0;
    *is_module = 0;
    *is_importmap = 0;
    const lxb_char_t *type =
        lxb_dom_element_get_attribute(el, (const lxb_char_t *)"type", 4, &len);
    if (type != NULL && len > 0 && type_is(type, len, "importmap")) {
        /* An import map is inline JSON only: an external one does not exist in HTML. */
        size_t sl = 0;
        if (lxb_dom_element_get_attribute(el, (const lxb_char_t *)"src", 3, &sl) != NULL)
            return SCRIPT_SKIP;
        *is_importmap = 1;
        return SCRIPT_INLINE;
    }
    if (type != NULL && len > 0 && type_is_module(type, len)) {
        *is_module = 1;
    } else if (type != NULL && len > 0
        && !mem_contains_ci(type, len, "javascript")
        && !mem_contains_ci(type, len, "ecmascript")) {
        return SCRIPT_SKIP;
    }
    size_t slen = 0;
    const lxb_char_t *s =
        lxb_dom_element_get_attribute(el, (const lxb_char_t *)"src", 3, &slen);
    if (s != NULL) {
        if (slen == 0) return SCRIPT_SKIP; /* src="" names no resource */
        *src = s;
        *src_len = slen;
        return SCRIPT_EXTERNAL;
    }
    return SCRIPT_INLINE;
}

