        char num[24];
        memcpy(num, p, (size_t)(nl - p));
        num[nl - p] = '\0';
        char *ep = NULL;
        long long st = strtoll(num, &ep, 10);
        if (ep == num || *ep != '\0') goto bad;
        m->stored = (time_t)st;
        p = nl +

static hc_status get_locked(hc_store *s, const char *partition, const char *url, hc_meta *meta,
                            uint8_t **body, size_t *body_len) {
    if (s == NULL || partition == NULL || url == NULL || meta == NULL || body == NULL
        || body_len == NULL) return HC_ERR_ARG;
    *body = NULL; *body_len = 0;
    char path[1300];
    if (entry_path(s, 'c', partition, url, path, sizeof path) != 0) return HC_ERR_ARG;
    return load_entry(s, path, meta, body, body_len);
}

/* Drops the oldest files until the directory fits HC_MAX_TOTAL (90 % target). */

    typedef struct { time_t mt; size_t sz; char name[80]; } ent;
    size_t cap = 256, n = 0, total = 0;
    ent *v = (ent *)malloc(cap * sizeof *v);
    if (v == NULL) return;
    DIR *d = opendir(s->dir);
    struct dirent *e;
    while (d != NULL && (e = readdir(d)) != NULL) {
        if (e->d_name[0] == '.' || strcmp(e->d_name, HC_KEY_FILE) == 0 || strlen(e->d_name) >= 80) continue;
        char p[1300];
        struct stat st;
        if (snprintf(p, sizeof p, "%s/%s", s->dir, e->d_name) >= (int)sizeof p || stat(p, &st) != 0
            || !S_ISREG(st.st_mode)) continue;
        if (n == cap) {
            if (cap > ((size_t)-1) / 2 / sizeof *v) break;
            ent *nv = (ent *)realloc(v, cap * 2 * sizeof *v);
            if (nv == NULL) break;
            v = nv; cap *= 2;
        }
        v[n].mt = st.st_mtime; v[n].sz = (size_t)st.st_size;
        memcpy(v[n].name, e->d_name, strlen(e->d_name) + 1);
        total += v[n].sz; ++n;
    }
    if (d != NULL) closedir(d);
    if (total > HC_MAX_TOTAL) {
        size_t target = HC_MAX_TOTAL / 10 * 9;
        while (total > target && n > 0) {
            size_t oldest = 0;
            for (size_t i = 1; i < n; ++i) if (v[i].mt < v[oldest].mt) oldest = i;
            char p[1300];
            if (snprintf(p, sizeof p, "%s/%s", s->dir, v[oldest].name) < (int)sizeof p) (void)unlink(p);
            total -= v[oldest].sz;
            v[oldest] = v[--n];
        }
    }
    free(v);
}

static hc_status put_locked(hc_store *s, const char *partition, const char *url, const hc_meta *meta,
                            const uint8_t *body, size_t body_len) {
    if (s == NULL || partition == NULL || url == NULL || meta == NULL || (body == NULL && body_len != 0))
        return HC_ERR_ARG;
    if (!meta_ok(meta) || has_nl(partition) || has_nl(url)) return HC_ERR_ARG;
    char path[1300];
    if (entry_path(s, 'c', partition, url, path, sizeof path) != 0) return HC_ERR_ARG;
    hc_status rc = store_entry(s, path, meta, body, body_len);
    if (rc == HC_OK && (++s->puts % HC_EVICT_EVERY) == 0) evict(s);
    return rc;
}

static hc_status redirect_put_locked(hc_store *s, const char *from, const char *to, time_t now) {
    if (s == NULL || from == NULL || to == NULL) return HC_ERR_ARG;
    if (strncmp(to, "https://", 8) != 0 || strcmp(from, to) == 0 || has_nl(from) || has_nl(to)
        || strlen(to) >= HC_URL_MAX) return HC_ERR_ARG;
    hc_meta m;
    memset(&m, 0, sizeof m);
    memcpy(m.final_url, to, strlen(to) + 1);
    m.stored = now;
    char path[1300];
    if (entry_path(s, 'r', "", from, path, sizeof path) != 0) return HC_ERR_ARG;
    return store_entry(s, path, &m, NULL, 0);
}

static hc_status redirect_get_locked(hc_store *s, const char *from, time_t now, char *out, size_t cap) {
    if (s == NULL || from == NULL || out == NULL || cap == 0) return HC_ERR_ARG;
    char path[1300];
    if (entry_path(s, 'r', "", from, path, sizeof path) != 0) return HC_ERR_ARG;
    hc_meta m;
    hc_status rc = load_entry(s, path, &m, NULL, NULL);
    if (rc != HC_OK) return rc;
    if (now < m.stored || now - m.stored > HC_REDIRECT_TTL) { (void)unlink(path); return HC_MISS; }
    size_t l = strlen(m.final_url);
    if (l >= cap || strncmp(m.final_url, "https://", 8) != 0) return HC_MISS;
    memcpy(out, m.final_url, l + 1);
    return HC_OK;
}

void hc_clear(hc_store *s) {
    if (s == NULL) return;
    pthread_mutex_lock(&s->lock);
    remove_entries(s->dir);
    pthread_mutex_unlock(&s->lock);
}

hc_status hc_get(hc_store *s, const char *partition, const char *url, hc_meta *meta,
                 uint8_t **body, size_t *body_len) {
    if (s == NULL) return HC_ERR_ARG;
    pthread_mutex_lock(&s->lock);
    hc_status r = get_locked(s, partition, url, meta, body, body_len);
    pthread_mutex_unlock(&s->lock);
    return r;
}

hc_status hc_put(hc_store *s, const char *partition, const char *url, const hc_meta *meta,
                 const uint8_t *body, size_t body_len) {
    if (s == NULL) return HC_ERR_ARG;
    pthread_mutex_lock(&s->lock);
    hc_status r = put_locked(s, partition, url, meta, body, body_len);
    pthread_mutex_unlock(&s->lock);
    return r;
}

hc_status hc_redirect_put(hc_store *s, const char *from, const char *to, time_t now) {
    if (s == NULL) return HC_ERR_ARG;
    pthread_mutex_lock(&s->lock);
    hc_status r = redirect_put_locked(s, from, to, now);
    pthread_mutex_unlock(&s->lock);
    return r;
}

hc_status hc_redirect_get(hc_store *s, const char *from, time_t now, char *out, size_t cap) {
    if (s == NULL) return HC_ERR_ARG;
    pthread_mutex_lock(&s->lock);
    hc_status r = redirect_get_locked(s, from, now, out, cap);
    pthread_mutex_unlock(&s->lock);
    return r;
}

#define _GNU_SOURCE
#include "identity.h"

#include <math.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "anti_fp.h"

void idn_defaults(idn_config *c) {
    if (c == NULL) return;
    memset(c, 0, sizeof *c);
    c->geo_mode = IDN_GEO_OFF;
}

int idn_is_default(const idn_config *c) {
    if (c == NULL) return 1;
    return c->user_agent[0] == '\0' && c->languages[0] == '\0' && c->geo_mode == IDN_GEO_OFF;
}

int idn_set_user_agent(idn_config *c, const char *ua) {
    if (c == NULL || ua == NULL) return -1;
    size_t n = strlen(ua);
    if (n >= IDN_UA_MAX) return -1;
    int printable = 0;
    for (size_t i = 0; i < n; ++i) {
        unsigned char ch = (unsigned char)ua[i];
        if (ch < 0x20 || ch > 0x7e) return -1;   /* controls (header injection) and non-ASCII */
        if (ch != ' ') printable = 1;
    }
    if (n != 0 && !printable) return -1;
    memcpy(c->user_agent, ua, n + 1);
    return 0;
}

/* Validates one language tag [s, s+n): aa|aaa then (-[alnum]{2,8})*. */

static int tag_valid(const char *s, size_t n) {
    size_t i = 0;
    while (i < n && is_alpha(s[i])) ++i;
    if (i < 2 || i > 3) return 0;
    while (i < n) {
        if (s[i] != '-') return 0;
        size_t j = ++i;
        while (i < n && is_alnum(s[i])) ++i;
        if (i - j < 2 || i - j > 8) return 0;
    }
    return 1;
}

int idn_set_languages(idn_config *c, const char *list) {
    if (c == NULL || list == NULL) return -1;
    char norm[IDN_LANG_MAX];
    size_t out = 0;
    unsigned tags = 0;
    const char *p = list;
    while (*p == ' ') ++p;
    if (*p == '\0') { c->languages[0] = '\0'; return 0; }
    for (;;) {
        const char *start = p;
        while (*p != '\0' && *p != ',') ++p;
        const char *end = p;
        while (end > start && end[-1] == ' ') --end;
        size_t n = (size_t)(end - start);
        if (!tag_valid(start, n) || ++tags > IDN_LANG_TAGS_MAX) return -1;
        if (out + n + 2 > sizeof norm) return -1;
        if (out != 0) norm[out++] = ',';
        memcpy(norm + out, start, n);
        out += n;
        if (*p == '\0') break;
        ++p;                                  /* skip ',' */
        while (*p == ' ') ++p;
    }
    norm[out] = '\0';
    memcpy(c->languages, norm, out + 1);
    return 0;
}

int idn_set_geo(idn_config *c, double lat, double lon, double accuracy_m) {
    if (c == NULL) return -1;
    if (!isfinite(lat) || !isfinite(lon) || !isfinite(accuracy_m)) return -1;
    if (lat < -90.0 || lat > 90.0 || lon < -180.0 || lon > 180.0) return -1;
    if (accuracy_m < IDN_GEO_ACC_MIN || accuracy_m > IDN_GEO_ACC_MAX) return -1;
    c->geo_mode = IDN_GEO_FIXED;
    c->geo_lat = lat;
    c->geo_lon = lon;
    c->geo_accuracy_m = accuracy_m;
    return 0;
}

void idn_clear_geo(idn_config *c) {
    if (c == NULL) return;
    c->geo_mode = IDN_GEO_OFF;
    c->geo_lat = c->geo_lon = c->geo_accuracy_m = 0.0;
}

const char *idn_user_agent(const idn_config *c) {
    return (c != NULL && c->user_agent[0] != '\0') ? c->user_agent : fp_user_agent();
}

size_t idn_accept_language(const idn_config *c, char *out, size_t cap) {
    if (out == NULL || cap == 0) return 0;
    out[0] = '\0';
    if (c == NULL || c->languages[0] == '\0') {
        const char *d = fp_accept_language_header();
        size_t n = strlen(d);
        if (n >= cap) return 0;
        memcpy(out, d, n + 1);
        return n;
    }
    size_t n = 0;
    int q = 10;
    const char *p = c->languages;
    while (*p != '\0') {
        const char *e = strchr(p, ',');
        size_t tl = (e != NULL) ? (size_t)(e - p) : strlen(p);
        int r;
        size_t space = cap - n;
        if (space == 0) { out[0] = '\0'; return 0; }
        if (n == 0) r = snprintf(out + n, space, "%.*s", (int)tl, p);
        else        r = snprintf(out + n, space, ",%.*s;q=0.%d", (int)tl, p, q > 1 ? q - 1 : 1);
        if (r < 0 || (size_t)r >= space) { out[0] = '\0'; return 0; }
        if (n != 0 && q > 1) --q;               /* the first tag carries no q */
        n += (size_t)r;
        p += tl;
        if (*p == ',') ++p;
    }
    return n;
}

size_t idn_primary_language(const idn_config *c, char *out, size_t cap) {
    if (out == NULL || cap == 0) return 0;
    out[0] = '\0';
    const char *src = (c != NULL && c->languages[0] != '\0') ? c->languages : fp_accept_language();
    const char *e = strchr(src, ',');
    size_t n = (e != NULL) ? (size_t)(e - src) : strlen(src);
    if (n >= cap) return 0;
    memcpy(out, src, n);
    out[n] = '\0';
    return n;
}

/* --- percent codec for the one-line form --- */

static int hexval(int ch) {
    if (ch >= '0' && ch <= '9') return ch - '0';
    if (ch >= 'a' && ch <= 'f') return ch - 'a' + 10;
    if (ch >= 'A' && ch <= 'F') return ch - 'A' + 10;
    return -1;
}

/* Decodes %XX (and '+' when plus) from [s, s+n) into out. Returns the length, or -1 when the
 * result does not fit in cap-1 bytes or a %-escape is malformed. */

static long pct_decode(const char *s, size_t n, char *out, size_t cap, int plus) {
    size_t o = 0;
    for (size_t i = 0; i < n; ++i) {
        char ch = s[i];
        if (ch == '%') {
            if (i + 2 >= n) return -1;
            int hi = hexval((unsigned char)s[i + 1]), lo = hexval((unsigned char)s[i + 2]);
            if (hi < 0 || lo < 0) return -1;
            ch = (char)(hi * 16 + lo);
            i += 2;
        } else if (plus && ch == '+') {
            ch = ' ';
        }
        if (o + 1 >= cap) return -1;
        out[o++] = ch;
    }
    out[o] = '\0';
    return (long)o;
}

static int append(char *buf, size_t *n, size_t cap, const char *fmt, ...) {
    if (*n >= cap) return -1;
    va_list ap;
    va_start(ap, fmt);
    int r = vsnprintf(buf + *n, cap - *n, fmt, ap);
    va_end(ap);
    if (r < 0 || (size_t)r >= cap - *n) { *n = cap; return -1; }
    *n += (size_t)r;
    return 0;
}

static int append_pct(char *buf, size_t *n, size_t cap, const char *s) {
    for (; *s != '\0'; ++s) {
        unsigned char ch = (unsigned char)*s;
        int bad = (ch == '|' || ch == '%' || ch < 0x20 || ch > 0x7e);
        if (append(buf, n, cap, bad ? "%%%02X" : "%c", bad ? (unsigned)ch : (int)ch) != 0) return -1;
    }
    return 0;
}

size_t idn_serialize(const idn_config *c, char *out, size_t cap) {
    if (out == NULL || cap == 0) return 0;
    out[0] = '\0';
    if (c == NULL) return 0;
    size_t n = 0;
    if (append(out, &n, cap, "ua=") != 0 || append_pct(out, &n, cap, c->user_agent) != 0
        || append(out, &n, cap, "|lang=") != 0 || append_pct(out, &n, cap, c->languages) != 0
        || append(out, &n, cap, "|geo=") != 0) { out[0] = '\0'; return 0; }
    if (c->geo_mode == IDN_GEO_FIXED
        && append(out, &n, cap, "%.6f,%.6f,%.1f", c->geo_lat, c->geo_lon, c->geo_accuracy_m) != 0) {
        out[0] = '\0';
        return 0;
    }
    return n;
}

/* Parses "lat,lon,acc" strictly; 0 on success. */

static int parse_geo(const char *s, double *lat, double *lon, double *acc) {
    char *e = NULL;
    *lat = strtod(s, &e);
    if (e == s || *e != ',') return -1;
    s = e + 1;
    *lon = strtod(s, &e);
    if (e == s || *e != ',') return -1;
    s = e + 1;
    *acc = strtod(s, &e);
    if (e == s || *e != '\0') return -1;
    return 0;
}

void idn_parse(idn_config *c, const char *text) {
    if (c == NULL) return;
    idn_defaults(c);
    if (text == NULL) return;
    const char *p = text;
    while (*p != '\0') {
        const char *e = strchr(p, '|');
        size_t sl = (e != NULL) ? (size_t)(e - p) : strlen(p);
        const char *eq = memchr(p, '=', sl);
        if (eq != NULL) {
            size_t kl = (size_t)(eq - p);
            const char *val = eq + 1;
            size_t vl = sl - kl - 1;
            char dec[IDN_QUERY_FIELD_MAX];
            if (kl == 2 && memcmp(p, "ua", 2) == 0) {
                if (pct_decode(val, vl, dec, sizeof dec, 0) >= 0) (void)idn_set_user_agent(c, dec);
            } else if (kl == 4 && memcmp(p, "lang", 4) == 0) {
                if (pct_decode(val, vl, dec, sizeof dec, 0) >= 0) (void)idn_set_languages(c, dec);
            } else if (kl == 3 && memcmp(p, "geo", 3) == 0 && vl > 0 && vl < sizeof dec) {
                memcpy(dec, val, vl);
                dec[vl] = '\0';
                double la, lo, ac;
                if (parse_geo(dec, &la, &lo, &ac) == 0) (void)idn_set_geo(c, la, lo, ac);
            }
        }
        if (e == NULL) break;
        p = e + 1;
    }
}

/* --- GET-form query --- */

static int parse_number(const char *s, double *out) {
    if (s[0] == '\0') return -1;
    char *e = NULL;
    *out = strtod(s, &e);
    return (*e == '\0') ? 0 : -1;
}

unsigned idn_apply_query(idn_config *c, const char *query) {
