/* Converts the current dc->frame (YUV) to BGRA and sends it as MD_FRAME with
 * the given PTS in microseconds. */

static void send_video_frame(decoder_ctx *dc, int64_t pts_us) {
    sws_scale(dc->sws,
              (const uint8_t *const *)dc->frame->data,
              dc->frame->linesize, 0, dc->h,
              dc->rgb->data, dc->rgb->linesize);
    uint8_t tag = MD_FRAME;
    int32_t w32 = (int32_t)dc->w, h32 = (int32_t)dc->h;
    size_t dlen = (size_t)dc->w * (size_t)dc->h * 4u;
    write_full(dc->out_fd, &tag, 1);
    write_full(dc->out_fd, &pts_us, sizeof pts_us);
    write_full(dc->out_fd, &w32, sizeof w32);
    write_full(dc->out_fd, &h32, sizeof h32);
    write_full(dc->out_fd, &dlen, sizeof dlen);
    write_full(dc->out_fd, dc->rgb->data[0], dlen);
}

/* Converts the current dc->audio_frame to interleaved S16LE PCM and sends it
 * as MD_AUDIO_FRAME with the given PTS in microseconds. Planar float (the
 * AAC decoder's native output) is converted; other formats emit silence of
 * the right duration so the audio clock stays continuous. */

static void send_audio_frame(decoder_ctx *dc, int64_t pts_us) {
    int rate = dc->audio_sample_rate > 0 ? dc->audio_sample_rate : 44100;
    int ch = dc->audio_channels > 0 ? dc->audio_channels : 2;
    int nsamples = dc->audio_frame->nb_samples;
    size_t pcm_bytes = (size_t)nsamples * (size_t)ch * 2u;
    if (pcm_bytes == 0) return;
    uint8_t *pcm = (uint8_t *)calloc(1, pcm_bytes);
    if (pcm == NULL) return;
    if (dc->audio_frame->format == AV_SAMPLE_FMT_FLTP) {
        for (int s = 0; s < nsamples; ++s) {
            for (int c = 0; c < ch; ++c) {
                float val = ((float *)dc->audio_frame->data[c])[s];
                if (val > 1.0f) val = 1.0f;
                if (val < -1.0f) val = -1.0f;
                int16_t s16 = (int16_t)(val * 32767.0f);
                pcm[(size_t)s * (size_t)ch * 2u + (size_t)c * 2u]      = (uint8_t)(s16 & 0xff);
                pcm[(size_t)s * (size_t)ch * 2u + (size_t)c * 2u + 1u] = (uint8_t)((s16 >> 8) & 0xff);
            }
        }
    }
    uint8_t tag = MD_AUDIO_FRAME;
    int32_t rate32 = (int32_t)rate;
    int32_t ch32 = (int32_t)ch;
    write_full(dc->out_fd, &tag, 1);
    write_full(dc->out_fd, &pts_us, sizeof pts_us);
    write_full(dc->out_fd, &rate32, sizeof rate32);
    write_full(dc->out_fd, &ch32, sizeof ch32);
    write_full(dc->out_fd, &pcm_bytes, sizeof pcm_bytes);
    write_full(dc->out_fd, pcm, pcm_bytes);
    free(pcm);
}

/* Decodes one segment of TS data and sends frames. Returns the number of
 * frames sent, or -1 on fatal error. */

static int decode_segment(decoder_ctx *dc, const uint8_t *data, size_t len) {
    if (!dc->stream_inited) {
        if (decoder_init(dc, data, len) != 0) return -1;
        /* Send MD_STREAM_INFO to parent. */
        uint8_t tag = MD_STREAM_INFO;
        int32_t codec = (int32_t)dc->video_codec_ctx->codec_id;
        int32_t w32 = (int32_t)dc->w, h32 = (int32_t)dc->h;
        int32_t ha32 = (int32_t)dc->has_audio;
        write_full(dc->out_fd, &tag, 1);
        write_full(dc->out_fd, &codec, sizeof codec);
        write_full(dc->out_fd, &w32, sizeof w32);
        write_full(dc->out_fd, &h32, sizeof h32);
        write_full(dc->out_fd, &ha32, sizeof ha32);
        /* v2: fall through and decode this same segment. v1 used the first
         * segment for the probe only, silently dropping its ~10 s of frames. */
    }

    /* We need to re-mux the segment into a new format context (each TS segment
     * is self-contained for HLS). We create a temporary AVFormatContext using
     * the same io buffer pattern. */
    AVFormatContext *seg_fmt = avformat_alloc_context();
    if (seg_fmt == NULL) { send_error(dc->out_fd, "OOM seg fmt"); return -1; }

    unsigned char *buf = (unsigned char *)av_malloc(len + AV_INPUT_BUFFER_PADDING_SIZE);
    if (buf == NULL) { avformat_free_context(seg_fmt); send_error(dc->out_fd, "OOM buf"); return -1; }
    memcpy(buf, data, len);
    memset(buf + len, 0, AV_INPUT_BUFFER_PADDING_SIZE);

    seg_fmt->pb = avio_alloc_context(buf, (int)len, 0, NULL, NULL, NULL, NULL);
    if (seg_fmt->pb == NULL) { av_free(buf); avformat_free_context(seg_fmt); re

     * one was silently dropped ("plays a couple of seconds then stops").
     * Reorder-buffered frames flush with the next segment's packets, or on
     * the final MD_FLUSH command. */

    avformat_close_input(&seg_fmt);
    return nframes;
}

/* --- main decoder loop --- */

void media_decoder_run(int out_fd, int cmd_fd) {
    signal(SIGPIPE, SIG_IGN);

    decoder_ctx dc;
    memset(&dc, 0, sizeof dc);
    dc.out_fd = out_fd;
    dc.stream_idx = -1;

    /* Register all FFmpeg muxers/demuxers/codecs once at startup. */
    avformat_network_init(); /* safe: a no-op when built without network, but harmless */

    for (;;) {
        uint8_t cmd;
        if (read_full(cmd_fd, &cmd, 1) != 0) break;

        if (cmd == MD_QUIT) break;

        if (cmd == MD_DECODE) {
            size_t len = 0;
            if (read_full(cmd_fd, &len, sizeof len) != 0) break;
            if (len == 0 || len > MD_MAX_SEGMENT_BYTES) {
                send_error(out_fd, "segment too large");
                continue;
            }

            uint8_t *data = (uint8_t *)malloc(len);
            if (data == NULL) break;
            if (read_full(cmd_fd, data, len) != 0) { free(data); break; }

            int fr = decode_segment(&dc, data, len);
            free(data);
            if (fr < 0) {
                /* Fatal: reset the decoder for the next stream. */
                decoder_close(&dc);
                dc.out_fd = out_fd;
                dc.stream_idx = -1;
            }
            continue;
        }

int media_decoder_spawn(pid_t *pid, int *out_fd, int *cmd_fd) {
    if (pid == NULL || out_fd == NULL || cmd_fd == NULL) return -1;

    int out_pipe[2], cmd_pipe[2];
    if (pipe(out_pipe) != 0 || pipe(cmd_pipe) != 0) return -1;

    pid_t p = fork();
    if (p < 0) {
        close(out_pipe[0]); close(out_pipe[1]);
        close(cmd_pipe[0]); close(cmd_pipe[1]);
        return -1;
    }

    if (p == 0) {
        /* Child: decoder process. */
        close(out_pipe[0]); /* child writes to out_pipe[1] */
        close(cmd_pipe[1]); /* child reads from cmd_pipe[0] */

        /* Close EVERY fd >= 3 EXCEPT our own pipe ends (out_pipe[1] for
         * writing decoded frames, cmd_pipe[0] for reading commands), to

         * prevent the Wayland display fd (inherited from the parent) from
         * surviving the exec. An inherited Wayland fd would be leaked to the
         * decoder child and, if accidentally written to (e.g. by an FFmpeg
         * library logging callback), would corrupt the Wayland protocol
         * connection — the most common cause of the white-flash/render-loop
         * bug. */
        int max_fd = (int)sysconf(_SC_OPEN_MAX);
        if (max_fd < 256) max_fd = 256;
        for (int fd = 3; fd < max_fd; ++fd) {
            if (fd == out_pipe[1] || fd == cmd_pipe[0]) continue;
            close(fd);
        }

        /* Build --media-decoder <out_fd> <cmd_fd> argv for re-exec. */
        char out_str[16], cmd_str[16];
        int out_n = snprintf(out_str, sizeof out_str, "%d", out_pipe[1]);
        int cmd_n = snprintf(cmd_str, sizeof cmd_str, "%d", cmd_pipe[0]);
        if (out_n < 0 || (size_t)out_n >= sizeof out_str
            || cmd_n < 0 || (size_t)cmd_n >= sizeof cmd_str)
            goto media_decoder_fallback;

        /* Re-exec ourselves as the decoder. */
        execl("/proc/self/exe", "freedom", "--media-decoder",
              out_str, cmd_str, (char *)NULL);

media_decoder_fallback:
        /* If exec fails (or snprintf truncated), run in-process. */
        media_decoder_run(out_pipe[1], cmd_pipe[0]);
        close(out_pipe[1]); close(cmd_pipe[0]);
        _exit(1);
    }

    /* Parent. */
    close(out_pipe[1]);
    close(cmd_pipe[0]);
    *pid = p;
    *out_fd = out_pipe[0];  /* read decoded frames from child */
    *cmd_fd = cmd_pipe[1];

static char lower(char c) {
    return (c >= 'A' && c <= 'Z') ? (char)(c + ('a' - 'A')) : c;
}

/* True if the lowercased host (length n) ends with ".suffix" AND has at least one
 * non-empty label before the dot. suffix is given without its leading dot. */

static int ends_with_realm(const char *host, size_t n, const char *suffix) {
    size_t sl = strlen(suffix);
    if (n < sl + 2) return 0;            /* need at least "x." + suffix */
    if (host[n - sl - 1] != '.') return 0;
    for (size_t i = 0; i < sl; ++i) {
        if (host[n - sl + i] != suffix[i]) return 0;  /* host already lowercased */
    }
    /* The label before the dot must be non-empty (reject ".onion"). */
    return (n - sl - 1) > 0;
}

nr_realm nr_classify_host(const char *host) {
    if (host == NULL) return NR_CLEARNET;
    size_t len = strlen(host);
    if (len == 0 || len > NR_MAX_HOST) return NR_CLEARNET;

    char buf[NR_MAX_HOST + 1];
    for (size_t i = 0; i < len; ++i) buf[i] = lower(host[i]);
    buf[len] = '\0';
    if (buf[len - 1] == '.') { --len; buf[len] = '\0'; }  /* trim one trailing dot */
    if (len == 0) return NR_CLEARNET;

    if (ends_with_realm(buf, len, "onion")) return NR_ONION;
    if (ends_with_realm(buf, len, "i2p")) return NR_I2P;
    return NR_CLEARNET;
}

/* Extracts the host of scheme://host[:port][/...] into out (lowercased not required
 * here; nr_classify_host lowercases). Returns 0 on success, -1 if no host. */

static int host_of(const char *url, char *out, size_t out_size) {
    if (url == NULL || out == NULL || out_size == 0) return -1;
    const char *p = strstr(url, "://");
    if (p == NULL) return -1;
    p += 3;
    size_t n = 0;
    while (p[n] != '\0' && p[n] != '/' && p[n] != ':' &&
           p[n] != '?' && p[n] != '#') {
        ++n;
    }
    if (n == 0 || n + 1 > out_size) return -1;
    memcpy(out, p, n);
    out[n] = '\0';
    return 0;
}

nr_realm nr_classify_url(const char *url) {
    char host[NR_MAX_HOST + 1];
    if (host_of(url, host, sizeof host) != 0) return NR_CLEARNET;
    return nr_classify_host(host);
}

nr_route nr_route_for(const char *url, nr_config cfg) {
    if (url == NULL) return NR_ROUTE_BLOCKED;  /* fail closed */
    switch (nr_classify_url(url)) {
        case NR_ONION:
            return cfg.tor_enabled ? NR_ROUTE_TOR : NR_ROUTE_BLOCKED;
        case NR_I2P:
            return cfg.i2p_enabled ? NR_ROUTE_I2P : NR_ROUTE_BLOCKED;
        case NR_CLEARNET:
        default:
            return (cfg.tor_enabled && cfg.torify_clearnet) ? NR_ROUTE_TOR
                                                            : NR_ROUTE_DIRECT;
    }
}

int nr_realm_allows_http(nr_realm r) {
    /* I2P eepsites are http; the I2P layer encrypts and authenticates by destination.
     * .onion stays https-only (owner's choice); clearnet is always https. */
    return r == NR_I2P;
}

const char *nr_realm_name(nr_realm r) {
    switch (r) {
        case NR_CLEARNET: return "clearnet";
        case NR_ONION:    return "onion";
        case NR_I2P:      return "i2p";
    }
    return "clearnet";
}

const char *nr_route_name(nr_route r) {
    switch (r) {
        case NR_ROUTE_DIRECT:  return "direct";
        case NR_ROUTE_TOR:     return "tor";
        case NR_ROUTE_I2P:     return "i2p";
        case NR_ROUTE_BLOCKED: return "blocked";
    }
    return "blocked";
}

