/* --- builder helpers --- */

/* Iterative pre-order successor of node within the subtree rooted at root. */

static lxb_dom_node_t *node_next(lxb_dom_node_t *node, const lxb_dom_node_t *root) {
    if (node->first_child != NULL) return node->first_child;
    while (node != root && node->next == NULL) {
        if (node->parent == NULL) return NULL;
        node = node->parent;
    }
    if (node == root) return NULL;
    return node->next;
}

static int is_block_tag(lxb_tag_id_t t) {
    switch (t) {
        case LXB_TAG_BODY: case LXB_TAG_DIV: case LXB_TAG_P:
        case LXB_TAG_H1: case LXB_TAG_H2: case LXB_TAG_H3:
        case LXB_TAG_H4: case LXB_TAG_H5: case LXB_TAG_H6:
        case LXB_TAG_UL: case LXB_TAG_OL: case LXB_TAG_LI:
        case LXB_TAG_SECTION: case LXB_TAG_ARTICLE: case LXB_TAG_HEADER:
        case LXB_TAG_FOOTER: case LXB_TAG_NAV: case LXB_TAG_MAIN:
        case LXB_TAG_ASIDE: case LXB_TAG_BLOCKQUOTE: case LXB_TAG_PRE:
        case LXB_TAG_TABLE: case LXB_TAG_TR: case LXB_TAG_FIGURE:
        case LXB_TAG_FORM: case LXB_TAG_FIELDSET:         case LXB_TAG_DL:
        case LXB_TAG_DT: case LXB_TAG_DD:
        case LXB_TAG_MENU:
        case LXB_TAG_DETAILS: case LXB_TAG_SUMMARY:
            return 1;
        default:
            return 0;
    }
}

/* An element should be treated as block-like (eligible for box registration,
 * hbox, float) when its CSS display property indicates a block-level box, even
 * if the tag itself is normally inline. This lets author CSS like
 *   a { display: inline-block; width: 22px; }
 * actually create a box for the <a> tag. */

static int is_block_like(lxb_tag_id_t t, css_display display) {
    if (display == CSS_DISP_INLINE) return 0;
    /* A flex or grid container generates a box whatever its tag (CSS Display 3
     * section 2): `<a style=display:flex>` is how card grids are written, and
     * leaving it to is_block_tag lost the card's height and background. */
    if (display == CSS_DISP_BLOCK || display == CSS_DISP_INLINE_BLOCK
        || display == CSS_DISP_LIST_ITEM || display == CSS_DISP_FLEX
        || display == CSS_DISP_GRID) return 1;
    /* Every box of the table family is a BLOCK CONTAINER (CSS 2.1 17.2): a
     * table, a row group, a row, a cell and a caption all establish a block
     * formatting context for their content. Only table-column generates no box
     * at all, so it is deliberately absent.
     *
     * Reaching is_block_tag for them meant a `figcaption{display:table-caption}`
     * -- how every MediaWiki thumbnail caption is written -- registered no box,
     * so nothing downstream could tell the caption apart from the picture it
     * describes. */
    if (display == CSS_DISP_TABLE || display == CSS_DISP_TABLE_ROW_GROUP ||
        display == CSS_DISP_TABLE_ROW || display == CSS_DISP_TABLE_CELL ||
        display == CSS_DISP_TABLE_CAPTION) return 1;
    return is_block_tag(t);
}

/* CSS 2.2 section 9.7: taking an element OUT OF FLOW -- position:absolute|fixed, or
 * any float other than none -- computes its `display` to `block`. An absolutely
 * positioned <span> is a block box, whatever its tag says.
 *
 * This matters beyond pedantry: without it such an elemen

 * box_tree already resolves (R4/R8) had nothing to place -- every badge/close
 * button/tooltip written on a <span> landed in the flow at full width instead of in
 * its corner. spec/page_view.md "position:absolute|fixed y float...". */
static int is_out_of_flow(const css_style *cs) {
    return cs->position == CSS_POS_ABSOLUTE || cs->position == CSS_POS_FIXED
        || cs->float_side == CSS_FLOAT_LEFT || cs->float_side == CSS_FLOAT_RIGHT;
}

/* is_block_like with the out-of-flow coercion applied. Takes the resolved style
 * because the answer depends on position/float, not just the declared display. */

static int is_block_like_style(lxb_tag_id_t t, const css_style *cs) {
    return is_out_of_flow(cs) || is_block_like(t, cs->display);
}

/* An element that can carry a BOX (border/background/padding rect). Table cells are
 * box-generating even though they are not block tags: they must not cause a block
 * break (a row of cells flows as one line through the grid container, and making
 * <td> a block tag would split multi-link nav cells), but `td { border: 1px solid }`
 * is one of the most common declarations on the web and used to paint nothing at all
 * because no box was ever registered for the cell. */
static int generates_box_style(lxb_tag_id_t t, const css_style *cs);

static int generates_box(lxb_tag_id_t t, css_display display) {
    /* Form controls (input/select/textarea/button) are inline-block by default
     * but can carry author CSS like position:absolute, opacity:0, borders, etc.
     * that need a box entry — otherwise they never register and the painter
     * ignores author styles on them entirely. */
    return is_block_like(t, display)
        || t == LXB_TAG_TD || t == LXB_TAG_TH
        || t == LXB_TAG_INPUT || t == LXB_TAG_SELECT
        || t == LXB_TAG_TEXTAREA || t == LXB_TAG_BUTTON;
}

/* generates_box with the out-of-flow coercion (see is_block_like_style). */

static int generates_box_style(lxb_tag_id_t t, const css_style *cs) {
    return is_out_of_flow(cs) || generates_box(t, cs->display);
}

/* Returns 1 when the element should cause a block break (start a new line).
 * display:inline-block and display:inline do NOT cause a break; they flow
 * inline while still being eligible for box registration. */

static int causes_block_break(lxb_tag_id_t t, css_display display) {
    if (display == CSS_DISP_INLINE || display == CSS_DISP_INLINE_BLOCK) return 0;
    /* A flex or grid container (and a list item) is block-LEVEL whatever its tag
     * (CSS Display 3 section 2): the text of `<a style=display:flex>` belongs to
     * the <a>, not to the block around it. */
    if (display == CSS_DISP_BLOCK || display == CSS_DISP_FLEX ||
        display == CSS_DISP_GRID || display == CSS_DISP_LIST_ITEM) return 1;
    return is_block_tag(t);
}

/* True iff an element has NO content of its own: no child elements and no
 * non-whitespace text. Such a decorated element (a styled bar/spacer/tile/icon)
 * is never reached by the text-node walk, so page_view emits a placeholder run

 * for it so its box reserves space and paints (spec/page_view.md §4 "Cajas
 * vacías"). Comment and other node types are ignored (they carry no content). */
/* True iff a TEXT node carries nothing but HTML whitespace (so it contributes no
 * content of its own). */
static int text_node_is_blank(const lxb_dom_node_t *c) {
    lxb_dom_text_t *tx = lxb_dom_interface_text((lxb_dom_node_t *)c);
    const char *d = (const char *)tx->char_data.data.data;
    size_t len = tx->char_data.data.length;
    for (size_t i = 0; i < len; ++i) {
        char ch = d[i];
        if (ch != ' ' && ch != '\t' && ch != '\n' && ch != '\r' && ch != '\f')
            return 0;
    }
    return 1;
}

/* element_is_content_leaf lives further down, next to the style cache it needs. */

/* User-agent box identity of a block-level element, from its lexbor tag id. Only the
 * tags the UA sheet gives a vertical margin need naming; everything else -- div,
 * section, header, article, footer, nav, main, the table family, the form family --
 * is BX_UA_NONE, which is the correct answer (no UA margin) and the fail-closed one.
 *
 * The lexbor id is page_view's own vocabulary, so the mapping lives here; the METRICS
 * behind each code stay in box_style's one table. spec/box_style.md 4d. */

static bx_ua_tag ua_tag_of(lxb_tag_id_t t) {
    switch (t) {
        case LXB_TAG_P:          return BX_UA_P;
        case LXB_TAG_H1:         return BX_UA_H1;
        case LXB_TAG_H2:         return BX_UA_H2;
        case LXB_TAG_H3:         return BX_UA_H3;
        case LXB_TAG_H4:         return BX_UA_H4;
        case LXB_TAG_H5:         return BX_UA_H5;
        case LXB_TAG_H6:         return BX_UA_H6;
        case LXB_TAG_UL:         return BX_UA_UL;
        case LXB_TAG_OL:         return BX_UA_OL;
        case LXB_TAG_MENU:       return BX_UA_MENU;
        case LXB_TAG_DL:         return BX_UA_DL;
        case LXB_TAG_PRE:        return BX_UA_PRE;
        case LXB_TAG_BLOCKQUOTE: return BX_UA_BLOCKQUOTE;
        case LXB_TAG_FIGURE:     return BX_UA_FIGURE;
        case LXB_TAG_HR:         return BX_UA_HR;
        case LXB_TAG_LI:         return BX_UA_LI;
        default:                 return BX_UA_NONE;
    }
}

static int heading_level(lxb_tag_id_t t) {
    switch (t) {
        case LXB_TAG_H1: return 1;
        case LXB_TAG_H2: return 2;
        case LXB_TAG_H3: return 3;
        case LXB_TAG_H4: return 4;
        case LXB_TAG_H5: return 5;
        case LXB_TAG_H6: return 6;
        default:         return 0;
    }
}

static lxb_tag_id_t node_tag(const lxb_dom_node_t *n) {
    return lxb_dom_element_tag_id(lxb_dom_interface_element((lxb_dom_node_t *)n));
}

/* Nonzero if any ancestor up to base is a non-rendered container. When js_enabled,

static int in_skipped_subtree(const lxb_dom_node_t *n, const lxb_dom_node_t *base,
                              int js_enabled) {
    for (const lxb_dom_node_t *p = n->parent; p != NULL; p = p->parent) {
        if (p->type == LXB_DOM_NODE_TYPE_ELEMENT) {
            lxb_tag_id_t t = node_tag(p);
            if (is_skipped_tag(t)) return 1;
            if (t == LXB_TAG_NOSCRIPT && js_enabled) return 1;
        }
        if (p == base) break;
    }
    return 0;
}

/* Largest color token value extracted from markup. A longer value is not a valid
 * color and is ignored (fail closed). */

#define PV_COLOR_TOKEN_MAX 64u

/* A color-valued legacy attribute (e.g. <font color>, bgcolor) as a packed
 * 0xRRGGBB, or -1. Not CSS: a separate fallback consulted only when no CSS
 * declaration for that channel won. */
static int color_attr(lxb_dom_element_t *el, const char *name, size_t name_len) {
    size_t cl = 0;
    const lxb_char_t *col =
        lxb_dom_element_get_attribute(el, (const lxb_char_t *)name, name_len, &cl);
    if (col != NULL && cl > 0 && cl < PV_COLOR_TOKEN_MAX) {
        char buf[PV_COLOR_TOKEN_MAX];
        memcpy(buf, col, cl);
        buf[cl] = '\0';
        cc_rgb rgb;
        cc_status st = cc_parse(buf, &rgb);
        if (st == CC_OK) return cc_pack(rgb);
        if (st == CC_TRANSPARENT) return CC_COLOR_TRANSPARENT;
        if (st == CC_CURRENT_COLOR) return CC_COLOR_CURRENT;
    }
    return -1;
}

static int font_color_attr(lxb_dom_element_t *el) {
    return color_attr(el, "color", 5);
}

/* Legacy bgcolor attribute (body/table/tr/td), the background twin of <font
 * color>: pre-CSS sites (Hacker News' orange bar and beige page) still use it. */

static int bgcolor_attr(lxb_dom_element_t *el) {
    return color_attr(el, "bgcolor", 7);
}

/* --- author flex/grid container layout: structure, not author styling. render_doc
 * applies it ALWAYS, decoupled from caps.css (doctrine "Layout != estilo de autor");
 * only author colors/text-align/font-size stay gated. The display and its params
 * (gap/justify/columns) come from the css cascade (<style> + inline), resolved by
 * cch_element_style like the colors. --- */

typedef struct pv_cont_info {
    int id, display, gap, justify, cols;
    /* Grid track sizes of the container (0 auto / >0 px / <0 fr x100) and the
     * ITEM's grid-column span (tracked like grow/shrink via the previous element
     * on the walk; 0 = 1 column). */
    int col_w[PV_GRID_TRACKS];
    int col_span;
    int grow, shrink, basis, order, direction;
    const lxb_dom_node_t *item;
    /* Float context (spec/float.md): float_side/float_id from the nearest floated
     * self-or-ancestor block, float_clear from the run's own leaf block. */
    int float_side, float_id, float_clear;
    /* The float FOUNDER's own horizontal margins (spec/float.md §7c.1): px halves
     * signed, pct halves per-mille signed, 0 = none. Stamped when the founder is
     * found, so the band packer sizes outer (margin) boxes, not borders. */
    int float_ml, float_ml_pct, float_mr, float_mr_pct;
    int float_w, float_w_pct;   /* the founder's own declared width (pv_run.float_w) */
    int float_box;              /* the founder's own box id (pv_run.float_box), -1 none */
    int float_ow, float_ow_pct; /* the OUTERMOST founder's own width halves (pv_run.float_ow) */
    int float_obox;             /* the OUTERMOST founder's own box id (pv_run.float_obox), -1 none */
    /* The OUTERMOST float founder (spec/float.md §7d.1): the last (highest)
     * floated self-or-ancestor block on this run's chain. float_oid is its

     * group id (-1 = the nearest IS the outermost: single-level float, the
     * painter's old path); float_oside its css_float side; float_oml/oml_pct/
     * omr/omr_pct its own horizontal margins (same halves as above, for the
     * outer column's pack). The walk already visits every ancestor, so keeping
     * the last match costs nothing. Structure like float_id. */
    int float_oid, float_oside;
    int float_oml, float_oml_pct, float_omr, float_omr_pct;
/* flex-wrap / row-gap / align-items (CONTAINER); align-self (ITEM, tracked
 * like grow/shrink/basis/order via the previous element on the walk).
 * align_content / justify_items (CONTAINER), grid_rows / grid_flow (grid
 * container), row_span (ITEM) — 2026-07-12 batch. */
int wrap, row_gap, align_items, align_self;
int justify_self;   /* the ITEM's justify-self (css_align_kw) */
/* Main-axis auto margins of the ITEM (Flexbox 8.1): bit 1 = margin-left:auto,
 * bit 2 = margin-right:auto (PV_MAUTO_*). */
int mauto;
int align_content, justify_items;
int grid_rows, grid_flow, row_span;
/* Named grid placement (2026-08-14): the item's resolved cell, or -1 for auto.
 * Resolved on the trusted side from grid-template-areas + grid-area, so the
 * painter receives numbers and never a name. */
int grid_row_start, grid_col_start;
/* The box enclosing the container's items (see pv_run.cont_box_id): the container
 * element's own box, else the nearest box-carrying ancestor, else -1. box_pending
 * is the walk's bookkeeping -- set when the container itself carried no box, so the
 * first box found further out claims the slot.

typedef struct pv_item_track {
    const lxb_dom_node_t *node[PV_MAX_CONTAINERS];
    int ord[PV_MAX_CONTAINERS];
} pv_item_track;

/* Ordinal for a run of container `cid` whose direct-child item is `item` (NULL =
 * anonymous: every such run is its own item). -1 when the run has no container. */

static int item_ordinal(pv_item_track *tr, int cid, const lxb_dom_node_t *item) {
    if (cid < 0 || (size_t)cid >= PV_MAX_CONTAINERS) return -1;
    if (item == NULL || item != tr->node[cid]) {
        tr->ord[cid]++;
        tr->node[cid] = item;
    }
    return tr->ord[cid];
}

/* Author box model resolved for a run: horizontal placement (l/r insets, w cap,
 * centered) from the nearest block ancestor that declares a box, plus the leaf
 * block's own vertical-margin override (mt/mb, or PV_LEN_UNSET). */

typedef struct pv_box_info {
    int l, r, w, center, mt, mb;
    int w_pct;   /* per-mille width cap (Hito 32), 0 = none; LAST so the existing
                  * positional initializers keep meaning what they say */
    int ua;      /* bx_ua_tag of the block this box came from; rides beside mt/mb
                  * because it is what makes them meaningful when the author sets
                  * neither. Appended, same reason as w_pct. */
    /* Percentage halves of the same placement, per-mille of the containing
     * block WIDTH (all four of them: CSS 2.1 8.3/8.4 resolve even the vertical
     * margins against the width). 0 = none. Appended for the same reason. */
    int l_pct, r_pct, mt_pct, mb_pct;
    int mw, mw_pct;  /* max-width, its own <length-percentage> (tanda 40) */
    dom_node_id block_node;  /* the block element these placements belong to */
} pv_box_info;

