static int css_has_hbox(const css_style *cs) {
    return cs->margin_left != CSS_LEN_UNSET || cs->margin_right != CSS_LEN_UNSET ||
           cs->pad_left   != CSS_LEN_UNSET || cs->pad_right   != CSS_LEN_UNSET ||
           cs->width != CSS_LEN_UNSET || cs->max_width != CSS_LEN_UNSET ||
           cs->pct[CSS_PCT_WIDTH] != 0 || cs->pct[CSS_PCT_MAX_WIDTH] != 0 ||
           cs->pct[CSS_PCT_MARGIN_LEFT] != 0 || cs->pct[CSS_PCT_MARGIN_RIGHT] != 0 ||
           cs->pct[CSS_PCT_PAD_LEFT] != 0 || cs->pct[CSS_PCT_PAD_RIGHT] != 0 ||
           cs->min_width > 0;
}

/* Pre-resolves the horizontal box (px) into a run's wire fields: l/r insets =
 * padding + non-auto margin of each side (clamped >= 0); w = the tightest of
 * width/max-width (0 = none); center = margin: 0 auto with a width cap. */
/* The PV_MAUTO_* bits of an element's own horizontal auto margins. */

static int pv_mauto_of(const css_style *cs) {
    return ((cs->margin_left == CSS_LEN_AUTO) ? PV_MAUTO_LEFT : 0)
         | ((cs->margin_right == CSS_LEN_AUTO) ? PV_MAUTO_RIGHT : 0)
         | ((cs->margin_top == CSS_LEN_AUTO) ? PV_MAUTO_TOP : 0)
         | ((cs->margin_bottom == CSS_LEN_AUTO) ? PV_MAUTO_BOTTOM : 0);
}

static void css_hbox_resolve(const css_style *cs, pv_box_info *out) {
    int ml = cs->margin_left, mr = cs->margin_right;
    int pl = (cs->pad_left  != CSS_LEN_UNSET) ? cs->pad_left  : 0;
    int pr = (cs->pad_right != CSS_LEN_UNSET) ? cs->pad_right : 0;
    int l = pl + ((ml != CSS_LEN_UNSET && ml != CSS_LEN_AUTO) ? ml : 0);
    int r = pr + ((mr != CSS_LEN_UNSET && mr != CSS_LEN_AUTO) ? mr : 0);
    /* An intrinsic sizing keyword is not a px cap: it names a measurement, and the
     * measurement this engine takes for an undeclared dimension IS content sizing
     * (CSS Sizing 3 section 5.1). Feeding the sentinel forward as a length would
     * hand layout a large negative width, so it reads as "no cap" here -- the same
     * answer `auto` gets -- and the keyword survives in cs->width for the
     * shrink-to-fit path that can act on it. */
    int cw = CSS_LEN_IS_INTRINSIC(cs->width) ? CSS_LEN_UNSET : cs->width;
    int cmw = CSS_LEN_IS_INTRINSIC(cs->max_width) ? CSS_LEN_UNSET : cs->max_width;
    /* width and max-width are two <length-percentage> values, each kept whole
     * (px half + per-mille half) and only compared at layout, where the basis is
     * known (bx_width_cap2). Racing their px halves and their percentage halves
     * separately and then SUMMING the winners turned `width:100%;max-width:768px`
     * into 768px + 100% = no cap at all. */
    int w = (cw != CSS_LEN_UNSET) ? cw : CSS_LEN_UNSET;
    int wp = (cs->pct[CSS_PCT_WIDTH] > 0) ? cs->pct[CSS_PCT_WIDTH] : 0;
    int mwp = (cs->pct[CSS_PCT_MAX_WIDTH] > 0) ? cs->pct[CSS_PCT_MAX_WIDTH] : 0;

static int css_has_position(const css_style *cs) {
    return cs->position == CSS_POS_RELATIVE || cs->position == CSS_POS_ABSOLUTE ||
           cs->position == CSS_POS_FIXED   || cs->position == CSS_POS_STICKY;
}

typedef struct pv_container_reg {
    const lxb_dom_node_t *node[PV_MAX_CONTAINERS];
    /* Per-container parameters + parent linkage (2026-07-31). Mirrors pv_box_reg's
     * def[] array: the registry is the one place that knows a container by identity,
     * so it is also the one place that describes it. See pv_cont_def. */
    pv_cont_def           def[PV_MAX_CONTAINERS];
    size_t count;
    const struct pv_node_map *nodes;  /* element ids (block_node), or NULL */
} pv_container_reg;

/* Resets a descriptor to "registered but undescribed": no parent, no parameters. */

static void cont_def_reset(pv_cont_def *d) {
    memset(d, 0, sizeof *d);
    d->parent_id = -1;
    d->parent_item = -1;
    d->row_gap = -1;
    d->box_id = -1;
    d->item_grow = -1;
    d->item_shrink = -1;
    d->item_basis = CSS_LEN_UNSET;
    d->item_order = CSS_LEN_UNSET;
    d->item_align_self = CSS_AK_UNSET;
    d->item_justify_self = CSS_AK_UNSET;
    d->item_mauto = 0;
    d->item_col_start = -1;
    d->item_row_start = -1;
    d->node_id = DOM_NODE_NONE;
}

/* Id of node in reg, registering it on first sight. -1 when reg is full. */

static int container_id(pv_container_reg *reg, const lxb_dom_node_t *node) {
    for (size_t i = 0; i < reg->count; ++i)
        if (reg->node[i] == node) return (int)i;
    if (reg->count >= PV_MAX_CONTAINERS) return -1;
    reg->node[reg->count] = node;
    cont_def_reset(&reg->def[reg->count]);
    reg->def[reg->count].node_id = pv_node_map_id(reg->nodes, node);
    return (int)reg->count++;
}

