    pv_set_float_w(v, cont->float_w, cont->float_w_pct, cont->float_box, cont->float_ow, cont->float_ow_pct, cont->float_obox);
    pv_set_box(v, box->l, box->r, box->w, box->center, box->mt, box->mb);
    pv_set_ua_tag(v, box->ua);
    pv_set_box_pct(v, box->w_pct, box->l_pct, box->r_pct, box->mt_pct, box->mb_pct);
    pv_set_box_maxw(v, box->mw, box->mw_pct)

typedef struct pv_after_pending {
    const lxb_dom_node_t *el;   /* element whose ::after is pending, NULL = none */
    char *text;                 /* owned generated content */
    int box;                    /* generated box id, -1 = none */
    int brk;                    /* generated box is block-level */
    int bdeco, indent;          /* the element's own block box and list indent */
    int align, font_scale, font_abs, line_scale, text_decoration;
    int color;                  /* inherited colour of the element, -1 = none declared */
    pv_cont_info cont;
    pv_box_info boxinfo;
    pv_text_ext ext;
} pv_after_pending;

static pv_status after_pending_emit(pv_view *v, pv_container_reg *reg, pv_item_track *items,
                                    pv_after_pending *ap, int node_id,
                                    const css_style *acs, int *pending_break) {
    pv_status st = pv_append(v, PV_TEXT, 0, (ap->box >= 0) ? ap->brk : 0, ap->text, NULL);
    if (st != PV_OK) return st;
    pv_set_node_id(v, node_id);
    if (ap->color >= 0) pv_set_color(v, ap->color);
    if (acs != NULL) {
        if (acs->background >= 0) pv_set_bgcolor(v, acs->background);
        pv_set_emphasis(v, acs->bold > 0, acs->italic > 0);
    }
    pv_set_indent(v, ap->indent);
    pv_set_text_style(v, ap->align, ap->font_scale, ap->font_abs, ap->line_scale,
                      ap->text_decoration);
    annotate_flow_run(v, reg, items, &ap->cont, &ap->boxinfo);
    pv_set_text_ext(v, &ap->ext);
    pv_set_block_id(v, ap->box >= 0 ? ap->box : ap->bdeco);
    if (ap->box >= 0 && ap->brk && pending_break != NULL) *pending_break = 1;
    free(ap->text);
    ap->text = NULL;
    ap->el = NULL;
    ap->box = -1;
    return PV_OK;
}

/* Box engine (Hito 23b-8 Step D): document-order registry of box-carrying block
 * nodes plus each box's resolved definition (decoration + parent link). A box's
 * block_id is its index here, so the painter can reconstruct the box tree. */

typedef struct pv_box_reg {
    const lxb_dom_node_t **node;
    pv_box_def            *def;
    size_t                 count, cap;
} pv_box_reg;

/* The registry grows on the HEAP, doubling, up to PV_MAX_BOXES.
 *
 * It used to be two fixed arrays inline in the struct, which put 1.5 MiB of
 * pv_box_def on pv_build's stack frame AND capped a page at 256 boxes -- a bound

 * a real page passes without trying (slashdot's front page saturates it), and past
 * it box_reg_id returns -1, so an element silently loses its box: no decoration, no
 * margins, and its descendants lay out against the page instead of against it. A
 * limit that a normal page hits is not an anti-DoS bound, it is a rendering bug.
 * PV_MAX_BOXES is the real bound and it is still hard: past it the page renders
 * with the boxes it has rather than growing without limit.
 *
 * Returns 0 on success, -1 when the cap or memory is exhausted (the caller then
 * degrades to "no box for this element", never a crash). */
static int box_reg_grow(pv_box_reg *r) {
    size_t ncap = (r->cap == 0) ? 64u : r->cap * 2u;
    if (ncap > PV_MAX_BOXES) ncap = PV_MAX_BOXES;
    if (ncap <= r->cap) return -1;
    const lxb_dom_node_t **nn =
        (const lxb_dom_node_t **)realloc(r->node, ncap * sizeof *nn);
    if (nn == NULL) return -1;
    r->node = nn;
    pv_box_def *nd = (pv_box_def *)realloc(r->def, ncap * sizeof *nd);
    if (nd == NULL) return -1;
    r->def = nd;
    /* V-002: realloc leaves the new tail uninitialised, and a pv_box_def read
     * before boxdef_from_style fills it would make the render depend on heap
     * residue. Zero it here so a slot is never live before it is defined. */
    memset(r->node + r->cap, 0, (ncap - r->cap) * sizeof *nn);
    memset(r->def  + r->cap, 0, (ncap - r->cap) * sizeof *nd);
    r->cap = ncap;
    return 0;
}

static void box_reg_free(pv_box_reg *r) {
    free(r->node); free(r->def);
    r->node = NULL; r->def = NULL;
    r->count = r->cap = 0;
}

/* Fills *d (decoration + hbox + bg; parent_id defaults to -1) from a resolved style.
 * Padding unset -> 0 (geometry default); the rest keep the css module's sentinels
 * (PV_LEN_UNSET width/radius/outline width, -1 colors, 0 the rest). */

static void boxdef_from_style(pv_box_def *d, const css_style *cs) {
    d->parent_id = -1;
    d->node_id = DOM_NODE_NONE;
    pv_box_info hb = { .mt = PV_LEN_UNSET, .mb = PV_LEN_UNSET, .ua = BX_UA_NONE };
    css_hbox_resolve(cs, &hb);
    d->box_l = hb.l; d->box_r = hb.r; d->box_w = hb.w; d->box_center = hb.center;
    d->box_w_pct = hb.w_pct;
    d->box_mw = hb.mw; d->box_mw_pct = hb.mw_pct;
    d->box_h_pct = (cs->position == CSS_POS_ABSOLUTE) ? cs->pct[CSS_PCT_HEIGHT] : 0;
    d->box_l_pct = hb.l_pct; d->box_r_pct = hb.r_pct;
