     * folded into box_l/box_r like the horizontal ones: a vertical margin has to
     * meet its neighbour's before either is used up (CSS 2.1 8.3.1 collapsing).
     * ua_tag is stamped by the caller, which is where the element's tag is known. */
    d->box_mt = (cs->margin_top    != CSS_LEN_UNSET) ? cs->margin_top    : PV_LEN_UNSET;
    d->box_mb = (cs->margin_bottom != CSS_LEN_UNSET) ? cs->margin_bottom : PV_LEN_UNSET;
    d->box_mt_pct = cs->pct[CSS_PCT_MARGIN_TOP];
    d->box_mb_pct = cs->pct[CSS_PCT_MARGIN_BOTTOM];
    d->ua_tag = BX_UA_NONE;
    d->font_px = 0;
    d->box_min_w_pct = (cs->pct[CSS_PCT_MIN_WIDTH] > 0) ? cs->pct[CSS_PCT_MIN_WIDTH] : 0;
    int bg = cs->background;
    d->bg_rgb = (bg >= 0) ? bg
              : (bg == CC_COLOR_TRANSPARENT) ? CC_COLOR_TRANSPARENT
              : (bg == CC_COLOR_CURRENT) ? -1
              : -1;
    d->bg_alpha = cs->bg_alpha;
    d->bg_clip = (cs->bg_clip == CSS_BGC_PADDING_BOX || cs->bg_clip == CSS_BGC_CONTENT_BOX)

 * always 0 here (the engine sizes boxes by their content). An intrinsic
 * keyword on the block axis (CSS Sizing 3 section 5.1) is content height
 * with indefinite available space, i.e. `auto`: letting CSS_LEN_FIT_CONTENT
 * arm box_h_set collapsed the box to zero and buried max-height with it
 * (jkanime's trending_div sidebar). */
int h_intrinsic = CSS_LEN_IS_INTRINSIC(cs->height);
d->box_h = (!h_intrinsic && cs->height > 0) ? cs->height : 0;
d->box_h_set = (!h_intrinsic && cs->height != CSS_LEN_UNSET) ? 1 : 0;
d->box_min_h = (cs->min_height > 0) ? cs->min_height : 0;
d->box_max_h = (cs->max_height > 0) ? cs->max_height : 0;
d->box_min_w = (cs->min_width > 0) ? cs->min_width : 0;
d->box_min_w_set = ((cs->min_width >= 0 && !CSS_LEN_IS_INTRINSIC(cs->min_width)) ||
                    cs->pct[CSS_PCT_MIN_WIDTH] > 0) ? 1 : 0;
/* width:max-content|fit-content (CSS Sizing 3 3.1): the box shrink-wraps its
 * content, exactly the inline-block measurement; fit-content is that clamped
 * to the available width, which the shrink path already does. */
d->box_w_intrinsic = (cs->width == CSS_LEN_MAX_CONTENT || cs->width == CSS_LEN_FIT_CONTENT);
d->grad_n = (cs->bg_grad_n >= 2) ? cs->bg_grad_n : 0;
