    if (n == NULL) { cvr_free(own); return parent; }
    n->own = *own;
    memset(own, 0, sizeof *own);
    n->chain.own = &n->own;
    n->chain.parent = parent;
    cache->vn[cache->nvn++] = n;
    return &n->chain;
