 * flat model, and auto keeps the intrinsic/attribute size (so the common
 * `img{max-width:100%;height:auto}` rule does not disturb it). This is layout,
 * not author colour, so it applies unconditionally (CLAUDE.md: layout != style).
 * An author rule therefore wins over the width/height presentation attribute,
 * matching the browser cascade. Regression it fixes: inline icons drawn at their

 * viewBox natural size (~100px) instead of the CSS 40px, blowing up flex rows. */
static void apply_css_replaced_size(lxb_dom_element_t *el, const css_sheet *sheet,
                                    pv_style_cache *cache, int *iw, int *ih) {
    const css_style *own = cached_element_style_ref(el, sheet, cache);
    if (own->width  > 0 && own->width  <= CSS_LEN_MAX) *iw = own->width;
    if (own->height > 0 && own->height <= CSS_LEN_MAX) *ih = own->height;
}

/* 1 when the element's height is a CSS px length (apply_css_replaced_size took it). */

 * unresolvable in this flat builder (no containing width in hand). box-sizing:border-box
 * (the near-universal reset) is honoured so the child fills the true content box. */
static int nearest_ancestor_content_width(const lxb_dom_node_t *n,
                                          const lxb_dom_node_t *base,
                                          const css_sheet *sheet,
                                          pv_style_cache *cache) {
    const lxb_dom_node_t *stop = (base != NULL) ? base->parent : NULL;
    for (const lxb_dom_node_t *p = (n != NULL) ? n->parent : NULL;
         p != NULL && p != stop; p = p->parent) {
        if (p->type != LXB_DOM_NODE_TYPE_ELEMENT) continue;
        lxb_dom_element_t *el = lxb_dom_interface_element((lxb_dom_node_t *)p);
        const css_style *st = cached_element_style_ref(el, sheet, cache);
        if (st->width > 0 && st->width <= CSS_LEN_MAX) {
            int w = st->width;
            if (st->box_sizing == CSS_BOXS_BORDER) {
                int pl = (st->pad_left  > 0) ? st->pad_left  : 0;
                int pr = (st->pad_right > 0) ? st->pad_right : 0;
                int bl = (st->border_left_width  > 0) ? st->border_left_width  : 0;
                int br = (st->border_right_width > 0) ? st->border_right_width : 0;
                w -= pl + pr + bl + br;
            }
            return (w > 0) ? w : 0;
        }
    }
    return 0;
}

/* Maps a css_justify (resolved by the css cascade) to a flex_layout fx_justify.
 * Unset / start / unknown all fall to FX_JUSTIFY_START (the default). */

static int css_to_fx_justify(css_justify j) {
    switch (j) {
        case CSS_JUSTIFY_END:           return FX_JUSTIFY_END;
        case CSS_JUSTIFY_CENTER:        return FX_JUSTIFY_CENTER;
        case CSS_JUSTIFY_SPACE_BETWEEN: return FX_JUSTIFY_SPACE_BETWEEN;
        case CSS_JUSTIFY_SPACE_AROUND:  return FX_JUSTIFY_SPACE_AROUND;
        case CSS_JUSTIFY_SPACE_EVENLY:  return FX_JUSTIFY_SPACE_EVENLY;
        case CSS_JUSTIFY_START:
        case CSS_JUSTIFY_UNSET:
        default:                        return FX_JUSTIFY_START;
    }
}

/* Inline emphasis carried by a tag: bold from <b>/<strong>/<th>, italic from
 * <i>/<em>. <th> is a header cell, conventionally bold. */
/* Tags the user-agent sheet renders bold. Headings belong here: making the UA bold
 * part of the RESOLVED weight is what lets an author turn it off -- the painter used
 * to force bold for every heading and only OR the author's value in, so
 * `h1{font-weight:normal}` was unrepresentable. */

static int is_bold_tag(lxb_tag_id_t t) {
    return t == LXB_TAG_B || t == LXB_TAG_STRONG || t == LXB_TAG_TH
        || t == LXB_TAG_H1 || t == LXB_TAG_H2 || t == LXB_TAG_H3
        || t == LXB_TAG_H4 || t == LXB_TAG_H5 || t == LXB_TAG_H6;
}

#define PV_MAX_INLINE_ROW_ITEMS 128   /* mirrors the layout engine's per-container item cap */

/* Inline-level box (CSS 2.1 9.2.2): display inline or inline-block, or a tag the UA
 * sheet makes inline, and not taken out of flow (which blockifies it). */

static int is_inline_level_style(lxb_tag_id_t t, const css_style *cs) {
    return !is_out_of_flow(cs) && cs->display != CSS_DISP_NONE
        && cs->display != CSS_DISP_FLEX && cs->display != CSS_DISP_GRID
        && (cs->display == CSS_DISP_INLINE_BLOCK || !is_block_like(t, cs->display));
}

/* True when `p` shares a line with inline content: a sibling that is non-blank text
 * or an inline-level element. */

static int in_mixed_line(const lxb_dom_node_t *p, const css_sheet *sheet,
                         pv_style_cache *cache) {
    if (p->parent == NULL) return 0;
    for (const lxb_dom_node_t *c = p->parent->first_child; c != NULL; c = c->next) {
        if (c == p) continue;
        if (c->type == LXB_DOM_NODE_TYPE_TEXT) {
            if (!text_node_is_blank(c)) return 1;
        } else if (c->type == LXB_DOM_NODE_TYPE_ELEMENT) {
            const css_style *ccs = cached_element_style_ref(
                lxb_dom_interface_element((lxb_dom_node_t *)c), sheet, cache);
            if (is_inline_level_style(node_tag(c), ccs)) return 1;
        }
    }
    return 0;
}

static int children_all_inline_block(const lxb_dom_node_t *p, const css_sheet *sheet,
                                     pv_style_cache *cache) {
    int nel = 0;
    for (const lxb_dom_node_t *c = p->first_child; c != NULL; c = c->next) {
        if (c->type == LXB_DOM_NODE_TYPE_TEXT) {
            if (!text_node_is_blank(c)) return 0;
        } else if (c->type == LXB_DOM_NODE_TYPE_ELEMENT) {
            lxb_dom_element_t *ce = lxb_dom_interface_element((lxb_dom_node_t *)c);
            const css_style *ccs = cached_element_style_ref(ce, sheet, cache);
            /* Not part of the line at all (CSS 2.1 9.7 / display:none): an
             * absolute overlay beside the inline-blocks does not stop them
             * forming their row. */
            if (ccs->display == CSS_DISP_NONE || ccs->position == CSS_POS_ABSOLUTE
                || ccs->position == CSS_POS_FIXED)
                continue;
            if (ccs->display != CSS_DISP_INLINE_BLOCK) return 0;
            if (++nel > PV_MAX_INLINE_ROW_ITEMS) return 0;
        }
    }
    return nel > 0;
}

/* True iff a column can have FREE space on its main axis: a px height or a px
 * min-height floor. Without one, auto margins distribute nothing, and block flow is
 * the same layout. Percentage heights are not resolved by this engine yet. */

static int col_has_free_space(const css_style *cs) {
    if (cs->min_height > 0) return 1;
    return cs->height > 0 && cs->height != CSS_LEN_AUTO && !CSS_LEN_IS_INTRINSIC(cs->height);
}

/* A flex COLUMN with the initial geometry (no reverse, no wrap, justify-content
 * start, align-items stretch) stacks full-width items one below the other: exactly
 * block flow. Such a container is not registered, so its items reach the full block
 * engine -- floats, boxes, margins, replaced rows -- instead of the column branch of
 * layout_container, which flowed bare text and lost every float on lobste.rs'
 * `body{display:flex;flex-direction:column}`. spec/page_view.md "Flex en COLUMNA". */

static int flex_column_flows_as_block(const lxb_dom_node_t *el, const css_style *cs,
                                      const css_sheet *sheet, pv_style_cache *cache) {
    if (!(cs->display == CSS_DISP_FLEX
          && cs->flex_direction == CSS_FD_COLUMN
          && (cs->flex_wrap == CSS_FW_UNSET || cs->flex_wrap == CSS_FW_NOWRAP)
          && (cs->justify == CSS_JUSTIFY_UNSET || cs->justify == CSS_JUSTIFY_START)
          && (cs->align_items == CSS_AK_UNSET || cs->align_items == CSS_AK_STRETCH)))
        return 0;
    /* `order` reorders a column too, and a per-item `align-self` other than
     * stretch shrink-wraps that item: either makes the column not block flow. */
    for (const lxb_dom_node_t *c = el->first_child; c != NULL; c = c->next) {
        if (c->type != LXB_DOM_NODE_TYPE_ELEMENT) continue;
        const css_style *ccs = cached_element_style_ref(lxb_dom_interface_element((lxb_dom_node_t *)c),
                                             sheet, cache);
        if (ccs->order != CSS_LEN_UNSET && ccs->order != 0) return 0;
        if (ccs->align_self != CSS_AK_UNSET && ccs->align_self != CSS_AK_AUTO &&
            ccs->align_self != CSS_AK_STRETCH) return 0;
        /* A growing item or a vertical auto margin (the sticky footer) does NOT
         * leave block flow: the column's free space is handed to the painter as
         * each child's share (col_free_share) and spent when the column's box
         * closes, so the page keeps the full block engine. */
    }
    return 1;
}

/* A child of a flex column that flows as plain block (see above) is still a

static void fold_column_gap(const lxb_dom_node_t *el, css_style *cs,
                            const css_sheet *sheet, pv_style_cache *cache) {
    const lxb_dom_node_t *par = el->parent;
    if (par == NULL || par->type != LXB_DOM_NODE_TYPE_ELEMENT) return;
    const css_style *pcs = cached_element_style_ref(lxb_dom_interface_element((lxb_dom_node_t *)par),
                                                    sheet, cache);
    if (pcs->gap <= 0 || pcs->display != CSS_DISP_FLEX ||
        pcs->flex_direction != CSS_FD_COLUMN)
        return;
    if (is_out_of_flow(cs) || cs->display == CSS_DISP_NONE) return;
    int prev = 0;
    for (const lxb_dom_node_t *c = el->prev; c != NULL && !prev; c = c->prev) {
        if (c->type != LXB_DOM_NODE_TYPE_ELEMENT) continue;
        const css_style *ccs = cached_element_style_ref(lxb_dom_interface_element((lxb_dom_node_t *)c),
                                                        sheet, cache);
        if (ccs->display != CSS_DISP_NONE && !is_out_of_flow(ccs)) prev = 1;
    }
    if (!prev || !flex_column_flows_as_block(par, pcs, sheet, cache)) return;
    int base = (cs->margin_top == CSS_LEN_UNSET || cs->margin_top == CSS_LEN_AUTO)
             ? 0 : cs->margin_top;
    cs->margin_top = base + pcs->gap;
}

/* Cheap prefilter: could fold_column_gap change this element's style? Only under a column flex
 * parent with a gap. resolve_context copies the (7 KB) style just when this is true. */

static int column_gap_candidate(const lxb_dom_node_t *el, const css_sheet *sheet,
                                pv_style_cache *cache) {
    const lxb_dom_node_t *par = el->parent;
    if (par == NULL || par->type != LXB_DOM_NODE_TYPE_ELEMENT) return 0;
    const css_style *pcs = cached_element_style_ref(lxb_dom_interface_element((lxb_dom_node_t *)par),
                                                    sheet, cache);
    return pcs->gap > 0 && pcs->display == CSS_DISP_FLEX && pcs->flex_direction == CSS_FD_COLUMN;
}

/* A flex/grid container that lays its children out itself (see above). */

static int is_layout_container(const lxb_dom_node_t *el, const css_style *cs,
                               const css_sheet *sheet, pv_style_cache *cache) {
    return (cs->display == CSS_DISP_FLEX
            && !flex_column_flows_as_block(el, cs, sheet, cache))
        || cs->display == CSS_DISP_GRID;
}

/* An element with a declared width (or max-width) needs a box even with no
 * decoration: the width bounds EVERYTHING inside it, nested boxes included, and
 * only a box can carry that to them. Without one, `.container{max-width:48rem;
 * margin:0 auto}` -- the page wrapper of every CSS framework -- capped its own text
 * runs but let a decorated child box span the whole page; and a flex item's size
 * (`.meter{width:280px}` in a centring column) had nowhere to be read from
 * (spec/page_view.md, tanda 40). */
/* A flex/grid ITEM: its parent element is a layout container. Such an item is
 * blockified whatever its display says (CSS Display 3 2.7, Flexbox 4). */
static int is_layout_item(const lxb_dom_node_t *el, const css_sheet *sheet,
                          pv_style_cache *cache) {
    const lxb_dom_node_t *par = el->parent;
    if (par == NULL || par->type != LXB_DOM_NODE_TYPE_ELEMENT) return 0;
    const css_style *pcs = cached_element_style_ref(
        lxb_dom_interface_element((lxb_dom_node_t *)par), sheet, cache);
    return is_layout_container(par, pcs, sheet, cache);
}

/* A non-zero horizontal margin, either half. */

static int css_has_hmargin(const css_style *cs) {
    return (cs->margin_left != CSS_LEN_UNSET && cs->margin_left != CSS_LEN_AUTO &&
            cs->margin_left != 0) ||
           (cs->margin_right != CSS_LEN_UNSET && cs->margin_right != CSS_LEN_AUTO &&
            cs->margin_right != 0) ||
           cs->pct[CSS_PCT_MARGIN_LEFT] != 0 || cs->pct[CSS_PCT_MARGIN_RIGHT] != 0;
}

/* An INLINE element whose box model changes the line: horizontal padding, border or
 * margin (CSS 2.1 8.1, 10.3.1 -- they apply to inline boxes and move the text around
 * them), or a background that needs a shape (radius, vertical padding, a border).
 * A bare background alone stays on the per-fragment fill, which is the common
 * `<code>`/`<mark>` case and needs no box. */
static int css_inline_boxdeco(const css_style *cs) {
    int hpad = (cs->pad_left != CSS_LEN_UNSET && cs->pad_left > 0) ||
               (cs->pad_right != CSS_LEN_UNSET && cs->pad_right > 0) ||
               cs->pct[CSS_PCT_PAD_LEFT] > 0 || cs->pct[CSS_PCT_PAD_RIGHT] > 0;
    int vpad = (cs->pad_top != CSS_LEN_UNSET && cs->pad_top > 0) ||
               (cs->pad_bottom != CSS_LEN_UNSET && cs->pad_bottom > 0);
    int border = (cs->border_left_width != CSS_LEN_UNSET && cs->border_left_width > 0) ||
                 (cs->border_right_width != CSS_LEN_UNSET && cs->border_right_width > 0) ||
                 (cs->border_top_width != CSS_LEN_UNSET && cs->border_top_width > 0) ||
                 (cs->border_bottom_width != CSS_LEN_UNSET && cs->border_bottom_width > 0);
    int bg = (cs->background >= 0 && (cs->bg_alpha == CSS_LEN_U

static int item_sizes_itself(const lxb_dom_node_t *el, const css_style *cs,
                             const css_sheet *sheet, pv_style_cache *cache) {
    if (!(cs->width > 0 || cs->pct[CSS_PCT_WIDTH] > 0 ||
          cs->max_width > 0 || cs->pct[CSS_PCT_MAX_WIDTH] > 0))
        return 0;
    if (is_layout_item(el, sheet, cache)) return 1;
    /* Otherwise only a BLOCK-level box: an inline-block with a width is an atom of
     * its line, sized on its run, and a box here would break the line around it. */
    if (cs->display == CSS_DISP_INLINE_BLOCK || cs->display == CSS_DISP_INLINE)
        return 0;
    return is_block_like_style(node_tag(el), cs);
}

/* A marker is generated by a `display:list-item` box (CSS Lists 3 3.1), which is
 * what the UA sheet makes an <li>; an author display (inline-block chips, a flex
 * nav) removes it. */

static int li_is_list_item(const lxb_dom_node_t *li, const css_sheet *sheet,
                           pv_style_cache *cache) {
    const css_style *lcs = cached_element_style_ref(lxb_dom_interface_element((lxb_dom_node_t *)li),
                                         sheet, cache);
    return lcs->display == CSS_DISP_UNSET || lcs->display == CSS_DISP_LIST_ITEM;
}

/* The anonymous row is a BLOCK-level box, so only a parent that may be one gets it.
 * An inline-level parent (inline / inline-block) sitting in its own parent's mixed
 * line is an atom of that line (CSS 2.1 9.2.2): a row there split lobste.rs' story
 * title from its domain. It stays a row when its own parent is itself a row of
 * inline-blocks (it is then an item of that row, a nested container). */
static int is_inline_block_row(const lxb_dom_node_t *p, const css_sheet *sheet,
                               pv_style_cache *cache) {
    if (!children_all_inline_block(p, sheet, cache)) return 0;
    if (p->type != LXB_DOM_NODE_TYPE_ELEMENT) return 1;
    const css_style *pcs = cached_element_style_ref(lxb_dom_interface_element((lxb_dom_node_t *)p),
                                         sheet, cache);
    if (!is_inline_level_style(node_tag(p), pcs)) return 1;
    const lxb_dom_node_t *gp = p->parent;
    if (gp == NULL || gp->type != LXB_DOM_NODE_TYPE_ELEMENT) return 1;
    return children_all_inline_block(gp, sheet, cache);
}

/* True iff an element has NO IN-FLOW content of its own: no in-flow child elements
 * and no non-whitespace text. Such a decorated element (a styled bar, spacer, tile,
 * icon) is

static int pv_element_has_before(lxb_dom_node_t *n, const css_sheet *sheet,
                                 pv_style_cache *cache) {
    const css_style *ecs = cached_element_style_ref(lxb_dom_interface_element(n), sheet, cache);
    if (ecs->content_before_str[0] != '\0') return 1;
    /* `content:""` generates a BOX when the pseudo has a style of its own (a glow, a frame,
     * an aspect-ratio spacer): the string is empty but the element does own ::before. A host
     * with no text of its own has no text node to fire it from. */
    if (!ecs->content_before_on) return 0;
    css_style bps = cached_pseudo_style(lxb_dom_interface_element(n), sheet, cache,
                                        CSS_PSEUDO_BEFORE);
    return bps.display != CSS_DISP_NONE && pseudo_generates_box(&bps);
}

/* Depth cap for subtree_has_own_text: attacker-controlled nesting fails open to
 * "has text", i.e. the pre-existing behavior (no entry emission). */

#define PV_TEXTLESS_DEPTH_MAX 64

/* Skip predicates defined further down (used before their definitions). */
static int in_hidden_subtree(const lxb_dom_node_t *n, const lxb_dom_node_t *base,
                             const css_sheet *sheet, pv_style_cache *style_cache,
                             int js_enabled);
static int in_closed_details_subtree(const lxb_dom_node_t *n,
                                     const lxb_dom_node_t *base);
static int in_boilerplate_subtree(const lxb_dom_node_t *n,
                                  const lxb_dom_node_t *base);

/* True when the subtree holds no non-blank text of its own outside skipped /
 * hidden / closed-details subtrees -- exactly the text the walk could ever visit
 * (blank text is skipped at emit, hidden/skipped/closed text never is). Lets an
 * element whose only content would be generated (::before on an icon wrapper
 * holding one empty span) emit it at entry; with own text the text-node path
 * stays the single emitter, so double emission is impossible by construction. */

static int subtree_has_own_text(const lxb_dom_node_t *n, const lxb_dom_node_t *base,
                                const css_sheet *sheet, pv_style_cache *cache,
                                int js_enabled, int reader, int depth) {
    if (depth > PV_TEXTLESS_DEPTH_MAX) return 1;
    for (const lxb_dom_node_t *c = n->first_child; c != NULL; c = c->next) {
        if (c->type == LXB_DOM_NODE_TYPE_TEXT) {
            if (!text_node_is_blank(c)) return 1;
            continue;
        }
        if (c->type != LXB_DOM_NODE_TYPE_ELEMENT) continue;
        if (in_skipped_subtree(c, base, js_enabled)) continue;
        if (in_hidden_subtree(c, base, sheet, cache, js_enabled)) continue;
        if (in_closed_details_subtree(c, base)) continue;
        if (reader && in_boilerplate_subtree(c, base)) continue;
        if (subtree_has_own_text(c, base, sheet, cache, js_enabled, reader, depth + 1))
            return 1;
    }
    return 0;
}

/* A plain wrapper: a generic container with no decoration and no size of its own, so
 * it adds nothing to its parent's geometry (a `<div>` around an absolute <video>). */

static int is_plain_wrapper(const lxb_dom_node_t *c, const css_style *cs) {
    switch (lxb_dom_node_tag_id((lxb_dom_node_t *)c)) {
        case LXB_TAG_DIV: case LXB_TAG_SPAN: case LXB_TAG_SECTION: case LXB_TAG_ARTICLE:
        case LXB_TAG_HEADER: case LXB_TAG_FOOTER: case LXB_TAG_ASIDE: case LXB_TAG_FIGURE:
            break;
        default:
            return 0;
    }
    return !css_has_boxdeco(cs) && cs->height <= 0 && cs->min_height <= 0 && cs->width <= 0 &&
           cs->aspect_num <= 0;
}

static int element_is_content_leaf_d(const lxb_dom_node_t *n, const css_sheet *sheet,
                                     pv_style_cache *cache, int depth) {
    for (const lxb_dom_node_t *c = n->first_child; c != NULL; c = c->next) {
        if (c->type == LXB_DOM_NODE_TYPE_ELEMENT) {
            lxb_dom_element_t *ce = lxb_dom_interface_element((lxb_dom_node_t *)c);
            const css_style *ccs = cached_element_style_ref(ce, sheet, cache);
            if (ccs->display == CSS_DISP_NONE) continue;
            if (ccs->position == CSS_POS_ABSOLUTE || ccs->position == CSS_POS_FIXED) continue;
            /* Out-of-flow content is not content of the box: a wrapper holding only
             * such children contributes nothing either, so the frame around it is as
             * empty as if the wrapper were not there (CSS 2.1 9.3.1: the box exists
             * whatever its content). */
            if (depth < PV_TEXTLESS_DEPTH_MAX && is_plain_wrapper(c, ccs) &&
                element_is_content_leaf_d(c, sheet, cache, depth + 1))
                continue;
            return 0;
        }
        if (c->type == LXB_DOM_NODE_TYPE_TEXT && !text_node_is_blank(c)) return 0;
    }
    return 1;
}

/* Whether a <video>/<audio> names anything to play: its own `src`, or a <source> child
 * with one. A source-less element has no frame to show but still has its CSS BOX (a
 * `background-color` placeholder, a radius, a declared size), exactly like any empty
 * decorated element -- so it must reach the empty-box path instead of vanishing. */

static int media_has_source(const lxb_dom_node_t *n) {
    size_t sl = 0;
    lxb_dom_element_t *el = lxb_dom_interface_element((lxb_dom_node_t *)n);
    if (lxb_dom_element_get_attribute(el, (const lxb_char_t *)"src", 3, &sl) != NULL && sl > 0)
        return 1;
    for (const lxb_dom_node_t *ch = n->first_child; ch != NULL; ch = ch->next) {
        if (ch->type != LXB_DOM_NODE_TYPE_ELEMENT || node_tag(ch) != LXB_TAG_SOURCE) continue;
        lxb_dom_element_t *sel = lxb_dom_interface_element((lxb_dom_node_t *)ch);
        if (lxb_dom_element_get_attribute(sel, (const lxb_char_t *)"src", 3, &sl) != NULL && sl > 0)
            return 1;
    }
    return 0;
}

static int element_is_content_leaf(const lxb_dom_node_t *n, const css_sheet *sheet,
                                   pv_style_cache *cache) {
    return element_is_content_leaf_d(n, sheet, cache, 0);
}

/* Nonzero when cell (a td/th) is a WALKED cell of a FLOW table (defined after the
 * flow-table machinery below): such a cell's content shares its ROW's line, so the
 * cell must not carry its own box (the painter flushes the line at every box
 * transition -- a per-cell box would split the row). */

struct pv_flow_reg;
static bx_table_role node_table_role(const lxb_dom_node_t *n, const struct pv_flow_reg *fr);
static int in_flow_table_cell(const lxb_dom_node_t *cell, const lxb_dom_node_t *base,
                              struct pv_flow_reg *fr);

static void resolve_context(const lxb_dom_node_t *n, const lxb_dom_node_t *base,
                            const css_sheet *sheet,
                            const char **href, size_t *href_len,
                            const lxb_dom_node_t **block, int *heading,
                            int *fg, int *bg, int *bold, int *italic,
                            int *align, int *font_scale, int *font_abs,
                            int *line_scale, int *deco,
                            const lxb_dom_node_t **li, int *list_depth, int *ordered,
                            pv_container_reg *reg, pv_cont_info *cont, pv_box_info *box,
                            pv_text_ext *ext, pv_box_reg *box_reg,
                            pv_container_reg *float_reg, int *block_id_out,
                            pv_style_cache *style_cache, struct pv_flow_reg *flowreg) {
    *href = NULL; *href_len = 0; *block = base; *heading = 0; *fg = -1; *bg = -1;
    *bold = 0; *italic = 0; *align = CSS_ALIGN_UNSET; *font_scale = 0; *font_abs = 0;
    *line_scale = 0;
    *deco = -1;
