void pv_root_insets(const css_style *body, int out[4]) {
    if (out == NULL) return;
    const int side[4] = { body->margin_top, body->margin_right,
                          body->margin_bottom, body->margin_left };
    const int pct[4] = { body->pct[CSS_PCT_MARGIN_TOP], body->pct[CSS_PCT_MARGIN_RIGHT],
                         body->pct[CSS_PCT_MARGIN_BOTTOM], body->pct[CSS_PCT_MARGIN_LEFT] };
    for (int k = 0; k < 4; ++k)
        out[k] = (side[k] == CSS_LEN_UNSET && pct[k] == 0) ? PV_UA_BODY_MARGIN : 0;
}

static char *collect_page_css(lxb_dom_node_t *root, const char *extern_css,
                              size_t extern_len, size_t *outlen) {
    size_t style_len = 0;
    char *style_text = collect_style_text(root, &style_len);
    if (extern_css != NULL && extern_len != 0) {
        if (extern_len > PV_MAX_STYLE_BYTES) extern_len = PV_MAX_STYLE_BYTES;
        size_t dlen = style_len;
        if (dlen > PV_MAX_STYLE_BYTES - extern_len) dlen = PV_MAX_STYLE_BYTES - extern_len;
        if (extern_len != (size_t)-1 && dlen != (size_t)-1) {
            char *comb = (char *)malloc(extern_len + 1 + dlen + 1);
            if (comb != NULL) {
                memcpy(comb, extern_css, extern_len);
                comb[extern_len] = '\n';
                if (dlen != 0) memcpy(comb + extern_len + 1, style_text, dlen);
                comb[extern_len + 1 + dlen] = '\0';
                free(style_text);
                style_text = comb;
                style_len = extern_len + 1 + dlen;
            }
        }
    }
    /* The UA layer goes FIRST of everything, external sheets included: a layer's
     * rank is the order of its first declaration. */
    char *ua = prepend_ua_css(style_text, &style_len);
    if (ua != NULL) { free(style_text); style_text = ua; }
    *outlen = style_len;
    return style_text;
}

