    int prev_us = 0; /* the previous emitted byte was a collapsed '_' */

    if (title != NULL) {
        for (size_t i = 0; title[i] != '\0' && n < PE_NAME_MAX; ++i) {
            unsigned char c = (unsigned char)title[i];
            if (pe_is_kept(c)) {
                tmp[n++] = (char)c;
                prev_us = 0;
            } else if (!prev_us) {
                tmp[n++] = '_'; /* map any other byte to '_', collapsing runs */
                prev_us = 1;
            }
        }
    }
    tmp[n] = '\0';

    size_t start = 0;
    while (start < n && pe_is_edge((unsigned char)tmp[start])) ++start;
    size_t end = n;
    while (end > start && pe_is_edge((unsigned char)tmp[end - 1])) --end;

    const char *name = tmp + start;
    size_t name_len = end - start;
    if (name_len == 0) {
        name = PE_FALLBACK_NAME;
        name_len = strlen(PE_FALLBACK_NAME);
    }

    if (name_len + 1 > outsz) { out[0] = '\0'; return PE_ERR_OVERFLOW; }
    memcpy(out, name, name_len);
    out[name_len] = '\0';
    return PE_OK;
}

pe_status pe_build_path_ext(const char *dir, const char *title, const char *ext,
                            char *out, size_t outsz) {
    if (dir == NULL || out == NULL || outsz == 0) return PE_ERR_NULL_ARG;
    if (ext == NULL) ext = "";

    char base[PE_NAME_MAX + 1];
    pe_status st = pe_safe_basename(title, base, sizeof base);
    if (st != PE_OK) { out[0] = '\0'; return st; } /* base always fits PE_NAME_MAX+1 */

    size_t dlen = strlen(dir);
    int need_slash = (dlen > 0 && dir[dlen - 1] != '/');
    size_t blen = strlen(base);
    size_t extlen = strlen(ext);
    size_t total = dlen + (size_t)(need_slash ? 1 : 0) + blen + extlen; /* excl. NUL */
    if (total + 1 > outsz) { out[0] = '\0'; return PE_ERR_OVERFLOW; }

    size_t pos = 0;
    memcpy(out + pos, dir, dlen); pos += dlen;
    if (need_slash) out[pos++] = '/';
    memcpy(out + pos, base, blen); pos += blen;
    memcpy(out + pos, ext, extlen); pos += extlen;
    out[pos] = '\0';
    return PE_OK;
}

pe_status pe_build_path(const char *dir, const char *title, char *out, size_t outsz) {
    return pe_build_path_ext(dir, title, PE_EXT, out, outsz);
}

size_t pe_paginate(const double *tops, const double *heights, size_t n,
                   double page_h, int *out_page, double *out_page_y) {
    if (tops == NULL || heights == NULL || out_page == NULL || out_page_y == NULL) return 0;
    if (n == 0 || page_h <= 0.0) return 0;

    int page = 0;
    double offset = 0.0; /* document-Y mapped to the top (y == 0) of the current page */
    for (size_t i = 0; i < n; ++i) {
        double y = tops[i] - offset;
        /* Break to a fresh page only if the row would overflow AND is not already
         * at the page top (an oversized row keeps its own page and overflows). */
        if (y > 0.0 && y + heights[i] > page_h) {
            ++page;
            offset = tops[i];
            y = 0.0;
        }
        out_page[i] = page;
        out_page_y[i] = y;
    }
    return (size_t)page + 1;
}

void pt_init(pt_trace *t) {
    if (!t) return;
    memset(t, 0, sizeof(*t));
}

uint64_t pt_elapsed_us(uint64_t start_us, uint64_t end_us) {
    if (end_us < start_us) return 0;
    return end_us - start_us;
}

void pt_record(pt_trace *t, pt_stage stage, uint64_t elapsed_us) {
    if (!t || !stage_valid(stage)) return;
    pt_stage_stats *s = &t->stage[stage];
    s->samples[s->next] = elapsed_us;
    s->next = (s->next + 1) % PT_MAX_SAMPLES;
    if (s->fill < PT_MAX_SAMPLES) s->fill++;
    s->total++;
}

size_t pt_count(const pt_trace *t, pt_stage stage) {
    if (!t || !stage_valid(stage)) return 0;
    return t->stage[stage].fill;
}

uint64_t pt_last_us(const pt_trace *t, pt_stage stage) {
    if (!t || !stage_valid(stage)) return 0;
    const pt_stage_stats *s = &t->stage[stage];
    if (s->fill == 0) return 0;
    /* next points one past the most recently written slot (with wrap) */
    size_t last_idx = (s->next + PT_MAX_SAMPLES - 1) % PT_MAX_SAMPLES;
    return s->samples[last_idx];
}

uint64_t pt_min_us(const pt_trace *t, pt_stage stage) {
    if (!t || !stage_valid(stage)) return 0;
    const pt_stage_stats *s = &t->stage[stage];
    if (s->fill == 0) return 0;
    uint64_t m = s->samples[0];
    for (size_t i = 1; i < s->fill; ++i) {
        if (s->samples[i] < m) m = s->samples[i];
    }
    return m;
}

uint64_t pt_max_us(const pt_trace *t, pt_stage stage) {
    if (!t || !stage_valid(stage)) return 0;
    const pt_stage_stats *s = &t->stage[stage];
    if (s->fill == 0) return 0;
    uint64_t m = s->samples[0];
    for (size_t i = 1; i < s->fill; ++i) {
        if (s->samples[i] > m) m = s->samples[i];
    }
    return m;
}

static int cmp_u64(const void *a, const void *b) {
    uint64_t x = *(const uint64_t *)a;
    uint64_t y = *(const uint64_t *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

uint64_t pt_median_us(const pt_trace *t, pt_stage stage) {
    if (!t || !stage_valid(stage)) return 0;
    const pt_stage_stats *s = &t->stage[stage];
    if (s->fill == 0) return 0;
    uint64_t sorted[PT_MAX_SAMPLES];
    memcpy(sorted, s->samples, s->fill * sizeof(uint64_t));
    qsort(sorted, s->fill, sizeof(uint64_t), cmp_u64);
    return sorted[s->fill / 2];
}

const char *pt_stage_name(pt_stage stage) {
    switch (stage) {
        case PT_FETCH:    return "fetch";
        case PT_PARSE:    return "parse";
        case PT_STYLE:    return "style";
        case PT_IPC:      return "ipc";
        case PT_RD_BUILD: return "rd_build";
        case PT_LAYOUT:   return "layout";
        case PT_PAINT:    return "paint";
        case PT_COMMIT:   return "commit";
        case PT_SHAPE:    return "shape";
        default:          return "unknown";
    }
}

/* Upper bound on one formatted line: longest stage name ("rd_build", 8) plus
 * five uint64_t fields (<=20 digits each) and literal text comfortably fits
 * in 160 bytes; verified by construction, not by truncation. */

size_t pt_format(const pt_trace *t, char *buf, size_t cap) {
    if (!t || !buf || cap == 0) return 0;
    size_t n = 0;
    for (int st = 0; st < PT_STAGE_COUNT; ++st) {
        size_t cnt = pt_count(t, (pt_stage)st);
        if (cnt == 0) continue;

        char line[PT_LINE_CAP];
        int r = snprintf(line, sizeof(line),
                          "stage=%s n=%zu last_us=%llu min_us=%llu max_us=%llu median_us=%llu\n",
                          pt_stage_name((pt_stage)st),
                          t->stage[st].total,
                          (unsigned long long)pt_last_us(t, (pt_stage)st),
                          (unsigned long long)pt_min_us(t, (pt_stage)st),
                          (unsigned long long)pt_max_us(t, (pt_stage)st),
                          (unsigned long long)pt_median_us(t, (pt_stage)st));
        if (r < 0) break; /* formatting error: fail-closed, stop here */
        size_t len = (size_t)r;
        if (len >= sizeof(line)) len = sizeof(line) - 1; /* defensive clamp */

        /* Only commit this line to buf if it (plus its NUL) fits within cap.
         * This never partially copies a line into the caller's buffer, so
         * buf[n] is always the '\0' right after the last COMPLETE line. */
        if (n + len >= cap) break;
        memcpy(buf + n, line, len);
        n += len;
    }
    buf[n] = '\0';
    return n;
}

struct pqs_keys {
    EVP_PKEY *pkey;
};

void pqs_buf_free(uint8_t *buf, size_t len) {
    if (buf == NULL) return;
    OPENSSL_cleanse(buf, len);
    free(buf);
}

void pqs_free(pqs_keys *k) {
    if (k == NULL) return;
    EVP_PKEY_free(k->pkey);
    free(k);
}

static pqs_keys *keys_wrap(EVP_PKEY *pkey) {
    pqs_keys *k = (pqs_keys *)calloc(1, sizeof *k);
    if (k == NULL) { EVP_PKEY_free(pkey); return NULL; }
    k->pkey = pkey;
    return k;
}

pqs_status pqs_generate(pqs_keys **out) {
    if (out == NULL) return PQS_ERR_NULL_ARG;
    *out = NULL;
    EVP_PKEY_CTX *c = EVP_PKEY_CTX_new_from_name(NULL, "ML-KEM-512", NULL);
    if (c == NULL) return PQS_ERR_CRYPTO;
    EVP_PKEY *pk = NULL;
    int ok = EVP_PKEY_keygen_init(c) == 1 && EVP_PKEY_keygen(c, &pk) == 1;
    EVP_PKEY_CTX_free(c);
    if (!ok || pk == NULL) { EVP_PKEY_free(pk); return PQS_ERR_CRYPTO; }
    *out = keys_wrap(pk);
    return *out != NULL ? PQS_OK : PQS_ERR_OOM;
}

pqs_status pqs_export(const pqs_keys *k, uint8_t **der, size_t *len) {
    if (k == NULL || der == NULL || len == NULL) return PQS_ERR_NULL_ARG;
    *der = NULL; *len = 0;
    int n = i2d_PrivateKey(k->pkey, NULL);
    if (n <= 0) return PQS_ERR_CRYPTO;
    uint8_t *buf = (uint8_t *)malloc((size_t)n);
    if (buf == NULL) return PQS_ERR_OOM;
    uint8_t *p = buf;
    if (i2d_PrivateKey(k->pkey, &p) != n) { pqs_buf_free(buf, (size_t)n); return PQS_ERR_CRYPTO; }
    *der = buf; *len = (size_t)n;
    return PQS_OK;
}

pqs_status pqs_import(const uint8_t *der, size_t len, pqs_keys **out) {
    if (der == NULL || out == NULL) return PQS_ERR_NULL_ARG;
    *out = NULL;
    if (len == 0 || len > (1u << 16)) return PQS_ERR_CRYPTO;
    const uint8_t *p = der;
    EVP_PKEY *pk = d2i_AutoPrivateKey(NULL, &p, (long)len);
    if (pk == NULL) return PQS_ERR_CRYPTO;
    if (EVP_PKEY_is_a(pk, "ML-KEM-512") != 1) { EVP_PKEY_free(pk); return PQS_ERR_CRYPTO; }
    *out = keys_wrap(pk);
    return *out != NULL ? PQS_OK : PQS_ERR_OOM;
}

/* HKDF-SHA256 over ss || wrap: the AEAD key. */

static int derive_key(const uint8_t ss[PQS_SS_LEN], const uint8_t wrap[LS_KEY_LEN],
                      uint8_t key[LS_KEY_LEN]) {
    uint8_t ikm[PQS_SS_LEN + LS_KEY_LEN];
    memcpy(ikm, ss, PQS_SS_LEN);
    memcpy(ikm + PQS_SS_LEN, wrap, LS_KEY_LEN);
    EVP_KDF *kdf = EVP_KDF_fetch(NULL, "HKDF", NULL);
    if (kdf == NULL) { OPENSSL_cleanse(ikm, sizeof ikm); return -1; }
    EVP_KDF_CTX *kc = EVP_KDF_CTX_new(kdf);
    EVP_KDF_free(kdf);
    if (kc == NULL) { OPENSSL_cleanse(ikm, sizeof ikm); return -1; }
    OSSL_PARAM params[5];
    char digest[] = "SHA256";
    char salt[] = "freedom-pqseal-v1";
    char info[] = "aead-key";
    params[0] = OSSL_PARAM_construct_utf8_string(OSSL_KDF_PARAM_DIGEST, digest, 0);
    params[1] = OSSL_PARAM_construct_octet_string(OSSL_KDF_PARAM_KEY, ikm, sizeof ikm);
    params[2] = OSSL_PARAM_construct_octet_string(OSSL_KDF_PARAM_SALT, salt, sizeof salt - 1);
    params[3] = OSSL_PARAM_construct_octet_string(OSSL_KDF_PARAM_INFO, info, sizeof info - 1);
    params[4] = OSSL_PARAM_construct_end();
    int ok = EVP_KDF_derive(kc, key, LS_KEY_LEN, params) == 1;
    EVP_KDF_CTX_free(kc);
    OPENSSL_cleanse(ikm, sizeof ikm);
    return ok ? 0 : -1;
}

pqs_status pqs_seal(const pqs_keys *k, const uint8_t wrap[LS_KEY_LEN],
                    const uint8_t *pt, size_t pt_len, uint8_t **out, size_t *out_len) {
    if (k == NULL || wrap == NULL || out == NULL || out_len == NULL || (pt == NULL && pt_len != 0))
        return PQS_ERR_NULL_ARG;
    *out = NULL; *out_len = 0;
    if (pt_len > LS_MAX_PLAINTEXT) return PQS_ERR_TOO_LARGE;

    EVP_PKEY_CTX *c = EVP_PKEY_CTX_new_from_pkey(NULL, k->pkey, NULL);
    if (c == NULL) return PQS_ERR_CRYPTO;
    size_t ctl = 0, ssl = 0;
    uint8_t ct[PQS_CT_LEN], ss[PQS_SS_LEN];
    int ok = EVP_PKEY_encapsulate_init(c, NULL) == 1
          && EVP_PKEY_encapsulate(c, NULL, &ctl, NULL, &ssl) == 1
          && ctl == PQS_CT_LEN && ssl == PQS_SS_LEN
          && EVP_PKEY_encapsulate(c, ct, &ctl, ss, &ssl) == 1;
    EVP_PKEY_CTX_free(c);
    if (!ok) return PQS_ERR_CRYPTO;

    uint8_t key[LS_KEY_LEN];
    int dk = derive_key(ss, wrap, key);
    OPENSSL_cleanse(ss, sizeof ss);
    if (dk != 0) return PQS_ERR_CRYPTO;

    uint8_t *body = NULL;
    size_t blen = 0;
    ls_status ls = ls_seal(key, LS_AEAD_CHACHA20_POLY1305, pt, pt_len, &body, &blen);
    OPENSSL_cleanse(key, sizeof key);
    if (ls != LS_OK) return ls == LS_ERR_OOM ? PQS_ERR_OOM : PQS_ERR_CRYPTO;

    size_t total = PQS_MAGIC_LEN + PQS_CT_LEN + blen;
    if (total < blen) { ls_free(body, blen); return PQS_ERR_TOO_LARGE; }
    uint8_t *blob = (uint8_t *)malloc(total);
    if (blob == NULL) { ls_free(body, blen); return PQS_ERR_OOM; }
    memcpy(blob, PQS_MAGIC, PQS_MAGIC_LEN);
    memcpy(blob + PQS_MAGIC_LEN, ct, PQS_CT_LEN);

pqs_status pqs_open(const pqs_keys *k, const uint8_t wrap[LS_KEY_LEN],
                    const uint8_t *in, size_t in_len, uint8_t **out, size_t *out_len) {
    if (k == NULL || wrap == NULL || in == NULL || out == NULL || out_len == NULL)
        return PQS_ERR_NULL_ARG;
    *out = NULL; *out_len = 0;
    if (in_len < PQS_MAGIC_LEN + PQS_CT_LEN + LS_OVERHEAD
        || memcmp(in, PQS_MAGIC, PQS_MAGIC_LEN) != 0)
        return PQS_ERR_FORMAT;

    EVP_PKEY_CTX *c = EVP_PKEY_CTX_new_from_pkey(NULL, k->pkey, NULL);
    if (c == NULL) return PQS_ERR_CRYPTO;
    uint8_t ss[PQS_SS_LEN];
    size_t ssl = sizeof ss;
    /* ML-KEM decapsulation never fails on a wrong ciphertext (implicit rejection): it yields a
     * pseudo-random secret, so the AEAD tag below is what reports the mismatch. */
    int ok = EVP_PKEY_decapsulate_init(c, NULL) == 1
          && EVP_PKEY_decapsulate(c, ss, &ssl, in + PQS_MAGIC_LEN, PQS_CT_LEN) == 1
          && ssl == PQS_SS_LEN;
    EVP_PKEY_CTX_free(c);
    if (!ok) return PQS_ERR_AUTH;

    uint8_t key[LS_KEY_LEN];
    int dk = derive_key(ss, wrap, key);
    OPENSSL_cleanse(ss, sizeof ss);
    if (dk != 0) return PQS_ERR_CRYPTO;

    uint8_t *pt = NULL;
    size_t ptl = 0;
    ls_status ls = ls_open(key, in + PQS_MAGIC_LEN + PQS_CT_LEN,
                           in_len - PQS_MAGIC_LEN - PQS_CT_LEN, &pt, &ptl);
    OPENSSL_cleanse(key, sizeof key);
    if (ls == LS_ERR_FORMAT) return PQS_ERR_FORMAT;
    if (ls == LS_ERR_OOM) return PQS_ERR_OOM;
    if (ls != LS_OK) return PQS_ERR_AUTH;
    *out = pt; *out_len = ptl;
    return PQS_OK;
}

#define _POSIX_C_SOURCE 200809L

#include "prefetch.h"
#include "url.h"
#include "import_map.h"

#include <stdlib.h>
#include <string.h>
#include <strings.h>

/* Longest raw reference the scanner keeps; matches URL_MAX_LEN (url.h) so a
 * ref the fetch path would reject on length is never even queued. */

static int is_ws(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
}

static int is_name_char(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
           (c >= '0' && c <= '9') || c == '-';
}

static int lower(int c) {
    return (c >= 'A' && c <= 'Z') ? c + ('a' - 'A') : c;
}

/* Case-insensitive: [p,end) starts with kw. */

static int ci_starts(const char *p, const char *end, const char *kw) {
    for (size_t i = 0; kw[i] != '\0'; ++i) {
        if (p + i >= end || lower((unsigned char)p[i]) != (unsigned char)kw[i])
            return 0;
    }
    return 1;
}

/* First case-insensitive occurrence of kw in [p,end), or NULL. */

static const char *ci_find(const char *p, const char *end, const char *kw) {
    size_t n = strlen(kw);
    while (p + n <= end) {
        if (ci_starts(p, end, kw)) return p;
        p++;
    }
    return NULL;
}

static int ci_eq_span(const char *s, size_t n, const char *kw) {
    if (strlen(kw) != n) return 0;
    for (size_t i = 0; i < n; ++i)
        if (lower((unsigned char)s[i]) != (unsigned char)kw[i]) return 0;
    return 1;
}

typedef struct attr_span {
    const char *name; size_t nlen;
    const char *val;  size_t vlen;   /* val NULL when the attribute is bare */
} attr_span;

/* Reads one attribute at *pp inside a tag. Returns 1 and advances past it, or
 * 0 when the tag ends (*pp is then just past '>' or at end). Never stalls: the
 * cursor strictly advances on every path. */
static int next_attr(const char **pp, const char *end, attr_span *a) {
    const char *p = *pp;
    while (p < end && (is_ws(*p) || *p == '/')) p++;
    if (p >= end) { *pp = p; return 0; }
    if (*p == '>') { *pp = p + 1; return 0; }

    a->name = p;
    while (p < end && *p != '=' && *p != '>' && *p != '/' && !is_ws(*p)) p++;
    a->nlen = (size_t)(p - a->name);
    if (a->nlen == 0) { *pp = p + 1; a->val = NULL; a->vlen = 0; return 1; }

    while (p < end && is_ws(*p)) p++;
    if (p < end && *p == '=') {
        p++;
        while (p < end && is_ws(*p)) p++;
        if (p < end && (*p == '"' || *p == '\'')) {
            char q = *p++;
            a->val = p;
            while (p < end && *p != q) p++;
            a->vlen = (size_t)(p - a->val);
            if (p < end) p++;
        } else {
            a->val = p;
            while (p < end && !is_ws(*p) && *p != '>') p++;
            a->vlen = (size_t)(p - a->val);
        }
    } else {
        a->val = NULL;
        a->vlen = 0;
    }
    *pp = p;
    return 1;

static void emit(pf_list *out, pf_kind kind, const char *val, size_t vlen) {
    if (out->count >= PF_MAX_REFS || val == NULL || vlen == 0 || vlen >= PF_MAX_URL)
        return;
    if (vlen == (size_t)-1) return;
    char *u = (char *)malloc(vlen + 1);
    if (u == NULL) return;
    memcpy(u, val, vlen);
    u[vlen] = '\0';
    out->refs[out->count].kind = kind;
    out->refs[out->count].url = u;
    out->count++;
}

int pf_scan(const char *html, size_t len, pf_list *out) {
    if (out != NULL) memset(out, 0, sizeof *out);
    if (html == NULL || out == NULL) return -1;

    const char *p = html, *end = html + len;
    while (p < end) {
        const char *lt = memchr(p, '<', (size_t)(end - p));
        if (lt == NULL) break;
        p = lt;

        if (ci_starts(p, end, "<!--")) {
            const char *close = ci_find(p + 4, end, "-->");
            p = (close != NULL) ? close + 3 : end;
            continue;
        }

        if (ci_starts(p, end, "<script") &&
            !(p + 7 < end && is_name_char(p[7]))) {
            const char *cur = p + 7;
            attr_span a;
            const char *src = NULL; size_t srclen = 0;
            while (next_attr(&cur, end, &a)) {
                if (a.val != NULL && ci_eq_span(a.name, a.nlen, "src")) {
                    src = a.val; srclen = a.vlen;
                }
            }
            if (src != NULL) emit(out, PF_SCRIPT, src, srclen);
            /* Raw-text element: the content (inline JS) is opaque. A missing
             * closer skips the rest -- fewer prefetches, never a wrong one. */
            const char *closer = ci_find(cur, end, "</script");
            p = (closer != NULL) ? closer + 8 : end;
            continue;
        }

        if (ci_starts(p, end, "<style") &&
            !(p + 6 < end && is_name_char(p[6]))) {
            const char *closer = ci_find(p + 6, end, "</style");
            p = (closer != NULL) ? closer + 7 : end;
            continue;
        }

void pf_list_free(pf_list *l) {
    if (l == NULL) return;
    for (size_t i = 0; i < l->count; ++i) free(l->refs[i].url);
    l->count = 0;
}

/* --- pool -------------------------------------------------------------- */


/* --- ES module graph (spec/prefetch.md section 8) --- */

static size_t js_skip_ws(const char *s, size_t i, size_t n) {
    while (i < n && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\r'))
        ++i;
    return i;
}

/* Index just past the string or template literal opening at s[i]. */

static size_t js_skip_string(const char *s, size_t i, size_t n) {
    char q = s[i++];
    while (i < n && s[i] != q) i += (s[i] == '\\') ? 2 : 1;
    return (i < n) ? i + 1 : n;
}

/* Captures the quoted specifier at s[i] when it is URL-shaped. */

static void js_take_spec(const char *s, size_t i, size_t n,
                         char (*out)[PF_SPEC_MAX], size_t cap, size_t *k) {
    if (i >= n || (s[i] != '"' && s[i] != '\'') || *k >= cap) return;
    char q = s[i];
    size_t a = i + 1, b = a;
    while (b < n && s[b] != q && s[b] != '\\' && s[b] != '\n') ++b;
    if (b >= n || s[b] != q) return;
    size_t len = b - a;
    if (len == 0 || len >= PF_SPEC_MAX) return;
    const char *sp = s + a;
    memcpy(out[*k], sp, len);
    out[*k][len] = '\0';
    ++*k;
}

size_t pf_scan_imports(const char *js, size_t len, char (*out)[PF_SPEC_MAX], size_t cap) {
    if (js == NULL || out == NULL || cap == 0) return 0;
    size_t k = 0, i = 0;
    int clause = 0;   /* inside `import ...`/`export ...` awaiting `from` */
    while (i < len && k < cap) {
        char c = js[i];
        if (c == '/' && i + 1 < len && js[i + 1] == '/') {
            while (i < len && js[i] != '\n') ++i;
            continue;
        }
        if (c == '/' && i + 1 < len && js[i + 1] == '*') {
            i += 2;
            while (i + 1 < len && !(js[i] == '*' && js[i + 1] == '/')) ++i;
            i = (i + 1 < len) ? i + 2 : len;
            continue;
        }
        if (c == '"' || c == '\'' || c == '`') { i = js_skip_string(js, i, len); continue; }
        if (c == ';') { clause = 0; ++i; continue; }
        if (!js_ident_ch(c)) { ++i; continue; }
        size_t a = i;
        while (i < len && js_ident_ch(js[i])) ++i;
        size_t wl = i - a;
        int boundary = (a == 0) || (js[a - 1] != '.' && !js_ident_ch(js[a - 1]));
        if (!boundary) continue;
        if (wl == 6 && memcmp(js + a, "import", 6) == 0) {
            size_t j = js_skip_ws(js, i, len);
            if (j < len && (js[j] == '"' || js[j] == '\'')) {   /* import "x" */
                js_take_spec(js, j, len, out, cap, &k);
                i = js_skip_string(js, j, len);
                clause = 0;
            } else if (j < len && (js[j] == '(' || js[j] == '.')) {
                clause = 0;   /* import() / import.meta: never prefetched */
            } else {
                clause = 1

int pf_pool_add(pf_pool *p, const char *url) {
    if (p == NULL || url == NULL || url[0] == '\0') return 0;
    pthread_mutex_lock(&p->lock);
    int added = 0;
    if (p->started && !p->closing && p->count < PF_MAX_JOBS) {
        int dup = 0;
        for (size_t j = 0; j < p->count; ++j)
            if (strcmp(p->jobs[j].url, url) == 0) { dup = 1; break; }
        if (!dup) {
            char *u = strdup(url);
            if (u != NULL) {
                p->jobs[p->count].url = u;
                p->jobs[p->count].state = PF_JOB_PENDING;
                p->count++;
                pthread_cond_signal(&p->work_cv);
                added = 1;
            }
        }
    }
    pthread_mutex_unlock(&p->lock);
    return added;
}

static int pf_is_js(const char *url, const char *ctype) {
    if (ctype != NULL && strstr(ctype, "javascript") != NULL) return 1;
    if (url == NULL) return 0;
    size_t n = strcspn(url, "?#");
    return (n >= 3 && memcmp(url + n - 3, ".js", 3) == 0)
        || (n >= 4 && memcmp(url + n - 4, ".mjs", 4) == 0);
}

static int pf_url_cb(void *ctx, const char *base, const char *ref, char *out, size_t outsz) {
    (void)ctx;
    return (url_resolve_https(base, ref, out, outsz) == URL_OK) ? 0 : -1;
}

static int pf_url_shaped(const char *sp) {
    return (sp[0] == '.' && sp[1] == '/') || (sp[0] == '.' && sp[1] == '.' && sp[2] == '/')
        || sp[0] == '/' || strncmp(sp, "https://", 8) == 0;
}

/* Queues the static imports of a fetched module body, resolved the way the module
 * loader resolves them: through the page's import map (which also covers bare
 * specifiers), else as a URL against the module's own. imap is immutable once the
 * pool started, so reading it from any thread needs no lock. */

static void pf_follow_imports(pf_pool *p, const char *base, const char *body, size_t len) {
    char (*specs)[PF_SPEC_MAX] = calloc(PF_MAX_IMPORTS, sizeof *specs);
    if (specs == NULL) return;
    size_t n = pf_scan_imports(body, len, specs, PF_MAX_IMPORTS);
    char abs[PF_SPEC_MAX * 2];
    for (size_t k = 0; k < n; ++k) {
        int ok = -1;
        if (p->imap != NULL)
            ok = im_resolve(p->imap, base, specs[k], pf_url_cb, NULL, abs, sizeof abs);
        if (ok != 0 && pf_url_shaped(specs[k]))
            ok = pf_url_cb(NULL, base, specs[k], abs, sizeof abs);
        if (ok == 0) (void)pf_pool_add(p, abs);
    }
    free(specs);
}

static void *pf_worker(void *arg) {
    pf_pool *p = (pf_pool *)arg;
    for (;;) {
        pthread_mutex_lock(&p->lock);
        /* Threads live until finish: a module fetched later may queue more work. */
        while (p->next >= p->count && !p->closing)
            pthread_cond_wait(&p->work_cv, &p->lock);
        size_t i = p->next;
        if (i >= p->count) {
            pthread_mutex_unlock(&p->lock);
            break;
        }
        p->next++;
        p->jobs[i].state = PF_JOB_RUNNING;
        pthread_mutex_unlock(&p->lock);

        pf_job *j = &p->jobs[i];
        int st = 0; char *b = NULL; size_t l = 0; char *ct = NULL;
        int rc = p->fetch(p->ctx, "GET", j->url, NULL, 0, &st, &b, &l, &ct);
        /* Queue this module's imports BEFORE publishing it: the worker that takes
         * it requests them next, and must find them already in the pool. */
        if (rc == 0 && b != NULL && st >= 200 && st < 300 && pf_is_js(j->url, ct))
            pf_follow_imports(p, j->url, b, l);

        pthread_mutex_lock(&p->lock);
        j->rc = rc; j->status = st; j->body = b; j->len = l; j->ctype = ct;
        j->state = PF_JOB_DONE;
        pthread_cond_broadcast(&p->done_cv);
        pthread_mutex_unlock(&p->lock);
    }
    return NULL;
}

static int pool_start(pf_pool *p, const char *const *urls, size_t nurls,
                      pf_fetch_fn fetch, void *ctx, struct im_map *map,
                      const char *page_url);
static int pf_url_cb(void *ctx, const char *base, const char *ref, char *out, size_t outsz);

int pf_pool_start(pf_pool *p, const char *const *urls, size_t nurls,
                  pf_fetch_fn fetch, void *ctx) {
    return pool_start(p, urls, nurls, fetch, ctx, NULL, NULL);
}

/* map (owned on success) is set BEFORE the threads start: they read it after a
 * fetch, unlocked, and it never changes afterwards. */

static int pool_start(pf_pool *p, const char *const *urls, size_t nurls,
                      pf_fetch_fn fetch, void *ctx, struct im_map *map,
                      const char *page_url) {
    if (p == NULL) return -1;
    memset(p, 0, sizeof *p);
    if (urls == NULL || nurls == 0 || fetch == NULL) return -1;

    for (size_t i = 0; i < nurls && p->count < PF_MAX_JOBS; ++i) {
        if (urls[i] == NULL || urls[i][0] == '\0') continue;
        int dup = 0;
        for (size_t j = 0; j < p->count; ++j)
            if (strcmp(p->jobs[j].url, urls[i]) == 0) { dup = 1; break; }
        if (dup) continue;
        char *u = strdup(urls[i]);
        if (u == NULL) continue;
        p->jobs[p->count].url = u;
        p->jobs[p->count].state = PF_JOB_PENDING;
        p->count++;
    }
    if (p->count == 0) return -1;

    pthread_mutex_init(&p->lock, NULL);
    pthread_cond_init(&p->done_cv, NULL);
    pthread_cond_init(&p->work_cv, NULL);
    p->fetch = fetch;
    p->ctx = ctx;
    p->imap = map;
    p->page_url = (page_url != NULL) ? strdup(page_url) : NULL;
    p->started = 1;   /* before the threads: a module they fetch may add jobs */

    /* Every thread: the module graph grows the job list after start. */
    for (size_t i = 0; i < PF_MAX_THREADS; ++i) {
        if (pthread_create(&p->threads[p->nthreads], NULL, pf_worker, p) != 0)
            break;
        p->nthreads++;
    }
    if (p->nthreads == 0) {
        /* No threads at all: performance fails open (caller fetches serially),
         * nothing may be left half-owned. */
        for (size_t i = 0; i < p->count; +

int pf_pool_take(pf_pool *p, const char *url, int *rc, int *status,
                 char **body, size_t *len, char **ctype) {
    if (rc != NULL) *rc = -1;
    if (status != NULL) *status = 0;
    if (body != NULL) *body = NULL;
    if (len != NULL) *len = 0;
    if (ctype != NULL) *ctype = NULL;
    if (p == NULL || url == NULL || !p->started) return 0;

    pthread_mutex_lock(&p->lock);
    pf_job *j = NULL;
    for (size_t i = 0; i < p->count; ++i) {
        if (p->jobs[i].state != PF_JOB_CONSUMED &&
            strcmp(p->jobs[i].url, url) == 0) {
            j = &p->jobs[i];
            break;
        }
    }
    if (j == NULL) {
        pthread_mutex_unlock(&p->lock);
        return 0;
    }
    while (j->state != PF_JOB_DONE)
        pthread_cond_wait(&p->done_cv, &p->lock);

    if (rc != NULL) *rc = j->rc;
    if (status != NULL) *status = j->status;
    if (body != NULL) { *body = j->body; j->body = NULL; }
    if (len != NULL) *len = j->len;
    if (ctype != NULL) { *ctype = j->ctype; j->ctype = NULL; }
    /* Anything not moved out is freed here: exactly one owner either way. */
    free(j->body);  j->body = NULL;
    free(j->ctype); j->ctype = NULL;
    j->len = 0;
    j->state = PF_JOB_CONSUMED;
    pthread_mutex_unlock(&p->lock);
    return 1;
}

int pf_find_importmap(const char *html, size_t len, size_t *start, size_t *n) {
    if (html == NULL || start == NULL || n == NULL) return 0;
    for (size_t i = 0; i + 7 < len; ++i) {
        if (html[i] != '<' || strncasecmp(html + i + 1, "script", 6) != 0) continue;
        size_t e = i + 7;
        while (e < len && html[e] != '>') ++e;
        if (e >= len) return 0;
        int is_map = 0;
        for (size_t k = i + 7; k + 9 <= e; ++k)
            if (strncasecmp(html + k, "importmap", 9) == 0) { is_map = 1; break; }
        if (!is_map) continue;
        size_t b = e + 1, c = b;
        while (c + 9 <= len && strncasecmp(html + c, "</script", 8) != 0) ++c;
        if (c + 9 > len) return 0;
        *start = b;
        *n = c - b;
        return 1;
    }
    return 0;
}

int pf_pool_start_page(pf_pool *p, const char *html, size_t len, const char *page_url,
                       int css_grant, int js_grant, pf_fetch_fn fetch, void *ctx) {
    if (p == NULL) return -1;
    memset(p, 0, sizeof *p);
    if (!(css_grant || js_grant)) return -1;
    pf_list scanned;
    scanned.count = 0;
    if (pf_scan(html, len, &scanned) != 0) return -1;
    /* Keys are ABSOLUTE: a classic script is requested by its raw src, a module
     * already resolved, and both must find the same job (pf_pooled_fetch
     * normalizes the request the same way). */
    const char *urls[PF_MAX_REFS];
    char (*absu)[PF_SPEC_MAX * 2] = calloc(PF_MAX_REFS, sizeof *absu);
    if (absu == NULL) { pf_list_free(&scanned); return -1; }
    size_t nurl = 0;
    for (size_t i = 0; i < scanned.count && nurl < PF_MAX_REFS; ++i) {
        int want = (scanned.refs[i].kind == PF_STYLESHEET) ? css_grant : js_grant;
        if (!want) continue;
        if (page_url != NULL &&
            pf_url_cb(NULL, page_url, scanned.refs[i].url, absu[nurl], sizeof absu[nurl]) == 0)
            urls[nurl] = absu[nurl];
        else
            urls[nurl] = scanned.refs[i].url;
        ++nurl;
    }
    struct im_map *map = NULL;
    size_t ms = 0, mn = 0;
    if (js_grant && page_url != NULL && pf_find_importmap(html, len, &ms, &mn))
        map = im_parse(html + ms, mn, page_url, pf_url_cb, NULL);
    int rc = (nurl > 0) ? pool_start(p, urls, nurl, fetch, ctx, map, page_url) : -1;
    free(absu);
    pf_list_free(&scanned);
    if (rc != 0) { im_free(map); return -1; }
    return 0;
}

void pf_pool_finish(pf_pool *p) {
    if (p == NULL || !p->started) return;
    pthread_mutex_lock(&p->lock);
    p->closing = 1;
    pthread_cond_broadcast(&p->work_cv);
    pthread_mutex_unlock(&p->lock);
    for (size_t i = 0; i < p->nthreads; ++i)
        pthread_join(p->threads[i], NULL);
    for (size_t i = 0; i < p->count; ++i) {
        free(p->jobs[i].url);
        free(p->jobs[i].body);
        free(p->jobs[i].ctype);
    }
    im_free(p->imap);
    free(p->page_url);
    pthread_mutex_destroy(&p->lock);
    pthread_cond_destroy(&p->done_cv);
    pthread_cond_destroy(&p->work_cv);
    memset(p, 0, sizeof *p);
}

int pf_pooled_fetch(void *vctx, const char *method, const char *url,
                    const char *body, size_t body_len,
                    int *out_status, char **out_body, size_t *out_len,
                    char **out_ctype) {
    pf_gated_fetch *g = (pf_gated_fetch *)vctx;
    if (g == NULL || g->inner == NULL) return -1;
    if (g->pool != NULL && method != NULL && strcmp(method, "GET") == 0) {
        int rc = -1;
        /* The same absolute key the pool was filled with; the fetch on a miss
         * still goes out with the request exactly as the worker made it. */
        char key[PF_SPEC_MAX * 2];
        const char *k = url;
        if (g->pool->page_url != NULL && url != NULL &&
            pf_url_cb(NULL, g->pool->page_url, url, key, sizeof key) == 0)
            k = key;
        if (pf_pool_take(g->pool, k, &rc, out_status, out_body, out_len,
                         out_ctype) == 1)
            return rc;
    }
    return g->inner(g->inner_ctx, method, url, body, body_len,
                    out_status, out_body, out_len, out_ctype);
}

#define _POSIX_C_SOURCE 200809L  /* strdup */

#include "prefs.h"
#include "zoom.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define PREFS_MAGIC "freedom-prefs"

/* --- validation / cleaning ------------------------------------------------ */

/* A representable URL: 1..PREFS_MAX_URL-1 bytes, no control bytes, no DEL.
 * Space is allowed (local paths may carry it; fields are tab-separated). */

static int url_valid(const char *url) {
    if (url == NULL || url[0] == '\0') return 0;
    size_t n = 0;
    for (const unsigned char *c = (const unsigned char *)url; *c != '\0'; ++c, ++n) {
        if (*c < 0x20u || *c == 0x7fu) return 0;
        if (n + 1 >= PREFS_MAX_URL) return 0;
    }
    return 1;
}

/* Copies src into a fresh buffer, mapping control bytes/DEL to ' ' and
 * truncating to PREFS_MAX_TITLE bytes on a UTF-8 sequence boundary. A NULL
 * src yields "". Returns NULL only on OOM. */

static char *title_clean(const char *src) {
    if (src == NULL) src = "";
    char *dst = (char *)malloc(PREFS_MAX_TITLE + 1);
    if (dst == NULL) return NULL;
    size_t n = 0;
    for (const unsigned char *c = (const unsigned char *)src;
         *c != '\0' && n < PREFS_MAX_TITLE; ++c) {
        dst[n++] = (*c < 0x20u || *c == 0x7fu) ? ' ' : (char)*c;
    }
    /* Trim a trailing incomplete UTF-8 sequence left by byte truncation. */
    size_t back = 0;
    while (back < 3 && back < n &&
           ((unsigned char)dst[n - 1 - back] & 0xC0u) == 0x80u) {
        ++back;
    }
    if (back < n) {
        unsigned char lead = (unsigned char)dst[n - 1 - back];
        size_t need = (lead >= 0xF0u) ? 4 : (lead >= 0xE0u) ? 3
                    : (lead >= 0xC0u) ? 2 : 1;
        if (need > back + 1) n -= back + 1;  /* incomplete: drop the sequence */
    }
    dst[n] = '\0';
    return dst;
}

/* --- lifecycle ------------------------------------------------------------- */

void prefs_init(prefs_state *p) {
    if (p == NULL) return;
    memset(p, 0, sizeof *p);
    p->js_mode = 1;           /* JSP_ALLOWLIST: Secure by Default */
    p->zoom_pct = zm_reset(); /* 100% */
    p->remember_history = 1;
}

void prefs_free(prefs_state *p) {
    if (p == NULL) return;
    for (size_t i = 0; i < p->bookmarks_len; ++i) {
        free(p->bookmarks[i].url);
        free(p->bookmarks[i].title);
    }
    free(p->bookmarks);
    for (size_t i = 0; i < p->history_len; ++i) free(p->history[i]);
    free(p->history);
    p->bookmarks = NULL; p->bookmarks_len = 0;
    p->history = NULL;   p->history_len = 0;
}

/* --- list plumbing ---------------------------------------------------------- */

/* Appends a cleaned bookmark. Duplicate URLs are skipped (PREFS_OK). Used by
 * the toggle's add path and by the parser. */

static prefs_status bookmark_push(prefs_state *p, const char *url, const char *title) {
    if (prefs_bookmark_index(p, url) >= 0) return PREFS_OK;
    if (p->bookmarks_len >= PREFS_MAX_BOOKMARKS) return PREFS_ERR_FULL;
    prefs_entry *grown = (prefs_entry *)realloc(
        p->bookmarks, (p->bookmarks_len + 1) * sizeof *grown);
    if (grown == NULL) return PREFS_ERR_OOM;
    p->bookmarks = grown;
    char *u = strdup(url);
    char *t = title_clean(title);
    if (u == NULL || t == NULL) { free(u); free(t); return PREFS_ERR_OOM; }
    p->bookmarks[p->bookmarks_len].url = u;
    p->bookmarks[p->bookmarks_len].title = t;
    p->bookmarks_len++;
    return PREFS_OK;
}

/* Appends a history entry at the BACK preserving document order (parser path;
 * the API path inserts at the front). Duplicates and overflow are skipped. */

static prefs_status history_push_back(prefs_state *p, const char *url) {
    if (p->history_len >= PREFS_MAX_HISTORY) return PREFS_OK;
    for (size_t i = 0; i < p->history_len; ++i)
        if (strcmp(p->history[i], url) == 0) return PREFS_OK;
    char **grown = (char **)realloc(p->history,
                                    (p->history_len + 1) * sizeof *grown);
    if (grown == NULL) return PREFS_ERR_OOM;
    p->history = grown;
    char *u = strdup(url);
    if (u == NULL) return PREFS_ERR_OOM;
    p->history[p->history_len++] = u;
    return PREFS_OK;
}

/* --- public list operations --------------------------------------------------- */

int prefs_bookmark_index(const prefs_state *p, const char *url) {
    if (p == NULL || url == NULL) return -1;
    for (size_t i = 0; i < p->bookmarks_len; ++i)
        if (strcmp(p->bookmarks[i].url, url) == 0) return (int)i;
    return -1;
}

prefs_status prefs_bookmark_toggle(prefs_state *p, const char *url,
                                   const char *title, int *added) {
    if (p == NULL || url == NULL) return PREFS_ERR_NULL_ARG;
    if (!url_valid(url)) return PREFS_ERR_INVALID;
    int idx = prefs_bookmark_index(p, url);
    if (idx >= 0) {
        free(p->bookmarks[idx].url);
        free(p->bookmarks[idx].title);
        memmove(&p->bookmarks[idx], &p->bookmarks[idx + 1],
                (p->bookmarks_len - (size_t)idx - 1) * sizeof p->bookmarks[0]);
        p->bookmarks_len--;
        if (added != NULL) *added = 0;
        return PREFS_OK;
    }
    if (p->bookmarks_len >= PREFS_MAX_BOOKMARKS) return PREFS_ERR_FULL;
    prefs_status st = bookmark_push(p, url, title);
    if (st == PREFS_OK && added != NULL) *added = 1;
    return st;
}

prefs_status prefs_history_add(prefs_state *p, const char *url) {
    if (p == NULL || url == NULL) return PREFS_ERR_NULL_ARG;
    if (!url_valid(url)) return PREFS_ERR_INVALID;
    if (p->history_len > 0 && strcmp(p->history[0], url) == 0) return PREFS_OK;
    for (size_t i = 1; i < p->history_len; ++i) {
        if (strcmp(p->history[i], url) == 0) {  /* move to front */
            char *hit = p->history[i];
            memmove(&p->history[1], &p->history[0], i * sizeof p->history[0]);
            p->history[0] = hit;
            return PREFS_OK;
        }
    }
    char *u = strdup(url);
    if (u == NULL) return PREFS_ERR_OOM;
    if (p->history_len >= PREFS_MAX_HISTORY) {
        free(p->history[p->history_len - 1]);  /* evict the oldest */
        p->history_len--;
    }
    char **grown = (char **)realloc(p->history,
                                    (p->history_len + 1) * sizeof *grown);
    if (grown == NULL) { free(u); return PREFS_ERR_OOM; }
    p->history = grown;
    memmove(&p->history[1], &p->history[0],
            p->history_len * sizeof p->history[0]);
    p->history[0] = u;
    p->history_len++;
    return PREFS_OK;
}

/* --- serialization ---------------------------------------------------------------- */

prefs_status prefs_format(const prefs_state *p, char **out, size_t *out_len) {
    if (p == NULL || out == NULL || out_len == NULL) return PREFS_ERR_NULL_ARG;
    *out = NULL;
    *out_len = 0;

    size_t cap = 256 + 3 + strlen(p->identity);  /* header + scalar keys + identity line */
    for (size_t i = 0; i < p->bookmarks_len; ++i)
        cap += 4 + strlen(p->bookmarks[i].url) + strlen(p->bookmarks[i].title);
    for (size_t i = 0; i < p->history_len; ++i)
        cap += 3 + strlen(p->history[i]);
    if (cap > PREFS_MAX_TEXT) return PREFS_ERR_FORMAT;  /* unreachable with the caps */

    char *buf = (char *)malloc(cap);
    if (buf == NULL) return PREFS_ERR_OOM;
    size_t n = (size_t)snprintf(buf, cap,
        PREFS_MAGIC " %u\n"
        "theme=%d\nforce=%d\nimages=%d\ncss=%d\nreader=%d\njs=%d\n"
        "tor=%d\ni2p=%d\ntorify=%d\nzoom=%d\nremhist=%d\n",
        PREFS_VERSION,
        p->theme_mode, p->force_theme, p->images, p->css, p->reader, p->js_mode,
        p->tor, p->i2p, p->torify, p->zoom_pct, p->remember_history);
    if (p->identity[0] != '\0') {
        size_t space = cap - n;
        int r = snprintf(buf + n, space, "id\t%s\n", p->identity);
        if (r < 0 || (size_t)r >= space) { free(buf); return PREFS_ERR_FORMAT; }
        n += (size_t)r;
    }
    for (size_t i = 0; i < p->bookmarks_len; ++i) {
        size_t space = cap - n;
        if (space == 0) break;
        int r = snprintf(buf + n, space, "b\t%s\t%s\n",
                         p->bookmarks[i].url, p->bookmarks[i].title);
        if (r < 0 || (size_t)r >= space) { n = cap; break; }

static void apply_kv(prefs_state *out, const char *key, long val) {
    int b = (val != 0);
    if      (strcmp(key, "theme") == 0)   out->theme_mode = (val >= 0 && val <= 2) ? (int)val : 0;
    else if (strcmp(key, "js") == 0)      out->js_mode = (val >= 0 && val <= 2) ? (int)val : 1;
    else if (strcmp(key, "zoom") == 0)    out->zoom_pct = zm_clamp((int)val);
    else if (strcmp(key, "force") == 0)   out->force_theme = b;
    else if (strcmp(key, "images") == 0)  out->images = b;
    else if (strcmp(key, "css") == 0)     out->css = b;
    else if (strcmp(key, "reader") == 0)  out->reader = b;
    else if (strcmp(key, "tor") == 0)     out->tor = b;
    else if (strcmp(key, "i2p") == 0)     out->i2p = b;
    else if (strcmp(key, "torify") == 0)  out->torify = b;
    else if (strcmp(key, "remhist") == 0) out->remember_history = b;
    /* unknown key: ignored (forward compatibility) */
}

