static int hdr_name_has_prefix(const char *a, size_t alen, const char *lit) {
    size_t n = strlen(lit);
    if (alen < n) return 0;
    for (size_t i = 0; i < n; ++i) if (hdr_lower((unsigned char)a[i]) != lit[i]) return 0;
    return 1;
