typedef struct body_sink {
    uint8_t *data;
    size_t   len;
    size_t   cap;
    size_t   limit;
    int      overflow;
} body_sink;

/* Snapshot of the negotiated TLS state. curl exposes the live SSL* only while a

typedef struct tls_capture {
    CURL         *curl;
    int           have;            /* nonzero once the snapshot was taken */
    char          version[32];
    char          group[64];
    int           chain_ok;        /* chain could be inspected */
    sf_chain_info chain;
    char          sigbuf[128];
} tls_capture;

typedef struct fetch_ctx {
    body_sink   sink;
    tls_capture cap;
    char        location[SF_MAX_URL]; /* last Location header value seen, if any */
    int         have_location;
    char        disposition[SF_MAX_URL]; /* last Content-Disposition value, if any */
    int         have_disposition;
    char        etag[SF_META_MAX], last_modified[SF_META_MAX], cache_control[SF_META_MAX];
    char        expires[SF_META_MAX], date[SF_META_MAX];
    void       *progress_ctx; /* userdata passed to the progress callback */
    void      (*progress_cb)(const uint8_t *body, size_t body_len, void *ctx);
    char        hdr_all[SF_RESPONSE_HEADERS_MAX]; /* final hop's header lines, status line excluded */
    size_t      hdr_len;
} fetch_ctx;

static int inspect_chain(SSL *ssl, sf_chain_info *info, char *sigbuf, size_t sigbuf_len);

static void copy_bounded(char *dst, size_t dstsz, const char *src) {
    if (dstsz == 0) return;
    dst[0] = '\0';
    if (src == NULL) return;
    size_t i = 0;
    for (; src[i] != '\0' && i + 1 < dstsz; ++i) dst[i] = src[i];
    dst[i] = '\0';
}


/* Helper: Extracts the name of the TLS group actually negotiated from OpenSSL */

static const char *get_negotiated_group_name(SSL *ssl) {
#if defined(OPENSSL_VERSION_NUMBER) && OPENSSL_VERSION_NUMBER >= 0x30200000L
    /* OpenSSL 3.2+: canonical name of the negotiated group. This is the ONLY
     * API that can name the provider-based PQ hybrids: X25519MLKEM768 has no

     * NID in the OBJ database (OBJ_sn2nid returns 0 on OpenSSL 3.6), so the
     * NID path below reports every PQ-hybrid handshake as unnamed and the
     * policy check rejects it -- exactly the sites doing TLS right. */
    const char *name = SSL_get0_group_name(ssl);
    if (name != NULL && name[0] != '\0') return name;
#endif
    int nid = 0;

#if OPENSSL_VERSION_NUMBER >= 0x30000000L
    /* OpenSSL 3.0+ has a dedicated API for obtaining the negotiated group*/
    nid = SSL_get_negotiated_group(ssl);
#else
    /* OpenSSL 1.1.1: SSL_get_shared_group(ssl, 0) returns the NID of the
     * first shared group, which corresponds to the negotiated key exchange

     * group (for both TLS 1.2 ECDHE and TLS 1.3). */
    nid = SSL_get_shared_group(ssl, 0);
#endif

    if (nid == 0) {
        return NULL; /* There is no negotiated group (e.g., TLS 1.2 without PFS or failure) */
    }

    /* OBJ_nid2sn returns the short name (e.g., "X25519", "prime256v1", "x25519") */
    return OBJ_nid2sn(nid);
}

static void tls_capture_from_ssl(tls_capture *cap, SSL *ssl);

/* Idempotent: takes the TLS snapshot the first time the SSL* is reachable. */

static void tls_capture_try(tls_capture *cap) {
    if (cap->have) return;

    struct curl_tlssessioninfo *ti = NULL;
    if (curl_easy_getinfo(cap->curl, CURLINFO_TLS_SSL_PTR, &ti) != CURLE_OK) return;
    if (ti == NULL || ti->backend != CURLSSLBACKEND_OPENSSL || ti->internals == NULL) return;
    tls_capture_from_ssl(cap, (SSL *)ti->internals);
}

/* The snapshot proper, from a live SSL*. Idempotent. */

static void tls_capture_from_ssl(tls_capture *cap, SSL *ssl) {
    if (cap->have || ssl == NULL) return;

    /* 1. Capture TLS version */
    copy_bounded(cap->version, sizeof cap->version, SSL_get_version(ssl));

    /* 2. Read the REAL group negotiated from OpenSSL.

     * We must NOT hardcode this (e.g., to "X25519"), as it breaks the checks.
     * PQ for groups that are not X25519 and causes false rejections.
     * If it is NULL (no group / not TLS 1.3 / no PFS), we copy "" which
     * will be correctly rejected by the policy (fail-closed). */
    const char *real_group = get_negotiated_group_name(ssl);
    if (real_group == NULL) {
        real_group = ""; /* Fail-closed: la cadena vacía será rechazada por la política */
    }
    copy_bounded(cap->group, sizeof cap->group, real_group);

    /* 3. Inspect the chain of certificates and signatures */
    memset(&cap->chain, 0, sizeof cap->chain);
    cap->chain_ok = (inspect_chain(ssl, &cap->chain, cap->sigbuf, sizeof cap->sigbuf) == 0);

    cap->have = 1;
}

