static sf_status sf_perform(const char *url, const sf_config *cfg, sf_response *out,
                            const void *post_body, size_t post_len,
                            const char *content_type) {
    if (url == NULL || out == NULL) return SF_ERR_NULL_ARG;

    memset(out, 0, sizeof *out);

    sf_config local = (cfg != NULL) ? *cfg : sf_config_default();
    if (local.timeout_ms == 0) local.timeout_ms = SF_DEFAULT_TIMEOUT_MS;
    if (local.max_body_bytes == 0) local.max_body_bytes = SF_DEFAULT_MAX_BODY;
    if (local.kex_groups == NULL) local.kex_groups = SF_DEFAULT_KEX_GROUPS;

    /* https is required everywhere except an overlay (.onion/.i2p) request that opted
     * into plain http: there the overlay layer authenticates and encrypts, so http is
     * not a downgrade. A malformed http URL (no host) still falls through to the
     * strict https validation and is rejected. */
    int http_overlay = local.allow_overlay_http && sf_url_is_http(url);
    if (!http_overlay) {
        sf_status vs = sf_validate_url(url);
        if (vs != SF_OK) { out->status = vs; return vs; }
    }

    CURL *curl = curl_easy_init();
    if (curl == NULL) { out->status = SF_ERR_OOM; return SF_ERR_OOM; }

    /* Share the ephemeral cookie jar so cookies survive across requests (login ->
     * redirect -> profile). The share is created once in sf_global_init; if it is
     * NULL (init not called / OOM) we still proceed without cookies. */
    if (sf_share != NULL) {
        curl_easy_setopt(curl, CURLOPT_SHARE, sf_share);
    }
    /* Enable libcurl's in-memory cookie engine on

sf_status sf_get(const char *url, const sf_config *cfg, sf_response *out) {
    return sf_perform(url, cfg, out, NULL, 0, NULL);
}

sf_status sf_post(const char *url, const sf_config *cfg,
                  const void *body, size_t body_len, const char *content_type,
                  sf_response *out) {
    if (url == NULL || out == NULL) return SF_ERR_NULL_ARG;
    if (body == NULL && body_len != 0) {
        memset(out, 0, sizeof *out);
        out->status = SF_ERR_NULL_ARG;
        return SF_ERR_NULL_ARG;
    }
    /* A non-empty body forces the POST path; an empty POST still sets POST via a
     * zero-length body pointer. */
    return sf_perform(url, cfg, out, (body != NULL) ? body : "", body_len, content_type);
}

/* --- permanent-redirect memory (RAM only, Zero Knowledge) --- */

typedef struct {
    char   from[SF_MAX_URL];
    char   to[SF_MAX_URL];
    time_t stored;
    int    used;
} sf_rcache_entry;

static sf_rcache_entry sf_rcache[SF_RCACHE_SLOTS];
static size_t sf_rcache_next;
static pthread_mutex_t sf_rcache_lock = PTHREAD_MUTEX_INITIALIZER;

void sf_rcache_clear(void) {
    pthread_mutex_lock(&sf_rcache_lock);
    memset(sf_rcache, 0, sizeof sf_rcache);
    sf_rcache_next = 0;
    pthread_mutex_unlock(&sf_rcache_lock);
}

static sf_rcache_load_fn sf_rcache_load_cb;
static sf_rcache_save_fn sf_rcache_save_cb;
static void *sf_rcache_backing_ctx;

void sf_rcache_set_backing(sf_rcache_load_fn load, sf_rcache_save_fn save, void *ctx) {
    pthread_mutex_lock(&sf_rcache_lock);
    sf_rcache_load_cb = load;
    sf_rcache_save_cb = save;
    sf_rcache_backing_ctx = ctx;
    pthread_mutex_unlock(&sf_rcache_lock);
}

static int rcache_put_ram(const char *from, const char *to, time_t now) {
    if (from == NULL || to == NULL || strcmp(from, to) == 0) return -1;
    if (strlen(from) >= SF_MAX_URL || strlen(to) >= SF_MAX_URL) return -1;
    pthread_mutex_lock(&sf_rcache_lock);
    size_t slot = SF_RCACHE_SLOTS;
    for (size_t i = 0; i < SF_RCACHE_SLOTS; ++i)
        if (sf_rcache[i].used && strcmp(sf_rcache[i].from, from) == 0) { slot = i; break; }
    if (slot == SF_RCACHE_SLOTS) {
        slot = sf_rcache_next;
        sf_rcache_next = (sf_rcache_next + 1) % SF_RCACHE_SLOTS;
    }
    memcpy(sf_rcache[slot].from, from, strlen(from) + 1);
    memcpy(sf_rcache[slot].to, to, strlen(to) + 1);
    sf_rcache[slot].stored = now;
    sf_rcache[slot].used = 1;
    pthread_mutex_unlock(&sf_rcache_lock);
    return 0;
}

int sf_rcache_put(const char *from, const char *to, time_t now) {
    if (rcache_put_ram(from, to, now) != 0) return -1;
    pthread_mutex_lock(&sf_rcache_lock);
    sf_rcache_save_fn save = sf_rcache_save_cb;
    void *bctx = sf_rcache_backing_ctx;
    pthread_mutex_unlock(&sf_rcache_lock);
    if (save != NULL) save(bctx, from, to, now);
    return 0;
}

int sf_rcache_get(const char *from, time_t now, char *out, size_t cap) {
    if (from == NULL || out == NULL || cap == 0) return 0;
    int hit = 0;
    pthread_mutex_lock(&sf_rcache_lock);
    for (size_t i = 0; i < SF_RCACHE_SLOTS; ++i) {
        if (!sf_rcache[i].used || strcmp(sf_rcache[i].from, from) != 0) continue;
        if (now - sf_rcache[i].stored > SF_RCACHE_TTL_S || now < sf_rcache[i].stored) {
            sf_rcache[i].used = 0;
            break;
        }
        size_t n = strlen(sf_rcache[i].to);
        if (n < cap) { memcpy(out, sf_rcache[i].to, n + 1); hit = 1; }
        break;
    }
    sf_rcache_load_fn load = sf_rcache_load_cb;
    void *bctx = sf_rcache_backing_ctx;
    pthread_mutex_unlock(&sf_rcache_lock);
    if (!hit && load != NULL) {
        /* RAM miss: the persistent memory may still know it (a previous session). */
        char to[SF_MAX_URL];
        if (load(bctx, from, now, to, sizeof to) && strlen(to) < cap) {
            memcpy(out, to, strlen(to) + 1);
            (void)rcache_put_ram(from, to, now);
            hit = 1;
        }
    }
    return hit;
}

sf_status sf_get_follow(const char *url, const sf_config *cfg, sf_response *out,
                        int max_redirects) {
    if (url == NULL || out == NULL) return SF_ERR_NULL_ARG;
    memset(out, 0, sizeof *out);
    if (max_redirects < 0) max_redirects = 0;

    char current[SF_MAX_URL];
    if (copy_checked(current, sizeof current, url) != 0) {
        out->status = SF_ERR_INVALID_URL;
        return SF_ERR_INVALID_URL;
    }

    for (int hops = 0; ; ++hops) {
        /* A permanent redirect already seen this session is not asked again: the next
         * hop is requested directly, under the full policy like any other hop. */
        char known[SF_MAX_URL];
        if (hops < max_redirects && sf_rcache_get(current, time(NULL), known, sizeof known)) {
            if (getenv("FREEDOM_TRACE_FETCH") != NULL)
                fprintf(stderr, "redirect-memory %s -> %s\n", current, known);
            memcpy(current, known, strlen(known) + 1);
            continue;
        }
        /* Each hop is a fresh request: the full TLS/PQ/chain policy is enforced
         * again. Nothing from the previous hop is trusted but the resolved URL. */
        sf_status s = sf_get(current, cfg, out);
        if (s != SF_OK) return s; /* out carries the failure reason */

        if (!sf_is_redirect_code(out->http_code) || out->location == NULL) {
            return SF_OK; /* final response */
        }
        if (hops >= max_redirects) {
            sf_response_free(out);
            out->status = SF_ERR_TOO_MANY_REDIRECTS;
            return SF_ERR_TOO_MANY_REDIRECTS;
        }

static void ws_ssl_info_cb(const SSL *ssl, int where, int ret) {
    (void)ret;
    if ((where & SSL_CB_HANDSHAKE_DONE) == 0) return;
    tls_capture *cap = (tls_capture *)SSL_CTX_get_app_data(SSL_get_SSL_CTX(ssl));
    if (cap != NULL) tls_capture_from_ssl(cap, (SSL *)ssl);
}

static CURLcode ws_ssl_ctx_cb(CURL *curl, void *sslctx, void *userdata) {
    (void)curl;
    SSL_CTX_set_app_data((SSL_CTX *)sslctx, userdata);
    SSL_CTX_set_info_callback((SSL_CTX *)sslctx, ws_ssl_info_cb);
    return CURLE_OK;
}

struct sf_ws {
    CURL              *curl;
    fetch_ctx         *ctx;      /* heap: the handle's callbacks point into it */
    struct curl_slist *hdrs;
    size_t             msg_len;  /* bytes of the message being received so far */
};

sf_status sf_ws_url_check(const char *url) {
    if (url == NULL) return SF_ERR_NULL_ARG;
    if (strncasecmp(url, "wss://", 6) != 0) return SF_ERR_INVALID_URL;
    /* The https twin must pass the same validator a fetch does. */
    char twin[SF_MAX_URL];
    size_t n = strlen(url);
    if (n + 2 >= sizeof twin) return SF_ERR_INVALID_URL;
    memcpy(twin, "https://", 8);
    memcpy(twin + 8, url + 6, n - 6 + 1);
    return (sf_validate_url(twin) == SF_OK) ? SF_OK : SF_ERR_INVALID_URL;
}

static void ws_free(sf_ws *ws) {
    if (ws == NULL) return;
    if (ws->curl != NULL) curl_easy_cleanup(ws->curl);
    curl_slist_free_all(ws->hdrs);
    if (ws->ctx != NULL) free(ws->ctx->sink.data);
    free(ws->ctx);
    free(ws);
}

sf_status sf_ws_open(const char *url, const sf_config *cfg, sf_ws **out) {
    if (out != NULL) *out = NULL;
    if (url == NULL || out == NULL) return SF_ERR_NULL_ARG;
    sf_status st = sf_ws_url_check(url);
    if (st != SF_OK) return st;

    sf_config local = (cfg != NULL) ? *cfg : sf_config_default();
    if (local.timeout_ms == 0) local.timeout_ms = SF_DEFAULT_TIMEOUT_MS;
    if (local.kex_groups == NULL) local.kex_groups = SF_DEFAULT_KEX_GROUPS;
    if (local.sec_fetch_dest == NULL) local.sec_fetch_dest = "websocket";
    if (local.sec_fetch_mode == NULL) local.sec_fetch_mode = "websocket";
    local.allow_overlay_http = 0;          /* never a plaintext WebSocket */
    local.progress_cb = NULL;

    sf_ws *ws = (sf_ws *)calloc(1, sizeof *ws);
    if (ws == NULL) return SF_ERR_OOM;
    ws->ctx = (fetch_ctx *)calloc(1, sizeof *ws->ctx);
    ws->curl = curl_easy_init();
    if (ws->ctx == NULL || ws->curl == NULL) { ws_free(ws); return SF_ERR_OOM; }
    ws->ctx->sink.limit = SF_WS_MAX_MESSAGE;
    ws->ctx->cap.curl = ws->curl;
    if (sf_share != NULL) curl_easy_setopt(ws->curl, CURLOPT_SHARE, sf_share);
    curl_easy_setopt(ws->curl, CURLOPT_COOKIEFILE, "");

    st = sf_setup_handle(ws->curl, url, &local, ws->ctx, "wss", &ws->hdrs);
    if (st != SF_OK) { ws_free(ws); return st; }
    curl_easy_setopt(ws->curl, CURLOPT_HTTPHEADER, ws->hdrs);
    /* Upgrade, then hand the live connection to curl_ws_send/recv. */
    curl_easy_setopt(ws->curl, CURLOPT_CONNECT_ONLY, 2L);
    curl_easy_setopt(ws->curl, CURLOPT_SSL_CTX_FUNCTION, ws_ssl_ctx_cb);
    curl_easy_setopt(ws->c

sf_status sf_ws_send(sf_ws *ws, const void *data, size_t len, int binary) {
    if (ws == NULL || (data == NULL && len != 0)) return SF_ERR_NULL_ARG;
    if (len > SF_WS_MAX_MESSAGE) return SF_ERR_TOO_LARGE;
    const unsigned char *p = (const unsigned char *)data;
    size_t off = 0;
    unsigned int flags = binary ? CURLWS_BINARY : CURLWS_TEXT;
    /* A few non-blocking retries: a message is small and the socket buffer usually
     * takes it at once; a peer that never drains is a broken link, not a wait. */
    for (int tries = 0; tries < 64; ++tries) {
        size_t sent = 0;
        CURLcode rc = curl_ws_send(ws->curl, p + off, len - off, &sent, 0, flags);
        if (rc == CURLE_OK) {
            off += sent;
            if (off >= len) return SF_OK;
            continue;
        }
        if (rc != CURLE_AGAIN) return SF_ERR_NETWORK;
        struct timespec ts = { 0, 2000000L };
        nanosleep(&ts, NULL);
    }
    return SF_ERR_NETWORK;
}

sf_status sf_ws_recv(sf_ws *ws, void *buf, size_t cap, size_t *got, int *flags, size_t *left) {
    if (got != NULL) *got = 0;
    if (flags != NULL) *flags = 0;
    if (left != NULL) *left = 0;
    if (ws == NULL || buf == NULL || got == NULL || flags == NULL) return SF_ERR_NULL_ARG;
    size_t n = 0;
    const struct curl_ws_frame *meta = NULL;
    CURLcode rc = curl_ws_recv(ws->curl, buf, cap, &n, &meta);
    if (rc == CURLE_AGAIN) return SF_OK;
    if (rc != CURLE_OK || meta == NULL) return SF_ERR_NETWORK;
    /* A fresh message starts at offset 0; bound its total size. */
    if (meta->offset == 0) ws->msg_len = 0;
    if (n > SF_WS_MAX_MESSAGE - ws->msg_len
        || (curl_off_t)ws->msg_len + meta->bytesleft > (curl_off_t)SF_WS_MAX_MESSAGE)
        return SF_ERR_TOO_LARGE;
    ws->msg_len += n;
    *got = n;
    *flags = meta->flags;
    if (left != NULL) *left = (meta->bytesleft > 0) ? (size_t)meta->bytesleft : 0;
    return SF_OK;
}

int sf_ws_fd(const sf_ws *ws) {
    if (ws == NULL || ws->curl == NULL) return -1;
    curl_socket_t fd = CURL_SOCKET_BAD;
    if (curl_easy_getinfo(ws->curl, CURLINFO_ACTIVESOCKET, &fd) != CURLE_OK) return -1;
    return (fd == CURL_SOCKET_BAD) ? -1 : (int)fd;
}

void sf_ws_close(sf_ws *ws) {
    if (ws == NULL) return;
    if (ws->curl != NULL) {
        size_t sent = 0;
        (void)curl_ws_send(ws->curl, "", 0, &sent, 0, CURLWS_CLOSE);
    }
    ws_free(ws);
}

/* --- navigability ladder (shared by GUI and headless fetchers) --- */

int sf_fallback_policy(sf_status failed, sf_policy tried, int allowlisted, sf_policy *next) {
    if (next == NULL) return 0;
    if (failed == SF_ERR_KEM_NOT_PQ && tried == SF_POLICY_PQ_HYBRID_KE) {
        *next = SF_POLICY_ALLOW_CLASSICAL_KE;
        return 1;
    }
    if (allowlisted && tried != SF_POLICY_ALLOWLISTED_INSECURE
        && failed != SF_OK) {
        *next = SF_POLICY_ALLOWLISTED_INSECURE;
        return 1;
    }
    return 0;
}

static int sf_downgrade_of(sf_policy p) {
    if (p == SF_POLICY_ALLOW_CLASSICAL_KE) return SF_DOWNGRADE_CLASSICAL_KE;
    if (p == SF_POLICY_ALLOWLISTED_INSECURE) return SF_DOWNGRADE_ALLOWLISTED;
    return SF_DOWNGRADE_NONE;
}

typedef sf_status (*sf_attempt_fn)(const char *url, const sf_config *cfg, sf_response *out,
                                   const void *body, size_t body_len, const char *ctype);

static sf_status sf_attempt_get(const char *url, const sf_config *cfg, sf_response *out,
                                const void *body, size_t body_len, const char *ctype) {
    (void)body; (void)body_len; (void)ctype;
    return sf_get_follow(url, cfg, out, SF_DEFAULT_MAX_REDIRECTS);
}

static sf_status sf_attempt_post(const char *url, const sf_config *cfg, sf_response *out,
                                 const void *body, size_t body_len, const char *ctype) {
    return sf_post(url, cfg, body, body_len, ctype, out);
}

static sf_status sf_navigable(sf_attempt_fn attempt, const char *url, sf_config *cfg,
                              sf_response *out, const void *body, size_t body_len,
                              const char *ctype, int *downgraded, int allowlisted) {
    sf_policy saved = cfg->policy;
    sf_policy tried = saved;
    int dg = SF_DOWNGRADE_NONE;
    sf_status s = attempt(url, cfg, out, body, body_len, ctype);
    sf_policy next;
    while (s != SF_OK && sf_fallback_policy(s, tried, allowlisted, &next)) {
        sf_response_free(out);
        cfg->policy = next;
        tried = next;
        s = attempt(url, cfg, out, body, body_len, ctype);
        if (s == SF_OK) dg = sf_downgrade_of(next);
    }
    cfg->policy = saved;
    if (downgraded != NULL) *downgraded = (s == SF_OK) ? dg : SF_DOWNGRADE_NONE;
    return s;
}

sf_status sf_get_follow_navigable(const char *url, sf_config *cfg, sf_response *out,
                                  int *downgraded, int allowlisted) {
