static int sv_flag(const char *s, size_t n, size_t *i, double *out) {
    while (*i < n && (sv_is_space(s[*i]) || s[*i] == ',')) ++(*i);
    if (*i >= n || (s[*i] != '0' && s[*i] != '1')) return 0;
    *out = (s[*i] == '1') ? 1.0 : 0.0;
    ++(*i);
    return 1;
}

