        if (read_full(fd, &elen, sizeof elen) != 0) { free(file); return -1; }
        if (elen > FB_MAX_ENTRY_BYTES) { free(file); return -1; }
        char *txt = NULL;
        if (elen != 0) {
            txt = (char *)malloc(elen);
