    if (read_full(t->resp_fd, &ok, sizeof ok) != 0) return io_failure(t);
    if (!ok) return TAB_ERR_SCRIPT; /* no page loaded / worker-level failure */

    int32_t is_exc = 0;
    if (read_full(t->resp_fd, &is_exc, sizeof is_exc) != 0) return io_failure(t);

    char *val = NULL;
    size_t vlen = 0;
    if (read_field(t->resp_fd, &val, &vlen) != 0) return io_failure(t);

    /* Console output produced by this eval (Freebug REPL transcript). */
    fb_buffer console;
    fb_buffer_init(&console);
    if (read_console(t->resp_fd, &console) != 0) {
        free(val); fb_buffer_free(&console);
        return io_failure(t);
    }

    out->value = val;
    out->value_len = vlen;
    out->is_exception = is_exc ? 1 : 0;
    out->console = console; /* ownership moves to the caller (tab_eval_result_free) */
    return TAB_OK;
}

/* Shared by tab_decode_image and tab_decode_image_data_url: sends `bytes` under
 * opcode `op` and parses the [ok][w][h][stride][dlen][pixels] response. *out must

static tab_status tab_decode_image_op(tab *t, uint8_t op, const char *bytes, size_t len,
                                      tab_image *out) {
    if (len > TAB_MAX_INPUT) return TAB_ERR_TOO_LARGE;

    tab_refresh_alive(t);
    if (!t->alive) return TAB_ERR_DEAD;

    tab_status sr = send_request(t, op, bytes, len);
    if (sr != TAB_OK) return sr;

    int32_t ok = 0;
    if (read_full(t->resp_fd, &ok, sizeof ok) != 0) return io_failure(t);
    if (!ok) return TAB_OK; /* not decodable: out stays zeroed, caller shows placeholder */

    uint32_t w = 0, h = 0, stride = 0;
    size_t dlen = 0;
    if (read_full(t->resp_fd, &w, sizeof w) != 0
     || read_full(t->resp_fd, &h, sizeof h) != 0
     || read_full(t->resp_fd, &stride, sizeof stride) != 0
     || read_full(t->resp_fd, &dlen, sizeof dlen) != 0) {
        return io_failure(t);
    }
    /* Validate the worker's claims against the same anti-DoS bounds the decoder
     * enforces, so a hostile child cannot desync the stream or over-claim memory
     * (dimensions_ok bounds w,h <= IMG_MAX_DIM, so w*4 and stride*h cannot overflow). */
    if (!img_dimensions_ok(w, h) || stride != w * 4u
     || dlen != (size_t)stride * (size_t)h) {
        return io_failure(t);
    }

    uint8_t *data = (uint8_t *)malloc(dlen);
    if (data == NULL) return TAB_ERR_OOM;
    if (read_full(t->resp_fd, data, dlen) != 0) { free(data); return io_failure(t); }

    out->width = w;
    out->height = h;
    out->stride = stride;
    out->data = data;
    out->data_len = dlen;
    return TAB_OK;

tab_status tab_decode_image(tab *t, const uint8_t *bytes, size_t len, tab_image *out) {
    tab_async_sync(t);
    if (t == NULL || out == NULL || (bytes == NULL && len != 0)) return TAB_ERR_NULL_ARG;
    memset(out, 0, sizeof *out);
    return tab_decode_image_op(t, OP_DECODE_IMAGE, (const char *)bytes, len, out);
}

tab_status tab_decode_image_data_url(tab *t, const char *data_url, tab_image *out) {
    tab_async_sync(t);
    if (t == NULL || data_url == NULL || out == NULL) return TAB_ERR_NULL_ARG;
    memset(out, 0, sizeof *out);

    /* Slicing the payload substring is pure pointer arithmetic over the hostile
     * URL string (same trust level as url_resolve_https parsing a hostile href in
     * this same parent process) -- it never interprets the bytes it points to. The
     * actual base64 decode, like the image format decode, happens inside the
     * confined worker. An unsupported/malformed data: URI is not a transport
     * error: it behaves like "not decodable" (placeholder), matching
     * tab_decode_image's convention. */
    const char *payload = NULL;
    size_t plen = 0;
    if (du_base64_payload(data_url, &payload, &plen) != DU_OK) return TAB_OK;

    return tab_decode_image_op(t, OP_DECODE_IMAGE_B64, payload, plen, out);
}

int tab_alive(const tab *t) {
    if (t == NULL) return 0;
    tab_refresh_alive((tab *)t);
    return t->alive;
}

pid_t tab_child_pid(const tab *t) {
    return (t != NULL) ? t->pid : -1;
}

void tab_close(tab *t) {
    if (t == NULL) return;
    tab_async_sync(t);                      /* a running job must not outlive its pipes */
    if (t->job_efd > 0) close(t->job_efd);
    if (t->req_fd >= 0) close(t->req_fd);   /* EOF => the child quits its loop */
    if (t->resp_fd >= 0) close(t->resp_fd);
    if (t->pid > 0 && !t->reaped) {
        kill(t->pid, SIGKILL); /* defensive: guarantee prompt teardown */
        int st;
        while (waitpid(t->pid, &st, 0) < 0 && errno == EINTR) { /* retry */ }
    }
    free(t->cookies_in);
    free(t->page_url);
    free(t->storage_in);
    free(t);
}

void tab_page_free(tab_page *p) {
    if (p == NULL) return;
    free(p->title);
    free(p->text);
    pv_free(p->view);
    free(p->nav_url);
    free(p->set_cookies);
    hist_ops_free(p->hist, p->nhist);
    p->hist = NULL;
    p->nhist = 0;
    open_urls_free(p->open_urls, p->nopen);
    p->open_urls = NULL;
    p->nopen = 0;
    ws_ops_free(p->ws, p->nws);
    p->ws = NULL;
    p->nws = 0;
    free(p->storage);
    p->storage = NULL;
    p->storage_len = 0;
    fb_buffer_free(&p->console);
    p->title = NULL;
    p->text = NULL;
    p->view = NULL;
    p->nav_url = NULL;
    p->set_cookies = NULL;
    p->nav_replace = 0;
    p->title_len = 0;
    p->text_len = 0;
}

void tab_eval_result_free(tab_eval_result *r) {
    if (r == NULL) return;
    free(r->value);
    fb_buffer_free(&r->console);
    r->value = NULL;
    r->value_len = 0;
    r->is_exception = 0;
}

void tab_image_free(tab_image *img) {
    if (img == NULL) return;
    free(img->data);
    img->data = NULL;
    img->width = 0;
    img->height = 0;
    img->stride = 0;
    img->data_len = 0;
}

/* Writes one encoded geometry table and waits for its acknowledgement (serving any network the
 * observer callbacks it triggers). No job synchronisation: the callers do that. */

static tab_status tab_geometry_send(tab *t, const int32_t *buf, size_t words) {
    tab_refresh_alive(t);
    if (!t->alive) return TAB_ERR_DEAD;
    uint8_t op = OP_GEOM;
    int wok = (write_full(t->req_fd, &op, 1) == 0
            && write_full(t->req_fd, &words, sizeof words) == 0
            && write_full(t->req_fd, buf, words * sizeof *buf) == 0);
    if (!wok) {
        tab_refresh_alive(t);
        return t->alive ? TAB_ERR_IO : TAB_ERR_DEAD;
    }
    int32_t accepted = 0;
    tab_status aw = tab_await_result(t);   /* observer callbacks (lazy loaders) may fetch */
    if (aw != TAB_OK) return aw;
    if (read_full(t->resp_fd, &accepted, sizeof accepted) != 0) return io_failure(t);
    return TAB_OK;
}

static int32_t *geometry_encode(const jg_table *g, size_t *words_out) {
    size_t words = jg_wire_len(g);
    if (words == 0 || words > TAB_MAX_GEOM_WORDS) return NULL;
    int32_t *buf = (int32_t *)calloc(words, sizeof *buf);
    if (buf == NULL) return NULL;
    if (jg_encode(g, buf, words) != 0) { free(buf); return NULL; }
    *words_out = words;
    return buf;
}

tab_status tab_set_geometry(tab *t, const jg_table *g) {
    if (t == NULL || g == NULL) return TAB_ERR_NULL_ARG;
    if (!t->last_net_granted) return TAB_OK;   /* untrusted page: never sent */
    tab_async_sync(t);
    size_t words = 0;
    int32_t *buf = geometry_encode(g, &words);
    if (buf == NULL) return TAB_ERR_TOO_LARGE;
    tab_status st = tab_geometry_send(t, buf, words);
    free(buf);
    return st;
}

/* ---- background jobs (tab_tick_async / tab_geometry_async) ---- */

static void job_discard(tab *t) {
    if (t->job_ready) tab_page_free(&t->job_page);
    memset(&t->job_page, 0, sizeof t->job_page);
    free(t->job_words);
    t->job_words = NULL;
    t->job_nwords = 0;
    t->job_ready = 0;
    t->in_async = 0;
}

/* Waits for a running job and DISCARDS its result: any other worker call is about to change
 * the page, so the finished job's view would be stale. */

static void tab_async_sync(tab *t) {
    if (t == NULL) return;
    if (t->job_running) {
        pthread_join(t->job_th, NULL);
        t->job_running = 0;
        t->job_ready = 1;
    }
    if (t->job_ready) job_discard(t);
}

static void *job_main(void *arg) {
    tab *t = (tab *)arg;
    tab_page pg;
    memset(&pg, 0, sizeof pg);
    tab_status st;
    if (t->job_is_tick) st = tab_mutation_request(t, OP_TICK, (int32_t)(t->job_elapsed >= 0 ? t->job_elapsed : 0), &pg);
    else st = tab_geometry_send(t, t->job_words, t->job_nwords);
    t->job_page = pg;
    t->job_st = st;
    free(t->job_words);
    t->job_words = NULL;
    uint64_t one = 1;
    if (t->job_efd >= 0) (void)!write(t->job_efd, &one, sizeof one);
    return NULL;
}

int tab_async_fd(tab *t) {
    if (t == NULL) return -1;
    if (t->job_efd <= 0) {
        int fd = eventfd(0, EFD_CLOEXEC | EFD_NONBLOCK);
        t->job_efd = fd >= 0 ? fd : -1;
    }
    return t->job_efd;
}

int tab_async_busy(const tab *t) {
    return t != NULL && (t->job_running || t->job_ready);
}

static tab_status job_start(tab *t) {
    if (tab_async_fd(t) < 0) return TAB_ERR_SPAWN;
    t->in_async = 1;
    if (pthread_create(&t->job_th, NULL, job_main, t) != 0) {
        t->in_async = 0;
        free(t->job_words);
        t->job_words = NULL;
        return TAB_ERR_SPAWN;
    }
    t->job_running = 1;
    return TAB_OK;
}

tab_status tab_tick_async(tab *t, int elapsed_ms) {
    if (t == NULL) return TAB_ERR_NULL_ARG;
    if (tab_async_busy(t)) return TAB_ERR_BUSY;
    tab_refresh_alive(t);
    if (!t->alive) return TAB_ERR_DEAD;
    t->job_is_tick = 1;
    t->job_elapsed = elapsed_ms;
    return job_start(t);
}

tab_status tab_geometry_async(tab *t, const jg_table *g) {
    if (t == NULL || g == NULL) return TAB_ERR_NULL_ARG;
    if (!t->last_net_granted) return TAB_OK;   /* untrusted page: never sent */
    if (tab_async_busy(t)) return TAB_ERR_BUSY;
    tab_refresh_alive(t);
    if (!t->alive) return TAB_ERR_DEAD;
    size_t words = 0;
    int32_t *buf = geometry_encode(g, &words);
    if (buf == NULL) return TAB_ERR_TOO_LARGE;
    t->job_is_tick = 0;
    t->job_words = buf;
    t->job_nwords = words;
    return job_start(t);
}

tab_status tab_async_finish(tab *t, tab_page *out, tab_status *job_status, int *was_tick) {
    if (t == NULL || out == NULL || job_status == NULL) return TAB_ERR_NULL_ARG;
    memset(out, 0, sizeof *out);
    if (t->job_running) {
        pthread_join(t->job_th, NULL);
        t->job_running = 0;
        t->job_ready = 1;
    }
    if (t->job_efd >= 0) {                       /* drain the completion counter */
        uint64_t v;
        while (read(t->job_efd, &v, sizeof v) > 0) { /* empty it */ }
    }
    if (!t->job_ready) return TAB_ERR_NULL_ARG;
    *out = t->job_page;
    memset(&t->job_page, 0, sizeof t->job_page);
    *job_status = t->job_st;
    if (was_tick != NULL) *was_tick = t->job_is_tick;
    t->job_ready = 0;
    t->in_async = 0;
    return TAB_OK;
}

tab_status tab_popstate(tab *t, int index, tab_page *out) {
    tab_async_sync(t);
    if (t == NULL || out == NULL) return TAB_ERR_NULL_ARG;
    memset(out, 0, sizeof *out);
    return tab_mutation_request(t, OP_POPSTATE, (int32_t)index, out);
}

tab_status tab_ws_event(tab *t, int id, int kind, int code, const char *data, size_t len,
                        tab_page *out) {
    tab_async_sync(t);
    if (t == NULL || out == NULL || (data == NULL && len != 0)) return TAB_ERR_NULL_ARG;
    memset(out, 0, sizeof *out);
    if (len > TAB_MAX_WS_MSG) return TAB_ERR_TOO_LARGE;
    tab_refresh_alive(t);
    if (!t->alive) return TAB_ERR_DEAD;
    uint8_t op = OP_WS_EVENT;
    int32_t a[3] = { (int32_t)id, (int32_t)kind, (int32_t)code };
    if (write_full(t->req_fd, &op, 1) != 0
     || write_full(t->req_fd, a, sizeof a) != 0
     || write_full(t->req_fd, &len, sizeof len) != 0
     || (len != 0 && write_full(t->req_fd, data, len) != 0)) {
        tab_refresh_alive(t);
        return t->alive ? TAB_ERR_IO : TAB_ERR_DEAD;
    }
    return tab_read_view_ex(t, out, 0);   /* a socket event is no user gesture */
}

void tab_set_storage(tab *t, const char *blob, size_t len) {
    if (t == NULL) return;
    free(t->storage_in);
    t->storage_in = NULL;
    t->storage_in_len = 0;
    if (blob == NULL || len == 0 || len > TAB_MAX_STORAGE) return;
    char *c = (char *)malloc(len);
    if (c == NULL) return;
    memcpy(c, blob, len);
    t->storage_in = c;
    t->storage_in_len = len;
}

uint32_t tc_upper(uint32_t cp) {
    if (cp >= 'a' && cp <= 'z') return cp - 0x20;
    if (cp < 0x80) return cp;
    if (cp >= 0x00E0 && cp <= 0x00FE && cp != 0x00F7) return cp - 0x20;
    if (cp == 0x00FF) return 0x0178;
    if (cp == 0x00B5) return 0x039C;
    int par = pair_parity(cp);
    if (par >= 0) return ((cp & 1u) == (uint32_t)par) ? cp - 1 : cp;
    if (cp >= 0x03B1 && cp <= 0x03CB && cp != 0x03C2) return cp - 0x20;
    if (cp == 0x03C2) return 0x03A3;
    if (cp == 0x03AC) return 0x0386;
    if (cp >= 0x03AD && cp <= 0x03AF) return cp - 0x25;
    if (cp == 0x03CC) return 0x038C;
    if (cp == 0x03CD || cp == 0x03CE) return cp - 0x3F;
    if (cp >= 0x0430 && cp <= 0x044F) return cp - 0x20;
    if (cp >= 0x0450 && cp <= 0x045F) return cp - 0x50;
    return cp;
}

uint32_t tc_lower(uint32_t cp) {
    if (cp >= 'A' && cp <= 'Z') return cp + 0x20;
    if (cp < 0x80) return cp;
    if (cp >= 0x00C0 && cp <= 0x00DE && cp != 0x00D7) return cp + 0x20;
    if (cp == 0x0178) return 0x00FF;
    int par = pair_parity(cp);
    if (par >= 0) return ((cp & 1u) != (uint32_t)par) ? cp + 1 : cp;
    if (cp >= 0x0391 && cp <= 0x03AB && cp != 0x03A2) return cp + 0x20;
    if (cp == 0x0386) return 0x03AC;
    if (cp >= 0x0388 && cp <= 0x038A) return cp + 0x25;
    if (cp == 0x038C) return 0x03CC;
    if (cp == 0x038E || cp == 0x038F) return cp + 0x3F;
    if (cp >= 0x0410 && cp <= 0x042F) return cp + 0x20;
    if (cp >= 0x0400 && cp <= 0x040F) return cp + 0x50;
    return cp;
}

int tc_is_lower(uint32_t cp) {
    return tc_upper(cp) != cp;
}

/* Decodes one UTF-8 code point of s[0,n) into *cp. Returns its byte length, or 0
 * for an invalid/truncated sequence (the caller copies that byte untouched). Only
 * 1-3 byte forms matter here: every mapped letter is in the BMP below U+0500. */

static size_t utf8_decode(const unsigned char *s, size_t n, uint32_t *cp) {
    if (n == 0) return 0;
    unsigned c = s[0];
    if (c < 0x80) { *cp = c; return 1; }
    if ((c >> 5) == 0x6) {
        if (n < 2 || (s[1] & 0xC0) != 0x80) return 0;
        *cp = ((c & 0x1Fu) << 6) | (s[1] & 0x3Fu);
        return (*cp >= 0x80) ? 2 : 0;
    }
    if ((c >> 4) == 0xE) {
        if (n < 3 || (s[1] & 0xC0) != 0x80 || (s[2] & 0xC0) != 0x80) return 0;
        *cp = ((c & 0x0Fu) << 12) | ((s[1] & 0x3Fu) << 6) | (s[2] & 0x3Fu);
        return (*cp >= 0x800) ? 3 : 0;
    }
    return 0;
}

/* Writes cp (known to need exactly len bytes) into out. */

static void utf8_put(uint32_t cp, size_t len, unsigned char *out) {
    if (len == 1) { out[0] = (unsigned char)cp; return; }
    if (len == 2) {
        out[0] = (unsigned char)(0xC0 | (cp >> 6));
        out[1] = (unsigned char)(0x80 | (cp & 0x3F));
        return;
    }
    out[0] = (unsigned char)(0xE0 | (cp >> 12));
    out[1] = (unsigned char)(0x80 | ((cp >> 6) & 0x3F));
    out[2] = (unsigned char)(0x80 | (cp & 0x3F));
}

static size_t utf8_len_of(uint32_t cp) {
    return (cp < 0x80) ? 1 : (cp < 0x800) ? 2 : (cp < 0x10000) ? 3 : 4;
}

size_t tc_transform(const char *s, size_t n, int transform, int word_start,
                    char *out, size_t cap) {
    if (s == NULL || out == NULL || cap < n) return 0;
    const unsigned char *u = (const unsigned char *)s;
    unsigned char *o = (unsigned char *)out;
    int at_word = word_start;
    for (size_t i = 0; i < n; ) {
        uint32_t cp = 0;
        size_t l = utf8_decode(u + i, n - i, &cp);
        if (l == 0) { o[i] = u[i]; ++i; at_word = 0; continue; }
        uint32_t m = cp;
        if (transform == CSS_TT_UPPERCASE) m = tc_upper(cp);
        else if (transform == CSS_TT_LOWERCASE) m = tc_lower(cp);
        else if (transform == CSS_TT_CAPITALIZE && at_word) m = tc_upper(cp);
        if (utf8_len_of(m) != l) m = cp;
        utf8_put(m, l, o + i);
        at_word = (cp == ' ' || cp == '\t' || cp == '\n');
        i += l;
    }
    return n;
}

size_t tc_smallcaps_runs(const char *s, size_t n, tc_run *out, size_t cap) {
    if (s == NULL || out == NULL || n == 0 || cap == 0) return 0;
    const unsigned char *u = (const unsigned char *)s;
    size_t count = 0;
    for (size_t i = 0; i < n; ) {
        uint32_t cp = 0;
        size_t l = utf8_decode(u + i, n - i, &cp);
        int low = 0;
        if (l == 0) l = 1;
        else low = tc_is_lower(cp);
        if (count > 0 && (out[count - 1].lowered == low || count == cap)) {
            out[count - 1].len += l;
        } else {
            out[count].off = i;
            out[count].len = l;
            out[count].lowered = low;
            ++count;
        }
        i += l;
    }
    return count;
}

#define _POSIX_C_SOURCE 200809L

#include "text_shape.h"
#include "css.h"
#include "webfont.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <cairo/cairo-ft.h>
#include <ft2build.h>
#include FT_FREETYPE_H
#include <harfbuzz/hb.h>
#include <fontconfig/fontconfig.h>

/* A single font file should never exceed this (CJK faces are the large case). */

#define TSH_MAX_FONT_BYTES ((long)(128 * 1024 * 1024))

/* One resolved face per (family, bold, italic). family is a CSS_FF_* bucket
 * (0..CSS_FF_FANTASY); idx = family*4 + bold*2 + italic. */

typedef struct tsh_entry {
    int                loaded;  /* 0 untried, 1 ok, -1 failed (don't retry) */
    unsigned char     *bytes;   /* font file contents (owned; FT + hb reference it) */
    long               nbytes;
    FT_Face            ftface;
    cairo_font_face_t *cface;
    hb_blob_t         *blob;
    hb_face_t         *hbface;
    hb_font_t         *hbfont;
} tsh_entry;

static FT_Library   g_ft;
static int          g_init_attempted;
static int          g_backend_ok;
static hb_buffer_t *g_buf;
static tsh_entry    g_cache[TSH_CACHE_SLOTS];

/* Static scratch for the measure/draw convenience wrappers (single-threaded). */
static cairo_glyph_t g_scratch[TSH_MAX_GLYPHS];

static const char *generic_name(int family) {
    switch (family) {
        case CSS_FF_SERIF:   return "serif";
        case CSS_FF_MONO:    return "monospace";
        case CSS_FF_CURSIVE: return "cursive";
        case CSS_FF_FANTASY: return "fantasy";
        default:             return "sans-serif"; /* CSS_FF_SANS / UNSET */
    }
}

static int backend_init(void) {
    if (g_init_attempted) return g_backend_ok;
    g_init_attempted = 1;
    if (FT_Init_FreeType(&g_ft) != 0) { g_backend_ok = 0; return 0; }
    /* FcInit is idempotent; FcFontMatch(NULL,...) inits implicitly anyway. */
    FcInit();
    g_buf = hb_buffer_create();
    if (g_buf == NULL || !hb_buffer_allocation_successful(g_buf)) {
        if (g_buf != NULL) { hb_buffer_destroy(g_buf); g_buf = NULL; }
        FT_Done_FreeType(g_ft);
        g_backend_ok = 0;
        return 0;
    }
    g_backend_ok = 1;
    return 1;
}

static unsigned char *read_font_file(const char *path, long *out_n) {
    FILE *fp = fopen(path, "rb");
    if (fp == NULL) return NULL;
    if (fseek(fp, 0, SEEK_END) != 0) { fclose(fp); return NULL; }
    long sz = ftell(fp);
    if (sz <= 0 || sz > TSH_MAX_FONT_BYTES) { fclose(fp); return NULL; }
    if (fseek(fp, 0, SEEK_SET) != 0) { fclose(fp); return NULL; }
    unsigned char *b = (unsigned char *)malloc((size_t)sz);
    if (b == NULL) { fclose(fp); return NULL; }
    size_t rd = fread(b, 1, (size_t)sz, fp);
    fclose(fp);
    if (rd != (size_t)sz) { free(b); return NULL; }
    *out_n = sz;
    return b;
}

/* Loads the face fontconfig matches for family name fam (a generic keyword or
 * an exact local family). FcPatternAddString, not FcNameParse: a family name may

static int load_entry_named(tsh_entry *e, const char *fam, int bold, int italic) {
    FcPattern *pat = FcPatternCreate();
    if (pat == NULL) return 0;
    if (!FcPatternAddString(pat, FC_FAMILY, (const FcChar8 *)fam)) {
        FcPatternDestroy(pat);
        return 0;
    }
    FcPatternAddInteger(pat, FC_WEIGHT, bold ? FC_WEIGHT_BOLD : FC_WEIGHT_NORMAL);
    FcPatternAddInteger(pat, FC_SLANT, italic ? FC_SLANT_ITALIC : FC_SLANT_ROMAN);
    FcConfigSubstitute(NULL, pat, FcMatchPattern);
    FcDefaultSubstitute(pat);
    FcResult res;
    FcPattern *match = FcFontMatch(NULL, pat, &res);
    FcPatternDestroy(pat);
    if (match == NULL) return 0;

    FcChar8 *file = NULL;
    if (FcPatternGetString(match, FC_FILE, 0, &file) != FcResultMatch || file == NULL) {
        FcPatternDestroy(match);
        return 0;
    }
    int index = 0;
    FcPatternGetInteger(match, FC_INDEX, 0, &index);
    int ok = load_entry_file(e, (const char *)file, index);
    FcPatternDestroy(match);
    return ok;
}

/* Loads face `index` of the font file at `path` into e (FreeType + cairo +
 * HarfBuzz over one owned copy of the bytes). 1 on success. */

static int load_entry_file(tsh_entry *e, const char *path, int index) {
    long nbytes = 0;
    unsigned char *bytes = read_font_file(path, &nbytes);
    if (bytes == NULL) return 0;

    FT_Face ft = NULL;
    if (FT_New_Memory_Face(g_ft, bytes, nbytes, index, &ft) != 0) {
        free(bytes);
        return 0;
    }
    cairo_font_face_t *cf = cairo_ft_font_face_create_for_ft_face(ft, 0);
    if (cf == NULL || cairo_font_face_status(cf) != CAIRO_STATUS_SUCCESS) {
        if (cf != NULL) cairo_font_face_destroy(cf);
        FT_Done_Face(ft);
        free(bytes);
        return 0;
    }
    hb_blob_t *blob = hb_blob_create((const char *)bytes, (unsigned)nbytes,
                                     HB_MEMORY_MODE_READONLY, NULL, NULL);
    hb_face_t *hf = hb_face_create(blob, (unsigned)index);
    hb_font_t *hfont = hb_font_create(hf);
    if (hfont == NULL || hf == NULL) {
        if (hfont != NULL) hb_font_destroy(hfont);
        if (hf != NULL) hb_face_destroy(hf);
        hb_blob_destroy(blob);
        cairo_font_face_destroy(cf);
        FT_Done_Face(ft);
        free(bytes);
        return 0;
    }

    e->bytes = bytes; e->nbytes = nbytes; e->ftface = ft; e->cface = cf;
    e->blob = blob; e->hbface = hf; e->hbfont = hfont;
    return 1;
}

static int load_entry(tsh_entry *e, int family, int bold, int italic) {
    return load_entry_named(e, generic_name(family), bold, italic);
}

static tsh_entry *get_entry(int family, int bold, int italic) {
    if (!backend_init()) return NULL;
    int fam = (family >= 0 && family <= CSS_FF_FANTASY) ? family : CSS_FF_SANS;
    int idx = fam * 4 + (bold ? 2 : 0) + (italic ? 1 : 0);
    tsh_entry *e = &g_cache[idx];
    if (e->loaded == 1) return e;
    if (e->loaded == -1) return NULL;
    if (load_entry(e, fam, bold, italic)) { e->loaded = 1; return e; }
    e->loaded = -1;
    return NULL;
}

/* Per-document @font-face table (spec/webfont.md): registered by the trusted
 * parent from policy-gated fetches, keyed by (name hash, bold, italic). Memory
 * only, freed by tsh_webfont_clear (navigation) and tsh_shutdown. Never the
 * worker: shaping a registered face runs on the painter side like every face. */

typedef struct tsh_web {
    int       used;
    unsigned  hash;
    int       bold;
    int       italic;
    tsh_entry e;
} tsh_web;

static tsh_web g_web[TSH_WEB_SLOTS];

static void web_entry_free(tsh_web *w) {
    if (w->e.hbfont != NULL) hb_font_destroy(w->e.hbfont);
    if (w->e.hbface != NULL) hb_face_destroy(w->e.hbface);
    if (w->e.blob != NULL) hb_blob_destroy(w->e.blob);
    if (w->e.cface != NULL) cairo_font_face_destroy(w->e.cface);
    if (w->e.ftface != NULL) FT_Done_Face(w->e.ftface);
    free(w->e.bytes);
    memset(w, 0, sizeof *w);
}

/* True for font programs FreeType parses without new decoders: wOFF/TrueType/
 * CFF-OpenType (and the mac aliases). wOF2 is deliberately refused until the

static int web_magic_ok(const unsigned char *b, size_t n) {
    if (b == NULL || n < 4) return 0;
    if (b[0] == 'w' && b[1] == 'O' && b[2] == 'F' && b[3] == 'F') return 1;
    if (b[0] == 0 && b[1] == 1 && b[2] == 0 && b[3] == 0) return 1;
    if (b[0] == 'O' && b[1] == 'T' && b[2] == 'T' && b[3] == 'O') return 1;
    if (b[0] == 't' && b[1] == 'r' && b[2] == 'u' && b[3] == 'e') return 1;
    if (b[0] == 't' && b[1] == 'y' && b[2] == 'p' && b[3] == '1') return 1;
    return 0;
}

/* Builds the shaping faces over an OWNED copy of bytes[0,nbytes) into e
 * (shared tail with load_entry's file path: same objects, same order, same
 * failure discipline -- free the copy on any failure, never half-register). */

static int web_make_entry(tsh_entry *e, const unsigned char *bytes, size_t nbytes) {
    unsigned char *copy = (unsigned char *)malloc(nbytes);
    if (copy == NULL) return 0;
    memcpy(copy, bytes, nbytes);
    FT_Face ft = NULL;
    if (FT_New_Memory_Face(g_ft, copy, (FT_Long)nbytes, 0, &ft) != 0) {
        free(copy);
        return 0;
    }
    cairo_font_face_t *cf = cairo_ft_font_face_create_for_ft_face(ft, 0);
    if (cf == NULL || cairo_font_face_status(cf) != CAIRO_STATUS_SUCCESS) {
        if (cf != NULL) cairo_font_face_destroy(cf);
        FT_Done_Face(ft);
        free(copy);
        return 0;
    }
    hb_blob_t *blob = hb_blob_create((const char *)copy, (unsigned)nbytes,
                                     HB_MEMORY_MODE_READONLY, NULL, NULL);
    hb_face_t *hf = hb_face_create(blob, 0);
    hb_font_t *hfont = hb_font_create(hf);
    if (hfont == NULL || hf == NULL) {
        if (hfont != NULL) hb_font_destroy(hfont);
        if (hf != NULL) hb_face_destroy(hf);
        hb_blob_destroy(blob);
        cairo_font_face_destroy(cf);
        FT_Done_Face(ft);
        free(copy);
        return 0;
    }
    e->bytes = copy;
    e->nbytes = (long)nbytes;
    e->ftface = ft;
    e->cface = cf;
    e->blob = blob;
    e->hbface = hf;
    e->hbfont = hfont;
    e->loaded = 1;
    return 1;
}

int tsh_webfont_register(const char *name,
                         const unsigned char *bytes, size_t nbytes,
                         int bold, int italic) {
    if (name == NULL || name[0] == '\0') return -1;
    if (bytes == NULL || nbytes == 0 || nbytes > WF_MAX_FACE_BYTES) return -1;
    if (!web_magic_ok(bytes, nbytes)) return -1;
    if (!backend_init()) return -1;
    unsigned h = wf_name_hash(name, strlen(name));
    if (h == 0) return -1;
    int bb = bold ? 1 : 0;
    int it = italic ? 1 : 0;
    tsh_web *slot = NULL;
    for (int i = 0; i < TSH_WEB_SLOTS; ++i) {
        if (g_web[i].used && g_web[i].hash == h
            && g_web[i].bold == bb && g_web[i].italic == it) {
            slot = &g_web[i];
            break;
        }
        if (slot == NULL && !g_web[i].used) slot = &g_web[i];
    }
    if (slot == NULL) return -1;   /* table full: fail closed */
    if (slot->used) web_entry_free(slot);
    memset(slot, 0, sizeof *slot);
    if (!web_make_entry(&slot->e, bytes, nbytes)) {
        memset(slot, 0, sizeof *slot);
        return -1;
    }
    slot->used = 1;
    slot->hash = h;
    slot->bold = bb;
    slot->italic = it;
    return 0;
}

void tsh_webfont_clear(void) {
    for (int i = 0; i < TSH_WEB_SLOTS; ++i)
        if (g_web[i].used) web_entry_free(&g_web[i]);
}

static tsh_entry *web_find(unsigned h, int bold, int italic) {
    if (h == 0) return NULL;
    for (int i = 0; i < TSH_WEB_SLOTS; ++i) {
        if (g_web[i].used && g_web[i].hash == h
            && g_web[i].bold == (bold ? 1 : 0)
            && g_web[i].italic == (italic ? 1 : 0)
            && g_web[i].e.loaded == 1)
            return &g_web[i].e;
    }
    return NULL;
}

static void entry_free(tsh_entry *e) {
    if (e->loaded != 1) { memset(e, 0, sizeof *e); return; }
    if (e->hbfont != NULL) hb_font_destroy(e->hbfont);
    if (e->hbface != NULL) hb_face_destroy(e->hbface);
    if (e->blob != NULL) hb_blob_destroy(e->blob);
    if (e->cface != NULL) cairo_font_face_destroy(e->cface);
    if (e->ftface != NULL) FT_Done_Face(e->ftface);
    free(e->bytes);
    memset(e, 0, sizeof *e);
}

/* --- Named local families (spec/text_shape.md section 7) --- */

static int ascii_ieq(const char *a, const char *b) {
    for (; *a != '\0' && *b != '\0'; ++a, ++b) {
        char x = (*a >= 'A' && *a <= 'Z') ? (char)(*a + 32) : *a;
        char y = (*b >= 'A' && *b <= 'Z') ? (char)(*b + 32) : *b;
        if (x != y) return 0;
    }
    return *a == '\0' && *b == '\0';
}

int tsh_family_is_generic(const char *name) {
    static const char *const kw[] = {
        "serif", "sans-serif", "monospace", "cursive", "fantasy", "system-ui",
        "emoji", "math", "fangsong",
    };
    if (name == NULL || name[0] == '\0') return 0;
    for (size_t i = 0; i < sizeof kw / sizeof *kw; ++i)
        if (ascii_ieq(name, kw[i])) return 1;
    return (name[0] == 'u' || name[0] == 'U') && (name[1] == 'i' || name[1] == 'I')
           && name[2] == '-';
}

int tsh_pick_from_list(const char *list, tsh_name_resolver resolve, void *ctx,
                       char *out, size_t cap) {
    if (list == NULL || resolve == NULL || out == NULL || cap == 0) return 0;
    const char *p = list;
    while (*p != '\0') {
        while (*p == ' ' || *p == '\t' || *p == ',') ++p;
        if (*p == '\0') break;
        const char *st = p;
        while (*p != '\0' && *p != ',') ++p;
        size_t n = (size_t)(p - st);
        while (n > 0 && (st[n - 1] == ' ' || st[n - 1] == '\t')) --n;
        char name[TSH_FAMILY_MAX];
        if (n == 0 || n >= sizeof name) continue;
        memcpy(name, st, n);
        name[n] = '\0';
        if (tsh_family_is_generic(name)) return 0;
        if (resolve(name, out, cap, ctx)) return 1;
    }
    return 0;
}

const char *tsh_pick_family(const char *req, const char *const *subs, const int *strong,
                            size_t n, int (*installed)(const char *name, void *ctx),
                            void *ctx) {
    if (req == NULL || installed == NULL) return NULL;
    if (installed(req, ctx)) return req;
    if (subs == NULL || strong == NULL) return NULL;
    /* subs[0] is the request itself; the run of strong substitutes follows. */
    for (size_t k = 1; k < n && strong[k]; ++k)
        if (subs[k] != NULL && installed(subs[k], ctx)) return subs[k];
    return NULL;
}

/* An exact (case-insensitive) family that fontconfig really has on disk. */

static int fc_installed(const char *name, void *ctx) {
    (void)ctx;
    FcPattern *p = FcPatternCreate();
    if (p == NULL) return 0;
    FcPatternAddString(p, FC_FAMILY, (const FcChar8 *)name);
    FcObjectSet *os = FcObjectSetBuild(FC_FAMILY, (char *)NULL);
    FcFontSet *fs = (os != NULL) ? FcFontList(NULL, p, os) : NULL;
    int ok = fs != NULL && fs->nfont > 0;
    if (fs != NULL) FcFontSetDestroy(fs);
    if (os != NULL) FcObjectSetDestroy(os);
    FcPatternDestroy(p);
    return ok;
}

#define TSH_SUBS_MAX 16

/* An @font-face local(NAME) source, marked '=NAME' by the cascade: a face whose
 * exact full name or PostScript name is NAME (CSS Fonts 4 4.3), answered with
 * its family. Never a fontconfig substitute: local("Arial") is not Liberation. */
static int fc_resolve_full_name(const char *name, char *out, size_t cap) {
    static const char *const keys[] = { FC_FULLNAME, FC_POSTSCRIPT_NAME };
    for (size_t k = 0; k < sizeof keys / sizeof keys[0]; ++k) {
        FcPattern *p = FcPatternCreate();
        if (p == NULL) return 0;
        FcPatternAddString(p, keys[k], (const FcChar8 *)name);
        FcObjectSet *os = FcObjectSetBuild(FC_FAMILY, (char *)NULL);
        FcFontSet *fs = (os != NULL) ? FcFontList(NULL, p, os) : NULL;
        int ok = 0;
        FcChar8 *fam = NULL;
        if (fs != NULL && fs->nfont > 0 &&
            FcPatternGetString(fs->fonts[0], FC_FAMILY, 0, &fam) == FcResultMatch &&
            fam != NULL && strlen((const char *)fam) < cap) {
            memcpy(out, fam, strlen((const char *)fam) + 1);
            ok = 1;
        }
        if (fs != NULL) FcFontSetDestroy(fs);
        if (os != NULL) FcObjectSetDestroy(os);
        FcPatternDestroy(p);
        if (ok) return 1;
    }
    return 0;
}

static int fc_resolve(const char *name, char *out, size_t cap, void *ctx) {
    (void)ctx;
    if (name[0] == '=') return fc_resolve_full_name(name + 1, out, cap);
    FcPattern *p = FcPatternCreate();
    if (p == NULL) return 0;
    FcPatternAddString(p, FC_FAMILY, (const FcChar8 *)name);
    FcConfigSubstitute(NULL, p, FcMatchPattern);
    const char *subs[TSH_SUBS_MAX];
    int strong[TSH_SUBS_MAX];
    size_t n = 0;
    for (int id = 0; n < TSH_SUBS_MAX; ++id) {
        FcValue v;
        FcValueBinding b;
        if (FcPatternGetWithBinding(p, FC_FAMILY, id, &v, &b) != FcResultMatch) break;
        if (v.type != FcTypeString) continue;
        subs[n] = (const char *)v.u.s;
        strong[n] = (b == FcValueBindingStrong || b == FcValueBindingSame);
        ++n;
    }
    const char *pick = tsh_pick_family(name, subs, strong, n, fc_installed, NULL);
    int ok = 0;
    if (pick != NULL && strlen(pick) < cap) {
        memcpy(out, pick, strlen(pick) + 1);
        ok = 1;
    }
    FcPatternDestroy(p);
    return ok;
}

typedef struct tsh_lfam {
    char      name[TSH_FAMILY_MAX];
    tsh_entry e[4];   /* bold*2 + italic */
    int       tried[4];
} tsh_lfam;

typedef struct tsh_llist {
    char *list;       /* owned copy, the cache key */
    int   fam;        /* index into g_lfam, -1 = resolves to nothing */
} tsh_llist;

static tsh_lfam  g_lfam[TSH_LOCAL_FAMILIES];
static size_t    g_nlfam;
static tsh_llist g_llist[TSH_LOCAL_LISTS];
static size_t    g_nllist;

static void local_clear(void) {
    for (size_t i = 0; i < g_nlfam; ++i)
        for (int k = 0; k < 4; ++k) entry_free(&g_lfam[i].e[k]);
    for (size_t i = 0; i < g_nllist; ++i) free(g_llist[i].list);
    memset(g_lfam, 0, sizeof g_lfam);
    memset(g_llist, 0, sizeof g_llist);
    g_nlfam = 0;
    g_nllist = 0;
}

static int lfam_index(const char *fam) {
    for (size_t i = 0; i < g_nlfam; ++i)
        if (ascii_ieq(g_lfam[i].name, fam)) return (int)i;
    if (g_nlfam >= TSH_LOCAL_FAMILIES || strlen(fam) >= TSH_FAMILY_MAX) return -1;
    memcpy(g_lfam[g_nlfam].name, fam, strlen(fam) + 1);
    return (int)g_nlfam++;
}

int tsh_local_handle(const char *list) {
    if (list == NULL || list[0] == '\0') return 0;
    for (size_t i = 0; i < g_nllist; ++i)
        if (strcmp(g_llist[i].list, list) == 0)
            return g_llist[i].fam >= 0 ? (int)i + 1 : 0;
    if (g_nllist >= TSH_LOCAL_LISTS || !backend_init()) return 0;
    size_t n = strlen(list);
    if (n == (size_t)-1) return 0;
    char *copy = malloc(n + 1);
    if (copy == NULL) return 0;
    memcpy(copy, list, n + 1);
    char fam[TSH_FAMILY_MAX];
    int fi = tsh_pick_from_list(list, fc_resolve, NULL, fam, sizeof fam) ? lfam_index(fam) : -1;
    g_llist[g_nllist].list = copy;
    g_llist[g_nllist].fam = fi;
    ++g_nllist;
    return fi >= 0 ? (int)g_nllist : 0;
}

static tsh_entry *local_entry(int handle, int bold, int italic) {
    if (handle <= 0 || (size_t)handle > g_nllist) return NULL;
    int fi = g_llist[handle - 1].fam;
    if (fi < 0 || (size_t)fi >= g_nlfam) return NULL;
    tsh_lfam *lf = &g_lfam[fi];
    int k = (bold ? 2 : 0) + (italic ? 1 : 0);
    if (lf->e[k].loaded == 1) return &lf->e[k];
    if (lf->tried[k]) return NULL;
    lf->tried[k] = 1;
    if (load_entry_named(&lf->e[k], lf->name, bold, italic)) {
        lf->e[k].loaded = 1;
        return &lf->e[k];
    }
    return NULL;
}

/* Entry for a full font selector: a registered @font-face wins over the local
 * bucket stack; a set-but-unregistered hash falls through to it (the face may
 * belong to another document -- the table is per-document, cleared on
 * navigation -- so missing is routine, never an error). */

static tsh_entry *get_entry_ex(const tsh_font *f) {
    if (f->wfh != 0) {
        tsh_entry *w = web_find(f->wfh, f->bold, f->italic);
        if (w != NULL) return w;
    }
    if (f->local > 0) {
        tsh_entry *l = local_entry(f->local, f->bold, f->italic);
        if (l != NULL) return l;
    }
    return get_entry(f->family, f->bold, f->italic);
}

int tsh_ready(void) {
    /* Backend usable iff the default (sans) face resolves. */
    return get_entry(CSS_FF_SANS, 0, 0) != NULL;
}

tsh_status tsh_shape(const tsh_font *f, double px, const char *text, size_t len,
                     cairo_glyph_t *out, size_t cap, size_t *out_n, double *out_adv) {
    if (f == NULL || out == NULL || out_n == NULL || out_adv == NULL) return TSH_ERR_INPUT;
    if (cap == 0) return TSH_ERR_INPUT;
    if (text == NULL && len != 0) return TSH_ERR_INPUT;
    /* px must be finite and positive; px>1e9 catches +inf, !(px>0) catches NaN/<=0. */
    if (!(px > 0.0) || px > 1.0e9) return TSH_ERR_INPUT;
    if (len > (size_t)TSH_MAX_TEXT) return TSH_ERR_INPUT;

    *out_n = 0;
    *out_adv = 0.0;
    if (len == 0) return TSH_OK;

    tsh_entry *e = get_entry_ex(f);
    if (e == NULL) return TSH_ERR_UNAVAIL;

    int scale = (int)(px * 64.0 + 0.5);
    if (scale < 1) scale = 1;
    hb_font_set_scale(e->hbfont, scale, scale);

    hb_buffer_reset(g_buf);
    hb_buffer_add_utf8(g_buf, text, (int)len, 0, (int)len);
    hb_buffer_guess_segment_properties(g_buf);
    hb_shape(e->hbfont, g_buf, NULL, 0);

    unsigned gn = hb_buffer_get_length(g_buf);
    if ((size_t)gn > cap || gn > TSH_MAX_GLYPHS) return TSH_ERR_OVERFLOW;

    const hb_glyph_info_t     *info = hb_buffer_get_glyph_infos(g_buf, NULL);
    const hb_glyph_position_t  *pos  = hb_buffer_get_glyph_positions(g_buf, NULL);
    if ((gn != 0) && (info == NULL || pos == NULL)) return TSH_ERR_UNAVAIL;

    double penx = 0.0, peny = 0.0;
    for (unsigned i = 0; i < gn; ++i) {
        out[i].index = info[i].codepoint;            /* glyph id (matches cface) */
        out[i].x = penx + (double)pos[i].x_offset / 64.0;
        out[i].y

static unsigned utf8_next(const char *s, size_t n, size_t *len) {
    const unsigned char *u = (const unsigned char *)s;
    unsigned c = u[0];
    size_t l = (c < 0x80) ? 1 : ((c >> 5) == 0x6) ? 2 : ((c >> 4) == 0xe) ? 3
             : ((c >> 3) == 0x1e) ? 4 : 1;
    if (l > n) l = 1;
    if (l == 1) { *len = 1; return (c < 0x80) ? c : 0xFFFDu; }
    unsigned cp = c & (0x7fu >> l);
    for (size_t k = 1; k < l; ++k) {
        if ((u[k] & 0xc0) != 0x80) { *len = 1; return 0xFFFDu; }
        cp = (cp << 6) | (u[k] & 0x3fu);
    }
    *len = l;
    return cp;
}

static int is_private_use(unsigned cp) {
    return (cp >= 0xe000 && cp <= 0xf8ff) || cp >= 0xf0000;
}

/* A character that never chooses a face of its own: it rides the run before it. */

static int rides_previous(unsigned cp) {
    return cp < 0x20 || cp == 0x7f ||
           (cp >= 0x300 && cp <= 0x36f) || (cp >= 0x1ab0 && cp <= 0x1aff) ||
           (cp >= 0x20d0 && cp <= 0x20ff) || (cp >= 0xfe20 && cp <= 0xfe2f) ||
           (cp >= 0xfe00 && cp <= 0xfe0f) || cp == 0x200c || cp == 0x200d ||
           (cp >= 0xe0100 && cp <= 0xe01ef);
}

int tsh_segment(const char *text, size_t len, tsh_cover_fn cover, void *ctx,
                tsh_run *runs, size_t cap) {
    if (text == NULL || cover == NULL || runs == NULL) return -1;
    size_t n = 0, i = 0;
    while (i < len) {
        size_t cl;
        unsigned cp = utf8_next(text + i, len - i, &cl);
        int face = (n > 0 && rides_previous(cp)) ? runs[n - 1].face
                 : (rides_previous(cp) ? 0 : cover(cp, ctx));
        if (n > 0 && runs[n - 1].face == face) {
            runs[n - 1].end = i + cl;
        } else {
            if (n >= cap) return -1;
            runs[n].start = i;
            runs[n].end = i + cl;
            runs[n].face = face;
            ++n;
        }
        i += cl;
    }
    return (int)n;
}

/* Fallback faces, one per font file fontconfig picked (bold/italic folded into
 * the match). The block cache maps (code point >> 8, bold) to a slot + 1, or -1
 * for "no installed face covers this block" (0 = not asked yet). */

typedef struct tsh_fb {
    char      file[512];
    int       index;
    int       bold;
    tsh_entry e;
} tsh_fb;

static tsh_fb g_fb[TSH_FB_SLOTS];
static size_t g_nfb;
static short  g_fb_block[2][TSH_FB_BLOCKS];

static void fb_clear(void) {
    for (size_t i = 0; i < g_nfb; ++i) entry_free(&g_fb[i].e);
    memset(g_fb, 0, sizeof g_fb);
    memset(g_fb_block, 0, sizeof g_fb_block);
    g_nfb = 0;
}

