typedef struct tsh_cover_ctx {
    tsh_entry *primary;
    int        bold;
    tsh_entry *faces[16];  /* face id k -> entry (k = 0 is the primary) */
    int        nfaces;
} tsh_cover_ctx;

/* cover callback: 0 when the requested face has the glyph (or nothing else
 * does), else the id of the fallback face that has it. */

static int cover_cp(unsigned cp, void *vctx) {
    tsh_cover_ctx *c = (tsh_cover_ctx *)vctx;
    hb_codepoint_t g;
    if (cp == ' ' || hb_font_get_nominal_glyph(c->primary->hbfont, cp, &g)) return 0;
    if (is_private_use(cp)) return 0;
    tsh_entry *e = fb_entry(cp, c->bold);
    if (e == NULL || e == c->primary) return 0;
    for (int k = 1; k < c->nfaces; ++k) if (c->faces[k] == e) return k;
    if (c->nfaces >= (int)(sizeof c->faces / sizeof c->faces[0])) return 0;
    c->faces[c->nfaces] = e;
    return c->nfaces++;
}

/* Shapes one run with one entry into g_scratch (n glyphs, advance adv). */

static tsh_status shape_entry(tsh_entry *e, double px, const char *text, size_t len,
                              size_t *out_n, double *out_adv) {
    int scale = (int)(px * 64.0 + 0.5);
    if (scale < 1) scale = 1;
    hb_font_set_scale(e->hbfont, scale, scale);
    hb_buffer_reset(g_buf);
    hb_buffer_add_utf8(g_buf, text, (int)len, 0, (int)len);
    hb_buffer_guess_segment_properties(g_buf);
    hb_shape(e->hbfont, g_buf, NULL, 0);
    unsigned gn = hb_buffer_get_length(g_buf);
    if (gn > TSH_MAX_GLYPHS) return TSH_ERR_OVERFLOW;
    const hb_glyph_info_t     *info = hb_buffer_get_glyph_infos(g_buf, NULL);
    const hb_glyph_position_t  *pos  = hb_buffer_get_glyph_positions(g_buf, NULL);
    if (gn != 0 && (info == NULL || pos == NULL)) return TSH_ERR_UNAVAIL;
    double penx = 0.0, peny = 0.0;
    for (unsigned i = 0; i < gn; ++i) {
        g_scratch[i].index = info[i].codepoint;
        if (info[i].codepoint == 0 && info[i].cluster < len) {
            size_t cl;
            if (is_private_use(utf8_next(text + info[i].cluster, len - info[i].cluster, &cl)))
                g_scratch[i].index = TSH_BLANK_GLYPH;
        }
        g_scratch[i].x = penx + (double)pos[i].x_offset / 64.0;
        g_scratch[i].y = peny - (double)pos[i].y_offset / 64.0;
        penx += (double)pos[i].x_advance / 64.0;
        peny -= (double)pos[i].y_advance / 64.0;
    }
    *out_n = gn;
    *out_adv = penx;
    return TSH_OK;
}

#define TSH_MAX_RUNS 64

/* Measures (cr == NULL) or draws [text,len) run by run, each with the face that
 * has its glyphs. Returns the status and the total advance. */

static tsh_status shape_runs(cairo_t *cr, const tsh_font *f, double px, double x,
                             double baseline, const char *text, size_t len,
                             double *out_adv) {
    *out_adv = 0.0;
    if (f == NULL || text == NULL || !(px > 0.0) || px > 1.0e9) return TSH_ERR_INPUT;
    if (len > (size_t)TSH_MAX_TEXT) return TSH_ERR_INPUT;
    if (len == 0) return TSH_OK;
    tsh_entry *e = get_entry_ex(f);
    if (e == NULL) return TSH_ERR_UNAVAIL;
    tsh_cover_ctx cc;
    memset(&cc, 0, sizeof cc);
    cc.primary = e;
    cc.bold = f->bold;
    cc.faces[0] = e;
    cc.nfaces = 1;
    tsh_run runs[TSH_MAX_RUNS];
    int nr = tsh_segment(text, len, cover_cp, &cc, runs, TSH_MAX_RUNS);
    if (nr <= 0) { nr = 1; runs[0].start = 0; runs[0].end = len; runs[0].face = 0; }
    double pen = 0.0;
    for (int r = 0; r < nr; ++r) {
        tsh_entry *re = (runs[r].face > 0 && runs[r].face < cc.nfaces) ? cc.faces[runs[r].face] : e;
        size_t n = 0;
        double adv = 0.0;
        tsh_status st = shape_entry(re, px, text + runs[r].start,
                                    runs[r].end - runs[r].start, &n, &adv);
        if (st != TSH_OK) return st;
        if (cr != NULL && n > 0) {
            cairo_set_font_face(cr, re->cface);
            cairo_set_font_size(cr, px);
            size_t shown = 0;
            for (size_t i = 0; i < n; ++i) {
                if (g_scratch[i].index == TSH_BLANK_GLYPH) continue;
                g_scratch[shown] = g_scratch[i];
                g_scratch[shown].x += x + pen;
                g_scratch[shown].y += baseli

double tsh_measure(const tsh_font *f, double px, const char *text, size_t len) {
    double adv = 0.0;
    tsh_status st = shape_runs(NULL, f, px, 0.0, 0.0, text, len, &adv);
    return (st == TSH_OK) ? adv : -1.0;
}

tsh_status tsh_draw(cairo_t *cr, const tsh_font *f, double px,
                    double x, double baseline, const char *text, size_t len) {
    if (cr == NULL) return TSH_ERR_INPUT;
    double adv = 0.0;
    return shape_runs(cr, f, px, x, baseline, text, len, &adv);
}

cairo_font_face_t *tsh_face(const tsh_font *f) {
    if (f == NULL || !backend_init()) return NULL;
    tsh_entry *e = get_entry_ex(f);
    return (e != NULL) ? e->cface : NULL;
}

void tsh_shutdown(void) {
    tsh_webfont_clear();
    fb_clear();
    for (int i = 0; i < TSH_CACHE_SLOTS; ++i) entry_free(&g_cache[i]);
    local_clear();
    if (g_buf != NULL) { hb_buffer_destroy(g_buf); g_buf = NULL; }
    if (g_backend_ok) FT_Done_FreeType(g_ft);
    g_backend_ok = 0;
    g_init_attempted = 0;
}

 * the buffer is rejected whole (fail closed), never applied partially.
 */

#include "textfield.h"

#include <string.h>

void tf_init(tf_field *f) {
    if (f == NULL) return;
    f->buf[0] = '\0';
    f->len = 0;
    f->cursor = 0;
}

void tf_clear(tf_field *f) {
    tf_init(f);
}

tf_status tf_set(tf_field *f, const char *s) {
    if (f == NULL || s == NULL) return TF_ERR_NULL_ARG;
    size_t n = strlen(s);
    if (n >= TF_CAP) return TF_ERR_FULL; /* leave the field intact */
    memcpy(f->buf, s, n);
    f->buf[n] = '\0';
    f->len = n;
    f->cursor = n;
    return TF_OK;
}

tf_status tf_insert(tf_field *f, char c) {
    if (f == NULL) return TF_ERR_NULL_ARG;
    if (f->len + 1 >= TF_CAP) return TF_ERR_FULL; /* no room beside the NUL */
    /* Shift the tail [cursor, len) one byte right, then drop c in. */
    memmove(f->buf + f->cursor + 1, f->buf + f->cursor, f->len - f->cursor);
    f->buf[f->cursor] = c;
    f->len += 1;
    f->cursor += 1;
    f->buf[f->len] = '\0';
    return TF_OK;
}

void tf_backspace(tf_field *f) {
    if (f == NULL || f->cursor == 0) return;
    memmove(f->buf + f->cursor - 1, f->buf + f->cursor, f->len - f->cursor);
    f->len -= 1;
    f->cursor -= 1;
    f->buf[f->len] = '\0';
}

void tf_delete(tf_field *f) {
    if (f == NULL || f->cursor >= f->len) return;
    memmove(f->buf + f->cursor, f->buf + f->cursor + 1, f->len - f->cursor - 1);
    f->len -= 1;
    f->buf[f->len] = '\0';
}

void tf_move(tf_field *f, long delta) {
    if (f == NULL) return;
    if (delta < 0) {
        size_t back = (size_t)(-delta);
        f->cursor = (back >= f->cursor) ? 0 : f->cursor - back;
    } else {
        size_t fwd = (size_t)delta;
        f->cursor = (fwd >= f->len - f->cursor) ? f->len : f->cursor + fwd;
    }
}

void tf_home(tf_field *f) {
    if (f == NULL) return;
    f->cursor = 0;
}

void tf_end(tf_field *f) {
    if (f == NULL) return;
    f->cursor = f->len;
}

const char *tf_text(const tf_field *f) {
    return (f != NULL) ? f->buf : "";
}

size_t tf_len(const tf_field *f) {
    return (f != NULL) ? f->len : 0;
}

size_t tf_cursor(const tf_field *f) {
    return (f != NULL) ? f->cursor : 0;
}

int ti_should_impersonate(int host_in_allowlist, int host_js_enabled,
                          int user_opt_in) {
    return (host_in_allowlist && host_js_enabled && user_opt_in) ? 1 : 0;
}

/* --- bounded string length (no dependency on strnlen / feature macros) --- */

static size_t bounded_len(const char *s, size_t max) {
    size_t i = 0;
    while (i < max && s[i] != '\0') i++;
    return i;
}

/* --- writer: accumulates into a fixed buffer, latches overflow, never overruns --- */

static void put_u8(ti_wr *w, uint8_t v) {
    if (w->ovf || w->off + 1u > w->cap) { w->ovf = 1; return; }
    w->p[w->off++] = v;
}

static void put_u32(ti_wr *w, uint32_t v) {
    if (w->ovf || w->off + 4u > w->cap) { w->ovf = 1; return; }
    w->p[w->off++] = (uint8_t)(v & 0xffu);
    w->p[w->off++] = (uint8_t)((v >> 8) & 0xffu);
    w->p[w->off++] = (uint8_t)((v >> 16) & 0xffu);
    w->p[w->off++] = (uint8_t)((v >> 24) & 0xffu);
}

static void put_u64(ti_wr *w, uint64_t v) {
    if (w->ovf || w->off + 8u > w->cap) { w->ovf = 1; return; }
    for (int i = 0; i < 8; ++i) w->p[w->off++] = (uint8_t)((v >> (8 * i)) & 0xffu);
}

static void put_blob(ti_wr *w, const uint8_t *b, size_t n) {
    put_u32(w, (uint32_t)n);
    if (w->ovf) return;
    if (w->off + n > w->cap) { w->ovf = 1; return; }
    if (n != 0 && b != NULL) { memcpy(w->p + w->off, b, n); w->off += n; }
    else if (n != 0) { w->ovf = 1; } /* claimed length with no data: refuse */
}

/* --- reader: bounds-checked, latches error, allocates owned copies --- */

static uint8_t get_u8(ti_rd *r) {
    if (r->err || r->off + 1u > r->len) { r->err = 1; return 0; }
    return r->p[r->off++];
}

static uint32_t get_u32(ti_rd *r) {
    if (r->err || r->off + 4u > r->len) { r->err = 1; return 0; }
    uint32_t v = (uint32_t)r->p[r->off]
               | ((uint32_t)r->p[r->off + 1] << 8)
               | ((uint32_t)r->p[r->off + 2] << 16)
               | ((uint32_t)r->p[r->off + 3] << 24);
    r->off += 4;
    return v;
}

static uint64_t get_u64(ti_rd *r) {
    if (r->err || r->off + 8u > r->len) { r->err = 1; return 0; }
    uint64_t v = 0;
    for (int i = 0; i < 8; ++i) v |= (uint64_t)r->p[r->off + i] << (8 * i);
    r->off += 8;
    return v;
}

/* Reads a length-prefixed byte blob (<= cap). n==0 yields (NULL,0). */

static void get_bytes(ti_rd *r, size_t cap, uint8_t **out, size_t *out_len) {
    *out = NULL; *out_len = 0;
    uint32_t n = get_u32(r);
    if (r->err) return;
    if ((size_t)n > cap || r->off + (size_t)n > r->len) { r->err = 1; return; }
    if (n == 0) return;
    uint8_t *b = malloc(n);
    if (b == NULL) { r->err = 1; return; }
    memcpy(b, r->p + r->off, n);
    r->off += n;
    *out = b; *out_len = n;
}

/* Reads a length-prefixed string (<= cap chars), NUL-terminates it. */

static char *get_str(ti_rd *r, size_t cap) {
    uint32_t n = get_u32(r);
    if (r->err) return NULL;
    if ((size_t)n > cap || r->off + (size_t)n > r->len) { r->err = 1; return NULL; }
    if (n == UINT32_MAX) { r->err = 1; return NULL; }
    char *s = malloc((size_t)n + 1u);
    if (s == NULL) { r->err = 1; return NULL; }
    if (n != 0) memcpy(s, r->p + r->off, n);
    s[n] = '\0';
    r->off += n;
    return s;
}

static int valid_profile(int p) {
    return p == TI_PROFILE_CHROME_CLASSIC || p == TI_PROFILE_CHROME_MLKEM;
}

/* --- request codec --- */

size_t ti_encode_req(const ti_req *r, uint8_t *out, size_t out_cap) {
    if (r == NULL || out == NULL) return 0;
    if (r->url == NULL || r->method == NULL || r->headers == NULL) return 0;
    if (!valid_profile((int)r->profile)) return 0;
    size_t ul = strlen(r->url), ml = strlen(r->method), hl = strlen(r->headers);
    if (ul > TI_MAX_URL || ml > TI_MAX_METHOD || hl > TI_MAX_HEADERS
     || r->body_len > TI_MAX_BODY) return 0;

    ti_wr w = { out, out_cap, 0, 0 };
    put_u32(&w, TI_MAGIC);
    put_u8(&w, (uint8_t)r->profile);
    put_blob(&w, (const uint8_t *)r->url, ul);
    put_blob(&w, (const uint8_t *)r->method, ml);
    put_blob(&w, (const uint8_t *)r->headers, hl);
    put_blob(&w, r->body, r->body_len);
    return w.ovf ? 0 : w.off;
}

int ti_decode_req(const uint8_t *in, size_t len, ti_req *out) {
    if (in == NULL || out == NULL) return -1;
    memset(out, 0, sizeof *out);

    ti_rd r = { in, len, 0, 0 };
    uint32_t magic = get_u32(&r);
    if (r.err || magic != TI_MAGIC) return -1;
    uint8_t prof = get_u8(&r);
    if (r.err || !valid_profile(prof)) return -1;

    char *url = get_str(&r, TI_MAX_URL);
    char *method = get_str(&r, TI_MAX_METHOD);
    char *headers = get_str(&r, TI_MAX_HEADERS);
    uint8_t *body = NULL; size_t body_len = 0;
    get_bytes(&r, TI_MAX_BODY, &body, &body_len);

    if (r.err || r.off != r.len) {
        free(url); free(method); free(headers); free(body);
        return -1;
    }
    out->url = url; out->method = method; out->headers = headers;
    out->body = body; out->body_len = body_len;
    out->profile = (ti_profile)prof;
    return 0;
}

void ti_req_free(ti_req *r) {
    if (r == NULL) return;
    free((void *)r->url);
    free((void *)r->method);
    free((void *)r->headers);
    free((void *)r->body);
    memset(r, 0, sizeof *r);
}

/* --- response codec --- */

size_t ti_encode_resp(const ti_resp *r, uint8_t *out, size_t out_cap) {
    if (r == NULL || out == NULL) return 0;
    const char *hdr = (r->headers != NULL) ? r->headers : "";
    size_t hl = strlen(hdr);
    size_t gl = bounded_len(r->negotiated_group, TI_MAX_GROUP);
    if (hl > TI_MAX_RESP_HDR || r->body_len > TI_MAX_RESP_BODY
     || r->peer_chain_len > TI_MAX_CHAIN || gl >= TI_MAX_GROUP) return 0;

    ti_wr w = { out, out_cap, 0, 0 };
    put_u32(&w, TI_MAGIC);
    put_u64(&w, (uint64_t)(int64_t)r->status);
    put_blob(&w, (const uint8_t *)hdr, hl);
    put_blob(&w, r->body, r->body_len);
    put_blob(&w, r->peer_chain_der, r->peer_chain_len);
    put_blob(&w, (const uint8_t *)r->negotiated_group, gl);
    put_u64(&w, (uint64_t)(int64_t)r->tls_version);
    return w.ovf ? 0 : w.off;
}

int ti_decode_resp(const uint8_t *in, size_t len, ti_resp *out) {
    if (in == NULL || out == NULL) return -1;
    memset(out, 0, sizeof *out);

    ti_rd r = { in, len, 0, 0 };
    uint32_t magic = get_u32(&r);
    if (r.err || magic != TI_MAGIC) return -1;
    uint64_t status = get_u64(&r);
    char *hdr = get_str(&r, TI_MAX_RESP_HDR);
    uint8_t *body = NULL; size_t body_len = 0;
    get_bytes(&r, TI_MAX_RESP_BODY, &body, &body_len);
    uint8_t *chain = NULL; size_t chain_len = 0;
    get_bytes(&r, TI_MAX_CHAIN, &chain, &chain_len);
    char *grp = get_str(&r, TI_MAX_GROUP - 1u);
    uint64_t ver = get_u64(&r);

    if (r.err || r.off != r.len) {
        free(hdr); free(body); free(chain); free(grp);
        return -1;
    }
    out->status = (long)(int64_t)status;
    out->headers = hdr;
    out->body = body; out->body_len = body_len;
    out->peer_chain_der = chain; out->peer_chain_len = chain_len;
    if (grp != NULL) {
        size_t gl = bounded_len(grp, TI_MAX_GROUP - 1u);
        memcpy(out->negotiated_group, grp, gl);
        out->negotiated_group[gl] = '\0';
        free(grp);
    }
    out->tls_version = (long)(int64_t)ver;
    return 0;
}

void ti_resp_free(ti_resp *r) {
    if (r == NULL) return;
    free(r->headers);
    free(r->body);
    free(r->peer_chain_der);
    memset(r, 0, sizeof *r);
}

static int layout_push(ui_layout *lay, size_t offset, size_t len) {
    if (lay->count == lay->cap) {
        size_t ncap = lay->cap ? lay->cap * 2 : 32;
        ui_line *grown = (ui_line *)realloc(lay->lines, ncap * sizeof *grown);
        if (grown == NULL) return -1;
        lay->lines = grown;
        lay->cap = ncap;
    }
    lay->lines[lay->count].offset = offset;
    lay->lines[lay->count].len = len;
    lay->count++;
    return 0;
}

