        else if ((c & 0xF0) == 0xE0) { k = 2; cp = c & 0x0F; min = 0x800; }
        else if ((c & 0xF8) == 0xF0) { k = 3; cp = c & 0x07; min = 0x10000; }
        else return 0;
        if (k > n - i - 1) return 0;
        for (size_t j = 1; j <= k; ++j) {
            if ((s[i + j] & 0xC0) != 0x80) return 0;
            cp = (cp << 6) | (s[i + j] & 0x3F);
        }
        if (cp < min || cp > 0x10FFFF) return 0;
        i += k + 1;
    }
    return 1;
}

static int key_cmp(const void *a, const void *b) {
    const key_ref *x = (const key_ref *)a, *y = (const key_ref *)b;
    uint32_t m = x->n < y->n ? x->n : y->n;
    int c = memcmp(x->p, y->p, m);
    if (c != 0) return c;
    return (x->n > y->n) - (x->n < y->n);
}

/* Full validation; on success *bytes_out (optional) = key + value bytes. */

static int check(const char *blob, size_t len, size_t *bytes_out) {
    if (blob == NULL || len < 4) return -1;
    const unsigned char *b = (const unsigned char *)blob;
    uint32_t n = get_u32(b);
    if (n > WST_MAX_KEYS) return -1;
    key_ref *keys = NULL;
    if (n > 0) {
        keys = (key_ref *)calloc(n, sizeof *keys);
        if (keys == NULL) return -1;
    }
    size_t o = 4, bytes = 0;
    int ok = 1;
    for (uint32_t i = 0; i < n && ok; ++i) {
        for (int part = 0; part < 2 && ok; ++part) {
            if (len - o < 4) { ok = 0; break; }
            uint32_t l = get_u32(b + o);
            o += 4;
            if (l > len - o || l > WST_QUOTA - bytes) { ok = 0; break; }
            if (!utf8_ok(b + o, l)) { ok = 0; break; }
            if (part == 0) { keys[i].p = b + o; keys[i].n = l; }
            bytes += l;
            o += l;
        }
    }
    if (ok && o != len) ok = 0;                     /* trailing bytes */
    if (ok && n > 1) {
        qsort(keys, n, sizeof *keys, key_cmp);
        for (uint32_t i = 1; i < n && ok; ++i)
            if (key_cmp(&keys[i - 1], &keys[i]) == 0) ok = 0;
    }
    free(keys);
    if (!ok) return -1;
    if (bytes_out != NULL) *bytes_out = bytes;
    return 0;
}

int wst_decode_check(const char *blob, size_t len) {
    return check(blob, len, NULL);
}

wst_db *wst_new(void) {
    return (wst_db *)calloc(1, sizeof(wst_db));
}

void wst_free(wst_db *db) {
    if (db == NULL) return;
    for (size_t i = 0; i < WST_MAX_ORIGINS; ++i) {
        free(db->o[i].origin);
        free(db->o[i].blob);
    }
    free(db);
}

static wst_origin *find(const wst_db *db, const char *origin) {
    for (size_t i = 0; i < WST_MAX_ORIGINS; ++i)
        if (db->o[i].origin != NULL && strcmp(db->o[i].origin, origin) == 0)
            return (wst_origin *)&db->o[i];
    return NULL;
}

int wst_encode(const wst_db *db, const char *origin, char **out, size_t *len) {
    if (db == NULL || origin == NULL || out == NULL || len == NULL) return -1;
    *out = NULL;
    *len = 0;
    const wst_origin *e = find(db, origin);
    size_t n = (e != NULL) ? e->len : 4;
    char *c = (char *)malloc(n);
    if (c == NULL) return -1;
    if (e != NULL) memcpy(c, e->blob, n);
    else memset(c, 0, 4);                           /* n = 0: an empty store */
    *out = c;
    *len = n;
    return 0;
}

int wst_replace(wst_db *db, const char *origin, const char *blob, size_t len) {
    if (db == NULL || origin == NULL) return -1;
    size_t olen = strlen(origin);
    if (olen == 0 || olen >= WST_ORIGIN_MAX) return -1;
    size_t bytes = 0;
    if (check(blob, len, &bytes) != 0) return -1;
    char *copy = (char *)malloc(len);
    if (copy == NULL) return -1;
    memcpy(copy, blob, len);

    wst_origin *e = find(db, origin);
    if (e == NULL) {
        /* A free slot, or evict the least recently used origin. */
        wst_origin *victim = &db->o[0];
        for (size_t i = 0; i < WST_MAX_ORIGINS; ++i) {
            if (db->o[i].origin == NULL) { victim = &db->o[i]; break; }
            if (db->o[i].used < victim->used) victim = &db->o[i];
        }
        char *oc = (char *)malloc(olen + 1);
        if (oc == NULL) { free(copy); return -1; }
        memcpy(oc, origin, olen + 1);
        free(victim->origin);
        free(victim->blob);
        memset(victim, 0, sizeof *victim);
        victim->origin = oc;
        e = victim;
    }
    free(e->blob);
    e->blob = copy;
    e->len = len;
    e->bytes = bytes;
    e->used = ++db->clock;
    return 0;
}

size_t wst_origin_bytes(const wst_db *db, const char *origin) {
    if (db == NULL || origin == NULL) return 0;
    const wst_origin *e = find(db, origin);
    return (e != NULL) ? e->bytes : 0;
}

int wst_foreach(const char *blob, size_t len,
                void (*fn)(void *ctx, const char *key, size_t klen,
                           const char *val, size_t vlen),
                void *ctx) {
    if (fn == NULL || check(blob, len, NULL) != 0) return -1;
    const unsigned char *b = (const unsigned char *)blob;
    uint32_t n = get_u32(b);
    size_t o = 4;
    for (uint32_t i = 0; i < n; ++i) {
        uint32_t kl = get_u32(b + o);
        const char *k = blob + o + 4;
        o += 4u + kl;
        uint32_t vl = get_u32(b + o);
        const char *v = blob + o + 4;
        o += 4u + vl;
        fn(ctx, k, kl, v, vl);
    }
    return 0;
}

static void put_u32(char *b, uint32_t v) {
    b[0] = (char)(v & 0xFF); b[1] = (char)((v >> 8) & 0xFF);
    b[2] = (char)((v >> 16) & 0xFF); b[3] = (char)((v >> 24) & 0xFF);
}

int wst_pack(const char *const *keys, const size_t *klens,
             const char *const *vals, const size_t *vlens, size_t n,
             char **out, size_t *len) {
    if (out == NULL || len == NULL) return -1;
    *out = NULL;
    *len = 0;
    if (n > WST_MAX_KEYS) return -1;
    if (n > 0 && (keys == NULL || klens == NULL || vals == NULL || vlens == NULL)) return -1;
    size_t total = 4;
    for (size_t i = 0; i < n; ++i) {
        if (klens[i] > WST_QUOTA || vlens[i] > WST_QUOTA) return -1;
        total += 8u + klens[i] + vlens[i];
        if (total > WST_QUOTA + 8u * (size_t)WST_MAX_KEYS + 4u) return -1;
    }
    char *b = (char *)malloc(total);
    if (b == NULL) return -1;
    put_u32(b, (uint32_t)n);
    size_t o = 4;
    for (size_t i = 0; i < n; ++i) {
        put_u32(b + o, (uint32_t)klens[i]); o += 4;
        if (klens[i] != 0) memcpy(b + o, keys[i], klens[i]);
        o += klens[i];
        put_u32(b + o, (uint32_t)vlens[i]); o += 4;
        if (vlens[i] != 0) memcpy(b + o, vals[i], vlens[i]);
        o += vlens[i];
    }
    /* The builder produces only what the parser accepts. */
    if (check(b, total, NULL) != 0) { free(b); return -1; }
    *out = b;
    *len = total;
    return 0;
}

wc_caps wc_safe(void) {
    wc_caps c = {0};
    return c;
}

wc_caps wc_derive(wc_input in) {
    /* Trust predicates (js_policy, the single tested source of the decision). */
    bool js_enabled = jsp_enabled(in.js_mode, in.host_in_js);
    bool present     = jsp_present_trusted(in.host_in_allow);     /* allow.conf alone */
    bool trusted     = jsp_trusted(js_enabled, in.host_in_allow); /* allow.conf AND js */

    /* Reader mode drops author presentation (it wins), without touching the user's
     * persistent toggles. */
    bool not_reader = (in.reader == 0);

    wc_caps c = {0};
    /* leak-free: user toggle OR presentation-trust, minus reader for presentation. */
    c.js     = js_enabled;
    c.css    = (in.user_css != 0 || present) && not_reader;
    c.images = (in.user_images != 0 || present) && not_reader;
    /* privacy-sensitive: the allow.conf AND js.conf double-consent. */
    c.net = c.cookies = c.persist = c.readback = c.gpu = c.sw = c.rtc = trusted;
    return c;
}

wc_caps wc_from_flags(bool js, bool css, bool images) {
    wc_caps c = {0};
    c.js     = js;
    c.css    = css;
    c.images = images;
    /* Headless: the operator's --js=on is the trust signal for network + every
     * privacy capability (orthogonal to the presentation flags). */
    c.net = c.cookies = c.persist = c.readback = c.gpu = c.sw = c.rtc = js;
    return c;
}

rdp_caps wc_render_caps(wc_caps c) {
    rdp_caps r;
    r.images = c.images;
    r.css    = c.css;
    r.js     = c.js;
    return r;
}

 * understanding just far enough to find candidates (family + first url() per
 * src entry + weight/style descriptors); the fetch layer picks the first
 * SUPPORTED format and policy-gates the download.
 */

#include "webfont.h"
#include "data_url.h"

#include <stdint.h>
#include <stdlib.h>
#include <string.h>

static int is_ws(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
}

static int lower_ch(char c) {
    return (c >= 'A' && c <= 'Z') ? c + ('a' - 'A') : c;
}

/* Case-insensitive span equality: s[0,n) vs NUL-terminated kw. */

static int ci_eq_span(const char *s, size_t n, const char *kw) {
    size_t k = 0;
    while (kw[k] != '\0') ++k;
    if (k != n) return 0;
    for (size_t i = 0; i < n; ++i)
        if (lower_ch(s[i]) != kw[i]) return 0;
    return 1;
}

/* Copies [a,b) trimmed of ASCII blanks into dst (cap bytes, NUL-terminated).
 * Truncates (fail closed: a truncated token simply will not match anything). */
static void copy_trim(const char *s, size_t a, size_t b, char *dst, size_t cap) {
    while (a < b && is_ws(s[a])) ++a;
    while (b > a && is_ws(s[b - 1])) --b;
    size_t n = b - a;
    if (cap == 0) return;
    if (n + 1 > cap) n = cap - 1;
    if (n > 0) memcpy(dst, s + a, n);
    dst[n] = '\0';
}

void wf_list_free(wf_list *l) {
    if (l == NULL) return;
    if (l->refs != NULL) {
        for (size_t i = 0; i < l->count; ++i) {
            free(l->refs[i].data_bytes);
            l->refs[i].data_bytes = NULL;
            l->refs[i].data_len = 0;
        }
        free(l->refs);
    }
    l->refs = NULL;
    l->count = 0;
    l->cap = 0;
}

void wf_ref_move(wf_ref *dst, wf_ref *src) {
    if (dst == NULL || src == NULL || dst == src) return;
    *dst = *src;
    src->data_bytes = NULL;
    src->data_len = 0;
    src->is_data = 0;
}

int wf_supported_format(const char *fmt) {
    if (fmt == NULL) return 0;
    if (fmt[0] == '\0') return 1;   /* no hint: fetch, sniff magic at receipt */
    return ci_eq_span(fmt, strlen(fmt), "woff")
        || ci_eq_span(fmt, strlen(fmt), "truetype")
        || ci_eq_span(fmt, strlen(fmt), "opentype");
}

/* Grows out for one more ref. Returns the slot, or NULL (full/OOM). */

static wf_ref *emit_slot(wf_list *out) {
    if (out->count >= WF_MAX_REFS) return NULL;
    if (out->count >= out->cap) {
        size_t nc = (out->cap != 0) ? out->cap * 2 : 8;
        if (nc > WF_MAX_REFS) nc = WF_MAX_REFS;
        wf_ref *g = (wf_ref *)realloc(out->refs, nc * sizeof *g);
        if (g == NULL) return NULL;
        out->refs = g;
        out->cap = nc;
    }
    wf_ref *r = &out->refs[out->count++];
    memset(r, 0, sizeof *r);
    return r;
}

static void emit_family_format(wf_ref *r, const char *family, const char *format) {
    size_t fl = strlen(family);
    if (fl >= WF_FAMILY_MAX) fl = WF_FAMILY_MAX - 1;
    memcpy(r->family, family, fl);
    r->family[fl] = '\0';
    if (format != NULL) {
        size_t xl = strlen(format);
        if (xl >= WF_FORMAT_MAX) xl = WF_FORMAT_MAX - 1;
        for (size_t i = 0; i < xl; ++i) r->format[i] = (char)lower_ch(format[i]);
        r->format[xl] = '\0';
    } else {
        r->format[0] = '\0';
    }
}

/* True when span[0,slen) is a data: URL (case-insensitive scheme). */

static int span_is_data(const char *span, size_t slen) {
    static const char pre[] = "data:";
    if (slen < sizeof pre - 1) return 0;
    for (size_t i = 0; i < sizeof pre - 1; ++i) {
        char a = span[i], b = pre[i];
        if (a >= 'A' && a <= 'Z') a = (char)(a + 32);
        if (a != b) return 0;
    }
    return 1;
}

/* Appends one https ref; drops silently past WF_MAX_REFS (bounded, fail closed). */

static void emit(wf_list *out, const char *family,
                 const char *url, size_t ulen,
                 const char *format, int bold, int italic) {
    if (family == NULL || family[0] == '\0') return;
    if (url == NULL || ulen == 0 || ulen >= WF_URL_MAX) return;
    wf_ref *r = emit_slot(out);
    if (r == NULL) return;
    emit_family_format(r, family, format);
    memcpy(r->url, url, ulen);
    r->url[ulen] = '\0';
    r->bold = bold ? 1 : 0;
    r->italic = italic ? 1 : 0;
}

/* Appends one data: ref, decoding the bytes NOW (a data: URL never fits url[];
 * the bytes ride the ref instead). Garbage/oversize decodes emit nothing. */

static void emit_data(wf_list *out, const char *family,
                      const char *span, size_t slen,
                      const char *format, int bold, int italic) {
    if (family == NULL || family[0] == '\0') return;
    if (span == NULL || slen == 0 || slen > WF_DATA_URL_MAX) return;
    char *tmp = (char *)malloc(slen + 1);
    if (tmp == NULL) return;
    memcpy(tmp, span, slen);
    tmp[slen] = '\0';
    uint8_t *bytes = NULL;
    size_t bn = 0;
    char mime[128];
    int ok = (du_decode(tmp, mime, sizeof mime, &bytes, &bn) == DU_OK)
             && bn > 0 && bn <= WF_MAX_FACE_BYTES;
    free(tmp);
    if (!ok) {
        free(bytes);
        return;
    }
    wf_ref *r = emit_slot(out);
    if (r == NULL) {
        free(bytes);
        return;
    }
    emit_family_format(r, family, format);
    r->url[0] = '\0';
    r->bold = bold ? 1 : 0;
    r->italic = italic ? 1 : 0;
    r->is_data = 1;
    r->data_bytes = bytes;
    r->data_len = bn;
}

