/* The two halves of a <length-percentage> are SUMMED, not raced.
 *
 * `width: calc(100% - 6px)` is one value with a px half of -6 and a percentage
 * half of 100%, and its used width is 794 of an 800px containing block. Treating
 * the halves as two independent caps and taking the tighter answered 800 -- the
 * -6px simply vanished. That rule was unreachable before calc() carried a

 * percentage (a plain `width:50%` leaves the px half UNSET, a plain `width:300px`
 * leaves the percentage half 0, so the two were never both set), which is why it
 * survived: it was defensive code for a case CSS could not produce. It can now. */
static void test_width_cap_sums_both_halves(void **state) {
    (void)state;
    /* calc(100% - 6px) against an 800px containing block. */
    assert_true(dbl_eq(bx_width_cap(-6, 1000, 800.0), 794.0));
    /* calc(50% + 20px). */
    assert_true(dbl_eq(bx_width_cap(20, 500, 800.0), 420.0));
    /* A used value that comes out negative is clamped to "no cap", not applied as

     * a negative width (CSS Values 4 section 10.1: out-of-range calc() results are
     * clamped at used-value time). */
    assert_true(dbl_eq(bx_width_cap(-900, 1000, 800.0), 0.0));
}

/* 2026-07-11: box-sizing: border-box subtracts the horizontal padding + border
 * from the width cap (bx_place interprets the cap as CONTENT width). */
static void test_content_cap_border_box(void **state) {
    (void)state;
    /* content-box / unset: identity */
    assert_true(dbl_eq(bx_content_cap(300.0, 0, 20.0, 20.0, 2.0, 2.0), 300.0));
    /* no cap: identity regardless of model */
    assert_true(dbl_eq(bx_content_cap(0.0, 1, 20.0, 20.0, 2.0, 2.0), 0.0));
    /* border-box: 300 - 20 - 20 - 2 - 2 = 256 */
    assert_true(dbl_eq(bx_content_cap(300.0, 1, 20.0, 20.0, 2.0, 2.0), 256.0));
    /* narrower than its own edges: clamps to 1, never negative */
    assert_true(dbl_eq(bx_content_cap(30.0, 1, 20.0, 20.0, 2.0, 2.0), 1.0));
    /* negative edges treated as 0 (defensive) */
    assert_true(dbl_eq(bx_content_cap(300.0, 1, -5.0, 20.0, -1.0, 2.0), 278.0));
}


/* An unavailable replaced element with a definite width and an aspect-ratio has a
 * definite BOX (CSS Sizing 4 section 4: the ratio supplies the missing axis). This
 * is the shape a catalogue thumbnail takes in Freedom by default -- images are off,
 * and a third-party CDN thumbnail is blocked even when they are on -- so getting it
 * wrong is not an edge case: with no box the alt text flows as ordinary paragraph
 * text and every card in the grid grows to fit a title it already shows underneath.
 * Firefox sizes it: `width:

static void test_flex_max_clamp(void **state) {
    (void)state;
    /* content-box: cap 240 + padding/border 20 + margin 10 */
    assert_true(fabs(bx_flex_max_clamp(780.0, 240.0, 0, 20.0, 10.0) - 270.0) < 1e-9);
    /* border-box: the cap already holds padding/border */
    assert_true(fabs(bx_flex_max_clamp(780.0, 240.0, 1, 20.0, 10.0) - 250.0) < 1e-9);
    /* under the cap: untouched */
    assert_true(fabs(bx_flex_max_clamp(100.0, 240.0, 0, 20.0, 10.0) - 100.0) < 1e-9);
    /* no max-width: untouched, and NaN never leaks */
    assert_true(fabs(bx_flex_max_clamp(780.0, 0.0, 0, 20.0, 10.0) - 780.0) < 1e-9);
    assert_true(fabs(bx_flex_max_clamp(780.0, -5.0, 0, 20.0, 10.0) - 780.0) < 1e-9);
    assert_true(fabs(bx_flex_max_clamp(780.0, NAN, 0, 20.0, 10.0) - 780.0) < 1e-9);
}


/* CSS 2.1 10.3.3: a declared width wider than the containing block overflows. */

static void test_place_declared_width_overflows(void **state) {
    (void)state;
    bx_hplace p = bx_place_ex(0, 0, 4000.0, 0, 960.0, 1);
    assert_true(fabs(p.content_w - 4000.0) < 1e-9);
    assert_true(fabs(p.x_off) < 1e-9);
    /* centring needs slack: an overflowing auto-margin box starts at the inset */
    p = bx_place_ex(10.0, 10.0, 4000.0, 1, 960.0, 1);
    assert_true(fabs(p.content_w - 4000.0) < 1e-9);
    assert_true(fabs(p.x_off - 10.0) < 1e-9);
    /* a max-width alone never enlarges a box */
    p = bx_place_ex(0, 0, 4000.0, 0, 960.0, 0);
    assert_true(fabs(p.content_w - 960.0) < 1e-9);
    /* under the room: identical to bx_place */
    bx_hplace a = bx_place_ex(40.0, 20.0, 500.0, 1, 800.0, 1);
    bx_hplace b = bx_place(40.0, 20.0, 500.0, 1, 800.0);
    assert_true(fabs(a.content_w - b.content_w) < 1e-9 && fabs(a.x_off - b.x_off) < 1e-9);
}

