    assert_int_equal(get("s", "https://x.test/4", &cfg, &r, NOW), SF_OK); sf_response_free(&r);
    assert_int_equal(get("s", "https://x.test/4", &cfg, &r, NOW + 1), SF_OK); sf_response_free(&r);
