static css_element cls_el(const char *tag, const char *const *cl, size_t n,
                          const css_element *parent, const cvr_chain *vars) {
    css_element e = { 0 };
    e.tag = tag;
    e.classes = cl;
    e.nclasses = n;
    e.parent = parent;
    e.child_count = -1;
    e.vars = vars;
    return e;
}


