    assert_int_equal(css_resolve_el(sh, &lone, NULL, 0).color, -1);
    /* css_resolve (no ancestor context) never matches through a combinator. */
    assert_int_equal(css_resolve(sh, "p", NULL, NULL, 0, NULL, 0).color, -1);
    css_free(sh);
}

