    assert_int_equal(st.clip_top, CSS_LEN_UNSET);
    assert_int_equal(st.clip_right, CSS_LEN_UNSET);
    st = css_parse_inline("clip-path:circle(50%)", 0);   /* shape not modelled: no clip */
    assert_int_equal(st.clip_top, CSS_LEN_UNSET);
}

