static void test_pack_unpack(void **state) {
    (void)state;
    cc_rgb a = { 0x12, 0x34, 0x56 };
    int p = cc_pack(a);
    assert_int_equal(p, 0x123456);
    assert_true(p >= 0);
    cc_rgb b = cc_unpack(p);
    assert_int_equal(b.r, a.r); assert_int_equal(b.g, a.g); assert_int_equal(b.b, a.b);

    /* High bits ignored by unpack. */
    cc_rgb c = cc_unpack((int)0x7fabcdef);
    assert_int_equal(c.r, 0xab); assert_int_equal(c.g, 0xcd); assert_int_equal(c.b, 0xef);
}


/* CSS Color 4: an rgb() channel is a <number> or <percentage> and an hsl()
 * saturation/lightness is a <percentage> -- none of them is restricted to whole
 * digits. Requiring integers dropped the colour, and with it the DECLARATION, which

 * is how a page written by a preprocessor (`hsl(0,0%,15.8333333333%)`, the shape a
 * SASS/LESS colour function emits) lost its entire palette. */
static void test_hsl_fractional_percentages(void **state) {
    (void)state;
    assert_int_equal(cc_parse("hsl(0,0%,15.8333333333%)", &C), CC_OK);
    /* 15.83% of 255 = 40.4 -> 40. An integer-only parser could not see the .83 at
     * all, so the whole declaration vanished. */
    assert_int_equal(C.r, 40); assert_int_equal(C.g, 40); assert_int_equal(C.b, 40);

    assert_int_equal(cc_parse("hsl(0,0%,91.862745098%)", &C), CC_OK);
    assert_int_equal(C.r, 234); assert_int_equal(C.g, 234); assert_int_equal(C.b, 234);
}

/* A fractional hue is a <number> too (and hsl() takes an <angle>, whose bare-number
 * form is degrees). */

static void test_hsl_fractional_hue(void **state) {
    (void)state;
    assert_int_equal(cc_parse("hsl(120.5,100%,50%)", &C), CC_OK);
    assert_int_equal(C.r, 0); assert_int_equal(C.g, 255);
}

/* rgb() channels take fractional numbers and fractional percentages. */

static void test_rgb_fractional(void **state) {
    (void)state;
    assert_int_equal(cc_parse("rgb(127.5, 0, 0)", &C), CC_OK);
    assert_int_equal(C.r, 128); assert_int_equal(C.g, 0); assert_int_equal(C.b, 0);
    assert_int_equal(cc_parse("rgb(50.5%, 0%, 0%)", &C), CC_OK);
    assert_int_equal(C.r, 129);
}

/* A leading-dot number is a valid <number> (CSS Syntax 4.3.12): `.5` must parse. */

static void test_leading_dot_number(void **state) {
    (void)state;
    assert_int_equal(cc_parse("rgba(0, 0, 0, .5)", &C), CC_OK);
    assert_int_equal(cc_parse("hsl(0,.5%,50%)", &C), CC_OK);
}

/* Out-of-range and malformed values still fail closed -- widening the grammar to
 * fractions must not widen it to junk. */

static void test_fractional_still_fails_closed(void **state) {
    (void)state;
    assert_int_not_equal(cc_parse("hsl(0,0%,150.5%)", &C), CC_OK);
    assert_int_not_equal(cc_parse("rgb(300.5, 0, 0)", &C), CC_OK);
    assert_int_not_equal(cc_parse("rgb(1.2.3, 0, 0)", &C), CC_OK);
    assert_int_not_equal(cc_parse("hsl(0,0%,5x%)", &C), CC_OK);
    assert_int_not_equal(cc_parse("rgb(., 0, 0)", &C), CC_OK);
}

/* CSS Color 4 space-separated components with optional slash alpha (spec/css_color.md):
 * the measured overlay/border idiom of real pages (`rgb(0 0 0 / 75%)`). rgb()/rgba()
 * (and hsl()/hsla()) are aliases; arity comes from the alpha, not the name. */

static void test_rgb_space_separated(void **state) {
    (void)state;
    assert_int_equal(cc_parse("rgb(0 0 0 / 75%)", &C), CC_OK);
    assert_int_equal(C.r, 0); assert_int_equal(C.g, 0); assert_int_equal(C.b, 0);

    assert_int_equal(cc_parse("rgb(229 233 240 / 50%)", &C), CC_OK);
    assert_int_equal(C.r, 229); assert_int_equal(C.g, 233); assert_int_equal(C.b, 240);

    assert_int_equal(cc_parse("rgb(255 0 0)", &C), CC_OK);
    assert_int_equal(C.r, 255); assert_int_equal(C.g, 0); assert_int_equal(C.b, 0);

    assert_int_equal(cc_parse("rgba(10 20 30 / 0.5)", &C), CC_OK);
    assert_int_equal(C.r, 10); assert_int_equal(C.g, 20); assert_int_equal(C.b, 30);

    assert_int_equal(cc_parse("RGB(100% 0% 50% / 100%)", &C), CC_OK);
    assert_int_equal(C.r, 255); assert_int_equal(C.g, 0); assert_int_equal(C.b, 128);
}

static void test_hsl_space_separated(void **state) {
    (void)state;
    assert_int_equal(cc_parse("hsl(0 0% 0% / 50%)", &C), CC_OK);
    assert_int_equal(C.r, 0); assert_int_equal(C.g, 0); assert_int_equal(C.b, 0);

    assert_int_equal(cc_parse("hsl(120 100% 50%)", &C), CC_OK);
    assert_int_equal(C.r, 0); assert_int_equal(C.g, 255); assert_int_equal(C.b, 0);

    assert_int_equal(cc_parse("hsla(240 100% 50% / .5)", &C), CC_OK);
    assert_int_equal(C.r, 0); assert_int_equal(C.g, 0); assert_int_equal(C.b, 255);
}

/* Mixing the two grammars, or a dangling slash, still fails closed. */

static void test_space_separated_still_fails_closed(void **state) {
    (void)state;
    assert_int_not_equal(cc_parse("rgb(0, 0, 0 / 50%)", &C), CC_OK);
    assert_int_not_equal(cc_parse("rgb(0 0)", &C), CC_OK);
    assert_int_not_equal(cc_parse("rgb(0 0 0 /)", &C), CC_OK);
    assert_int_not_equal(cc_parse("rgb(0 0 0 // 50%)", &C), CC_OK);
    assert_int_not_equal(cc_parse("rgb(0  0  0  0)", &C), CC_OK);
    assert_int_not_equal(cc_parse("rgb(256 0 0)", &C), CC_OK);
    /* Out-of-range alpha clamps at computed-value time (CSS Color 4), like the
     * legacy `rgba(0,0,0,2)` the parser already accepts: valid, discarded. */
    assert_int_equal(cc_parse("rgb(0 0 0 / 150%)", &C), CC_OK);
    assert_int_not_equal(cc_parse("hsl(0 50% 50% / 0.5 / 0.5)", &C), CC_OK);
    assert_int_not_equal(cc_parse("hsl(0 150% 50%)", &C), CC_OK);
}


/* A colour whose alpha is ZERO is `transparent` (CSS Color 4 section 6.1: it IS

 * result (`border:1px solid rgba(0,0,0,0)`). A non-zero alpha stays a colour. */
static void test_zero_alpha_is_transparent(void **state) {
    (void)state;
    cc_rgb c;
    assert_int_equal(cc_parse("rgba(0,0,0,0)", &c), CC_TRANSPARENT);
    assert_int_equal(cc_parse("rgba(10,20,30,0.0)", &c), CC_TRANSPARENT);
    assert_int_equal(cc_parse("rgb(0 0 0 / 0%)", &c), CC_TRANSPARENT);
    assert_int_equal(cc_parse("hsla(0,0%,0%,0)", &c), CC_TRANSPARENT);
    assert_int_equal(cc_parse("#0000", &c), CC_TRANSPARENT);
    assert_int_equal(cc_parse("#ffffff00", &c), CC_TRANSPARENT);
    assert_int_equal(cc_parse("oklch(0.5 0.1 120 / 0)", &c), CC_TRANSPARENT);
    assert_int_equal(cc_parse("rgba(0,0,0,0.5)", &c), CC_OK);
    assert_int_equal(cc_parse("#0008", &c), CC_OK);
    assert_int_equal(cc_parse("#00000001", &c), CC_OK);
}

static const char *get(const css_style *st, double fpx, int icol, const char *p) {
    static char buf[CCM_VALUE_MAX];
    ccm_input in = { st, fpx, icol, NULL };
    (void)ccm_get(&in, p, buf, sizeof buf);
    return buf;
}

static css_style blank(void) {
    css_style s;
    memset(&s, 0, sizeof s);
    s.color = -1; s.background = -1; s.bg_alpha = CSS_LEN_UNSET;
    s.width = s.height = CSS_LEN_UNSET;
    s.margin_top = s.margin_right = s.margin_bottom = s.margin_left = CSS_LEN_UNSET;
    s.pad_top = s.pad_right = s.pad_bottom = s.pad_left = CSS_LEN_UNSET;
    s.opacity = -1; s.bold = -1; s.z_index = CSS_LEN_UNSET;
    return s;
}

static void test_initial_values(void **state) {
    (void)state;
    css_style s = blank();
    assert_string_equal(get(&s, 16, -1, "display"), "inline");
    assert_string_equal(get(&s, 16, -1, "position"), "static");
    assert_string_equal(get(&s, 16, -1, "visibility"), "visible");
    assert_string_equal(get(&s, 16, -1, "opacity"), "1");
    assert_string_equal(get(&s, 16, -1, "color"), "rgb(0, 0, 0)");
    assert_string_equal(get(&s, 16, -1, "background-color"), "rgba(0, 0, 0, 0)");
    assert_string_equal(get(&s, 16, -1, "margin-top"), "0px");
    assert_string_equal(get(&s, 16, -1, "width"), "auto");
    assert_string_equal(get(&s, 16, -1, "z-index"), "auto");
    assert_string_equal(get(&s, 16, -1, "font-weight"), "400");
    s.gap = -1;                                   /* the engine's "unset" sentinel */
    assert_string_equal(get(&s, 16, -1, "gap"), "normal");
    s.gap = 8;
    assert_string_equal(get(&s, 16, -1, "gap"), "8px");
}

static void test_declared_values(void **state) {
    (void)state;
    css_style s = blank();
    s.display = CSS_DISP_FLEX; s.position = CSS_POS_ABSOLUTE;
    s.color = 0x336699; s.background = 0xff0000; s.bg_alpha = 50;
    s.margin_left = 12; s.pad_top = 7; s.width = 240; s.bold = 1; s.opacity = 25;
    s.z_index = -3;
    assert_string_equal(get(&s, 20, -1, "display"), "flex");
    assert_string_equal(get(&s, 20, -1, "position"), "absolute");
    assert_string_equal(get(&s, 20, -1, "color"), "rgb(51, 102, 153)");
    assert_string_equal(get(&s, 20, -1, "background-color"), "rgba(255, 0, 0, 0.5)");
    assert_string_equal(get(&s, 20, -1, "margin-left"), "12px");
    assert_string_equal(get(&s, 20, -1, "padding-top"), "7px");
    assert_string_equal(get(&s, 20, -1, "width"), "240px");
    assert_string_equal(get(&s, 20, -1, "font-weight"), "700");
    assert_string_equal(get(&s, 20, -1, "opacity"), "0.25");
    assert_string_equal(get(&s, 20, -1, "z-index"), "-3");
    assert_string_equal(get(&s, 20, -1, "font-size"), "20px");
}

static void test_ua_display_by_tag(void **state) {
    (void)state;
    css_style s = blank();
    char buf[CCM_VALUE_MAX];
    const char *cases[][2] = { { "p", "block" }, { "div", "block" }, { "span", "inline" },
        { "li", "list-item" }, { "script", "none" }, { "td", "table-cell" }, { "table", "table" },
        { "button", "inline-block" }, { "a", "inline" } };
    for (size_t i = 0; i < sizeof cases / sizeof *cases; ++i) {
        ccm_input in = { &s, 16, -1, cases[i][0] };
        (void)ccm_get(&in, "display", buf, sizeof buf);
        assert_string_equal(buf, cases[i][1]);
    }
    s.display = CSS_DISP_FLEX;                       /* a declared value beats the tag default */
    ccm_input in = { &s, 16, -1, "span" };
    (void)ccm_get(&in, "display", buf, sizeof buf);
    assert_string_equal(buf, "flex");
}

static void test_color_inherits(void **state) {
    (void)state;
    css_style s = blank();
    assert_string_equal(get(&s, 16, 0xabcdef, "color"), "rgb(171, 205, 239)");
    s.color = 0x010203;
    assert_string_equal(get(&s, 16, 0xabcdef, "color"), "rgb(1, 2, 3)");
}

static void test_unknown_property_is_empty(void **state) {
    (void)state;
    css_style s = blank();
    assert_string_equal(get(&s, 16, -1, "not-a-property"), "");
    assert_string_equal(get(&s, 16, -1, ""), "");
    char buf[4];
    ccm_input in = { &s, 16, -1, NULL };
    assert_int_equal(ccm_get(&in, "display", buf, sizeof buf), 0);  /* does not fit: fail closed */
    assert_string_equal(buf, "");
    assert_int_equal(ccm_get(NULL, "display", buf, sizeof buf), 0);
}

static void test_enumeration(void **state) {
    (void)state;
    assert_true(ccm_property_count() >= 40);
    css_style s = blank();
    for (size_t i = 0; i < ccm_property_count(); ++i) {
        const char *n = ccm_property_name(i);
        assert_non_null(n);
        char buf[CCM_VALUE_MAX];
        ccm_input in = { &s, 16, -1, NULL };
        assert_true(ccm_get(&in, n, buf, sizeof buf) > 0);  /* every listed property has a value */
    }
    assert_null(ccm_property_name(ccm_property_count()));
}

int main(void) {
    const struct CMUnitTest t[] = {
        cmocka_unit_test(test_initial_values),
        cmocka_unit_test(test_declared_values),
        cmocka_unit_test(test_ua_display_by_tag),
        cmocka_unit_test(test_color_inherits),
        cmocka_unit_test(test_unknown_property_is_empty),
        cmocka_unit_test(test_enumeration),
    };
    return cmocka_run_group_tests(t, NULL, NULL);
}

static const css_drop *find_drop(const css_drop_log *log, const char *prop) {
    for (size_t i = 0; i < log->n; ++i)
        if (strcmp(log->items[i].prop, prop) == 0) return &log->items[i];
    return NULL;
}

/* Given a rule whose property name is not in the dispatch, when parsed with a log,
 * then it is reported once as an unknown property. */

static void test_unknown_property_is_logged(void **state) {
    (void)state;
    css_drop items[8];
    css_drop_log log;
    css_sheet *sh = parse_logged("a{unknown-prop:1}", items, 8, &log);
    assert_int_equal((int)log.total, 1);
    assert_int_equal((int)log.n, 1);
    assert_string_equal(items[0].prop, "unknown-prop");
    assert_string_equal(items[0].val, "1");
    assert_int_equal(items[0].cause, CSS_DROP_UNKNOWN_PROP);
    assert_int_equal(items[0].count, 1);
    css_free(sh);
}

/* Given an implemented property with a value the grammar rejects, then the cause is
 * BAD_VALUE -- the distinction that matters, because the property "exists" and the
 * declaration is lost anyway. */

static void test_bad_value_is_distinguished(void **state) {
    (void)state;
