    assert_int_equal(s.transform_oy, 100);
    css_free(sh);
}

/* background-size accepts one or two <length-percentage>|auto components
 * (Backgrounds 3 3.9). ddg ships `44px 12px` 11 times, jkanime a calc() pair. */

