    assert_true(fabs(px_of("0", &c)) < EPS);
    assert_true(fabs(px_of("-0", &c)) < EPS);
    assert_true(fabs(px_of("0.0", &c)) < EPS);
    expect_err("12", &c, CL_ERR_UNIT);
    expect_err("1.5", &c, CL_ERR_UNIT);
}

/* 3 / 4: the absolute family, with 1in == 96px as the anchor. */

