    assert_false(m("(scripting:enabled)"));
    assert_false(m("not (frobnicate:1)"));
    assert_false(m("tv"));
    assert_false(m("((((((((((((((((((width>0px))))))))))))))))))"));
    assert_false(cmq_matches(NULL, 0, &ENV));
    assert_false(cmq_matches("(width>0px)", 11, NULL));
}

