    assert_int_equal(du_base64_decode("QQ!=", 4, &out, &out_len), DU_ERR_BAD_BASE64);
    assert_null(out);
    /* Whitespace is not part of the alphabet either -- fail closed, don't skip it. */
    assert_int_equal(du_base64_decode("QQ =", 4, &out, &out_len), DU_ERR_BAD_BASE64);
    assert_null(out);
}

static void test_decode_too_large(void **state) {
