    assert_int_equal(dom_create_element(idx, "SPAN", &created), DOM_OK);
    assert_int_not_equal(created, DOM_NODE_NONE);
    /* new node is queryable (handle valid) and tagged span (lowercased) */
    size_t tl = 0;
