/* Flexbox 8.1: auto margins take the positive free space before justify-content. */

static void test_auto_margins_push_right_and_center(void **state) {
    (void)state;
    fx_item it[3] = { {40, 0, 1, 0}, {40, 0, 1, 0}, {40, 0, 1, 0} };
    fx_result r[3];
    assert_int_equal(fx_flex_line(it, 3, 300.0, 10.0, FX_JUSTIFY_CENTER, r), FX_OK);
    unsigned char al[3] = { 0, 0, 1 }, ar[3] = { 0, 0, 0 };
    assert_int_equal(fx_auto_margins(r, 3, al, ar, 300.0, 10.0), FX_OK);
    assert_item(r[0], 0.0, 40.0);
    assert_item(r[1], 50.0, 40.0);
    assert_item(r[2], 260.0, 40.0);

    fx_item one[1] = { {100, 0, 1, 0} };
    fx_result c[1];
    assert_int_equal(fx_flex_line(one, 1, 300.0, 0.0, FX_JUSTIFY_START, c), FX_OK);
    unsigned char bl[1] = { 1 }, br[1] = { 1 };
    assert_int_equal(fx_auto_margins(c, 1, bl, br, 300.0, 0.0), FX_OK);
    assert_item(c[0], 100.0, 100.0);

    /* No auto margin, or no free space: positions untouched. */
    unsigned char z[3] = { 0, 0, 0 };
    fx_result keep[3] = { {5, 40}, {60, 40}, {110, 40} };
    assert_int_equal(fx_auto_margins(keep, 3, z, z, 300.0, 10.0), FX_OK);
    assert_item(keep[1], 60.0, 40.0);
    fx_result full[1] = { {0, 300} };
    assert_int_equal(fx_auto_margins(full, 1, bl, br, 300.0, 0.0), FX_OK);
    assert_item(full[0], 0.0, 300.0);
    /* Fail closed. */
    assert_int_equal(fx_auto_margins(NULL, 1, bl, br, 300.0, 0.0), FX_ERR_NULL_ARG);
    assert_int_equal(fx_auto_margins(c, 1, bl, br, -1.0, 0.0), FX_ERR_RANGE);
}


/* --- flex column placement (spec/flex_layout.md, tanda 40) --- */

static void test_column_place_stack_and_justify(void **state) {
    (void)state;
    double y[3], h[3], ext = -1.0;
    const double h2[2] = { 20.0, 30.0 };
    assert_int_equal(fx_column_place(h2, NULL, 2, 10.0, 0.0, FX_JUSTIFY_CENTER, 0,
                                     y, h, &ext), FX_OK);
    assert_true(y[0] == 0.0 && y[1] == 30.0 && ext == 60.0);
    const double h1[1] = { 20.0 };
    assert_int_equal(fx_column_place(h1, NULL, 1, 0.0, 100.0, FX_JUSTIFY_CENTER, 0,
                                     y, h, &ext), FX_OK);
    assert_true(y[0] == 40.0 && ext == 60.0);
    fx_column_place(h1, NULL, 1, 0.0, 100.0, FX_JUSTIFY_END, 0, y, h, &ext);
    assert_true(y[0] == 80.0);
    const double hh[2] = { 20.0, 20.0 }, gr[2] = { 0.0, 1.0 };
    fx_column_place(hh, gr, 2, 0.0, 100.0, FX_JUSTIFY_START, 0, y, h, &ext);
    assert_true(h[0] == 20.0 && h[1] == 80.0 && y[0] == 0.0 && y[1] == 20.0 && ext == 100.0);
    const double h10[2] = { 10.0, 10.0 };
    fx_column_place(h10, NULL, 2, 0.0, 50.0, FX_JUSTIFY_SPACE_BETWEEN, 0, y, h, &ext);
    assert_true(y[0] == 0.0 && y[1] == 40.0);
    const double hr[2] = { 10.0, 20.0 };
    fx_column_place(hr, NULL, 2, 0.0, 0.0, FX_JUSTIFY_START, 1, y, h, &ext);
    assert_true(y[0] == 20.0 && y[1] == 0.0 && ext == 30.0);
    /* overfull: free < 0 is treated as 0 */
    fx_column_place(h2, NULL, 2, 0.0, 10.0, FX_JUSTIFY_CENTER, 0, y, h, &ext);
    assert_true(y[0] == 0.0);
    assert_int_equal(fx_column_place(h2, NULL, 2, 0.0, 0.0, 0, 0, NULL, h, &ext),
                     FX_ERR_NULL_ARG);
}

