/* True when some `box[` line matches w (+-0.6) and h (+-0.6) and top in [t0, t1]. */

static int has_box(const char *out, double w, double h, double t0, double t1) {
    for (const char *q = strstr(out, "box["); q != NULL; q = strstr(q + 1, "box[")) {
        double x, top, bw, bh;
        int bid;
        size_t i;
        if (sscanf(q, "box[%zu] bid=%d x=%lf top=%lf w=%lf h=%lf", &i, &bid, &x, &top, &bw, &bh) != 6)
            continue;
        if (bw > w - 0.6 && bw < w + 0.6 && bh > h - 0.6 && bh < h + 0.6 && top >= t0 && top <= t1)
            return 1;
    }
    return 0;
}

/* True when some `box[` line has x (+-0.6) and w (+-0.6). */

static int has_box_x(const char *out, double x0, double w0) {
    for (const char *q = strstr(out, "box["); q != NULL; q = strstr(q + 1, "box[")) {
        double x, top, bw, bh;
        int bid;
        size_t i;
        if (sscanf(q, "box[%zu] bid=%d x=%lf top=%lf w=%lf h=%lf", &i, &bid, &x, &top, &bw, &bh) != 6)
            continue;
        if (x > x0 - 0.6 && x < x0 + 0.6 && bw > w0 - 0.6 && bw < w0 + 0.6) return 1;
    }
    return 0;
}

/* True when some `row[` line has x_off within 0.6 of x0. */

static int has_row_x(const char *out, double x0) {
    for (const char *q = strstr(out, "row["); q != NULL; q = strstr(q + 1, "row[")) {
        double top, h, xo;
        size_t i;
        if (sscanf(q, "row[%zu] top=%lf h=%lf x_off=%lf", &i, &top, &h, &xo) != 4) continue;
        if (xo > x0 - 0.6 && xo < x0 + 0.6) return 1;
    }
    return 0;
}

/* True when some `sub box` line (an out-of-flow subtree) has x within 1.5 of x0. */

static int has_sub_x(const char *out, double x0) {
    for (const char *q = strstr(out, "sub box"); q != NULL; q = strstr(q + 1, "sub box")) {
        double x, top, bw, bh;
        int bid;
        if (sscanf(q, "sub box bid=%d x=%lf top=%lf w=%lf h=%lf", &bid, &x, &top, &bw, &bh) != 5) continue;
        if (x > x0 - 1.5 && x < x0 + 1.5) return 1;
    }
    return 0;
}

