    fclose(f);

    char out[8192];
    int rc;
    assert_int_equal(run_freedom("--author-css --dump-layout __freedom_contfloat.html",
                                 out, sizeof out, &rc), 0);
    assert_int_equal(rc, 0);
    /* Every row starts at top=0: the text wraps beside the float. */
    char *p = out;
    int rows = 0;
    while ((p = strstr(p, "row[")) != NULL) {
        double t = -1.0;
