    EXPECT(f, "n", "1");
    (void)jd_fire_mouse_event(f->ctx, h, "mouseout", 0, 0, 0);
    EXPECT(f, "n", "11");
    (void)jd_fire_mouse_event(f->ctx, h, "mousemove", 0, 0, 0);
