    (void)jd_fire_mouse_event(f->ctx, h, "mouseleave", 0, 0, 0);
    EXPECT(f, "n", "11111");
    (void)jd_fire_mouse_event(f->ctx, h, "wheel", 0, 0, -1);
    EXPECT(f, "n", "111111");
}

