/* js_set_time_budget lowers the wall-clock cap armed on subsequent evals, so a
 * caller can enforce a single page-wide budget across many evaluations. A tiny
 * budget interrupts an infinite loop; a NULL context is a safe no-op. */

static void test_set_time_budget_applies(void **state) {
    (void)state;
    js_set_time_budget(NULL, 1000); /* no-op, must not crash */
    js_context *ctx = NULL;
    assert_int_equal(js_context_new(NULL, &ctx), JS_OK); /* default budget = 1000ms */
    js_set_time_budget(ctx, 50); /* shrink it for a fast test */
    js_result r;
    memset(&r, 0, sizeof r);

    assert_int_equal(js_eval(ctx, "while(true){}", 13, &r), JS_ERR_TIMEOUT);
    js_result_free(&r);
    /* A subsequent eval still honours the lowered budget (it persists on the ctx). */
    memset(&r, 0, sizeof r);
    assert_int_equal(js_eval(ctx, "for(;;){}", 9, &r), JS_ERR_TIMEOUT);
    js_result_free(&r);
    js_context_free(ctx);
}

/* The sampling profiler names the JS function that burned the time, charges native-call time
 * to its caller, stays inert until enabled, and is a safe no-op on NULL. */

static void test_profiler_names_the_hot_function(void **state) {
    (void)state;
    char out[1024];
    js_profile_enable(NULL);
    assert_int_equal((int)js_profile_report(NULL, out, sizeof out, 5), 0);

    js_context *ctx = NULL;
    assert_int_equal(js_context_new(NULL, &ctx), JS_OK);
    js_set_time_budget(ctx, 60000);   /* a sanitizer build is far slower than the 1 s default allows */
    js_result r;
    memset(&r, 0, sizeof r);
    static const char busy[] =
        "function spinHere(){var t=Date.now(),n=0;for(var i=0;i<2e6;i++){n+=i%7;}return n;}"
        "spinHere();spinHere();0";
    assert_int_equal(js_eval(ctx, busy, sizeof busy - 1, &r), JS_OK); /* profiler off */
    js_result_free(&r);
    assert_int_equal((int)js_profile_report(ctx, out, sizeof out, 5), 0);

    js_profile_enable(ctx);
    memset(&r, 0, sizeof r);
    assert_int_equal(js_eval(ctx, busy, sizeof busy - 1, &r), JS_OK);
    js_result_free(&r);
    size_t n = js_profile_report(ctx, out, sizeof out, 5);
    assert_true(n > 0);
    assert_true(n < sizeof out);
    assert_non_null(strstr(out, "spinHere"));
    assert_non_null(strstr(out, "%"));
    char tiny[8];
    assert_true(js_profile_report(ctx, tiny, sizeof tiny, 5) < sizeof tiny);
    js_context_free(ctx);
}

/* The throw tracer records EVERY thrown value, caught or not, with its site and a count, in a
 * fixed-size table, and stays inert until enabled. */

static void test_throw_tracer_records_caught_exceptions(void **state) {
    (void)state;
    char out[2048];
    js_throws_enable(NULL);
    assert_int_equal((int)js_throws_report(NULL, out, sizeof out, 5), 0);
    js_context *ctx = NULL;
    assert_int_equal(js_context_new(NULL, &ctx), JS_OK);
    js_result r;
    static const char code[] =
        "function boomHere(){ throw new Error('boom'); }"
        "for(var i=0;i<3;i++){ try{ boomHere(); }catch(e){} }"
        "try{ null.x; }catch(e){} try{ throw 'plain string'; }catch(e){} 0";
    memset(&r, 0, sizeof r);
    assert_int_equal(js_eval(ctx, code, sizeof code - 1, &r), JS_OK);   /* tracer off */
    js_result_free(&r);
    assert_int_equal((int)js_throws_report(ctx, out, sizeof out, 5), 0);

    js_throws_enable(ctx);
    memset(&r, 0, sizeof r);
    assert_int_equal(js_eval(ctx, code, sizeof code - 1, &r), JS_OK);
    js_result_free(&r);
    size_t n = js_throws_report(ctx, out, sizeof out, 8);
    assert_true(n > 0 && n < sizeof out);
    assert_non_null(strstr(out, "3x boom"));
    assert_non_null(strstr(out, "boomHere"));
    assert_non_null(strstr(out, "cannot read property"));
    assert_non_null(strstr(out, "plain string"));
    assert_true(strstr(out, "3x boom") < strstr(out, "plain string"));   /* most frequent first */
    js_context_free(ctx);
}

