static void test_build_combinator_selectors(void **state) {
    (void)state;
    hp_document *doc = parse(
        "<head><style>"
        "div p { color:#990000 }"     /* descendant: any p under a div */
        "nav > a { color:#003399 }"   /* child: a whose parent is nav */
