        { "<body><div>x<br></div><p>end</p></body>", 0 },
        { "<body><div>x<br>y</div></body>", 0 },
        { "<body><p>a <br style=\"display:block\"> b</p></body>", 0 },
        { "<body><p>a <br style=\"display:none\"><br style=\"display:none\"> b</p></body>", 0 },
    };
