    rdp_caps caps = rdp_caps_safe();
    caps.css = true;
    assert_int_equal(rd_build(v, caps, TOP, &d), RD_OK);
    p = first_kind(d, RD_PARAGRAPH);
    assert_non_null(p);
    assert_int_equal(p->fg_rgb, 0x3366cc);
    assert_int_equal(p->bg_rgb, 0xeeddcc);
    rd_free(d);

    pv_free(v);
}

