     * classified as a tracker by the size heuristic. */
    assert_int_equal(rdp_is_tracking_pixel(1, 300), 0);
    assert_int_equal(rdp_is_tracking_pixel(800, 600), 0);
}

static void test_tracking_pixel_unknown(void **state) {
    (void)state;
