    tab_page p;
    assert_int_equal(tab_load(t, H, sizeof H - 1, &p), TAB_OK);
    assert_non_null(p.view);

    int seen_plain = 0, seen_over = 0;
    for (size_t i = 0; i < pv_count(p.view); ++i) {
        const pv_run *r = pv_at(p.view, i);
        if (r->text != NULL && strcmp(r->text, "plain") == 0) {
