static size_t build(char *b, const char *const *kv, uint32_t n) {
    size_t o = put_u32(b, 0, n);
    for (uint32_t i = 0; i < n; ++i) {
        uint32_t kl = (uint32_t)strlen(kv[2 * i]), vl = (uint32_t)strlen(kv[2 * i + 1]);
        o = put_u32(b, o, kl); memcpy(b + o, kv[2 * i], kl); o += kl;
        o = put_u32(b, o, vl); memcpy(b + o, kv[2 * i + 1], vl); o += vl;
    }
    return o;
}

static void test_unknown_origin_encodes_empty(void **state) {
    (void)state;
    wst_db *db = wst_new();
    assert_non_null(db);
    char *out = NULL;
    size_t len = 0;
    assert_int_equal(wst_encode(db, "https://a.test", &out, &len), 0);
    assert_int_equal(len, 4);
    assert_int_equal(wst_decode_check(out, len), 0);
    free(out);
    assert_int_equal(wst_origin_bytes(db, "https://a.test"), 0);
    wst_free(db);
    wst_free(NULL);
}

static void test_replace_then_encode_roundtrip(void **state) {
    (void)state;
    wst_db *db = wst_new();
    char b[256];
    const char *kv[] = { "theme", "dark", "draft", "hola \xc3\xb1" };
    size_t n = build(b, kv, 2);
    assert_int_equal(wst_replace(db, "https://a.test", b, n), 0);
    assert_int_equal(wst_origin_bytes(db, "https://a.test"), 5 + 4 + 5 + 7);
    /* other origin untouched */
    assert_int_equal(wst_origin_bytes(db, "https://b.test"), 0);
    char *out = NULL;
    size_t len = 0;
    assert_int_equal(wst_encode(db, "https://a.test", &out, &len), 0);
    assert_int_equal(len, n);
    assert_memory_equal(out, b, n);
    free(out);
    /* a later snapshot REPLACES (clear/removeItem reach the parent) */
    const char *kv2[] = { "theme", "light" };
    n = build(b, kv2, 1);
    assert_int_equal(wst_replace(db, "https://a.test", b, n), 0);
    assert_int_equal(wst_origin_bytes(db, "https://a.test"), 5 + 5);
    wst_free(db);
}

static void test_hostile_snapshots_rejected_and_db_unchanged(void **state) {
    (void)state;
    wst_db *db = wst_new();
    char b[256];
    const char *kv[] = { "k", "v" };
    size_t n = build(b, kv, 1);
    assert_int_equal(wst_replace(db, "https://a.test", b, n), 0);

    char bad[64];
    memcpy(bad, b, n);
    /* truncated */
    assert_int_equal(wst_replace(db, "https://a.test", bad, n - 1), -1);
    /* trailing garbage */
    bad[n] = 'x';
    assert_int_equal(wst_replace(db, "https://a.test", bad, n + 1), -1);
    /* count larger than content */
    put_u32(bad, 0, 2);
    assert_int_equal(wst_replace(db, "https://a.test", bad, n), -1);
    /* giant length */
    memcpy(bad, b, n);
    put_u32(bad, 4, 0xFFFFFFF0u);
    assert_int_equal(wst_replace(db, "https://a.test", bad, n), -1);
    /* invalid UTF-8 */
    const char *kvu[] = { "k", "\xc3\x28" };
    size_t nu = build(bad, kvu, 1);
    assert_int_equal(wst_decode_check(bad, nu), -1);
    /* duplicate keys */
    const char *kvd[] = { "k", "1", "k", "2" };
    size_t nd = build(bad, kvd, 2);
    assert_int_equal(wst_decode_check(bad, nd), -1);
    assert_int_equal(wst_decode_check(NULL, 4), -1);
    assert_int_equal(wst_decode_check(b, 3), -1);
    /* the stored content survived every rejection */
    assert_int_equal(wst_origin_bytes(db, "https://a.test"), 2);
    assert_int_equal(wst_replace(NULL, "https://a.test", b, n), -1);
    assert_int_equal(wst_replace(db, NULL, b, n), -1);
    wst_free(db);
}

static void test_quota_enforced(void **state) {
    (void)state;
    size_t big = WST_QUOTA;             /* key "k" (1) + value WST_QUOTA > quota */
    char *b = (char *)malloc(big + 64);
    assert_non_null(b);
    size_t o = put_u32(b, 0, 1);
    o = put_u32(b, o, 1); b[o++] = 'k';
    o = put_u32(b, o, (uint32_t)big); memset(b + o, 'a', big); o += big;
    assert_int_equal(wst_decode_check(b, o), -1);
    /* exactly at quota is fine */
    o = put_u32(b, 0, 1);
    o = put_u32(b, o, 1); b[o++] = 'k';
    o = put_u32(b, o, (uint32_t)(big - 1)); memset(b + o, 'a', big - 1); o += big - 1;
    assert_int_equal(wst_decode_check(b, o), 0);
    free(b);
}

static void test_origin_table_is_bounded_lru(void **state) {
    (void)state;
    wst_db *db = wst_new();
    char b[64];
    const char *kv[] = { "k", "v" };
    size_t n = build(b, kv, 1);
    char origin[64];
    for (unsigned i = 0; i < WST_MAX_ORIGINS + 5; ++i) {
        snprintf(origin, sizeof origin, "https://o%u.test", i);
        assert_int_equal(wst_replace(db, origin, b, n), 0);
    }
    /* the oldest ones were evicted, the newest kept */
    assert_int_equal(wst_origin_bytes(db, "https://o0.test"), 0);
    snprintf(origin, sizeof origin, "https://o%u.test", WST_MAX_ORIGINS + 4);
    assert_int_equal(wst_origin_bytes(db, origin), 2);
    wst_free(db);
}

static void count_pair(void *ctx, const char *k, size_t kl, const char *v, size_t vl) {
    (void)k; (void)v;
    size_t *acc = (size_t *)ctx;
    acc[0]++;
    acc[1] += kl + vl;
}

static void test_pack_foreach_roundtrip(void **state) {
    (void)state;
    const char *keys[] = { "a", "b\xc3\xb1" };
    const char *vals[] = { "1", "" };
    size_t kl[] = { 1, 3 }, vl[] = { 1, 0 };
    char *out = NULL;
    size_t len = 0;
    assert_int_equal(wst_pack(keys, kl, vals, vl, 2, &out, &len), 0);
    assert_int_equal(wst_decode_check(out, len), 0);
    size_t acc[2] = { 0, 0 };
    assert_int_equal(wst_foreach(out, len, count_pair, acc), 0);
    assert_int_equal(acc[0], 2);
    assert_int_equal(acc[1], 5);
    free(out);
    /* empty store packs to a valid empty snapshot */
    assert_int_equal(wst_pack(NULL, NULL, NULL, NULL, 0, &out, &len), 0);
    assert_int_equal(len, 4);
    free(out);
    /* duplicates / bad UTF-8 are refused by the builder too */
    const char *dk[] = { "k", "k" };
    size_t dkl[] = { 1, 1 };
    assert_int_equal(wst_pack(dk, dkl, vals, vl, 2, &out, &len), -1);
    /* an invalid snapshot never reaches the callback */
    acc[0] = 0;
    assert_int_equal(wst_foreach("\x01\x00\x00\x00", 4, count_pair, acc), -1);
    assert_int_equal(acc[0], 0);
}

int main(void) {
    const struct CMUnitTest tests[] = {
        cmocka_unit_test(test_unknown_origin_encodes_empty),
        cmocka_unit_test(test_replace_then_encode_roundtrip),
        cmocka_unit_test(test_hostile_snapshots_rejected_and_db_unchanged),
        cmocka_unit_test(test_quota_enforced),
        cmocka_unit_test(test_origin_table_is_bounded_lru),
        cmocka_unit_test(test_pack_foreach_roundtrip),
    };
    return cmocka_run_group_tests(tests, NULL, NULL);
}

static wc_input mk(jsp_mode mode, int in_js, int in_allow) {
    wc_input in;
    memset(&in, 0, sizeof in);
    in.js_mode = mode;
    in.host_in_js = in_js;
    in.host_in_allow = in_allow;
    return in;
}

static void test_safe_is_all_off(void **state) {
    (void)state;
    wc_caps c = wc_safe();
    wc_caps zero;
    memset(&zero, 0, sizeof zero);
    assert_memory_equal(&c, &zero, sizeof c);
}

/* A fully trusted host (allow.conf AND js.conf, allowlist JS mode) gets everything. */

static void test_trusted_host_gets_all_caps(void **state) {
    (void)state;
    wc_caps c = wc_derive(mk(JSP_ALLOWLIST, 1, 1));
    assert_true(c.js);
    assert_true(c.css);
    assert_true(c.images);
    assert_true(c.net);
    assert_true(c.cookies);
    assert_true(c.persist);
    assert_true(c.readback);
    assert_true(c.gpu);
    assert_true(c.sw);
    assert_true(c.rtc);
}

/* Presentation-trust: allow.conf ALONE (not in js.conf) unlocks author CSS + images
 * but NEVER the privacy-sensitive caps (net/cookies/persist/...). JS stays off since
 * the host is not on js.conf under the default allowlist mode. */

static void test_present_trust_css_images_only(void **state) {
    (void)state;
    wc_caps c = wc_derive(mk(JSP_ALLOWLIST, 0, 1));
    assert_false(c.js);      /* not on js.conf */
    assert_true(c.css);      /* presentation-trust */
    assert_true(c.images);   /* presentation-trust */
    assert_false(c.net);     /* privacy: needs allow AND js */
    assert_false(c.cookies);
    assert_false(c.persist);
    assert_false(c.readback);
    assert_false(c.gpu);
    assert_false(c.sw);
    assert_false(c.rtc);
}

/* A host on js.conf but NOT allow.conf: JS runs (leak-free) but no presentation-trust
 * and no privacy caps (both need allow.conf). css/images stay off (no user toggle). */
static void test_js_without_allow_is_not_trust(void **state) {
    (void)state;
    wc_caps c = wc_derive(mk(JSP_ALLOWLIST, 1, 0));
    assert_true(c.js);
    assert_false(c.css);
    assert_false(c.images);
    assert_false(c.net);
    assert_false(c.persist);
}

/* Global JSP_ON enables JS everywhere, but is NOT trust: a host absent from
 * allow.conf gets JS yet no network / privacy caps. */

static void test_jspon_alone_is_not_trust(void **state) {
    (void)state;
    wc_caps c = wc_derive(mk(JSP_ON, 0, 0));
    assert_true(c.js);       /* JSP_ON runs JS for every host */
    assert_false(c.css);     /* not allowlisted, no user toggle */
    assert_false(c.images);
    assert_false(c.net);     /* JSP_ON is not allow.conf trust */
    assert_false(c.gpu);
    /* But JSP_ON + allow.conf IS trust. */
    wc_caps t = wc_derive(mk(JSP_ON, 0, 1));
    assert_true(t.net);
    assert_true(t.persist);
}

/* User session toggles turn on the leak-free presentation caps without any trust. */

static void test_user_toggles_grant_leakfree(void **state) {
    (void)state;
    wc_input in = mk(JSP_OFF, 0, 0);
    in.user_css = 1;
    in.user_images = 1;
    wc_caps c = wc_derive(in);
    assert_true(c.css);
    assert_true(c.images);
    assert_false(c.js);      /* JS off (no toggle path here) */
    assert_false(c.net);     /* no trust */
}

/* Reader mode wins: css and images are forced off even for a fully trusted host,
 * while the privacy caps (driven by trust, not presentation) are unaffected. */
static void test_reader_forces_css_images_off(void **state) {
    (void)state;
    wc_input in = mk(JSP_ALLOWLIST, 1, 1);
    in.reader = 1;
    wc_caps c = wc_derive(in);
    assert_false(c.css);
    assert_false(c.images);
    assert_true(c.js);       /* execution is not presentation */
    assert_true(c.net);      /* trust unaffected by reader */
    assert_true(c.persist);
}

/* Fail-closed: an out-of-range mode never enables JS (delegates to jsp_enabled). */

static void test_bad_mode_fails_closed(void **state) {
    (void)state;
    wc_caps c = wc_derive(mk((jsp_mode)999, 1, 1));
    assert_false(c.js);
    /* allow.conf still grants presentation-trust independent of JS. */
    assert_true(c.css);
    /* but trust needs js_enabled, which is false here, so no network. */
    assert_false(c.net);
}

/* The rdp_caps projection carries exactly the leak-free triple. */

static void test_render_caps_projection(void **state) {
    (void)state;
    wc_caps c = wc_derive(mk(JSP_ALLOWLIST, 1, 1));
    rdp_caps r = wc_render_caps(c);
    assert_true(r.images);
    assert_true(r.css);
    assert_true(r.js);
    /* Safe caps project to all-off. */
    rdp_caps z = wc_render_caps(wc_safe());
    assert_false(z.images);
    assert_false(z.css);
    assert_false(z.js);
}

/* Headless operator-flag path: --js=on is the trust signal; flags are orthogonal. */

static void test_from_flags_headless(void **state) {
    (void)state;
    /* --js=on only. */
    wc_caps j = wc_from_flags(true, false, false);
    assert_true(j.js);
    assert_true(j.net);
    assert_true(j.cookies);
    assert_true(j.persist);
    assert_false(j.css);
    assert_false(j.images);
    /* --author-css only: presentation on, no network. */
    wc_caps c = wc_from_flags(false, true, false);
    assert_true(c.css);
    assert_false(c.js);
    assert_false(c.net);
    /* --images only. */
    wc_caps i = wc_from_flags(false, false, true);
    assert_true(i.images);
    assert_false(i.net);
    /* nothing: all off. */
    wc_caps n = wc_from_flags(false, false, false);
    rdp_caps zero;
    memset(&zero, 0, sizeof zero);

    assert_memory_equal(&(rdp_caps){0}, &zero, sizeof zero);
    assert_false(n.js);
    assert_false(n.net);
}

int main(void) {
    const struct CMUnitTest tests[] = {
        cmocka_unit_test(test_safe_is_all_off),
        cmocka_unit_test(test_trusted_host_gets_all_caps),
        cmocka_unit_test(test_present_trust_css_images_only),
        cmocka_unit_test(test_js_without_allow_is_not_trust),
        cmocka_unit_test(test_jspon_alone_is_not_trust),
        cmocka_unit_test(test_user_toggles_grant_leakfree),
        cmocka_unit_test(test_reader_forces_css_images_off),
        cmocka_unit_test(test_bad_mode_fails_closed),
        cmocka_unit_test(test_render_caps_projection),
        cmocka_unit_test(test_from_flags_headless),
    };
    return cmocka_run_group_tests(tests, NULL, NULL);
}

