#define _DEFAULT_SOURCE
#include <stdarg.h>
#include <stddef.h>
#include <setjmp.h>
#include <sys/socket.h>
#include <time.h>
#include <unistd.h>
#include <cmocka.h>
#include <wayland-client.h>

#include "wl_guard.h"

static long ms_since(const struct timespec *a) {
    struct timespec b;
    clock_gettime(CLOCK_MONOTONIC, &b);
    return (b.tv_sec - a->tv_sec) * 1000 + (b.tv_nsec - a->tv_nsec) / 1000000;
}

/* The helper starts on a live display, tolerates an idle socket, and stops promptly (it polls in
 * 100 ms slices): a hung join would hang the GUI's shutdown. NULL is a no-op everywhere. */

static void test_guard_starts_idles_and_stops_promptly(void **state) {
    (void)state;
    int sv[2];
    assert_int_equal(socketpair(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0, sv), 0);
    struct wl_display *d = wl_display_connect_to_fd(sv[0]);
    assert_non_null(d);
    wl_guard *g = wlg_start(d);
    assert_non_null(g);
    usleep(250 * 1000);                           /* several idle polls */
    struct timespec t0;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    wlg_stop(g);
    assert_true(ms_since(&t0) < 1000);
    wl_display_disconnect(d);                     /* closes sv[0] */
    close(sv[1]);
    wlg_stop(NULL);
    assert_null(wlg_start(NULL));
}

/* A peer that disappears (compositor gone) ends the helper by itself instead of spinning. */

static void test_guard_survives_peer_hangup(void **state) {
    (void)state;
    int sv[2];
    assert_int_equal(socketpair(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0, sv), 0);
    struct wl_display *d = wl_display_connect_to_fd(sv[0]);
    assert_non_null(d);
    wl_guard *g = wlg_start(d);
    assert_non_null(g);
    close(sv[1]);                                 /* hang up */
    usleep(300 * 1000);
    wlg_stop(g);
    wl_display_disconnect(d);
}

int main(void) {
    const struct CMUnitTest tests[] = {
        cmocka_unit_test(test_guard_starts_idles_and_stops_promptly),
        cmocka_unit_test(test_guard_survives_peer_hangup),
    };
    return cmocka_run_group_tests(tests, NULL, NULL);
}

#define _POSIX_C_SOURCE 200809L
#include <stdarg.h>
#include <stddef.h>
#include <stdint.h>
#include <setjmp.h>
#include <poll.h>
#include <time.h>
#include <string.h>
#include <cmocka.h>

#include "ws_hub.h"

static void emit(void *ctx, int id, int kind, int code, const char *data, size_t len) {
    (void)data; (void)len;
    rec *r = (rec *)ctx;
    if (r->n < 16) { r->id[r->n] = id; r->kind[r->n] = kind; r->code[r->n] = code; r->n++; }
}

/* Waits (bounded) for the notify pipe and drains it once. */

static void wait_notify(wh_hub *h, rec *r) {
    struct pollfd p = { wh_notify_fd(h), POLLIN, 0 };
    assert_true(poll(&p, 1, 5000) > 0);
    wh_on_notify(h, emit, r);
}

static void test_new_free(void **state) {
    (void)state;
    wh_hub *h = wh_new();
    assert_non_null(h);
    assert_true(wh_notify_fd(h) >= 0);
    assert_int_equal(wh_count(h), 0);
    struct pollfd fds[8];
    int ids[8];
    assert_int_equal(wh_poll_fds(h, fds, ids, 8), 0);
    wh_free(h);
    wh_free(NULL);
}

static void test_failed_open_reports_error_then_close(void **state) {
    (void)state;
    wh_hub *h = wh_new();
    assert_non_null(h);
    assert_int_equal(wh_open_async(h, 3, "ws://plaintext.example/", NULL), 0);
    rec r;
    memset(&r, 0, sizeof r);
    wait_notify(h, &r);
    assert_int_equal(r.n, 2);
    assert_int_equal(r.id[0], 3);
    assert_int_equal(r.kind[0], WH_EV_ERROR);
    assert_int_equal(r.kind[1], WH_EV_CLOSE);
    assert_int_equal(r.code[1], WH_CLOSE_ABNORMAL);
    assert_int_equal(wh_count(h), 0);
    wh_free(h);
}

static void test_duplicate_and_capacity(void **state) {
    (void)state;
    wh_hub *h = wh_new();
    assert_non_null(h);
    for (int i = 1; i <= WH_MAX; ++i)
        assert_int_equal(wh_open_async(h, i, "ws://x.example/", NULL), 0);
    assert_int_equal(wh_open_async(h, 1, "ws://x.example/", NULL), -1);          /* dup */
    assert_int_equal(wh_open_async(h, WH_MAX + 1, "ws://x.example/", NULL), -1); /* full */
    assert_int_equal(wh_open_async(NULL, 1, "ws://x.example/", NULL), -1);
    assert_int_equal(wh_open_async(h, 99, NULL, NULL), -1);
    rec r;
    memset(&r, 0, sizeof r);
    for (int guard = 0; r.n < 2 * WH_MAX && guard < 50; ++guard) wait_notify(h, &r);
    assert_int_equal(r.n, 2 * WH_MAX);
    /* all slots free again */
    assert_int_equal(wh_open_async(h, 42, "ws://x.example/", NULL), 0);
    memset(&r, 0, sizeof r);
    wait_notify(h, &r);
    wh_free(h);
}

static void test_close_all_drops_late_results(void **state) {
