def line_sites(text):
    lines = text.split("\n")
    out = []
    in_block = False
    for i, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith("#"):
            continue
        if stripped.startswith("//") or stripped.startswith("/*"):
            if stripped.startswith("/*") and "*/" not in stripped:
                in_block = True
            continue
        if in_block:
            if "*/" in line:
                in_block = False
            continue
        if stripped.startswith('"') or stripped.startswith("'"):
            continue
        clean = re.sub(r"/\*.*?\*/", "", line)
        clean = re.sub(r"//.*", "", clean)
        clean = re.sub(r'"(?:[^"\\]|\\.)*"', '""', clean)
        clean = re.sub(r"'(?:[^'\\]|\\.)*'", "''", clean)
        for op in ("<=", ">=", "==", "!=", "&&", "||", "+", "-", "<", ">"):
            if op not in clean:
                continue
            if op in SKIP_EXTRA_OPS:
                continue
            if op in ("+", "-") and any(
                s in clean for s in ("++", "--", "+=", "-=")):
                continue
            out.append((i, op))
    return out

def mutate_line(line, op):
    opp = dict(OPS)
    token = opp[op]
    idx = line.find(op)
    while idx >= 0:
        if op in ("<=", ">=", "==", "!=", "&&", "||"):
            return line[:idx] + token + line[idx + len(op):]
        if op == "<" and idx + 1 < len(line) and line[idx + 1] == "=":
            idx = line.find(op, idx + 2)
            continue
        if op == ">" and idx + 1 < len(line) and line[idx + 1] == "=":
            idx = line.find(op, idx + 2)
            continue
        if op in ("<", ">") and idx > 0 and line[idx - 1] == "-":
            idx = line.find(op, idx + 1)
            continue
        if op in ("<", ">") and idx + 1 < len(line) and line[idx + 1] in "<>":
            idx = line.find(op, idx + 1)
            continue
        if op in ("+", "-") and idx + 1 < len(line) and line[idx + 1] in "+-=>":
            idx = line.find(op, idx + 1)
            continue
        if op in ("+", "-") and idx > 0 and line[idx - 1] in "+-":
            idx = line.find(op, idx + 1)
            continue
        if op in ("+", "-") and idx + 1 < len(line) and line[idx + 1].isdigit():
            idx = line.find(op, idx + 1)
            continue
        return line[:idx] + token + line[idx + 1:]
    return None

def find_modules(root):
    mods = []
    for name in sorted(os.listdir(os.path.join(root, "tests"))):
        m = re.fullmatch(r"test_(.+)\.c", name)
        if m and os.path.exists(os.path.join(root, "src", m.group(1) + ".c")):
            mods.append(m.group(1))
    return mods

def run_bin(path):
    # A hung suite is a killed mutant: the fault was detected (nothing passed).
    # Without a timeout one size_t-underflow mutant hangs the whole run, and a
    # SIGKILLed harness leaves that mutant on disk (no finally on SIGKILL).
    try:
        proc = subprocess.run([path], stdout=subprocess.DEVNULL,
                              stderr=subprocess.DEVNULL, timeout=MUTATE_TIMEOUT)
    except subprocess.TimeoutExpired:
        return False
    return proc.returncode == 0

